# -------- Helpers --------
def hash_password(pw: str) -> str:
    return bcrypt.hashpw(pw.encode(), bcrypt.gensalt()).decode()

def verify_password(plain: str, hashed: str) -> bool:
    try:
        return bcrypt.checkpw(plain.encode(), hashed.encode())
    except Exception:
        return False

def create_access_token(user_id: str, email: str, role: str, token_version: int = 0) -> str:
    payload = {
        "sub": user_id,
        "email": email,
        "role": role,
        "ver": int(token_version or 0),
        "iat": datetime.now(timezone.utc),
        "exp": datetime.now(timezone.utc) + timedelta(days=ACCESS_TOKEN_EXPIRE_DAYS),
        "type": "access",
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALG)


def _mfa_fernet_for(material: str) -> Fernet:
    """Fernet derived from the given secret material. The derivation string is
    unchanged from the original so a JWT-derived key still decrypts secrets
    written before MFA_ENCRYPTION_KEY existed."""
    key = base64.urlsafe_b64encode(hashlib.sha256((material + "|mfa-secret-v1").encode()).digest())
    return Fernet(key)


def _mfa_fernets() -> List[Fernet]:
    """Keys to try, most-preferred first.

    ENCRYPTION always uses the first entry. DECRYPTION walks the list, which
    is what makes turning MFA_ENCRYPTION_KEY on a no-migration change: a
    secret enrolled before the dedicated key existed was written with the
    JWT-derived key and still decrypts through the fallback, while everything
    written from now on uses the dedicated key. Once the dedicated key is set,
    rotating JWT_SECRET no longer touches MFA at all.
    """
    if MFA_ENCRYPTION_KEY:
        return [_mfa_fernet_for(MFA_ENCRYPTION_KEY), _mfa_fernet_for(JWT_SECRET)]
    return [_mfa_fernet_for(JWT_SECRET)]


def _mfa_encrypt_secret(secret: str) -> str:
    return _mfa_fernets()[0].encrypt(secret.encode()).decode()


def _mfa_decrypt_secret(token: str) -> Optional[str]:
    raw = (token or "").encode()
    for fernet in _mfa_fernets():
        try:
            return fernet.decrypt(raw).decode()
        except (InvalidToken, ValueError, TypeError):
            continue
    return None


def _totp_code(secret: str, counter: int) -> str:
    padded = (secret or "").upper() + "=" * ((8 - len(secret or "") % 8) % 8)
    key = base64.b32decode(padded, casefold=True)
    msg = struct.pack(">Q", int(counter))
    digest = hmac.new(key, msg, hashlib.sha1).digest()
    offset = digest[-1] & 0x0F
    binary = struct.unpack(">I", digest[offset:offset + 4])[0] & 0x7FFFFFFF
    return f"{binary % 1000000:06d}"


def _verify_totp(secret: str, code: str, *, at: Optional[int] = None) -> bool:
    clean = re.sub(r"\D", "", code or "")
    if len(clean) != 6:
        return False
    now_s = int(at if at is not None else datetime.now(timezone.utc).timestamp())
    counter = now_s // 30
    return any(hmac.compare_digest(_totp_code(secret, counter + drift), clean) for drift in (-1, 0, 1))


def _mfa_recovery_hash(code: str) -> str:
    normalized = re.sub(r"[^A-Z0-9]", "", (code or "").upper())
    return hashlib.sha256((JWT_SECRET + "|mfa-recovery|" + normalized).encode()).hexdigest()


def _new_recovery_codes() -> list[str]:
    return [f"{secrets.token_hex(3).upper()}-{secrets.token_hex(3).upper()}" for _ in range(8)]


def _create_mfa_challenge(user: dict) -> str:
    payload = {
        "sub": user["id"], "email": user.get("email"), "ver": _token_version(user),
        "iat": datetime.now(timezone.utc), "exp": datetime.now(timezone.utc) + timedelta(minutes=10),
        "type": "mfa_challenge",
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALG)


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _client_ip(request: Request) -> str:
    """Best-effort client IP behind nginx/Cloudflare without trusting arbitrary hops."""
    cf = (request.headers.get("cf-connecting-ip") or "").strip()
    if cf:
        return cf[:80]
    forwarded = (request.headers.get("x-forwarded-for") or "").split(",", 1)[0].strip()
    if forwarded:
        return forwarded[:80]
    return (request.client.host if request.client else "unknown")[:80]


def _security_key(value: str) -> str:
    return hashlib.sha256((value or "").encode("utf-8", "ignore")).hexdigest()


async def _enforce_rate_limit(
    request: Request,
    scope: str,
    subject: str,
    *,
    limit: int,
    window_seconds: int,
    silent: bool = False,
) -> bool:
    """Mongo-backed fixed-window limiter shared by every backend worker.

    Only hashes of identifiers are stored.  Returning False is useful for
    forgot-password, where the response must not reveal whether an account
    exists.  Other callers receive a normal 429 with Retry-After.
    """
    now = datetime.now(timezone.utc)
    bucket = int(now.timestamp()) // max(1, int(window_seconds))
    raw = f"{scope}|{subject}|{bucket}"
    doc_id = _security_key(raw)
    expires = now + timedelta(seconds=max(60, int(window_seconds) * 2))
    update = {
        "$inc": {"count": 1},
        "$setOnInsert": {
            "scope": scope,
            "subject_hash": _security_key(subject),
            "bucket": bucket,
            "created_at": now,
            "expires_at": expires,
        },
    }
    try:
        row = await db.auth_rate_limits.find_one_and_update(
            {"_id": doc_id}, update, upsert=True, return_document=ReturnDocument.AFTER
        )
    except DuplicateKeyError:
        # Two workers can attempt the first insert in the same millisecond.
        # The deterministic key makes a simple non-upsert retry safe.
        row = await db.auth_rate_limits.find_one_and_update(
            {"_id": doc_id}, {"$inc": {"count": 1}}, upsert=False,
            return_document=ReturnDocument.AFTER,
        )
    count = int((row or {}).get("count") or 0)
    if count <= limit:
        return True
    if silent:
        return False
    retry_after = max(1, int(window_seconds - (int(now.timestamp()) % window_seconds)))
    raise HTTPException(
        status_code=429,
        detail="Too many attempts. Please wait and try again.",
        headers={"Retry-After": str(retry_after)},
    )


def _token_version(user: dict) -> int:
    try:
        return int(user.get("token_version") or 0)
    except Exception:
        return 0


# Sprint 110bg — Business timezone. The whole app's "today" / "this month" /
# "this week" boundaries are anchored on US Eastern (operator is in Warren OH).
# Storage timestamps remain in UTC (now_iso) so backups & cross-tz queries stay
# consistent — only DAY-LEVEL operator-facing math uses this.
BUSINESS_TZ = ZoneInfo("America/New_York")


def business_today() -> date:
    """Return today's date in the business timezone (US Eastern)."""
    return datetime.now(BUSINESS_TZ).date()


def _business_date_from_timestamp(value: Optional[str], fallback: Optional[str] = None) -> str:
    """Convert a stored UTC/ISO timestamp to its America/New_York business date."""
    if value:
        try:
            parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(BUSINESS_TZ).date().isoformat()
        except Exception:
            pass
    return fallback or business_today().isoformat()


def now_local() -> datetime:
    """Naive local datetime (no tzinfo) — handy for hour/minute comparisons in
    the auto-backup loop where we want wall-clock semantics."""
    return datetime.now(BUSINESS_TZ).replace(tzinfo=None)


def _business_day_utc_bounds(day_iso: str) -> Tuple[str, str]:
    """Return UTC ISO bounds for one America/New_York business date.

    Register activity must follow the local day when money was actually
    collected. Using a plain UTC ``YYYY-MM-DD`` prefix can put evening cash
    payments into tomorrow's drawer, especially during daylight-saving time.
    """
    local_day = date.fromisoformat(day_iso)
    start_local = datetime.combine(local_day, datetime.min.time(), tzinfo=BUSINESS_TZ)
    end_local = start_local + timedelta(days=1)
    return (
        start_local.astimezone(timezone.utc).isoformat(),
        end_local.astimezone(timezone.utc).isoformat(),
    )


