# Short-lived authenticated-user cache. The admin dashboard opens many API
# requests in parallel; without this, every request rereads the exact same user
# row from Mongo. The cache is intentionally tiny and short-lived so password
# changes/deactivation still take effect quickly, while simultaneous requests
# share one database lookup per backend worker.
_AUTH_USER_CACHE: Dict[str, Tuple[float, Dict[str, Any]]] = {}
_AUTH_USER_INFLIGHT: Dict[str, asyncio.Future] = {}
_AUTH_USER_CACHE_TTL_SECONDS = max(1.0, float(os.environ.get("AUTH_USER_CACHE_TTL_SECONDS", "5")))
_AUTH_USER_CACHE_MAX = 512


async def _load_auth_user(user_id: str) -> Optional[dict]:
    now = asyncio.get_running_loop().time()
    hit = _AUTH_USER_CACHE.get(user_id)
    if hit and hit[0] > now:
        return dict(hit[1])
    task = _AUTH_USER_INFLIGHT.get(user_id)
    if task is None:
        # Motor returns an asyncio-compatible Future here, not a coroutine.
        # ensure_future accepts either and still lets parallel requests share
        # the same in-flight lookup. create_task would raise TypeError.
        task = asyncio.ensure_future(
            db.users.find_one({"id": user_id}, {"_id": 0, "password_hash": 0})
        )
        _AUTH_USER_INFLIGHT[user_id] = task
    try:
        user = await task
    finally:
        if _AUTH_USER_INFLIGHT.get(user_id) is task:
            _AUTH_USER_INFLIGHT.pop(user_id, None)
    if user:
        if len(_AUTH_USER_CACHE) >= _AUTH_USER_CACHE_MAX:
            # Simple bounded eviction; cache entries are disposable.
            _AUTH_USER_CACHE.pop(next(iter(_AUTH_USER_CACHE)), None)
        _AUTH_USER_CACHE[user_id] = (now + _AUTH_USER_CACHE_TTL_SECONDS, dict(user))
        return dict(user)
    _AUTH_USER_CACHE.pop(user_id, None)
    return None


def _invalidate_auth_user_cache(user_id: Optional[str] = None) -> None:
    if user_id:
        _AUTH_USER_CACHE.pop(user_id, None)
    else:
        _AUTH_USER_CACHE.clear()


async def get_current_user(request: Request, creds: Optional[HTTPAuthorizationCredentials] = Depends(security)) -> dict:
    token = None
    if creds and creds.scheme.lower() == "bearer":
        token = creds.credentials
    if not token:
        auth = request.headers.get("Authorization", "")
        if auth.lower().startswith("bearer "):
            token = auth[7:]
    if not token:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALG])
        if payload.get("type") != "access":
            raise HTTPException(status_code=401, detail="Invalid token type")
        user = await _load_auth_user(payload["sub"])
        if not user:
            raise HTTPException(status_code=401, detail="User not found")
        # Safety: deactivated staff/client accounts must not keep working from
        # old saved JWTs. Legacy rows without an `active` field are treated as
        # active so existing production accounts are not locked out.
        if user.get("active") is False:
            raise HTTPException(status_code=403, detail="Account disabled")
        # Backward compatible session invalidation. Legacy tokens/users both
        # resolve to version 0; changing/resetting a password increments the
        # user version and immediately invalidates every older token.
        if int(payload.get("ver") or 0) != _token_version(user):
            raise HTTPException(status_code=401, detail="Session expired. Please sign in again.")
        if user.get("must_change_password") is True and request.url.path not in (
            "/api/auth/me", "/api/auth/change-password"
        ):
            raise HTTPException(
                status_code=403,
                detail="Temporary password must be changed before continuing.",
            )
        return user
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")


async def require_admin(user: dict = Depends(get_current_user)) -> dict:
    if user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin access required")
    return user


async def require_employee_or_admin(user: dict = Depends(get_current_user)) -> dict:
    """Allow employees and admins through; clients are blocked.
    Use this on any endpoint that staff need (clock-in, today's roster, etc.).
    Sensitive endpoints (income, P&L, settings, billing) keep `require_admin`."""
    if user.get("role") not in ("admin", "employee"):
        raise HTTPException(status_code=403, detail="Staff access required")
    return user


def require_admin_and_permission(key: str):
    """Security checkpoint — backend permission enforcement (following the
    frontend can() fix). This composes require_employee_or_admin (the broad
    account-type gate — keeps clients out entirely, but lets BOTH `role:
    admin` and `role: employee` staff accounts through) with a specific
    permission check from the same matrix `/me/permissions` already exposes,
    so the two can never drift apart.

    Permission-matrix product-defect fix: this used to compose require_admin
    instead, which meant every `role: employee` Staff Portal account was
    rejected here regardless of its configured staff_role/permissions — the
    entire permission matrix was unreachable for the accounts it exists to
    govern. `_perms_for()` is what actually decides what an account can do,
    and it already resolves employees correctly by their staff_role; it only
    ever returns full/unrestricted permissions for a true owner (role=="admin"
    with no staff_role, or staff_role=="owner") — a `role: employee` account
    can never satisfy that, so widening the gate here cannot grant an
    employee unrestricted admin access, only the specific keys their staff_role
    (or an admin-edited override) actually grants.

    Defined here (near the top of the file, before PERMISSION_KEYS/_perms_for
    exist) because `Depends(require_admin_and_permission("key"))` calls this
    factory immediately at import time, as each endpoint below is defined —
    so the key-validity check has to live inside `_dep` (deferred to actual
    request time, by which point the whole module has finished loading)
    rather than in this outer function body."""
    async def _dep(user: dict = Depends(require_employee_or_admin)) -> dict:
        if key not in PERMISSION_KEYS:
            raise RuntimeError(f"Unknown permission key '{key}'")
        perms = _perms_for(user)
        if not perms.get(key):
            raise HTTPException(status_code=403, detail=f"Missing permission: {key}")
        return user
    return _dep


def require_admin_and_any_permission(*keys: str):
    """Like ``require_admin_and_permission`` but satisfied by ANY of ``keys``.

    School consolidation (B4): the unified School assignment route needs
    "manage_school OR manage_training_sessions" — a trainer who runs
    in-person delivery must be able to assign a program without being handed
    general Online School administration. That was briefly expressed as
    ``Depends(get_current_user)`` plus an in-body check, which let clients
    reach the handler body at all and left authorization resting entirely on
    that inner check. This restores the OUTER gate: it composes the same
    ``require_employee_or_admin`` account-type gate (so clients are rejected
    before the handler runs) with an any-of permission test drawn from the
    same matrix ``/me/permissions`` exposes.

    Delivery-mode-specific narrowing (e.g. online assignment additionally
    requiring ``manage_school``) still lives inside the route — this gate is
    the coarse "may you touch School assignment at all" boundary.
    """
    async def _dep(user: dict = Depends(require_employee_or_admin)) -> dict:
        for key in keys:
            if key not in PERMISSION_KEYS:
                raise RuntimeError(f"Unknown permission key '{key}'")
        perms = _perms_for(user)
        if not any(perms.get(k) for k in keys):
            raise HTTPException(
                status_code=403,
                detail="Missing permission: " + " or ".join(keys),
            )
        return user
    return _dep


def _is_owner(user: Dict[str, Any]) -> bool:
    """True owner per the exact same rule `_perms_for` uses for its
    lockout-protection bypass: role=="admin" AND (no staff_role at all, or
    staff_role=="owner"). Deliberately NOT derived from resolved permissions
    — a role-matrix override that happens to grant a manager every key
    (e.g. via the admin-editable overrides layer) must never be treated as
    equivalent to being the actual owner, or a delegate could use that to
    edit the matrix itself and escalate further."""
    role = (user.get("role") or "").lower()
    if role != "admin":
        return False
    sr = (user.get("staff_role") or "").lower()
    return not sr or sr == "owner"


async def require_owner(user: dict = Depends(get_current_user)) -> dict:
    """For the handful of actions that must never be delegatable at all —
    editing the permission matrix itself, reassigning staff_role, exporting
    raw password hashes — regardless of what any override says."""
    if not _is_owner(user):
        raise HTTPException(status_code=403, detail="Owner access required")
    return user


