class RegisterIn(BaseModel):
    email: EmailStr
    password: str = Field(min_length=8)
    name: str
    referred_by_code: Optional[str] = None  # optional referral code from another client

class LoginIn(BaseModel):
    email: EmailStr
    password: str

class MfaLoginVerifyIn(BaseModel):
    challenge_token: str = Field(min_length=20, max_length=4096)
    code: str = Field(min_length=6, max_length=64)

class MfaCodeIn(BaseModel):
    code: str = Field(min_length=6, max_length=64)

class MfaDisableIn(BaseModel):
    current_password: str
    code: str = Field(min_length=6, max_length=64)

class UserOut(BaseModel):
    model_config = ConfigDict(extra="ignore")
    id: str
    email: str
    name: str
    role: str
    client_id: Optional[str] = None
    # Sprint 110ex — Phase 7: fine-grained staff role layered on top of `role`
    staff_role: Optional[str] = None
    must_change_password: bool = False
    # Passwordless-first claim flow — client accounts created via
    # POST /claim/{token}/login get an unusable random password_hash and this
    # flag set, so the portal can gently prompt them to set a real one.
    needs_password: bool = False

class AuthOut(BaseModel):
    token: str
    user: UserOut

class ClientIn(BaseModel):
    name: str
    address: Optional[str] = ""
    phone: Optional[str] = ""
    email: Optional[str] = ""
    emerg: Optional[str] = ""
    credits: float = 0  # daycare credits; supports .5 balances for additional dogs
    training_credits: float = 0  # 1-on-1 / lesson credits
    boarding_credits: float = 0  # overnight stay credits — 1 credit = 1 dog/night; extra dogs can use .5
    referred_by_code: Optional[str] = None  # set on creation if referred by another client
    photo: Optional[str] = ""  # base64 data URL of the client's profile photo (small avatar). Optional.
    photo_gallery_url: Optional[str] = ""  # per-client link to their photo gallery (e.g. PicTime, Pixieset)
    photo_gallery_pin: Optional[str] = ""  # per-client PIN required to download photos from the gallery
    photo_gallery_has_new: bool = False  # admin-set nudge: pulses a "NEW" badge on the portal gallery CTA
    # Sprint 110aw — Meet-n-Greet / Temperament-eval lifecycle. Default `active`
    # so existing clients aren't affected. When `Settings → evaluation
    # → require_evaluation_first` is on, *new* clients are created as
    # `prospect` and can only book the evaluation service until staff mark them
    # `active` (or `rejected`).
    client_status: Optional[Literal["prospect", "evaluation_scheduled", "evaluated", "active", "rejected"]] = "active"
    evaluation_notes: Optional[str] = ""  # admin notes from the meet-n-greet
    # Sprint 110di-51 — Per-client running tab. POSITIVE = client owes the
    # business (accounts receivable). NEGATIVE = client has pre-paid credit
    # on file. Moved by checkout partial-pay + manual ledger adjustments.
    account_balance: float = 0.0
    # Stripe Online (Phase 3A) — stripe_customer_id (stable mapping to a
    # lazily-created Stripe Customer) and stripe_ar_adjustments_applied (the
    # internal idempotency marker preventing a crash-and-retry from
    # double-applying an AR $inc) are DELIBERATELY NOT fields on ClientIn.
    # This is the admin create/edit INPUT model — every admin/employee client
    # edit does `db.clients.update_one(..., {"$set": body.model_dump()})|`,
    # so if these lived here, submitting an ordinary profile edit (e.g.
    # changing a phone number) would silently reset them to None/[] every
    # time, both losing the Stripe Customer cache AND (far worse) re-opening
    # the idempotency guard so a redelivered webhook could double-apply an
    # AR adjustment. Every real reader/writer of these two fields (Stripe
    # checkout-session creation, _apply_stripe_payment's Step B2) already
    # goes through raw db.clients.find_one/update_one — never through this
    # model — so they don't need to be here for the app to function, and
    # keeping them off ClientIn/ClientOut is also what keeps them out of
    # every admin/portal API response by construction.

class ClientOut(ClientIn):
    id: str
    waiver: bool = False
    portal_email: Optional[str] = None  # the login email of linked user
    dogs: Optional[List[Dict[str, Any]]] = None  # lightweight [{id, name, breed}] for admin listing
    last_login_at: Optional[str] = None  # ISO timestamp of the client's most recent portal login
    login_count: int = 0  # total number of times this client has logged in
    # Sprint 110g — per-pool stamp of the most recent "low credit" email we
    # fired, so the idempotency guard can avoid spamming and the UI can show
    # "client was notified".
    low_credit_emailed_at: Optional[Dict[str, Any]] = None
    # Sprint 110dh-6 — admin-side label for first-time setup completion.
    setup_badge: Optional[str] = None       # "Ready to Book" | "Pending Vaccine Review" | "Setup Incomplete"
    setup_overall: Optional[str] = None     # "complete" | "pending_review" | "in_progress" | "not_started"
    created_at: str

