# -------- Client files (Sprint 84) --------
# Admin uploads PDFs, photos, short videos to a specific client. Optionally
# tags to a specific dog (e.g. "Rocky's loose-leash homework"). Clients see
# them in the portal under a "Training Files & Homework" section.
#
# Storage: base64 inline in Mongo for consistency with existing photo storage.
# Capped at 10 MB per file to keep doc size sane.
CLIENT_FILE_MAX_BYTES = 10 * 1024 * 1024  # 10 MB

class ClientFileIn(BaseModel):
    name: str
    content_type: str
    data: str  # base64-encoded content (data URI or raw base64 both accepted)
    note: Optional[str] = ""
    dog_id: Optional[str] = None  # optional — file tagged to a specific dog


class PortalIntakeFileUploadIn(BaseModel):
    name: str
    content_type: str
    data: str


PORTAL_INTAKE_UPLOAD_CONTENT_TYPES = {
    "application/pdf",
    "text/plain",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
}

def _strip_data_uri(s: str) -> str:
    """Accept either a raw base64 string or a `data:...;base64,...` URI."""
    if s.startswith("data:") and ";base64," in s:
        return s.split(";base64,", 1)[1]
    return s


def _validated_client_file_payload(data: str, *, client_portal: bool = False, content_type: str = "") -> tuple[str, int]:
    """Validate base64 and enforce the Mongo-safe size cap. Client-originated
    intake uploads use a deliberately small allowlist (PDF/images/text/Word)
    so an intake form cannot become an arbitrary binary-upload surface."""
    raw_b64 = re.sub(r"\s+", "", _strip_data_uri(data or ""))
    if not raw_b64:
        raise HTTPException(status_code=400, detail="File is empty.")
    try:
        decoded = base64.b64decode(raw_b64, validate=True)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid uploaded file.")
    size = len(decoded)
    if size <= 0:
        raise HTTPException(status_code=400, detail="File is empty.")
    if size > CLIENT_FILE_MAX_BYTES:
        raise HTTPException(status_code=413, detail=f"File too large. Max {CLIENT_FILE_MAX_BYTES // (1024*1024)} MB.")
    if client_portal:
        ct = (content_type or "").split(";", 1)[0].strip().lower()
        if not (ct.startswith("image/") or ct in PORTAL_INTAKE_UPLOAD_CONTENT_TYPES):
            raise HTTPException(status_code=415, detail="Intake uploads must be a PDF, image, text file, or Word document.")
    return raw_b64, size

@api.post("/clients/{client_id}/files")
async def upload_client_file(client_id: str, body: ClientFileIn, user: dict = Depends(require_admin)):
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1, "name": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    raw_b64, approx_bytes = _validated_client_file_payload(body.data or "", content_type=body.content_type)
    if body.dog_id:
        # Verify the dog belongs to this client (so admin can't accidentally tag the wrong dog)
        owned = await db.dogs.find_one({"id": body.dog_id, "owner_id": client_id}, {"_id": 0, "id": 1})
        if not owned:
            raise HTTPException(status_code=400, detail="That dog doesn't belong to this client.")
    doc = {
        "id": str(uuid.uuid4()),
        "client_id": client_id,
        "dog_id": body.dog_id,
        "name": (body.name or "untitled").strip()[:160],
        "content_type": (body.content_type or "application/octet-stream").strip()[:120],
        "data": raw_b64,
        "size_bytes": approx_bytes,
        "note": (body.note or "").strip()[:500],
        "uploaded_at": now_iso(),
        "uploaded_by": user.get("name", "admin"),
    }
    await db.client_files.insert_one(doc)
    # Return without the base64 payload — front end fetches that on demand
    return {k: doc[k] for k in doc if k not in ("data", "_id")}

@api.get("/clients/{client_id}/files")
async def list_client_files(client_id: str, _: dict = Depends(require_admin)):
    files = await db.client_files.find(
        {"client_id": client_id},
        {"_id": 0, "data": 0},  # exclude base64 payload — fetched per file on download
    ).sort("uploaded_at", -1).to_list(500)
    return files

@api.get("/portal/files")
async def list_my_files(user: dict = Depends(get_current_user)):
    """Client portal — lists files the admin has uploaded to this client.
    Excludes the base64 payload; clients click an item to download it."""
    if not user.get("client_id"):
        return []
    files = await db.client_files.find(
        {"client_id": user["client_id"]},
        {"_id": 0, "data": 0},
    ).sort("uploaded_at", -1).to_list(500)
    return files

@api.get("/files/{file_id}/download")
async def download_file(file_id: str, user: dict = Depends(get_current_user)):
    """Fetch the actual file bytes. Admin OR the owner client only."""
    f = await db.client_files.find_one({"id": file_id}, {"_id": 0})
    if not f:
        raise HTTPException(status_code=404, detail="File not found")
    is_admin = user.get("role") == "admin"
    is_owner = user.get("client_id") and user["client_id"] == f["client_id"]
    if not (is_admin or is_owner):
        raise HTTPException(status_code=403, detail="Not your file.")
    return {
        "id": f["id"],
        "name": f["name"],
        "content_type": f["content_type"],
        "data": f["data"],  # raw base64
        "size_bytes": f.get("size_bytes", 0),
    }

@api.delete("/files/{file_id}")
async def delete_file(file_id: str, _: dict = Depends(require_admin)):
    res = await db.client_files.delete_one({"id": file_id})
    if res.deleted_count == 0:
        raise HTTPException(status_code=404, detail="File not found")
    return {"ok": True}



# -------- Bookings cold-storage archive (Sprint 88) --------
# Completed / cancelled / rejected bookings older than ARCHIVE_AFTER_DAYS get
# moved out of the hot `bookings` collection into `bookings_archive`. Keeps
# the main collection snappy and the active queue uncluttered while preserving
# every historical record for tax/legal/customer-history lookups.
ARCHIVE_AFTER_DAYS = 90
ARCHIVE_TERMINAL_STATUSES = ["completed", "cancelled", "canceled", "rejected"]

async def _archive_old_bookings_once() -> dict:
    """Move terminal-status bookings whose `date` is older than the cutoff out
    of `bookings` and into `bookings_archive`. Idempotent — safe to call as
    often as you like."""
    cutoff = (datetime.now(timezone.utc) - timedelta(days=ARCHIVE_AFTER_DAYS)).strftime("%Y-%m-%d")
    cursor = db.bookings.find(
        {"status": {"$in": ARCHIVE_TERMINAL_STATUSES}, "date": {"$lt": cutoff}},
        {"_id": 0},
    )
    moved = 0
    async for b in cursor:
        b["archived_at"] = now_iso()
        try:
            await db.bookings_archive.insert_one(b)
            await db.bookings.delete_one({"id": b["id"]})
            moved += 1
        except Exception as e:
            logger.warning("archive: failed for booking %s: %s", b.get("id"), e)
    return {"moved": moved, "cutoff_date": cutoff}

@api.post("/admin/bookings/archive-now")
async def archive_now(_: dict = Depends(require_admin)):
    """Manual trigger. scheduler.py also runs this on every tick (idempotent, once per business day)."""
    return await _archive_old_bookings_once()

# Once-per-UTC-day guard so we don't re-archive on every dashboard load.
async def _maybe_archive_today():
    try:
        today = business_today().isoformat()
        marker = await db.system_runs.find_one({"_id": "archive_bookings"})
        if marker and marker.get("date") == today:
            return
        result = await _archive_old_bookings_once()
        await db.system_runs.update_one(
            {"_id": "archive_bookings"},
            {"$set": {"date": today, "ran_at": now_iso(), "moved": result["moved"]}},
            upsert=True,
        )
        if result["moved"]:
            logger.info("Archived %d old bookings (cutoff %s)", result["moved"], result["cutoff_date"])
    except Exception as e:
        logger.warning("auto-archive failed (non-fatal): %s", e)

async def _run_once_per_business_day(marker_id: str, fn) -> Dict[str, Any]:
    """Run `fn()` at most once per business day, recorded on a `system_runs`
    marker (`_id` = marker_id). The slot is reserved BEFORE the run so two
    callers can't overlap; a failure clears the slot so the next tick retries."""
    today = business_today().isoformat()
    marker = await db.system_runs.find_one({"_id": marker_id})
    if marker and marker.get("date") == today:
        return {"skipped": "done_today", "ran_at": marker.get("ran_at")}
    await db.system_runs.update_one(
        {"_id": marker_id}, {"$set": {"date": today, "started_at": now_iso()}}, upsert=True,
    )
    try:
        result = await fn()
    except Exception as exc:
        await db.system_runs.update_one({"_id": marker_id}, {"$set": {"date": None, "error": str(exc)[:500]}})
        raise
    await db.system_runs.update_one(
        {"_id": marker_id}, {"$set": {"ran_at": now_iso(), "result": job_scheduler.jsonable(result)}, "$unset": {"error": ""}},
    )
    return result


# ── Recurring schedules: keep them booked ahead automatically ──────────────
# `POST /recurring-templates/{id}/extend` was the ONLY thing that created the
# next weeks of a client's M/W/F schedule, and it was a manual button. If
# nobody clicked, recurring clients silently stopped having bookings. The
# scheduler now extends any active, auto_extend template whose booked-through
# date is within RECURRING_AUTO_EXTEND_LEAD_DAYS, by its default horizon.
# A template that has NEVER been extended is left alone: the first manual
# Extend is the operator's opt-in (it may still be a draft).
RECURRING_AUTO_EXTEND_LEAD_DAYS = int(os.environ.get("RECURRING_AUTO_EXTEND_LEAD_DAYS", "14"))
_SCHEDULER_USER: Dict[str, Any] = {"id": "system:scheduler", "role": "admin", "name": "Scheduler", "email": ""}


async def _auto_extend_recurring_templates_once() -> Dict[str, Any]:
    today = business_today()
    edge = (today + timedelta(days=RECURRING_AUTO_EXTEND_LEAD_DAYS)).isoformat()
    summary: Dict[str, Any] = {"checked": 0, "extended": 0, "created": 0, "skipped_slots": 0, "errors": []}
    q = {
        "active": {"$ne": False},
        "auto_extend": {"$ne": False},
        "last_booked_through": {"$type": "string", "$lte": edge},
    }
    async for t in db.recurring_templates.find(q, {"_id": 0}):
        summary["checked"] += 1
        try:
            res = await extend_recurring_template(t["id"], ExtendTemplateIn(weeks=None), _SCHEDULER_USER)
            summary["extended"] += 1
            summary["created"] += int(res.get("created") or 0)
            summary["skipped_slots"] += len(res.get("skipped") or [])
            await db.recurring_templates.update_one(
                {"id": t["id"]},
                {"$set": {"last_auto_extended_at": now_iso(),
                          "last_auto_extend_result": {"window": res.get("window"), "created": res.get("created"),
                                                      "skipped": len(res.get("skipped") or [])}}},
            )
        except HTTPException as exc:
            summary["errors"].append({"template_id": t["id"], "label": t.get("label"), "error": str(exc.detail)[:300]})
        except Exception as exc:  # one broken template must not stop the sweep
            logger.warning("auto-extend failed for template %s: %s", t.get("id"), exc)
            summary["errors"].append({"template_id": t["id"], "label": t.get("label"), "error": str(exc)[:300]})
    if summary["extended"]:
        logger.info("recurring auto-extend: %s", summary)
    return summary


async def _maybe_auto_extend_recurring_today() -> Dict[str, Any]:
    return await _run_once_per_business_day("recurring_auto_extend", _auto_extend_recurring_templates_once)


@api.get("/admin/bookings/archive")
async def list_archived(skip: int = 0, limit: int = 100, _: dict = Depends(require_admin)):
    """Paged read of the archive. Newest archived first."""
    total = await db.bookings_archive.count_documents({})
    items = await db.bookings_archive.find({}, {"_id": 0}).sort("archived_at", -1).skip(int(skip)).limit(int(limit)).to_list(int(limit))
    return {"total": total, "skip": skip, "limit": limit, "items": items}


# GET /bookings budgets. Past and future are counted separately so a large
# history can never consume the rows reserved for current/future bookings.
_BOOKINGS_UPCOMING_MAX = 5000
_BOOKINGS_PAST_MAX = 3000
_BOOKINGS_RANGE_MAX = 20000


async def _booking_rows_anywhere(
    query: Optional[Dict[str, Any]] = None,
    projection: Optional[Dict[str, Any]] = None,
    *,
    include_archive: bool = True,
    limit: int = 50000,
    sort_field: str = "date",
    sort_desc: bool = False,
) -> List[Dict[str, Any]]:
    """Return booking rows from hot storage plus archive, without duplicates.

    Old completed/cancelled rows are moved into `bookings_archive` after 90 days.
    Reports, exports, dog history, and client snapshots must read both collections
    so tax/history data does not silently disappear after the archive job runs.
    Active `bookings` wins if a duplicate id exists.
    """
    q = query or {}
    proj = projection or {"_id": 0}
    # Sort in Mongo BEFORE truncating. `.to_list(limit)` on an UNSORTED
    # cursor returns whichever rows the scan reached first (natural order),
    # and the Python sort further down then only reorders that arbitrary
    # slice. So every sort-dependent caller was silently handed a random
    # subset the moment its result set outgrew `limit` — which is how a
    # 3000-row cap on GET /bookings hid all 277 upcoming bookings behind
    # older rows. Ordering first makes the truncation mean what the caller
    # actually asked for.
    direction = DESCENDING if sort_desc else ASCENDING
    rows: List[Dict[str, Any]] = await (
        db.bookings.find(q, proj).sort(sort_field, direction).to_list(limit))
    if include_archive:
        try:
            archived = await (
                db.bookings_archive.find(q, proj).sort(sort_field, direction).to_list(limit))
        except Exception:
            archived = []
        seen = {r.get("id") for r in rows if r.get("id")}
        for r in archived:
            rid = r.get("id")
            if rid and rid in seen:
                continue
            rows.append(r)
            if rid:
                seen.add(rid)
    rows.sort(key=lambda r: str(r.get(sort_field) or ""), reverse=sort_desc)
    return rows[:limit]


async def _booking_count_anywhere(query: Optional[Dict[str, Any]] = None) -> int:
    q = query or {}
    hot = await db.bookings.count_documents(q)
    try:
        archived = await db.bookings_archive.count_documents(q)
    except Exception:
        archived = 0
    return int(hot) + int(archived)


async def _first_booking_created_for_clients(client_ids: List[str]) -> Dict[str, str]:
    """Earliest booking.created_at per client across hot + archived bookings."""
    out: Dict[str, str] = {}
    if not client_ids:
        return out
    rows = await _booking_rows_anywhere(
        {"client_id": {"$in": client_ids}},
        {"_id": 0, "client_id": 1, "created_at": 1},
        limit=50000,
        sort_field="created_at",
    )
    for r in rows:
        cid = r.get("client_id")
        ca = r.get("created_at") or ""
        if cid and ca and (cid not in out or ca < out[cid]):
            out[cid] = ca
    return out



@api.post("/clients/send-claim-emails/bulk")
async def send_claim_emails_bulk(_: dict = Depends(require_admin)):
    """Send a claim email to EVERY client who has an email on file but no
    portal user yet. Designed for one-shot recovery after a data migration
    (e.g. moving from an older hosted instance) where login credentials weren't preserved.

    Returns a per-client breakdown so the admin can see exactly who got an
    email, who was skipped (no email), and who errored."""
    clients = await db.clients.find({}, {"_id": 0, "id": 1, "name": 1, "email": 1}).to_list(2000)
    # Build the set of client_ids that already have a portal user — these get skipped
    # (re-sending a reset to them would still work, but the intent of this button is
    # to onboard people who can't log in at all).
    users_with_link = await db.users.find({"client_id": {"$ne": None}}, {"_id": 0, "client_id": 1}).to_list(5000)
    linked_ids = {u["client_id"] for u in users_with_link if u.get("client_id")}

    sent: List[Dict[str, Any]] = []
    skipped_no_email: List[Dict[str, Any]] = []
    skipped_already_linked: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []

    for c in clients:
        target_email = (c.get("email") or "").strip().lower()
        if not target_email:
            skipped_no_email.append({"id": c["id"], "name": c.get("name", "")})
            continue
        if c["id"] in linked_ids:
            skipped_already_linked.append({"id": c["id"], "name": c.get("name", ""), "email": target_email})
            continue
        try:
            # Mint a fresh token (invalidate any previously unused ones for safety)
            await db.claim_tokens.delete_many({"client_id": c["id"], "used": False})
            token = secrets.token_urlsafe(32)
            expires_at = datetime.now(timezone.utc) + timedelta(days=CLAIM_TOKEN_EXPIRY_DAYS)
            await db.claim_tokens.insert_one({
                "token": token,
                "client_id": c["id"],
                "email": target_email,
                "is_reset": False,
                "used": False,
                "created_at": now_iso(),
                "expires_at": expires_at.isoformat(),
            })
            claim_url = _build_claim_url(token)
            await send_account_claim(
                to_email=target_email,
                client_name=c.get("name", ""),
                claim_url=claim_url,
                is_reset=False,
                expires_days=CLAIM_TOKEN_EXPIRY_DAYS,
            )
            sent.append({"id": c["id"], "name": c.get("name", ""), "email": target_email})
        except Exception as e:
            logger.warning("bulk-claim: failed for %s (%s): %s", c.get("name"), target_email, e)
            errors.append({"id": c["id"], "name": c.get("name", ""), "email": target_email, "error": str(e)[:200]})

    return {
        "ok": True,
        "total_clients": len(clients),
        "sent_count": len(sent),
        "skipped_no_email_count": len(skipped_no_email),
        "skipped_already_linked_count": len(skipped_already_linked),
        "errors_count": len(errors),
        "sent": sent,
        "skipped_no_email": skipped_no_email,
        "skipped_already_linked": skipped_already_linked,
        "errors": errors,
    }


@api.post("/clients/{client_id}/send-claim-email")
async def send_claim_email(client_id: str, _: dict = Depends(require_admin)):
    """Generate a one-time claim/reset token for this client and email it.
    Re-callable any time — issuing a new token invalidates older unused ones."""
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    target_email = (client.get("email") or "").strip().lower()
    if not target_email:
        raise HTTPException(
            status_code=400,
            detail="This client has no email on file. Add an email first.",
        )

    existing_user = await db.users.find_one({"client_id": client_id})
    is_reset = bool(existing_user)
    if existing_user:
        target_email = existing_user["email"]

    await db.claim_tokens.delete_many({"client_id": client_id, "used": False})

    token = secrets.token_urlsafe(32)
    expires_at = datetime.now(timezone.utc) + timedelta(days=CLAIM_TOKEN_EXPIRY_DAYS)
    await db.claim_tokens.insert_one({
        "token": token,
        "client_id": client_id,
        "email": target_email,
        "is_reset": is_reset,
        "used": False,
        "created_at": now_iso(),
        "expires_at": expires_at.isoformat(),
    })

    claim_url = _build_claim_url(token)
    try:
        await send_account_claim(
            to_email=target_email,
            client_name=client.get("name", ""),
            claim_url=claim_url,
            is_reset=is_reset,
            expires_days=CLAIM_TOKEN_EXPIRY_DAYS,
        )
    except Exception as e:
        logger.warning("send_claim_email: failed to dispatch email to %s: %s", target_email, e)

    return {
        "ok": True,
        "is_reset": is_reset,
        "sent_to": target_email,
        "expires_at": expires_at.isoformat(),
    }


@api.get("/claim/{token}", response_model=ClaimVerifyOut)
async def verify_claim_token(token: str, request: Request):
    await _enforce_rate_limit(request, "claim_verify_ip", _client_ip(request), limit=60, window_seconds=900)
    """Public — verify a claim/reset token and return who it's for."""
    rec = await db.claim_tokens.find_one({"token": token, "used": False}, {"_id": 0})
    if not rec:
        return ClaimVerifyOut(valid=False)
    try:
        exp = datetime.fromisoformat(rec["expires_at"])
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=timezone.utc)
    except Exception:
        return ClaimVerifyOut(valid=False)
    if datetime.now(timezone.utc) > exp:
        return ClaimVerifyOut(valid=False)
    # Look up display name: prefer client name (if token tied to a client),
    # fall back to user.name (used for admin/staff resets without a client_id).
    display_name = ""
    if rec.get("client_id"):
        client = await db.clients.find_one({"id": rec["client_id"]}, {"_id": 0, "name": 1})
        display_name = (client or {}).get("name", "")
    elif rec.get("user_id"):
        u = await db.users.find_one({"id": rec["user_id"]}, {"_id": 0, "name": 1})
        display_name = (u or {}).get("name", "")
    return ClaimVerifyOut(
        valid=True,
        client_name=display_name,
        email=rec.get("email", ""),
        is_reset=bool(rec.get("is_reset", False)),
        expires_at=rec.get("expires_at"),
        is_client=bool(rec.get("client_id")),
    )


@api.post("/claim/{token}", response_model=AuthOut)
async def consume_claim_token(token: str, body: ClaimSetIn, request: Request):
    await _enforce_rate_limit(request, "claim_consume_ip", _client_ip(request), limit=20, window_seconds=900)
    await _enforce_rate_limit(request, "claim_consume_token", token, limit=10, window_seconds=900)
    """Public — set the password using a valid claim/reset token and auto-log in.
    Handles three cases:
      1. Token tied to a client_id + existing portal user → update user's password.
      2. Token tied to a client_id only (no user yet)     → create the portal user.
      3. Token tied to a user_id (no client_id)           → admin/staff password reset.
    """
    rec = await db.claim_tokens.find_one({"token": token, "used": False}, {"_id": 0})
    if not rec:
        raise HTTPException(status_code=400, detail="This link is invalid or has already been used.")
    try:
        exp = datetime.fromisoformat(rec["expires_at"])
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=timezone.utc)
    except Exception:
        raise HTTPException(status_code=400, detail="This link is invalid.")
    if datetime.now(timezone.utc) > exp:
        raise HTTPException(status_code=400, detail="This link has expired. Request a new password reset.")

    client_id = rec.get("client_id")
    user_id_on_token = rec.get("user_id")
    email = (rec.get("email") or "").lower()
    new_hash = hash_password(body.password)

    # Case 3: admin/staff reset — token tied directly to a user_id, no client.
    if user_id_on_token and not client_id:
        existing_user = await db.users.find_one({"id": user_id_on_token})
        if not existing_user:
            raise HTTPException(status_code=400, detail="That account no longer exists.")
        await db.users.update_one(
            {"id": existing_user["id"]},
            {"$set": {"password_hash": new_hash, "must_change_password": False}, "$inc": {"token_version": 1}},
        )
        _invalidate_auth_user_cache(existing_user["id"])
        await db.claim_tokens.update_one({"token": token}, {"$set": {"used": True, "used_at": now_iso()}})
        new_ver = _token_version(existing_user) + 1
        access = create_access_token(existing_user["id"], existing_user["email"], existing_user.get("role", "admin"), new_ver)
        return AuthOut(
            token=access,
            user=UserOut(
                id=existing_user["id"],
                email=existing_user["email"],
                name=existing_user.get("name", ""),
                role=existing_user.get("role", "admin"),
                client_id=existing_user.get("client_id"),
            ),
        )

    # Cases 1 + 2: client claim or client reset — token tied to client_id.
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=400, detail="The client account no longer exists.")

    existing_user = await db.users.find_one({"client_id": client_id})

    if existing_user:
        await db.users.update_one(
            {"id": existing_user["id"]},
            # `needs_password` may have been set by the passwordless claim
            # login (POST /claim/{token}/login) — setting a real password
            # here through the classic form satisfies that, so clear it too.
            {"$set": {"password_hash": new_hash, "must_change_password": False, "needs_password": False}, "$inc": {"token_version": 1}},
        )
        _invalidate_auth_user_cache(existing_user["id"])
        user_id = existing_user["id"]
        user_email = existing_user["email"]
        user_name = existing_user.get("name") or client.get("name", "")
    else:
        conflict = await db.users.find_one({"email": email})
        if conflict:
            raise HTTPException(status_code=400, detail="This email is already in use. Contact your trainer.")
        user_id = str(uuid.uuid4())
        await db.users.insert_one({
            "id": user_id,
            "email": email,
            "password_hash": new_hash,
            "name": client.get("name", email),
            "role": "client",
            "client_id": client_id,
            "created_at": now_iso(),
            "token_version": 0,
            "must_change_password": False,
        })
        user_email = email
        user_name = client.get("name", email)

    await db.claim_tokens.update_one({"token": token}, {"$set": {"used": True, "used_at": now_iso()}})

    claim_user = await db.users.find_one({"id": user_id}, {"_id": 0, "token_version": 1})
    access = create_access_token(user_id, user_email, "client", _token_version(claim_user or {}))
    return AuthOut(
        token=access,
        user=UserOut(id=user_id, email=user_email, name=user_name, role="client", client_id=client_id),
    )


@api.post("/claim/{token}/login", response_model=AuthOut)
async def claim_token_login(token: str, request: Request):
    """Public — passwordless-first claim. Validates the token exactly like
    consume_claim_token (unused, unexpired) but only ever accepts tokens tied
    to a client_id. Tokens without a client_id (staff/admin resets — case 3
    of consume_claim_token) are rejected; those must keep using the password
    path. Logs the client straight in: if a portal user already exists for
    this client, log them in as-is; otherwise create one with an unusable
    random password and `needs_password=True` so the portal can prompt them
    to set a real password later, on their own schedule."""
    await _enforce_rate_limit(request, "claim_login_ip", _client_ip(request), limit=20, window_seconds=900)
    await _enforce_rate_limit(request, "claim_login_token", token, limit=10, window_seconds=900)

    rec = await db.claim_tokens.find_one({"token": token, "used": False}, {"_id": 0})
    if not rec:
        raise HTTPException(status_code=400, detail="This link is invalid or has already been used.")
    try:
        exp = datetime.fromisoformat(rec["expires_at"])
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=timezone.utc)
    except Exception:
        raise HTTPException(status_code=400, detail="This link is invalid.")
    if datetime.now(timezone.utc) > exp:
        raise HTTPException(status_code=400, detail="This link has expired. Request a new one.")

    client_id = rec.get("client_id")
    email = (rec.get("email") or "").lower()

    # Case 3 (staff/admin reset) tokens never carry a client_id — reject and
    # keep them on the password path (consume_claim_token / POST /claim/{token}).
    if not client_id:
        raise HTTPException(status_code=400, detail="This link requires setting a password.")

    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=400, detail="The client account no longer exists.")

    existing_user = await db.users.find_one({"client_id": client_id})

    if existing_user:
        user_id = existing_user["id"]
        user_email = existing_user["email"]
        user_name = existing_user.get("name") or client.get("name", "")
    else:
        conflict = await db.users.find_one({"email": email})
        if conflict:
            raise HTTPException(status_code=400, detail="This email is already in use. Contact your trainer.")
        user_id = str(uuid.uuid4())
        await db.users.insert_one({
            "id": user_id,
            "email": email,
            "password_hash": hash_password(secrets.token_urlsafe(32)),  # unusable — nobody knows this
            "name": client.get("name", email),
            "role": "client",
            "client_id": client_id,
            "created_at": now_iso(),
            "token_version": 0,
            "must_change_password": False,
            "needs_password": True,
        })
        user_email = email
        user_name = client.get("name", email)

    await db.claim_tokens.update_one({"token": token}, {"$set": {"used": True, "used_at": now_iso()}})
    _invalidate_auth_user_cache(user_id)

    claim_user = await db.users.find_one({"id": user_id}, {"_id": 0, "token_version": 1, "needs_password": 1})
    access = create_access_token(user_id, user_email, "client", _token_version(claim_user or {}))
    return AuthOut(
        token=access,
        user=UserOut(
            id=user_id, email=user_email, name=user_name, role="client", client_id=client_id,
            needs_password=bool((claim_user or {}).get("needs_password", False)),
        ),
    )


# -------- Public forgot-password (self-service for everyone) --------
class ForgotPasswordIn(BaseModel):
    email: str

@api.post("/auth/forgot-password")
async def forgot_password(body: ForgotPasswordIn, request: Request):
    """Public — anyone can request a password reset for their email.
    For security, ALWAYS returns ok regardless of whether the email exists.
    This prevents attackers from probing the DB for valid emails."""
    email = (body.email or "").strip().lower()
    if not email:
        return {"ok": True}
    ip = _client_ip(request)
    allowed_ip = await _enforce_rate_limit(request, "forgot_ip", ip, limit=20, window_seconds=3600, silent=True)
    allowed_pair = await _enforce_rate_limit(request, "forgot_email_ip", f"{ip}|{email}", limit=5, window_seconds=3600, silent=True)
    if not (allowed_ip and allowed_pair):
        return {"ok": True}

    user = await db.users.find_one({"email": email}, {"_id": 0})
    if not user:
        # Don't leak the existence/non-existence of accounts.
        return {"ok": True}

    # Mint a fresh token and invalidate any old unused ones for this user.
    await db.claim_tokens.delete_many({
        "$or": [
            {"user_id": user["id"], "used": False},
            {"client_id": user.get("client_id"), "used": False} if user.get("client_id") else {"_unused": True},
        ]
    })
    token = secrets.token_urlsafe(32)
    expires_at = datetime.now(timezone.utc) + timedelta(days=CLAIM_TOKEN_EXPIRY_DAYS)
    await db.claim_tokens.insert_one({
        "token": token,
        "user_id": user["id"],
        "client_id": user.get("client_id"),  # may be None for admins
        "email": email,
        "is_reset": True,
        "used": False,
        "created_at": now_iso(),
        "expires_at": expires_at.isoformat(),
    })

    claim_url = _build_claim_url(token)
    display_name = user.get("name") or ""
    if user.get("client_id") and not display_name:
        c = await db.clients.find_one({"id": user["client_id"]}, {"_id": 0, "name": 1})
        display_name = (c or {}).get("name", "")
    try:
        await send_account_claim(
            to_email=email,
            client_name=display_name,
            claim_url=claim_url,
            is_reset=True,
            expires_days=CLAIM_TOKEN_EXPIRY_DAYS,
        )
    except Exception as e:
        logger.warning("forgot_password: email dispatch failed for %s: %s", email, e)

    return {"ok": True}


# -------- Public "Request a Meet & Greet" --------
@api.get("/public/meet-greet-slots")
async def public_meet_greet_slots(date_str: str, request: Request):
    """Public — candidate Meet & Greet times for one date, computed from
    Settings → meet_greet (admin-configured days/hours) with anything that
    overlaps an existing appointment on the calendar marked unavailable."""
    await _enforce_rate_limit(request, "meet_greet_slots_ip", _client_ip(request), limit=120, window_seconds=900)
    try:
        the_date = date.fromisoformat(date_str)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid date.")
    settings = await get_settings()
    result = await _compute_meet_greet_slots(settings, the_date)
    return {"date": date_str, **result}


class MeetGreetRequestIn(BaseModel):
    owner_name: str = Field(min_length=1)
    email: EmailStr
    phone: str = Field(min_length=1)
    dog_name: str = Field(min_length=1)
    date: str = Field(min_length=1)  # YYYY-MM-DD — must be an open Meet & Greet slot
    time: str = Field(min_length=1)  # HH:MM


@api.post("/public/meet-greet-request")
async def request_meet_greet(body: MeetGreetRequestIn, request: Request):
    """Public — anyone can request a meet & greet straight from the landing
    page. Creates (or reuses) a `prospect` client record, books the chosen
    slot onto the calendar (re-validated server-side against the admin's
    real schedule and configured availability), mints a claim link via the
    existing claim_tokens system, and pings the admin. Rate-limited the same
    as /auth/register since it's an unauthenticated write."""
    email = body.email.lower()
    ip = _client_ip(request)
    await _enforce_rate_limit(request, "meet_greet_ip", ip, limit=10, window_seconds=3600)
    await _enforce_rate_limit(request, "meet_greet_email_ip", f"{ip}|{email}", limit=5, window_seconds=3600)

    owner_name = body.owner_name.strip()
    phone = body.phone.strip()
    dog_name = body.dog_name.strip()
    chosen_date = body.date.strip()
    chosen_time = body.time.strip()

    try:
        the_date = date.fromisoformat(chosen_date)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid date.")
    if _hhmm_to_min(chosen_time) is None:
        raise HTTPException(status_code=400, detail="Invalid time.")

    # Re-validate against the admin's real schedule + configured availability
    # right before booking — defends against the slot list going stale
    # between page-load and submit (someone else grabbed it, hours changed).
    settings = await get_settings()
    day_slots = await _compute_meet_greet_slots(settings, the_date)
    if day_slots["closed"] or not any(s["time"] == chosen_time and s["available"] for s in day_slots["slots"]):
        raise HTTPException(status_code=400, detail="That time is no longer available. Please pick another time.")
    slot_minutes = day_slots["slot_minutes"]

    request_note_parts = [f"Meet & Greet request ({now_iso()})."]
    if dog_name:
        request_note_parts.append(f"Dog: {dog_name}.")
    request_note_parts.append(f"Scheduled: {chosen_date} at {chosen_time}.")
    request_note = " ".join(request_note_parts)

    # Auto-merge (same pattern as /auth/register): reuse an admin-created
    # client record with this email instead of creating a duplicate. Unlike
    # register, there's no "email already registered" error path here — a
    # meet & greet request from someone who already has a portal account
    # just re-uses their existing client record and (below) sends them a
    # reset-capable claim link instead of a fresh one.
    existing_client = await db.clients.find_one(
        {"email": {"$regex": f"^{re.escape(email)}$", "$options": "i"}},
        {"_id": 0},
    )

    if existing_client:
        client_id = existing_client["id"]
        merged = True
        prior_notes = (existing_client.get("evaluation_notes") or "").strip()
        update_fields = {
            "evaluation_notes": f"{prior_notes}\n{request_note}".strip() if prior_notes else request_note,
        }
        # Only fill in phone if missing — don't overwrite admin's data.
        if phone and not existing_client.get("phone"):
            update_fields["phone"] = phone
        await db.clients.update_one({"id": client_id}, {"$set": update_fields})
        client_doc = {**existing_client, **update_fields}
    else:
        client_id = str(uuid.uuid4())
        client_doc = {
            "id": client_id,
            "name": owner_name,
            "address": "",
            "phone": phone,
            "email": email,
            "emerg": "",
            "credits": 0,
            "waiver": False,
            "referred_by_code": None,
            "client_status": "prospect",
            "evaluation_notes": request_note,
            "created_at": now_iso(),
        }
        await db.clients.insert_one(client_doc)
        merged = False

    # Put the slot on the calendar so it (a) shows up on the admin's schedule
    # and (b) itself blocks any later Meet & Greet request for the same time.
    # `service_type="other"` keeps this out of every existing service_type
    # switch/enum in checkout, P&L, etc.; `is_meet_greet` is how GET /events
    # and the admin recognize it as a Meet & Greet rather than a generic
    # booking. `dog_id` is intentionally blank — there's no dog record yet.
    mg_booking = {
        "id": str(uuid.uuid4()),
        "dog_id": "",
        "dog_name": dog_name,
        "client_id": client_id,
        "client_name": client_doc.get("name") or owner_name,
        "date": chosen_date,
        "time": chosen_time,
        "duration_minutes": slot_minutes,
        "service_type": "other",
        "status": "pending",
        "notes": "Meet & Greet requested via the public landing page.",
        "created_at": now_iso(),
        "is_meet_greet": True,
    }
    await db.bookings.insert_one(dict(mg_booking))

    # Claim token (existing system) — lets them set a portal password, or
    # (if a portal account already exists on this client) reset it.
    linked_user = await db.users.find_one({"client_id": client_id}, {"_id": 0, "id": 1})
    await db.claim_tokens.delete_many({"client_id": client_id, "used": False})
    token = secrets.token_urlsafe(32)
    expires_at = datetime.now(timezone.utc) + timedelta(days=CLAIM_TOKEN_EXPIRY_DAYS)
    await db.claim_tokens.insert_one({
        "token": token,
        "client_id": client_id,
        "email": email,
        "is_reset": bool(linked_user),
        "used": False,
        "created_at": now_iso(),
        "expires_at": expires_at.isoformat(),
    })
    claim_url = _build_claim_url(token)
    try:
        await send_meet_greet_request_received(
            to_email=email,
            client_name=client_doc.get("name") or owner_name,
            dog_name=dog_name,
            claim_url=claim_url,
            expires_days=CLAIM_TOKEN_EXPIRY_DAYS,
        )
    except Exception as e:
        logger.warning("meet_greet_request: email dispatch failed for %s: %s", email, e)

    # Operator alert — the request is the AUTHORITATIVE record and already
    # exists as a pending booking (it's in Action Required from this moment);
    # this email is supplemental. notify_admin_meet_greet_request is durable
    # (outbox retry on failure, notification_log stamp on success), and the
    # failure branch below logs loudly instead of the old silent
    # generic-new-client email that could vanish in quiet hours. The client's
    # request NEVER fails because the business email did.
    try:
        sent_now = await notify_admin_meet_greet_request(mg_booking, client_doc)
        if not sent_now:
            logger.warning(
                "meet_greet_request: admin alert email for booking %s not sent immediately "
                "(queued for retry or skipped — see email_outbox / last error: %s)",
                mg_booking["id"], email_service.last_send_error,
            )
    except Exception as e:
        logger.error("meet_greet_request: admin alert email dispatch crashed for booking %s: %s", mg_booking["id"], e)

    return {"ok": True}


# -------- Dogs --------
async def _resolve_client_scope(user: dict) -> Optional[str]:
    """Return client_id if user is a client (to filter), None if admin (no filter)."""
    if user.get("role") == "admin":
        return None
    return user.get("client_id")

# Dogs list contract. `_DOGS_PAGE_MAX` bounds an explicitly paged request;
# `_DOGS_SAFETY_CEILING` is a runaway guard for an unpaged read, NOT a product
# limit — if it is ever reached we log, because a list that quietly stops
# short is exactly the failure this replaced (1000 of 3193 dogs returned, and
# the roster screen reporting the page length as the roll total).
_DOGS_PAGE_MAX = 200
_DOGS_SAFETY_CEILING = 10000


async def _dogs_query(user: dict, include_deleted: bool, search: Optional[str],
                      owner_id: Optional[str]) -> Dict:
    """Canonical dog filter. One place so the list and its count can never
    disagree, and so ownership scoping is applied identically to both."""
    scope = await _resolve_client_scope(user)
    q: Dict = {}
    if scope is not None:
        # A client is pinned to their own dogs; an owner_id they supply is
        # deliberately ignored rather than honoured, so the parameter can
        # never widen their scope.
        q["owner_id"] = scope
    elif owner_id:
        q["owner_id"] = owner_id
    if not include_deleted:
        q["deleted_at"] = {"$exists": False}
    term = (search or "").strip()
    if term:
        rx = _search_re(term)
        q["$or"] = [{"name": rx}, {"breed": rx}]
    return q


@api.get("/dogs", response_model=List[DogOut])
async def list_dogs(user: dict = Depends(get_current_user), include_deleted: bool = False,
                    search: Optional[str] = None, owner_id: Optional[str] = None,
                    limit: Optional[int] = None, offset: int = 0):
    """Dogs the caller may see, by name.

    `search` and `owner_id` are matched in the DATABASE, not by the caller
    over a truncated array — `owner_id` in particular used to be accepted and
    silently dropped (FastAPI discards unknown query params), so a caller
    asking for one client's dogs was quietly handed everyone's.

    Pass `limit`/`offset` to page. Omit them for the full scoped roster.
    """
    q = await _dogs_query(user, include_deleted, search, owner_id)
    # Strip gallery photos from list payload — they balloon the response when
    # multiple dogs have 5+ images each. Detail endpoint `/dogs/{id}` returns
    # the full record (with gallery) for the edit modal.
    cap = _DOGS_SAFETY_CEILING if limit is None else max(1, min(int(limit), _DOGS_PAGE_MAX))
    cursor = db.dogs.find(q, {"_id": 0, "photos": 0}).sort("name", 1)
    if offset:
        cursor = cursor.skip(max(0, int(offset)))
    items = await cursor.to_list(cap)
    if limit is None and len(items) >= _DOGS_SAFETY_CEILING:
        logger.warning(
            "GET /dogs: safety ceiling (%s) reached — the roster is being "
            "truncated; this endpoint needs a paged caller.", _DOGS_SAFETY_CEILING)
    # Sprint 110di-27 — Boundary coercion so a single legacy/malformed row
    # (e.g. sex='male' lowercase from an old import or hand-edit) can't 500
    # the entire endpoint and lock the client out of their portal. The
    # response_model is intentionally strict; we normalise inputs here.
    return [_normalize_dog_doc(d) for d in items]


def _normalize_dog_doc(d: dict) -> dict:
    """Coerce legacy/malformed dog rows into the shape DogOut expects so the
    strict response_model never trips on a single bad apple. Idempotent."""
    sex = d.get("sex")
    if isinstance(sex, str):
        s = sex.strip().lower()
        if s in ("male", "m"): d["sex"] = "Male"
        elif s in ("female", "f"): d["sex"] = "Female"
        elif sex not in ("Male", "Female"): d["sex"] = "Male"
    else:
        d["sex"] = "Male"
    fixed = d.get("fixed")
    if isinstance(fixed, bool):
        d["fixed"] = "Yes" if fixed else "No"
    elif isinstance(fixed, str):
        f = fixed.strip().lower()
        if f in ("yes", "true", "1", "spayed", "neutered"): d["fixed"] = "Yes"
        elif f in ("no", "false", "0", "intact"): d["fixed"] = "No"
        elif fixed not in ("Yes", "No"): d["fixed"] = "No"
    else:
        d["fixed"] = "No"
    # created_at is required by DogOut; legacy rows from very early seeds
    # might be missing it.
    if not d.get("created_at"):
        d["created_at"] = now_iso()
    return d


@api.get("/dogs/summary")
async def dogs_summary(user: dict = Depends(get_current_user), include_deleted: bool = False,
                       search: Optional[str] = None, owner_id: Optional[str] = None):
    """How many dogs the caller can actually see, for the same filters.

    Counted in the database rather than measured from a returned page, so a
    roster screen can state a real total instead of restating its page size.
    """
    q = await _dogs_query(user, include_deleted, search, owner_id)
    total = int(await db.dogs.count_documents(q))
    return {"total": total, "page_max": _DOGS_PAGE_MAX}


@api.get("/dogs/{dog_id}", response_model=DogOut)
async def get_dog(dog_id: str, user: dict = Depends(get_current_user)):
    """Full dog record including gallery photos. Use this when the user
    opens the edit modal so the list endpoint can stay lightweight."""
    scope = await _resolve_client_scope(user)
    q = {"id": dog_id} if scope is None else {"id": dog_id, "owner_id": scope, "deleted_at": {"$exists": False}}
    dog = await db.dogs.find_one(q, {"_id": 0})
    if not dog:
        raise HTTPException(status_code=404, detail="Dog not found")
    return _normalize_dog_doc(dog)

@api.post("/dogs", response_model=DogOut)
async def create_dog(body: DogIn, _: dict = Depends(require_admin_and_permission("dogs_edit"))):
    client = await db.clients.find_one({"id": body.owner_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Owner not found")
    doc = body.model_dump()
    doc.update({"id": str(uuid.uuid4()), "training_logs": [], "created_at": now_iso()})
    await db.dogs.insert_one(doc)
    doc.pop("_id", None)
    return doc

@api.put("/dogs/{dog_id}", response_model=DogOut)
async def update_dog(dog_id: str, body: DogIn, _: dict = Depends(require_admin_and_permission("dogs_edit"))):
    existing = await db.dogs.find_one({"id": dog_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Dog not found")
    update = body.model_dump()
    await db.dogs.update_one({"id": dog_id}, {"$set": update})
    existing.update(update)
    return existing

@api.delete("/dogs/{dog_id}")
async def delete_dog(dog_id: str, user: dict = Depends(require_admin)):
    perms = _perms_for(user)
    if not perms.get("delete_records"):
        raise HTTPException(status_code=403, detail="Missing permission: delete_records")
    existing = await db.dogs.find_one({"id": dog_id}, {"_id": 0, "id": 1})
    if not existing:
        raise HTTPException(status_code=404, detail="Dog not found")
    await db.dogs.update_one(
        {"id": dog_id},
        {"$set": {"deleted_at": now_iso(), "deleted_by": user.get("id"), "active": False}},
    )
    return {"ok": True, "soft_deleted": True}

@api.post("/dogs/{dog_id}/training-logs", response_model=DogOut)
async def add_training_log(dog_id: str, body: TrainingLogIn, _: dict = Depends(require_admin)):
    existing = await db.dogs.find_one({"id": dog_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Dog not found")
    log = TrainingLog(date=body.date, note=body.note, tags=body.tags).model_dump()
    await db.dogs.update_one({"id": dog_id}, {"$push": {"training_logs": log}})
    existing["training_logs"] = existing.get("training_logs", []) + [log]
    # If a `sessions` completion rule is configured on the active enrollment,
    # this new log might tip it over the threshold — check now.
    active_id = existing.get("active_program_id")
    if active_id:
        enrollment = await db.dog_programs.find_one({"id": active_id}, {"_id": 0})
        if enrollment and enrollment.get("status") == "active":
            rule = enrollment.get("completion_rule") or {}
            if rule.get("type") == "sessions":
                started = enrollment.get("started_at", "")[:10]
                logs_since = [
                    lg for lg in existing["training_logs"]
                    if (lg.get("date") or "") >= started
                ]
                await _auto_complete_if_satisfied(enrollment, sessions_logged=len(logs_since))
    return existing


# -------- Bookings --------
def _dates_in_range(start: str, end: Optional[str]) -> List[str]:
    """Inclusive presence dates.

    This is for operational views: kennel board, run sheet, capacity, closed-day
    checks. It intentionally includes both drop-off and pickup dates. Do NOT use
    this helper to bill boarding nights.
    """
    s = datetime.fromisoformat(start).date()
    e = datetime.fromisoformat(end).date() if end else s
    if e < s:
        e = s
    out = []
    cur = s
    while cur <= e:
        out.append(cur.isoformat())
        cur += timedelta(days=1)
    return out


def _presence_dates(start: str, end: Optional[str]) -> List[str]:
    """Explicit alias for inclusive dates when the dog is physically present."""
    return _dates_in_range(start, end)


def _billable_boarding_nights(start: str, end: Optional[str], *, legacy_minimum: int = 0) -> int:
    """Exclusive pickup-date math for overnight boarding nights only.

    July 1 → July 2 = 1 night. July 1 → July 4 = 3 nights. Pickup-day
    boarding is deliberately handled by `_billable_boarding_units` so every
    quote, credit calculation, and checkout uses the same clock-time rule.
    """
    try:
        s = datetime.fromisoformat(str(start)[:10]).date()
        e = datetime.fromisoformat(str(end or start)[:10]).date()
    except Exception:
        return legacy_minimum
    return max(legacy_minimum, (e - s).days)


DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF = "17:00"


def _clock_minutes(value: Optional[str]) -> Optional[int]:
    """Parse HH:MM (or an ISO-ish time prefix) into minutes after midnight."""
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        hh, mm = raw[:5].split(":", 1)
        hours = int(hh)
        minutes = int(mm)
        if not (0 <= hours <= 23 and 0 <= minutes <= 59):
            return None
        return hours * 60 + minutes
    except Exception:
        return None


def _boarding_full_day_cutoff_from_rules(rules: Optional[dict]) -> str:
    """Return the admin-configured boarding pickup cutoff as valid HH:MM."""
    raw = str((rules or {}).get("boarding_full_day_pickup_cutoff") or "").strip()
    return raw[:5] if _clock_minutes(raw) is not None else DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF


def _boarding_pickup_day_units(
    pickup_time: Optional[str],
    cutoff_time: Optional[str] = DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF,
    grace_minutes: int = 0,
) -> float:
    """1.0 when the boarding pickup is late enough to bill, else 0.0.

    The cutoff is the boarding checkout time. Pickup at or before it (plus the
    admin-configured grace window) is free; pickup after it means the dog
    spent the day in the daycare group, so the pickup day bills per the
    configured charge mode (see _boarding_late_pickup_daycare_fee). Missing
    times keep legacy overnight-only pricing rather than inventing a charge
    on old records.
    """
    pickup_minutes = _clock_minutes(pickup_time)
    cutoff_minutes = _clock_minutes(cutoff_time)
    if cutoff_minutes is None:
        cutoff_minutes = _clock_minutes(DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF) or (17 * 60)
    if pickup_minutes is None:
        return 0.0
    try:
        grace = max(0, int(grace_minutes or 0))
    except Exception:
        grace = 0
    return 0.0 if pickup_minutes <= cutoff_minutes + grace else 1.0


def _billable_boarding_units(
    start: str,
    end: Optional[str],
    pickup_time: Optional[str],
    *,
    legacy_minimum: int = 0,
    cutoff_time: Optional[str] = DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF,
) -> float:
    """Boarding bills overnight NIGHTS only, at the boarding rate.

    The old rule added pickup-day care as extra boarding units (half day
    before the cutoff, full day at/after). Industry-standard model now: a
    pickup after the checkout time bills a separate full DAYCARE day instead
    — see _boarding_late_pickup_daycare_fee. The pickup args are kept so
    stored pricing_snapshot call sites don't need signature churn.
    """
    return float(_billable_boarding_nights(start, end, legacy_minimum=legacy_minimum))


async def _boarding_late_pickup_daycare_fee(
    client_id: Optional[str],
    pickup_time: Optional[str],
    cutoff_time: Optional[str] = DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF,
) -> Dict[str, Any]:
    """Facade; canonical late-pickup daycare fee lives in domains.pricing.

    Pickup after the boarding checkout time bills one full daycare day at the
    default daycare service price (honoring the client's grandfathered rate).
    Callers apply the additional-dog 50% row factor themselves, exactly like
    the boarding base. `amount` is 0.0 when the pickup is on time, when no
    pickup time is stored, or when no daycare service is configured.
    """
    return await pricing_domain_services.late_pickup_daycare_fee(
        client_id=client_id, pickup_time=pickup_time, cutoff_time=cutoff_time,
    )


async def _boarding_auto_base(booking: dict, settings: dict) -> float:
    """This row's auto-computed boarding base: saved unit rate × nights, plus
    the late-pickup daycare fee, times the group-row discount factor. Shared
    by checkout repair, modifier previews, and the manual-override audit
    stamp so they can never disagree. 0.0 for non-boarding/unusable rows."""
    if booking.get("service_type") != "boarding" or not booking.get("end_date"):
        return 0.0
    ps = booking.get("pricing_snapshot") or {}
    unit_rate = float(ps.get("unit_price") or booking.get("unit_price") or 0)
    if unit_rate <= 0:
        return 0.0
    cutoff_time = ps.get("pickup_cutoff_time") or _boarding_full_day_cutoff_from_rules(settings.get("booking_rules") or {})
    pickup_clock = booking.get("pickup_time") or cutoff_time
    units = _billable_boarding_units(
        booking.get("date"), booking.get("end_date"), pickup_clock,
        legacy_minimum=1, cutoff_time=cutoff_time,
    )
    fee = await _boarding_late_pickup_daycare_fee(booking.get("client_id"), pickup_clock, cutoff_time)
    return round((unit_rate * units + float(fee.get("amount") or 0)) * _group_row_price_factor(booking), 2)


def _money_modifier_breakdown(
    booking: Dict[str, Any],
    base_amount: float,
    settings: Dict[str, Any],
    checkout_ts: Optional[str] = None,
) -> Dict[str, Any]:
    """Facade; canonical seasonal/late-pickup modifier math lives in domains.pricing."""
    return pricing_domain_services.money_modifier_breakdown(booking, base_amount, settings, checkout_ts)


def _credit_units_required(service_type: str, start: str, end: Optional[str], dog_count: int = 1, pickup_time: Optional[str] = None, pickup_cutoff_time: Optional[str] = DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF) -> float:
    """Facade; canonical credit-unit math lives in domains.pricing."""
    return pricing_domain_services.credit_units_required(
        service_type, start, end, dog_count=dog_count,
        pickup_time=pickup_time, pickup_cutoff_time=pickup_cutoff_time,
    )


def _credit_unit_value_from_quote(quote: Dict[str, Any]) -> float:
    """Dollar value of one credit unit for estimate/partial-credit math."""
    return round(float(quote.get("unit_price") or 0), 2)


def _service_base_credit_units_for_booking(booking: dict) -> float:
    """Facade; canonical per-booking credit-unit rule lives in domains.pricing."""
    return pricing_domain_services.service_base_credit_units_for_booking(booking)

async def _booking_days_count(target_date: str) -> int:
    bookings = await db.bookings.find(
        {"status": {"$in": ["approved", "pending"]}}, {"_id": 0}
    ).to_list(2000)
    count = 0
    for b in bookings:
        days = _dates_in_range(b["date"], b.get("end_date"))
        if target_date in days:
            count += 1
    return count

async def list_bookings(
    user: dict = Depends(get_current_user),
    status_filter: Optional[str] = None,
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    include_all: bool = False,
    dog_id: Optional[str] = None,
    client_id: Optional[str] = None,
):
    """Lists bookings. By default returns a tight rolling window (90 days
    back to 90 days forward) so admin screens stay snappy as historical
    bookings pile up. Pass `include_all=true` for the full table (CSV
    exports, reconciliation) or `start_date` / `end_date` for a custom range.

    `dog_id` narrows to a single dog's bookings. Added after an incident
    where a script assumed this filter already existed, got the unfiltered
    default window instead (FastAPI silently drops unrecognized query
    params), and bulk-cancelled ~1150 unrelated bookings. Now a real,
    server-validated filter instead of a silent no-op.

    `client_id` narrows to a single client's bookings (used by the admin
    Client Hub's Bookings tab). Ignored for a client-role caller, who is
    always scoped to their own client_id regardless."""
    q: Dict = {}
    if status_filter:
        q["status"] = status_filter
    if dog_id:
        q["dog_id"] = dog_id
    # Admins + employees see all bookings (employees need this to run the
    # facility). Clients see only their own.
    if user.get("role") == "client":
        q["client_id"] = user.get("client_id")
    elif client_id:
        q["client_id"] = client_id
    if include_all or start_date or end_date:
        # An explicitly-bounded read: the caller chose the range, so one
        # ordered query is right. include_all also pulls the archive.
        if not include_all:
            if not start_date:
                start_date = (business_today() - timedelta(days=90)).isoformat()
            if not end_date:
                end_date = (business_today() + timedelta(days=90)).isoformat()
            q["date"] = {"$gte": start_date, "$lte": end_date}
        items = await _booking_rows_anywhere(
            q, {"_id": 0}, include_archive=include_all,
            limit=_BOOKINGS_RANGE_MAX, sort_field="date")
        if len(items) >= _BOOKINGS_RANGE_MAX:
            logger.warning(
                "GET /bookings: explicit range hit the %s-row ceiling; "
                "caller should narrow the range or page.", _BOOKINGS_RANGE_MAX)
    else:
        # Default rolling window. Past and future are budgeted SEPARATELY.
        #
        # A single shared budget lets one temporal category starve another:
        # with 7954 rows in the window a flat 3000-row cap was consumed by
        # older bookings, so all 277 upcoming ones were dropped and the
        # admin feed truthfully rendered what it was sent — "0 upcoming".
        # Giving each category its own budget makes that impossible: history
        # volume can no longer displace current/future work, whatever the
        # ratio between them.
        today_iso = business_today().isoformat()
        window_start = (business_today() - timedelta(days=90)).isoformat()
        window_end = (business_today() + timedelta(days=90)).isoformat()
        upcoming = await _booking_rows_anywhere(
            {**q, "date": {"$gte": today_iso, "$lte": window_end}}, {"_id": 0},
            include_archive=False, limit=_BOOKINGS_UPCOMING_MAX, sort_field="date")
        # Past reads newest-first so a truncated history keeps the MOST
        # RECENT days rather than the oldest ones.
        past = await _booking_rows_anywhere(
            {**q, "date": {"$gte": window_start, "$lt": today_iso}}, {"_id": 0},
            include_archive=False, limit=_BOOKINGS_PAST_MAX, sort_field="date",
            sort_desc=True)
        if len(upcoming) >= _BOOKINGS_UPCOMING_MAX:
            logger.warning(
                "GET /bookings: upcoming budget (%s) exhausted — clients are "
                "seeing a partial future window.", _BOOKINGS_UPCOMING_MAX)
        items = sorted(past + upcoming, key=lambda r: str(r.get("date") or ""))
    # Sprint 110di-25 — Defensive coercion at the API boundary so legacy /
    # mid-migration rows don't 500 the entire list endpoint. The response
    # model is strict (Literal status enum, required dog_name/client_name),
    # but the DB has older test/seed rows with `status: "checked_out"` and
    # missing display names. Map those to safe defaults rather than reject.
    _STATUS_REMAP = {
        "checked_in": "approved",
        "checked_out": "completed",
        # Legacy one-l spelling still exists in old rows (the archive job's
        # ARCHIVE_TERMINAL_STATUSES and the frontend's FINISHED set both
        # acknowledge it), and no_show predates the current status enum.
        "canceled": "cancelled",
        "no_show": "cancelled",
    }
    out: List[BookingOut] = []
    for it in items:
        if it.get("status") in _STATUS_REMAP:
            it["status"] = _STATUS_REMAP[it["status"]]
        if not it.get("dog_name"):
            it["dog_name"] = ""
        if not it.get("client_name"):
            it["client_name"] = ""
        if not it.get("created_at"):
            it["created_at"] = ""
        # Per-row salvage: a single malformed row must degrade to a logged
        # skip, never a 500 for the whole list (the page renders nothing at
        # all when this endpoint fails).
        try:
            out.append(BookingOut.model_validate(it))
        except ValidationError as ve:
            logger.warning(
                "GET /bookings: skipping malformed booking row id=%s (%s)",
                it.get("id"), str(ve)[:300],
            )
    return out

def _service_cost(rules: dict, service_type: str, days: int) -> int:
    # Legacy credit-cost field: ONLY daycare credits. Do not use for dollars.
    if service_type == "daycare":
        return int(rules.get("daycare_cost", 1)) * max(days, 1)
    return 0


async def _quote_base_service_price(
    *,
    client_id: Optional[str],
    service_type: str,
    start_date: str,
    end_date: Optional[str] = None,
    pickup_time: Optional[str] = None,
    pickup_cutoff_time: Optional[str] = DEFAULT_BOARDING_FULL_DAY_PICKUP_CUTOFF,
    service_id: Optional[str] = None,
    legacy_boarding_minimum: int = 0,
    grooming_type: Optional[str] = None,
) -> Dict[str, Any]:
    """Compatibility facade; canonical quote pricing lives in domains.pricing."""
    return await pricing_domain_services.quote_base_service_price(
        client_id=client_id, service_type=service_type, start_date=start_date,
        end_date=end_date, pickup_time=pickup_time, pickup_cutoff_time=pickup_cutoff_time,
        service_id=service_id, legacy_boarding_minimum=legacy_boarding_minimum,
        grooming_type=grooming_type,
    )


class PricingQuoteIn(BaseModel):
    service_type: Literal["daycare", "boarding", "training", "grooming", "photography", "other"]
    date: str
    end_date: Optional[str] = None
    dropoff_time: Optional[str] = None
    pickup_time: Optional[str] = None
    dog_id: Optional[str] = None
    client_id: Optional[str] = None
    service_id: Optional[str] = None
    grooming_type: Optional[str] = None
    addon_service_ids: List[str] = []
    # Read-only estimate helper for grouped bookings. First dog bills at the
    # standard rate; additional dogs can receive the configured sibling discount.
    dog_count: int = 1


async def pricing_quote(body: PricingQuoteIn, user: dict = Depends(get_current_user)):
    """Backend source-of-truth quote for booking screens.

    This endpoint is intentionally read-only. It does not create bookings, spend
    credits, or mutate client/dog records. Frontend estimate widgets should call
    this instead of re-implementing boarding-night math in React.
    """
    client_id = body.client_id
    if body.dog_id:
        dog = await db.dogs.find_one({"id": body.dog_id}, {"_id": 0, "owner_id": 1})
        if not dog:
            raise HTTPException(status_code=404, detail="Dog not found")
        if user.get("role") == "client" and dog.get("owner_id") != user.get("client_id"):
            raise HTTPException(status_code=403, detail="Not your dog")
        client_id = dog.get("owner_id") or client_id
    if user.get("role") == "client":
        client_id = user.get("client_id")

    if body.service_type == "boarding" and body.end_date:
        nights = _billable_boarding_nights(body.date, body.end_date, legacy_minimum=0)
        if nights <= 0:
            raise HTTPException(status_code=400, detail="Boarding pickup date must be after drop-off date.")

    settings = await get_settings()
    pickup_cutoff_time = _boarding_full_day_cutoff_from_rules(settings.get("booking_rules") or {})
    effective_pickup_time = (body.pickup_time or pickup_cutoff_time) if body.service_type == "boarding" else body.pickup_time
    quote = await _quote_base_service_price(
        client_id=client_id,
        service_type=body.service_type,
        start_date=body.date,
        end_date=body.end_date,
        pickup_time=effective_pickup_time,
        pickup_cutoff_time=pickup_cutoff_time,
        service_id=body.service_id,
        grooming_type=body.grooming_type if body.service_type == "grooming" else None,
    )
    add_ons: List[Dict[str, Any]] = []
    add_on_total = 0.0
    if body.addon_service_ids:
        add_ons = await resolve_addon_snapshots(
            client_id, body.addon_service_ids, body.service_type,
        )
        for a in add_ons:
            add_on_total += float(a.get("price") or 0) * int(a.get("qty") or 1)

    units = float(quote.get("units") or 0)
    dog_count = max(1, min(12, int(body.dog_count or 1)))
    additional_dogs = max(0, dog_count - 1)

    first_dog_base = float(quote.get("estimated_price") or 0)
    additional_dog_unit_price = float(quote.get("additional_dog_unit_price") or quote.get("unit_price") or 0)
    # Late-pickup daycare fee (boarding pickup after the checkout time) is part
    # of each dog's base, so additional dogs get the sibling discount on it too.
    late_pickup_fee = float(quote.get("late_pickup_daycare_fee") or 0)
    raw_additional_dog_base = round(additional_dogs * (additional_dog_unit_price * units + late_pickup_fee), 2)

    md_cfg = _multi_dog_discount_config_for(settings, body.service_type)
    multi_dog_discount_amount = _discount_amount_for_extra_dogs(raw_additional_dog_base, md_cfg, additional_dogs)
    discounted_additional_dog_base = max(0.0, round(raw_additional_dog_base - multi_dog_discount_amount, 2))

    # Base estimate means service/base price for all dogs after sibling
    # discount. Add-ons remain separate and full price.
    subtotal = round(first_dog_base + discounted_additional_dog_base, 2)
    total = round(subtotal + add_on_total, 2)
    credit_units = _credit_units_required(
        body.service_type, body.date, body.end_date,
        dog_count=dog_count, pickup_time=effective_pickup_time,
        pickup_cutoff_time=pickup_cutoff_time,
    )
    credit_pool_field = _credit_balance_field(body.service_type)
    credit_unit_value = _credit_unit_value_from_quote(quote)
    credits_available = 0.0
    if client_id and credit_pool_field:
        try:
            cdoc = await db.clients.find_one({"id": client_id}, {"_id": 0, credit_pool_field: 1})
            credits_available = float((cdoc or {}).get(credit_pool_field) or 0)
        except Exception:
            credits_available = 0.0
    credits_applied = min(credits_available, float(credit_units or 0)) if credit_pool_field else 0.0
    credits_remaining_after = round(max(0.0, credits_available - credits_applied), 2)
    credit_shortfall = round(max(0.0, float(credit_units or 0) - credits_applied), 2)
    base_cash_due_after_credits = round(max(0.0, subtotal - (credits_applied * credit_unit_value)), 2) if credit_pool_field else subtotal
    cash_due = round(base_cash_due_after_credits + add_on_total, 2)
    # Credits cover boarding nights only — a late-pickup daycare fee stays cash,
    # so its presence means the booking is never "fully covered by credits".
    covered_by_credits = (
        bool(credit_pool_field) and float(credit_units or 0) > 0
        and credit_shortfall <= 0.0001 and add_on_total <= 0.0001
        and late_pickup_fee <= 0.0001
    )

    multi_dog_discount = None
    if additional_dogs > 0 and multi_dog_discount_amount > 0 and md_cfg:
        multi_dog_discount = {
            "amount": round(multi_dog_discount_amount, 2),
            "mode": md_cfg.get("mode") or "percent",
            "value": float(md_cfg.get("value") or 0),
            "label": md_cfg.get("label") or "Additional dog discount",
            "additional_dogs": additional_dogs,
            "discount_base_price": round(raw_additional_dog_base, 2),
        }

    return {
        "service_type": body.service_type,
        "service_id": quote.get("service_id"),
        "service_name": quote.get("service_name"),
        "date": body.date,
        "end_date": body.end_date,
        "dropoff_time": body.dropoff_time,
        "pickup_time": effective_pickup_time,
        "pickup_day_units": (1.0 if quote.get("late_pickup_daycare_applies") else 0.0) if body.service_type == "boarding" else 0.0,
        "pickup_cutoff_time": pickup_cutoff_time if body.service_type == "boarding" else None,
        "late_pickup_daycare_fee": round(late_pickup_fee, 2),
        "late_pickup_daycare_applies": bool(quote.get("late_pickup_daycare_applies")),
        "late_pickup_daycare_service_name": quote.get("late_pickup_daycare_service_name"),
        "presence_dates": _presence_dates(body.date, body.end_date),
        "billable_units": units,
        "unit_label": quote.get("unit_label"),
        "unit_price": quote.get("unit_price"),
        "list_unit_price": quote.get("list_unit_price"),
        "preferred_rate_applied": quote.get("preferred_rate_applied", False),
        "price_override_id": quote.get("price_override_id"),
        "price_source": quote.get("price_source"),
        "price_label": quote.get("price_label"),
        "additional_dog_unit_price": round(additional_dog_unit_price, 2),
        "dog_count": dog_count,
        "additional_dogs": additional_dogs,
        "first_dog_base_price": round(first_dog_base, 2),
        "additional_dog_base_price": round(raw_additional_dog_base, 2),
        "multi_dog_discount": multi_dog_discount,
        "multi_dog_discount_amount": round(multi_dog_discount_amount, 2),
        "base_estimated_price": round(subtotal, 2),
        "add_ons": add_ons,
        "add_on_total": round(add_on_total, 2),
        "estimated_price": total,
        "credit_units_required": round(float(credit_units or 0), 2),
        "credit_pool_field": credit_pool_field,
        "credit_unit_value": credit_unit_value,
        "credits_available": round(credits_available, 2),
        "credits_applied": round(credits_applied, 2),
        "credits_remaining_after": credits_remaining_after,
        "credit_shortfall": credit_shortfall,
        "cash_due": cash_due,
        "covered_by_credits": covered_by_credits,
        "payment_display_mode": "credits" if covered_by_credits else ("partial_credits" if credits_applied > 0 else "cash"),
    }


def _pending_vaccine_cert_for(dog: dict, vaccine: str) -> Optional[dict]:
    cert = (dog.get("vaccine_certs") or {}).get(vaccine)
    if not isinstance(cert, dict):
        return None
    if cert.get("reviewed_at") or cert.get("uploaded_by_admin"):
        return None
    # Only block records created by the safer upload flow. Legacy rows may already
    # have been trusted in production, so do not retroactively strand customers.
    if cert.get("status") in ("pending_review", "pending") or cert.get("pending_expires_on"):
        return cert
    return None


def _validate_base64_uploads(photos: List[str], *, max_items: int = 4, max_chars_each: int = 3_000_000) -> None:
    if len(photos) > max_items:
        raise HTTPException(status_code=400, detail=f"Please upload no more than {max_items} photos.")
    for p in photos:
        if not isinstance(p, str):
            raise HTTPException(status_code=400, detail="Invalid uploaded file.")
        if len(p) > max_chars_each:
            # Sprint 110ff — this used to always say "image", which was
            # confusing for PDF vaccine-cert uploads (the wizard explicitly
            # invites those) since a PDF can't be "compressed" the way a
            # photo can from the portal.
            if p.startswith("data:application/pdf"):
                raise HTTPException(status_code=400, detail="Uploaded PDF is too large. Please upload a smaller PDF, or a photo of the document instead.")
            raise HTTPException(status_code=400, detail="Uploaded photo is too large. Please use a smaller/compressed image.")


def _required_vaccines_for_service(settings: dict, service_type: Optional[str]) -> List[str]:
    """Resolve the vaccine requirement the same way Settings describes it.

    A non-empty per-service list overrides the global required_vaccines list;
    an empty/missing per-service list deliberately falls back to the global
    requirement. This keeps booking-time and check-in-time enforcement aligned
    with Day-to-Day Controls instead of presenting a decorative setting.
    """
    global_required = [str(v).strip().lower() for v in (settings.get("required_vaccines") or ["rabies"]) if str(v).strip()]
    per_service = (((settings.get("day_to_day") or {}).get("compliance") or {}).get("vaccines_per_service") or {})
    scoped = per_service.get((service_type or "").strip().lower()) if isinstance(per_service, dict) else None
    if isinstance(scoped, list):
        cleaned = [str(v).strip().lower() for v in scoped if str(v).strip()]
        if cleaned:
            return cleaned
    return global_required


async def _validate_dog_vaccines(
    dog: dict,
    required: List[str],
    *,
    block_on_expiry_day: bool = True,
    document_required: bool = False,
) -> None:
    """Validate the canonical approved vaccine record.

    `block_on_expiry_day` and `document_required` are live Day-to-Day
    compliance controls. Legacy callers keep the historical strict defaults.
    """
    today = business_today().isoformat()
    vaccines = dog.get("vaccines") or {}
    certs = dog.get("vaccine_certs") or {}
    for v in required:
        if _pending_vaccine_cert_for(dog, v):
            raise HTTPException(status_code=400, detail=f"{v.title()} vaccine is pending admin review")
        d = str(vaccines.get(v, "") or "")[:10]
        expired = bool(d and (d <= today if block_on_expiry_day else d < today))
        if not d or expired:
            raise HTTPException(status_code=400, detail=f"{v.title()} vaccine missing or expired")
        if document_required:
            cert = certs.get(v) or {}
            if not isinstance(cert, dict) or cert.get("status") != "approved":
                raise HTTPException(status_code=400, detail=f"{v.title()} vaccine document must be approved before booking")


def _dog_vaccine_checkin_warning(dog: dict, required: List[str]) -> Optional[str]:
    """Non-fatal check-in-time vaccine check — a booking can be days or
    weeks old, so a vaccine valid when the booking was made may have since
    expired. Returns a human-readable warning if so, else None. Unlike
    _validate_dog_vaccines (booking time), this never blocks by itself —
    the caller decides whether to require staff acknowledgement."""
    today = business_today().isoformat()
    vaccines = dog.get("vaccines") or {}
    for v in required:
        if _pending_vaccine_cert_for(dog, v):
            return f"{v.title()} vaccine is pending admin review."
        d = vaccines.get(v, "")
        if not d:
            return f"{v.title()} vaccine is missing from this dog's record."
        if d < today:
            return f"{v.title()} vaccine expired {d}."
    return None


def _parse_hhmm_strict(value: Optional[str], *, field_label: str) -> Optional[time]:
    """Parse an HH:MM wall-clock value without silently accepting junk."""
    raw = (value or "").strip()
    if not raw:
        return None
    try:
        return datetime.strptime(raw, "%H:%M").time()
    except Exception:
        raise HTTPException(status_code=400, detail=f"Invalid {field_label}. Please use a valid time.")


def _service_hours_for_date(settings: dict, service_type: str, target_date: date) -> dict:
    """Return the effective service-hours row for one local business date.

    Boarding is intentionally 24/7. Other services inherit the business-hours
    row when their own service-hours grid is missing.
    """
    if service_type == "boarding":
        return {"mode": "24_7", "closed": False}
    day_key = DEFAULT_DAYS[target_date.weekday()]
    service_cfg = (settings.get("service_hours") or {}).get(service_type) or {}
    if isinstance(service_cfg, dict) and service_cfg.get("mode") == "24_7":
        return {"mode": "24_7", "closed": False}
    row = service_cfg.get(day_key) if isinstance(service_cfg, dict) else None
    if not isinstance(row, dict):
        row = ((settings.get("business_hours") or {}).get(day_key) or {})
    return dict(row or {})


def _booking_start_local(body: BookingIn, settings: dict) -> datetime:
    """Resolve the actual booking start in America/New_York.

    Time-slotted services use `time`; daycare/boarding use `dropoff_time`.
    When an untimed service has no explicit drop-off, its configured opening
    time is used instead of midnight so minimum-notice rules are fair.
    """
    try:
        target_date = date.fromisoformat(str(body.date)[:10])
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid booking date.")

    effective_service_type = training_domain_services.effective_booking_service_type(body)
    hours_row = _service_hours_for_date(settings, effective_service_type, target_date)
    if hours_row.get("closed"):
        raise HTTPException(status_code=400, detail=f"{effective_service_type.title()} is closed on that day.")

    if effective_service_type in TIME_SLOTTED_SERVICES:
        explicit = _parse_hhmm_strict(body.time, field_label="appointment time")
        if explicit is None:
            raise HTTPException(status_code=400, detail=f"Please select a time for this {effective_service_type} service.")
    else:
        explicit = _parse_hhmm_strict(body.dropoff_time, field_label="drop-off time")

    open_time = None
    close_time = None
    if hours_row.get("mode") != "24_7":
        open_time = _parse_hhmm_strict(hours_row.get("open") or "07:00", field_label="service opening time")
        close_time = _parse_hhmm_strict(hours_row.get("close") or "19:00", field_label="service closing time")

    if explicit is None and open_time is None:
        # Boarding is bookable 24/7, but an omitted drop-off time should not
        # collapse notice math back to midnight. Use the facility's configured
        # opening time as the fair default for an untimed request.
        day_key = DEFAULT_DAYS[target_date.weekday()]
        business_row = ((settings.get("business_hours") or {}).get(day_key) or {})
        open_time = _parse_hhmm_strict(business_row.get("open") or "07:00", field_label="business opening time")
    chosen = explicit or open_time or datetime.min.time()
    local_dt = datetime.combine(target_date, chosen, tzinfo=BUSINESS_TZ)

    # Direct/old clients must not bypass service hours by posting a time outside
    # the same window used by the slot picker. Boarding remains 24/7.
    if explicit is not None and open_time is not None and close_time is not None:
        if explicit < open_time or explicit > close_time:
            raise HTTPException(
                status_code=400,
                detail=f"Selected time is outside {effective_service_type} hours ({open_time.strftime('%-I:%M %p')}–{close_time.strftime('%-I:%M %p')}).",
            )
    return local_dt


async def _resolve_base_service_for_booking(body: BookingIn, user: dict) -> Optional[dict]:
    """Compatibility facade; exact service selection lives in domains.bookings."""
    return await bookings_domain_services.resolve_base_service_for_booking(body, user)



CAPACITY_LOCK_TTL_SECONDS = 180


def _capacity_waitlist_allowed(settings: dict) -> bool:
    fv = settings.get("feature_visibility") or {}
    bfc = settings.get("booking_flow_controls") or {}
    return fv.get("waitlist", True) is not False and bfc.get("waitlist_on_capacity", True) is not False


def _capacity_error(settings: dict, body: BookingIn, message: str, *, resource: str, target_date: Optional[str] = None) -> HTTPException:
    copy = ((settings.get("booking_flow_controls") or {}).get("capacity_reached_copy") or message)
    return HTTPException(
        status_code=409,
        detail={
            "code": "capacity_full",
            "message": message,
            "display_message": copy,
            "resource": resource,
            "date": target_date or body.date,
            "service_type": body.service_type,
            "service_id": body.service_id,
            "waitlist_allowed": _capacity_waitlist_allowed(settings),
        },
    )


def _capacity_resource_keys(body: BookingIn) -> List[str]:
    keys: List[str] = []
    if body.service_type == "daycare":
        keys.append(f"daycare:{body.date}")
    elif body.service_type == "boarding":
        for d in _presence_dates(body.date, body.end_date):
            keys.append(f"boarding:{d}")
            if (body.kennel or "").strip():
                keys.append(f"kennel:{(body.kennel or '').strip().lower()}:{d}")
    elif body.service_type in ("training", "grooming", "photography"):
        keys.append(f"timepool:{body.date}")
    return sorted(set(keys))


async def _release_capacity_locks(owner: str, keys: Optional[List[str]] = None) -> None:
    q: Dict[str, Any] = {"owner": owner}
    if keys:
        q["_id"] = {"$in": keys}
    await db.capacity_locks.delete_many(q)


async def _acquire_capacity_locks(keys: List[str], *, owner: Optional[str] = None) -> str:
    """Acquire sorted Mongo-backed leases shared by every API worker.

    Capacity is still calculated from bookings; these short leases only make
    the final count-and-insert sequence serial so two simultaneous requests
    cannot both see the last opening.
    """
    if not keys:
        return owner or str(uuid.uuid4())
    owner = owner or str(uuid.uuid4())
    for attempt in range(10):
        acquired: List[str] = []
        failed = False
        for key in sorted(set(keys)):
            now = datetime.now(timezone.utc)
            expires = now + timedelta(seconds=CAPACITY_LOCK_TTL_SECONDS)
            query = {
                "_id": key,
                "$or": [
                    {"owner": owner},
                    {"expires_at": {"$exists": False}},
                    {"expires_at": {"$lte": now}},
                ],
            }
            try:
                row = await db.capacity_locks.find_one_and_update(
                    query,
                    {"$set": {"owner": owner, "acquired_at": now, "expires_at": expires}},
                    upsert=True,
                    return_document=ReturnDocument.AFTER,
                )
            except DuplicateKeyError:
                row = None
            if not row or row.get("owner") != owner:
                failed = True
                break
            acquired.append(key)
        if not failed and len(acquired) == len(set(keys)):
            return owner
        await _release_capacity_locks(owner, acquired)
        await asyncio.sleep(0.025 * (attempt + 1))
    raise HTTPException(status_code=409, detail={
        "code": "capacity_busy",
        "message": "That opening is being booked by someone else. Please try again.",
    })


async def _active_capacity_bookings(service_type: str, *, exclude_booking_id: Optional[str] = None) -> List[dict]:
    q: Dict[str, Any] = {
        "service_type": service_type,
        "status": {"$in": ["pending", "approved", "completed"]},
    }
    if exclude_booking_id:
        q["id"] = {"$ne": exclude_booking_id}
    rows = await db.bookings.find(q, {"_id": 0}).to_list(10000)
    return [b for b in rows if not b.get("checked_out_at")]


async def _assert_capacity_available(
    body: BookingIn,
    settings: dict,
    selected_service: Optional[dict],
    *,
    exclude_booking_id: Optional[str] = None,
) -> None:
    """Recount capacity while the matching Mongo lease is held."""
    if body.service_type == "daycare":
        cap = max(0, int(settings.get("daycare_capacity", DAYCARE_CAPACITY) or 0))
        count = await _booking_days_count_filtered(body.date, "daycare", exclude_booking_id=exclude_booking_id)
        if cap <= 0 or count >= cap:
            raise _capacity_error(settings, body, "Daycare is fully booked for that date.", resource="daycare", target_date=body.date)
        return

    if body.service_type == "boarding":
        cap = max(0, int(settings.get("boarding_capacity", 10) or 0))
        for stay_day in _presence_dates(body.date, body.end_date):
            count = await _booking_days_count_filtered(stay_day, "boarding", exclude_booking_id=exclude_booking_id)
            if cap <= 0 or count >= cap:
                raise _capacity_error(settings, body, f"Boarding is fully booked for {stay_day}.", resource="boarding", target_date=stay_day)

        kennel = (body.kennel or "").strip()
        if kennel:
            max_per = int((((settings.get("day_to_day") or {}).get("guardrails") or {}).get("max_dogs_per_kennel", 1)) or 1)
            max_per = max(1, max_per)
            existing = await _active_capacity_bookings("boarding", exclude_booking_id=exclude_booking_id)
            for stay_day in _presence_dates(body.date, body.end_date):
                used = sum(
                    1 for b in existing
                    if (b.get("kennel") or "").strip().lower() == kennel.lower()
                    and stay_day in _presence_dates(b.get("date"), b.get("end_date"))
                )
                if used >= max_per:
                    raise _capacity_error(settings, body, f"{kennel} is already full for {stay_day}.", resource="kennel", target_date=stay_day)
        return

    if body.service_type not in ("training", "grooming", "photography") or not (body.time or "").strip():
        return

    duration = int((selected_service or {}).get("duration_minutes") or 0) or await _get_default_duration(body.service_type)
    start = _hhmm_to_min(body.time or "")
    if start is None or duration <= 0:
        return
    exact_service_id = (selected_service or {}).get("id") or body.service_id
    slot_capacity = max(1, int((selected_service or {}).get("capacity_per_slot") or 1))
    existing = await db.bookings.find(
        {
            "date": body.date,
            "status": {"$in": ["pending", "approved", "completed"]},
            "service_type": {"$in": ["training", "grooming", "photography"]},
            "time": {"$ne": ""},
            **({"id": {"$ne": exclude_booking_id}} if exclude_booking_id else {}),
        },
        {"_id": 0, "id": 1, "time": 1, "service_type": 1, "service_id": 1, "duration_minutes": 1, "dog_name": 1, "checked_out_at": 1},
    ).to_list(2000)
    same_service_overlaps = 0
    for b in existing:
        if b.get("checked_out_at"):
            continue
        bstart = _hhmm_to_min(b.get("time") or "")
        if bstart is None:
            continue
        bdur = int(b.get("duration_minutes") or 0) or await _get_default_duration(b.get("service_type"))
        if not _slot_overlaps(start, duration, bstart, bdur):
            continue
        if exact_service_id and b.get("service_id") == exact_service_id:
            same_service_overlaps += 1
            continue
        raise _capacity_error(
            settings,
            body,
            f"That time conflicts with an existing {b.get('service_type')} appointment at {b.get('time')}.",
            resource="time_slot",
            target_date=body.date,
        )
    if same_service_overlaps >= slot_capacity:
        label = (selected_service or {}).get("name") or body.service_type.title()
        raise _capacity_error(settings, body, f"{label} is full at {body.time}.", resource="class_or_slot", target_date=body.date)



async def _update_booking_with_capacity(booking: dict, update: Dict[str, Any]) -> dict:
    """Apply a reschedule/assignment only after race-safe capacity validation."""
    _assert_booking_financial_edit_allowed(booking, update.keys())
    merged = dict(booking)
    merged.update(update)
    body = BookingIn(
        dog_id=merged.get("dog_id"),
        date=merged.get("date"),
        end_date=merged.get("end_date"),
        service_type=merged.get("service_type") or "other",
        service_id=merged.get("service_id"),
        grooming_type=merged.get("grooming_type"),
        notes=merged.get("notes") or "",
        kennel=merged.get("kennel") or "",
        time=merged.get("time") or "",
        dropoff_time=merged.get("dropoff_time") or "",
        pickup_time=merged.get("pickup_time") or "",
    )
    selected = None
    if body.service_id:
        selected = await db.services.find_one({"id": body.service_id}, {"_id": 0})
    settings = await get_settings()
    keys = _capacity_resource_keys(body)
    owner = await _acquire_capacity_locks(keys) if keys else None
    try:
        if booking.get("status") in ("pending", "approved", "completed") and not booking.get("checked_out_at"):
            await _assert_capacity_available(body, settings, selected, exclude_booking_id=booking.get("id"))
        await db.bookings.update_one({"id": booking["id"]}, {"$set": update})
    finally:
        if owner:
            await _release_capacity_locks(owner, keys)
    merged.update(update)
    return merged


async def _dog_conflicting_booking(
    dog_id: str, date: str, end_date: Optional[str], service_type: str,
    *, exclude_booking_id: Optional[str] = None,
) -> Optional[dict]:
    """Find an existing active booking for the same dog + same service type
    whose date range overlaps the given one. Scoped to matching service
    types only — a dog boarding while also having a same-day grooming
    appointment is normal and must stay allowed."""
    new_days = set(_dates_in_range(date, end_date))
    q: Dict[str, Any] = {
        "dog_id": dog_id,
        "service_type": service_type,
        "status": {"$in": ["pending", "approved", "completed"]},
    }
    if exclude_booking_id:
        q["id"] = {"$ne": exclude_booking_id}
    existing = await db.bookings.find(q, {"_id": 0}).to_list(500)
    for b in existing:
        if b.get("checked_out_at"):
            continue
        if new_days & set(_dates_in_range(b.get("date"), b.get("end_date"))):
            return b
    return None


async def _crate_conflict(booking_id: str, date: str, end_date: Optional[str], crate: str) -> Optional[dict]:
    """A crate is a single physical container — unlike Room, Yard Group, or
    Training Group (which the app's own default labels — "Big Dogs",
    "Group A", etc. — show are meant to hold several dogs together), a
    crate can only ever hold one dog. Kennel already had this protection;
    Crate didn't, so two dogs could be assigned the same crate at once
    with no warning."""
    if not crate:
        return None
    new_days = set(_dates_in_range(date, end_date))
    existing = await db.bookings.find(
        {"crate": crate, "status": {"$in": ["pending", "approved", "completed"]}, "id": {"$ne": booking_id}},
        {"_id": 0},
    ).to_list(500)
    for b in existing:
        if b.get("checked_out_at"):
            continue
        if new_days & set(_dates_in_range(b.get("date"), b.get("end_date"))):
            return b
    return None


async def _create_booking_impl(body: BookingIn, user: dict = Depends(get_current_user)):
    _require_booking_edit(user)
    dog = await db.dogs.find_one({"id": body.dog_id}, {"_id": 0})
    if not dog:
        raise HTTPException(status_code=404, detail="Dog not found")
    if user.get("role") != "admin" and dog["owner_id"] != user.get("client_id"):
        raise HTTPException(status_code=403, detail="Not your dog")
    client = await db.clients.find_one({"id": dog["owner_id"]}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")

    settings = await get_settings()
    rules = settings.get("booking_rules", {})
    required = _required_vaccines_for_service(settings, body.service_type)

    # Resolve the exact active catalog service before applying rules. This
    # closes the old category-only API path that could otherwise bypass an
    # exact service's online-booking, notice, approval, and duration controls.
    selected_service = await _resolve_base_service_for_booking(body, user)
    svc_rules = _booking_flow_rules_for(settings, body.service_type, body.service_id)
    if user.get("role") != "admin" and svc_rules.get("client_booking_enabled") is False:
        label = (selected_service or {}).get("name") or body.service_type.title()
        raise HTTPException(status_code=400, detail=f"{label} is not currently available for online booking.")
    daycare_cap = int(settings.get("daycare_capacity", DAYCARE_CAPACITY))
    boarding_cap = int(settings.get("boarding_capacity", 10))

    # Sprint 110di-17 — Feature Visibility guard. If the admin has turned
    # off this service in Settings → Feature Visibility, reject the booking
    # server-side regardless of how it got submitted. Admins bypass so they
    # can still clean up historical data if needed.
    fv = settings.get("feature_visibility") or {}
    if user.get("role") != "admin" and body.service_type in fv and fv.get(body.service_type) is False:
        raise HTTPException(status_code=400, detail=f"{body.service_type.title()} bookings are currently disabled.")

    # Sprint 110di-28 — Boarding zero-night guard. The boarding price model
    # is nights × per-night rate; zero nights means no stay. Same-day
    # drop-off is FINE; what we reject is pickup === drop-off (which would
    # be a zero-count stay). For a one-day no-overnight stay, daycare is
    # the right product. Admins are NOT exempt because there's no
    # historical use-case for a zero-night boarding row.
    if body.service_type == "boarding":
        if not body.end_date or str(body.end_date)[:10] <= str(body.date)[:10]:
            raise HTTPException(
                status_code=400,
                detail="Boarding requires at least one overnight stay — pickup must be on a later date than drop-off. (Same-day drop-off is fine, but pickup the same day would be zero nights.)",
            )

    # Per-service booking controls are evaluated against the real local start
    # time, never midnight/UTC. This makes a 4 PM appointment tomorrow count as
    # the actual hours available from now in America/New_York.
    booking_start_local = None
    if user.get("role") != "admin" and body.date:
        booking_start_local = _booking_start_local(body, settings)
        now_business = datetime.now(BUSINESS_TZ)
        req_date = booking_start_local.date()
        today = now_business.date()
        if req_date < today:
            raise HTTPException(status_code=400, detail="Please choose a future booking date.")
        has_explicit_start = bool((body.time or "").strip() or (body.dropoff_time or "").strip())
        if has_explicit_start and booking_start_local <= now_business:
            raise HTTPException(status_code=400, detail="Please choose a future booking time.")
        if svc_rules.get("same_day") is False and req_date == today:
            raise HTTPException(status_code=400, detail=f"Same-day {body.service_type} bookings are not allowed. Please pick a future date.")
        min_lead = svc_rules.get("min_lead_hours")
        if isinstance(min_lead, (int, float)) and min_lead > 0:
            hours_lead = (booking_start_local - now_business).total_seconds() / 3600.0
            if hours_lead < float(min_lead):
                label = (selected_service or {}).get("name") or body.service_type.title()
                raise HTTPException(status_code=400, detail=f"{label} requires at least {int(min_lead)}h advance notice.")
        max_adv = svc_rules.get("max_advance_days")
        if isinstance(max_adv, (int, float)) and max_adv > 0:
            if (req_date - today).days > int(max_adv):
                label = (selected_service or {}).get("name") or body.service_type.title()
                raise HTTPException(status_code=400, detail=f"{label} can only be booked up to {int(max_adv)} days in advance.")

    # Sprint 110aw — Meet-n-Greet gate. Prospect / rejected clients cannot
    # book regular services; admin can override by passing the booking through
    # manually with `override_capacity=True` (treated as a force-flag).
    cstat = client.get("client_status") or "active"
    if cstat in ("prospect", "evaluation_scheduled", "rejected"):
        # Admin override path: respect explicit override_capacity intent so
        # admin can still schedule the evaluation booking itself.
        if user.get("role") != "admin" or not body.override_capacity:
            if cstat == "rejected":
                raise HTTPException(
                    status_code=400,
                    detail="This client has been marked rejected — bookings are disabled.",
                )
            raise HTTPException(
                status_code=400,
                detail="This client needs to complete a Meet-n-Greet evaluation before booking. Please schedule one first.",
            )

    # Day-to-Day money guard — this setting used to be presentation-only.
    # For client-created bookings, a configured threshold now genuinely blocks
    # additional booking requests when the client's canonical account_balance
    # exceeds it. Admin/staff booking remains available so the owner can make
    # an intentional exception after reviewing the account.
    if user.get("role") != "admin":
        money_controls = ((settings.get("day_to_day") or {}).get("money") or {})
        decline_over = float(money_controls.get("auto_decline_if_balance_over") or 0)
        current_balance = round(float(client.get("account_balance") or 0), 2)
        if decline_over > 0 and current_balance > decline_over + 0.005:
            raise HTTPException(
                status_code=409,
                detail=f"New bookings are paused while your account balance is ${current_balance:.2f}. Please contact Sit Happens to review the balance.",
            )

    # Waiver check for clients
    if user.get("role") != "admin" and bool(settings.get("waiver_required_for_booking", True)):
        sig = await db.waiver_signatures.find_one({"client_id": client["id"]}, sort=[("signed_at", -1)])
        current_version = int(settings.get("waiver_version", 1))
        if not sig or int(sig.get("waiver_version", 1)) < current_version:
            raise HTTPException(status_code=400, detail="Waiver must be signed before booking")
    if user.get("role") != "admin":
        await _require_agreements_signed(client["id"], service_type=body.service_type)

    # Vaccine check (multi-vaccine + per-service Day-to-Day policy).
    # `block_bookings_if_vaccines_expired` used to be decorative; it now
    # genuinely controls client booking enforcement. Staff can still use the
    # existing explicit override_vaccines path when authorized.
    is_admin = user.get("role") == "admin"
    compliance = ((settings.get("day_to_day") or {}).get("compliance") or {})
    guardrails = ((settings.get("day_to_day") or {}).get("guardrails") or {})
    should_block_vaccines = bool(guardrails.get("block_bookings_if_vaccines_expired", True))
    if should_block_vaccines and not (is_admin and body.override_vaccines):
        await _validate_dog_vaccines(
            dog, required,
            block_on_expiry_day=bool(compliance.get("block_on_expiry_day", True)),
            document_required=bool(compliance.get("vaccine_doc_upload_required", False)),
        )

    # Sprint 110ff — Same-dog duplicate-booking guard. GET /bookings/conflicts
    # only ever showed an informational "heads up" banner in one screen and
    # nothing actually stopped the save — a dog could end up with two active
    # bookings for the same service overlapping the same day(s) (e.g. a
    # manual booking landing on top of a recurring-template session),
    # producing duplicate charges and duplicate cards on the Run Sheet.
    # Scoped to the SAME service_type only — a dog boarding and also having
    # a same-day grooming appointment is normal and must stay allowed.
    if not (is_admin and body.override_capacity):
        dup = await _dog_conflicting_booking(body.dog_id, body.date, body.end_date, body.service_type)
        if dup:
            dup_end = dup.get("end_date")
            span = f" through {dup_end}" if dup_end else ""
            raise HTTPException(
                status_code=409,
                detail=f"{dog['name']} already has a {body.service_type} booking on {dup.get('date')}"
                       f"{span} (status: {dup.get('status')}).",
            )

    # Closed-day enforcement (clients only — admin can override by creating manually).
    # Blocks any booking whose start date OR any day in its range falls on a closed date.
    if not is_admin:
        closed = set(settings.get("closed_dates") or [])
        if closed:
            booking_dates = _dates_in_range(body.date, body.end_date)
            hit = [d for d in booking_dates if d in closed]
            if hit:
                pretty = ", ".join(hit[:3]) + ("…" if len(hit) > 3 else "")
                raise HTTPException(status_code=400, detail=f"Sit Happens is closed on {pretty}. Please pick another date.")

    # Advance-booking limit (clients only) — exempt daycare so regulars can
    # set up long-running recurring schedules without bumping the global cap.
    if user.get("role") != "admin" and body.service_type != "daycare" and svc_rules.get("max_advance_days") is None:
        max_adv = int(rules.get("max_advance_days", 60))
        if max_adv > 0:
            limit_date = (business_today() + timedelta(days=max_adv)).isoformat()
            if body.date > limit_date:
                raise HTTPException(status_code=400, detail=f"Bookings allowed up to {max_adv} days in advance")

    # Sprint 110dm — day-to-day guardrails (min advance, same-day toggle,
    # weekend lead time, max-bookings-per-day, max-consecutive-boarding-nights).
    # Admins bypass these via override_capacity for emergency fixes.
    if user.get("role") != "admin" or not (body.override_capacity or False):
        guard = ((settings.get("day_to_day") or {}).get("guardrails") or {})
        # Reuse the same Eastern-aware, actual-time calculation as the exact
        # service rules. No second midnight/UTC interpretation is allowed.
        effective_start_local = booking_start_local or _booking_start_local(body, settings)
        now_business = datetime.now(BUSINESS_TZ)
        hours_until = (effective_start_local - now_business).total_seconds() / 3600.0

        if not svc_rules.get("_exact_same_day"):
            if not guard.get("same_day_booking_allowed", True) and effective_start_local.date() == now_business.date():
                raise HTTPException(status_code=400, detail="Same-day bookings are currently disabled.")
        if not svc_rules.get("_exact_min_lead"):
            min_adv_h = float(guard.get("min_advance_booking_hours", 0) or 0)
            if min_adv_h > 0 and hours_until < min_adv_h:
                raise HTTPException(status_code=400, detail=f"Bookings require at least {int(min_adv_h)}h advance notice.")
        wknd_lead = float(guard.get("weekend_lead_time_hours", 0) or 0)
        if wknd_lead > 0 and effective_start_local.weekday() in (5, 6):
            if hours_until < wknd_lead:
                raise HTTPException(status_code=400, detail=f"Weekend bookings require {int(wknd_lead)}h advance notice.")
        max_pcd = int(guard.get("max_bookings_per_client_per_day", 0) or 0)
        if max_pcd > 0:
            same_day = await db.bookings.count_documents({
                # Bookings store the linked client-record id, not the portal
                # login user's id. Using the login id made this limit a no-op.
                "client_id": client.get("id"),
                "date": body.date,
                "status": {"$nin": ["cancelled", "rejected"]},
            })
            if same_day >= max_pcd:
                raise HTTPException(status_code=400, detail=f"This client already has {max_pcd} booking(s) for that date.")
        max_nights = int(guard.get("max_consecutive_boarding_nights", 0) or 0)
        if max_nights > 0 and body.service_type == "boarding" and body.end_date:
            try:
                nights = (date.fromisoformat(body.end_date) - date.fromisoformat(body.date)).days
                if nights > max_nights:
                    raise HTTPException(status_code=400, detail=f"Boarding stays cannot exceed {max_nights} consecutive nights.")
            except Exception:
                pass

    # Duration is snapshotted now; the race-safe capacity/time-slot recount is
    # performed immediately before insert while a shared Mongo lease is held.
    duration_minutes_used = 0
    if body.service_type in TIME_SLOTTED_SERVICES and (body.time or "").strip():
        duration_minutes_used = int((selected_service or {}).get("duration_minutes") or 0) or await _get_default_duration(body.service_type)
        new_start = _hhmm_to_min(body.time)
        if new_start is not None and duration_minutes_used > 0:
            try:
                target_day = date.fromisoformat(body.date)
                hours_row = _service_hours_for_date(settings, body.service_type, target_day)
                close_min = _hhmm_to_min(hours_row.get("close") or "")
                if close_min is not None and new_start + duration_minutes_used > close_min:
                    raise HTTPException(status_code=400, detail="That appointment would run past closing time.")
            except HTTPException:
                raise
            except Exception:
                pass

    # Credit units and money are separate. `cost` remains the old daycare-credit
    # field for backward compatibility; dollars go into `estimated_price`.
    # New boarding rows always carry a pickup time so the pickup-day charge
    # cannot silently disappear. A missing selection defaults to the admin's
    # full-day cutoff rather than underquoting the stay.
    pickup_cutoff_time = _boarding_full_day_cutoff_from_rules(rules)
    effective_pickup_time = (body.pickup_time or pickup_cutoff_time) if body.service_type == "boarding" else (body.pickup_time or "")
    days = _presence_dates(body.date, body.end_date)
    cost = _service_cost(rules, body.service_type, len(days))
    credit_units_required = _credit_units_required(
        body.service_type, body.date, body.end_date,
        dog_count=1, pickup_time=effective_pickup_time,
        pickup_cutoff_time=pickup_cutoff_time,
    )
    quote = await _quote_base_service_price(
        client_id=client.get("id"),
        service_type=body.service_type,
        start_date=body.date,
        end_date=body.end_date,
        pickup_time=effective_pickup_time,
        pickup_cutoff_time=pickup_cutoff_time,
        service_id=body.service_id,
        grooming_type=body.grooming_type if body.service_type == "grooming" else None,
    )
    estimated_price = float(quote.get("estimated_price") or 0)

    auto_approve = bool(rules.get("auto_approve", False))
    if is_admin:
        status_val = "approved"
    elif svc_rules.get("require_approval") is True:
        status_val = "pending"
    elif svc_rules.get("instant_book") is True:
        status_val = "approved"
    else:
        status_val = "approved" if auto_approve else "pending"

    doc = {
        "id": str(uuid.uuid4()),
        "dog_id": dog["id"],
        "dog_name": dog["name"],
        "client_id": client["id"],
        "client_name": client["name"],
        "date": body.date,
        "end_date": body.end_date,
        "service_type": body.service_type,
        "grooming_type": body.grooming_type if body.service_type == "grooming" else None,
        "status": status_val,
        "notes": body.notes or "",
        "kennel": body.kennel or "",
        "time": body.time or "",
        "duration_minutes": duration_minutes_used,  # snapshot for future conflict checks
        "dropoff_time": body.dropoff_time or "",
        "pickup_time": effective_pickup_time,
        "created_at": now_iso(),
        "cost": cost,
        "credit_units_required": credit_units_required,
        "estimated_price": round(estimated_price, 2),
        "service_id": quote.get("service_id"),
        "service_name": quote.get("service_name"),
        "unit_price": quote.get("unit_price"),
        "list_unit_price": quote.get("list_unit_price"),
        "preferred_rate_applied": quote.get("preferred_rate_applied", False),
        "price_override_id": quote.get("price_override_id"),
        "price_source": quote.get("price_source"),
        "price_label": quote.get("price_label"),
        "pricing_snapshot": {
            "service_id": quote.get("service_id"),
            "service_name": quote.get("service_name"),
            "unit_price": quote.get("unit_price"),
            "list_unit_price": quote.get("list_unit_price"),
            "preferred_rate_applied": quote.get("preferred_rate_applied", False),
            "price_override_id": quote.get("price_override_id"),
            "price_source": quote.get("price_source"),
            "price_label": quote.get("price_label"),
            "billable_units": quote.get("units"),
            "unit_label": quote.get("unit_label"),
            "pickup_cutoff_time": pickup_cutoff_time if body.service_type == "boarding" else None,
            "created_at": now_iso(),
        },
        "balance_due": 0.0,
        # Sprint 110di-38 — Multi-dog group booking. Persist the group_id
        # so list/detail endpoints and the run sheet can render the "🔗
        # Group · N dogs" badge. None for legacy single-dog flows.
        "group_id": body.group_id,
    }
    if is_admin and body.check_in_now:
        doc["checked_in_at"] = now_iso()
    # NOTE: credits are no longer deducted at booking time or on approval —
    # they're only deducted at checkout (see check_out()). This makes credit
    # use predictable and prevents accidental deductions for bookings that get
    # rescheduled, cancelled before drop-off, or paid with cash on the day.
    doc["credits_deducted"] = 0
    # Sprint 110an — attach any add-ons the client picked at booking time
    # (e.g. "Add a nail trim with my daycare"). Snapshots include price &
    # legacy-pricing override so the rate is locked in for this booking.
    if body.addon_service_ids:
        doc["add_ons"] = await resolve_addon_snapshots(
            client.get("id"),
            body.addon_service_ids,
            body.service_type,
        )
        try:
            add_on_est = sum(float(a.get("price") or 0) * int(a.get("qty") or 1) for a in (doc.get("add_ons") or []))
            doc["estimated_price"] = round(float(doc.get("estimated_price") or 0) + add_on_est, 2)
        except Exception:
            pass
    # Sprint 110aw — Optional service pre-selection. When the caller picks a
    # specific service row (e.g. a Board-and-Train package), snapshot it onto
    # the booking so check-out / auto-enroll can use it.
    if body.service_id:
        svc_row = await db.services.find_one(
            {"id": body.service_id},
            {"_id": 0, "id": 1, "name": 1, "base_price": 1},
        )
        if svc_row:
            doc["service_id"] = svc_row["id"]
            doc["service_name"] = svc_row.get("name")
    capacity_keys = _capacity_resource_keys(body)
    capacity_ctx = _capacity_lock_ctx.get()
    owns_capacity_lock = False
    capacity_owner = None
    if not (is_admin and body.override_capacity) and capacity_keys:
        if capacity_ctx and set(capacity_keys).issubset(set(capacity_ctx.get("keys") or [])):
            capacity_owner = capacity_ctx.get("owner")
        else:
            capacity_owner = await _acquire_capacity_locks(capacity_keys)
            owns_capacity_lock = True
    try:
        if not (is_admin and body.override_capacity):
            await _assert_capacity_available(body, settings, selected_service)
        await db.bookings.insert_one(doc)
    finally:
        if owns_capacity_lock and capacity_owner:
            await _release_capacity_locks(capacity_owner, capacity_keys)
    doc.pop("_id", None)
    # School-only training model — Board & Train package linkage now creates
    # (or reuses) the same canonical In-Person School enrollment used by the
    # daily trainer workflow. A legacy modules/goals-only program is NEVER
    # resurrected here; the booking remains valid and is visibly stamped as
    # needing its linked program repaired/migrated in Program Studio.
    try:
        if doc.get("service_id"):
            svc_row = await db.services.find_one(
                {"id": doc["service_id"]},
                {"_id": 0, "package_program_id": 1, "name": 1},
            )
            prog_id = (svc_row or {}).get("package_program_id")
            if prog_id:
                program = await db.programs.find_one({"id": prog_id}, {"_id": 0})
                dog_row = await db.dogs.find_one({"id": doc.get("dog_id")}, {"_id": 0})
                warning = None
                canonical = await db.dog_programs.find_one(
                    {"dog_id": doc.get("dog_id"), "program_id": prog_id, "status": "active",
                     "delivery_channel": {"$in": list(STAFF_SCHOOL_DELIVERY_CHANNELS)}},
                    {"_id": 0},
                )
                legacy_active = await db.dog_programs.find_one(
                    {"dog_id": doc.get("dog_id"), "program_id": prog_id, "status": "active",
                     "delivery_channel": {"$nin": list(SCHOOL_DELIVERY_CHANNELS)}},
                    {"_id": 0, "id": 1},
                )
                enrollment_id = None
                if canonical:
                    enrollment_id = canonical.get("id")
                elif legacy_active:
                    warning = "This dog still has an active retired legacy enrollment for the Board & Train curriculum. Migrate it into School before training starts."
                elif not program or not _school_curriculum_readiness(program).get("ready"):
                    warning = "The Board & Train service is linked to a retired legacy curriculum. Add explicit lessons in Program Studio or relink the service to a School-ready program."
                elif not dog_row or not dog_row.get("owner_id"):
                    warning = "The Board & Train dog needs an owning client before its School training enrollment can be created."
                else:
                    result = await _grant_staff_school_enrollment(
                        dog_row, program, delivery_mode="in_person", enrolled_by=user.get("id"),
                        trainer_notes=f"Auto-enrolled from Board-and-Train package · booking {doc['id']}",
                        started_at=doc.get("date") or business_today().isoformat(),
                    )
                    enrollment_id = result["enrollment"]["id"]
                    await db.dog_programs.update_one(
                        {"id": enrollment_id},
                        {"$set": {"source_booking_id": doc["id"], "enrollment_source": "board_train_package"}},
                    )
                    await db.school_enrollments.update_one(
                        {"id": result["school_enrollment"]["id"]},
                        {"$set": {"source_booking_id": doc["id"], "enrollment_source": "board_train_package"}},
                    )
                booking_set = {}
                if enrollment_id:
                    booking_set.update({
                        "package_enrolled_program_id": enrollment_id,
                        "package_enrollment_status": "school_ready",
                    })
                    doc["package_enrolled_program_id"] = enrollment_id
                    doc["package_enrollment_status"] = "school_ready"
                if warning:
                    booking_set.update({
                        "package_enrollment_status": "needs_school_program_migration",
                        "package_enrollment_warning": warning,
                    })
                    doc["package_enrollment_status"] = "needs_school_program_migration"
                    doc["package_enrollment_warning"] = warning
                if booking_set:
                    await db.bookings.update_one({"id": doc["id"]}, {"$set": booking_set})
    except Exception as exc:
        # Booking creation must not be rolled back because curriculum linkage
        # needs Admin repair. Surface the issue on the booking instead.
        warning = "Board & Train booking was created, but its School enrollment could not be prepared. Review the linked School curriculum and the dog/client setup."
        doc["package_enrollment_status"] = "needs_school_program_migration"
        doc["package_enrollment_warning"] = warning
        await db.bookings.update_one(
            {"id": doc.get("id")},
            {"$set": {"package_enrollment_status": "needs_school_program_migration", "package_enrollment_warning": warning}},
        )
        logger.warning("board-and-train School auto-enroll failed for booking %s: %s", doc.get("id"), exc)
    # Best-effort notification: tell admin when a client books from the portal.
    # Admin-created bookings (via Quick Check-in etc.) don't trigger an alert to themselves.
    # In bulk-create flows (recurring / multi-dates), this is suppressed and the
    # bulk endpoint sends ONE summary email after the loop.
    if not is_admin and not _suppress_admin_booking_email.get():
        try:
            if doc.get("status") == "pending":
                # Approval-required booking — the durable "needs your
                # approval" alert (outbox retry on failure, delivery result
                # stamped in notification_log). The pending booking itself is
                # already in Action Required regardless of email fate.
                sent_now = await notify_admin_booking_approval(doc, client)
                if not sent_now:
                    logger.warning(
                        "create_booking: approval alert email for booking %s not sent immediately "
                        "(queued for retry or skipped — see email_outbox / last error: %s)",
                        doc.get("id"), email_service.last_send_error,
                    )
            else:
                await notify_admin_new_booking(doc, client)
        except Exception as exc:
            logger.error("create_booking: admin booking email dispatch crashed for %s: %s", doc.get("id"), exc)
    # 🎉 First-ever booking for this client? Send a celebratory email to the operator,
    # and if they came in via a referral code, the referrer is auto-credited on
    # this client's FIRST CHECKOUT — see check_out() below.
    try:
        booking_count = await _booking_count_anywhere({"client_id": client["id"]})
        if booking_count == 1:
            await notify_admin_first_booking(doc, client)
    except Exception:
        pass
    return doc

async def create_booking(body: BookingIn, user: dict = Depends(get_current_user)):
    """Bookings-domain facade for the proven booking transaction implementation."""
    return await bookings_domain_services.create_booking(body, user)


@api.get("/admin/vaccine-cert-uploads")
async def admin_list_vaccine_uploads(include_reviewed: bool = False, _: dict = Depends(require_admin)):
    """List recent client-uploaded vaccine certificates. Unreviewed first."""
    dogs = await db.dogs.find(
        {"vaccine_certs": {"$exists": True, "$ne": {}}},
        {"_id": 0, "id": 1, "name": 1, "owner_id": 1, "vaccine_certs": 1, "vaccines": 1},
    ).to_list(500)
    out = []
    for d in dogs:
        certs = d.get("vaccine_certs") or {}
        vaccines = d.get("vaccines") or {}
        for vacc, info in certs.items():
            if not info or not isinstance(info, dict):
                continue
            reviewed = bool(info.get("reviewed_at"))
            if reviewed and not include_reviewed:
                continue
            out.append({
                "dog_id": d["id"],
                "dog_name": d.get("name", ""),
                "owner_id": d.get("owner_id"),
                "vaccine": vacc,
                "expires_on": info.get("expires_on") or vaccines.get(vacc, ""),
                "photo": info.get("photo"),
                # Sprint 110di — multi-photo upload. Falls back to `[photo]` for
                # back-compat with older single-photo records.
                "photos": info.get("photos") or ([info["photo"]] if info.get("photo") else []),
                "uploaded_at": info.get("uploaded_at"),
                "uploaded_by": info.get("uploaded_by", ""),
                "reviewed_at": info.get("reviewed_at"),
                "reviewed_by": info.get("reviewed_by", ""),
            })
    # Owner names
    owner_ids = list({x["owner_id"] for x in out if x.get("owner_id")})
    if owner_ids:
        owners = await db.clients.find({"id": {"$in": owner_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)
        omap = {o["id"]: o["name"] for o in owners}
        for x in out:
            x["client_name"] = omap.get(x.get("owner_id"), "")
    out.sort(key=lambda x: x.get("uploaded_at", ""), reverse=True)
    return out


