# -------- Sprint 110di-4 — Announcements (admin → client portal) --------
class AnnouncementBullet(BaseModel):
    title: str = ""
    body: str = ""


class AnnouncementIn(BaseModel):
    title: str = Field(min_length=1, max_length=180)
    body: str = ""                                   # plain text, multi-paragraph
    image: Optional[str] = ""                        # optional base64 data URL
    pinned: bool = False
    expires_on: Optional[str] = ""                   # ISO YYYY-MM-DD or "" for no expiry
    published: bool = True


def _ann_visible_today(a: Dict[str, Any]) -> bool:
    if not a.get("published", True):
        return False
    exp = (a.get("expires_on") or "").strip()
    if not exp:
        return True
    today = datetime.now(timezone.utc).date().isoformat()
    return exp >= today


@api.get("/admin/announcements")
async def list_admin_announcements(_: dict = Depends(require_admin_and_permission("manage_communications"))):
    items = await db.announcements.find({}, {"_id": 0}).to_list(length=None)
    items.sort(key=lambda a: (not a.get("pinned"), a.get("created_at") or ""), reverse=False)
    # Newest first, with pinned floated to top.
    items.sort(key=lambda a: a.get("created_at") or "", reverse=True)
    items.sort(key=lambda a: not a.get("pinned"))
    return items


@api.post("/admin/announcements")
async def create_announcement(body: AnnouncementIn, admin: dict = Depends(require_admin_and_permission("manage_communications"))):
    doc = body.model_dump()
    doc["id"] = uuid.uuid4().hex
    doc["created_at"] = now_iso()
    doc["created_by"] = admin.get("name", "admin")
    doc["updated_at"] = doc["created_at"]
    await db.announcements.insert_one(doc.copy())
    doc.pop("_id", None)
    # Sprint 110di-5 — every PUBLISHED announcement also fires an email
    # broadcast to every client with an email on file. Drafts (published=False)
    # stay silent. Edits never re-broadcast (see PUT endpoint).
    #
    # We kick the broadcast off as a background task so the admin doesn't have
    # to wait for Resend to fan out across hundreds of recipients. The composer
    # UI sees the recipient *count* immediately and a toast confirms the post.
    summary: Dict[str, Any] = {"sent": 0, "skipped": 0}
    if doc.get("published", True):
        # Cheap pre-count — only clients with a non-empty email get the blast.
        recipient_count = await db.clients.count_documents({"email": {"$exists": True, "$nin": ["", None]}})
        summary["queued"] = recipient_count
        asyncio.create_task(email_service.broadcast_announcement_email(doc))
    doc["email_broadcast"] = summary
    return doc


@api.put("/admin/announcements/{ann_id}")
async def update_announcement(ann_id: str, body: AnnouncementIn, admin: dict = Depends(require_admin_and_permission("manage_communications"))):
    update = body.model_dump()
    update["updated_at"] = now_iso()
    update["updated_by"] = admin.get("name", "admin")
    r = await db.announcements.update_one({"id": ann_id}, {"$set": update})
    if r.matched_count == 0:
        raise HTTPException(status_code=404, detail="Announcement not found")
    doc = await db.announcements.find_one({"id": ann_id}, {"_id": 0})
    return doc


@api.delete("/admin/announcements/{ann_id}")
async def delete_announcement(ann_id: str, _: dict = Depends(require_admin_and_permission("manage_communications"))):
    r = await db.announcements.delete_one({"id": ann_id})
    if r.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Announcement not found")
    # Drop read receipts for this announcement so we don't leak orphaned rows.
    await db.announcement_reads.delete_many({"announcement_id": ann_id})
    return {"ok": True}


@api.get("/portal/announcements")
async def list_portal_announcements(user: dict = Depends(get_current_user)):
    """Returns published, non-expired announcements with a `read` flag for
    the current client (computed from `announcement_reads`)."""
    client_id = user.get("client_id")
    items = await db.announcements.find({}, {"_id": 0}).to_list(length=None)
    items = [a for a in items if _ann_visible_today(a)]
    items.sort(key=lambda a: a.get("created_at") or "", reverse=True)
    items.sort(key=lambda a: not a.get("pinned"))
    if client_id:
        reads = await db.announcement_reads.find(
            {"client_id": client_id}, {"_id": 0, "announcement_id": 1}
        ).to_list(length=None)
        read_ids = {r["announcement_id"] for r in reads}
    else:
        read_ids = set()
    for a in items:
        a["read"] = a["id"] in read_ids
    unread = sum(1 for a in items if not a["read"])
    return {"items": items, "unread": unread}


@api.post("/portal/announcements/{ann_id}/read")
async def mark_announcement_read(ann_id: str, user: dict = Depends(get_current_user)):
    client_id = user.get("client_id")
    if not client_id:
        raise HTTPException(status_code=400, detail="Only portal clients can mark announcements read")
    ann = await db.announcements.find_one({"id": ann_id}, {"_id": 0, "id": 1})
    if not ann:
        raise HTTPException(status_code=404, detail="Announcement not found")
    await db.announcement_reads.update_one(
        {"client_id": client_id, "announcement_id": ann_id},
        {"$set": {"read_at": now_iso()}},
        upsert=True,
    )
    return {"ok": True}


# -------- Change Password --------
class ChangePwIn(BaseModel):
    current_password: str
    new_password: str = Field(min_length=8)

@api.post("/auth/change-password")
async def change_password(body: ChangePwIn, request: Request, user: dict = Depends(get_current_user)):
    await _enforce_rate_limit(request, "change_password_user", user.get("id", "unknown"), limit=10, window_seconds=900)
    full = await db.users.find_one({"id": user["id"]})
    if not full or not verify_password(body.current_password, full["password_hash"]):
        raise HTTPException(status_code=400, detail="Current password is incorrect")
    new_ver = _token_version(full) + 1
    await db.users.update_one(
        {"id": user["id"]},
        {
            "$set": {"password_hash": hash_password(body.new_password), "must_change_password": False},
            "$inc": {"token_version": 1},
        },
    )
    _invalidate_auth_user_cache(user["id"])
    token = create_access_token(full["id"], full["email"], full.get("role", "client"), new_ver)
    return {"ok": True, "token": token, "must_change_password": False}


class SetPasswordIn(BaseModel):
    password: str = Field(min_length=8)

@api.patch("/auth/set-password")
async def set_password(body: SetPasswordIn, request: Request, user: dict = Depends(get_current_user)):
    """Lets a client who logged in passwordless (needs_password=True) set a
    real password, one time, without knowing their current (unusable random)
    one. Once cleared, `needs_password` stays false — call change-password
    for any later password change."""
    await _enforce_rate_limit(request, "set_password_user", user.get("id", "unknown"), limit=10, window_seconds=900)
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Only client accounts can use this endpoint")
    full = await db.users.find_one({"id": user["id"]})
    if not full or not full.get("needs_password"):
        raise HTTPException(status_code=400, detail="A password is already set. Use Change Password instead.")
    new_ver = _token_version(full) + 1
    await db.users.update_one(
        {"id": user["id"]},
        {
            "$set": {"password_hash": hash_password(body.password), "needs_password": False, "must_change_password": False},
            "$inc": {"token_version": 1},
        },
    )
    _invalidate_auth_user_cache(user["id"])
    token = create_access_token(full["id"], full["email"], full.get("role", "client"), new_ver)
    return {"ok": True, "token": token, "needs_password": False}


# -------- Per-user UI Preferences (Sprint 68) --------
# Each user (admin or client) can pick their own text size. Stored on the user
# document under `preferences`. Read via GET /me/preferences, write via PUT.
ALLOWED_TEXT_SIZES = ["S", "M", "L", "XL"]

class PreferencesIn(BaseModel):
    text_size: Optional[str] = None  # one of S/M/L/XL

@api.get("/me/preferences")
async def get_my_prefs(user: dict = Depends(get_current_user)):
    full = await db.users.find_one({"id": user["id"]}, {"_id": 0, "preferences": 1})
    return (full or {}).get("preferences") or {"text_size": "M"}

@api.put("/me/preferences")
async def set_my_prefs(body: PreferencesIn, user: dict = Depends(get_current_user)):
    update = {}
    if body.text_size is not None:
        ts = body.text_size.upper()
        if ts not in ALLOWED_TEXT_SIZES:
            raise HTTPException(status_code=400, detail=f"text_size must be one of {ALLOWED_TEXT_SIZES}")
        update["preferences.text_size"] = ts
    if not update:
        return await get_my_prefs(user)
    await db.users.update_one({"id": user["id"]}, {"$set": update})
    return await get_my_prefs(user)


# -------- Waivers --------
class AgreementTemplateIn(BaseModel):
    name: str = Field(min_length=1, max_length=120)
    title: str = Field(min_length=1, max_length=200)
    body: str = Field(min_length=1, max_length=30000)
    scope_type: Literal["general", "service_type", "program_id"] = "general"
    scope_value: Optional[str] = Field(default=None, max_length=200)
    required: bool = True
    active: bool = True


class AgreementSignIn(BaseModel):
    typed_name: str = Field(min_length=2, max_length=120)
    dog_id: Optional[str] = None


def _agreement_scope_matches(template: dict, *, service_type: Optional[str] = None, program_id: Optional[str] = None) -> bool:
    scope_type = template.get("scope_type") or "general"
    scope_value = str(template.get("scope_value") or "")
    if scope_type == "general":
        return True
    if scope_type == "service_type":
        return bool(service_type and scope_value == service_type)
    if scope_type == "program_id":
        return bool(program_id and scope_value == program_id)
    return False


async def _unsigned_required_agreements(client_id: str, *, service_type: Optional[str] = None, program_id: Optional[str] = None) -> list[dict]:
    templates = await db.agreement_templates.find({"active": True, "required": True}, {"_id": 0}).to_list(500)
    applicable = [t for t in templates if _agreement_scope_matches(t, service_type=service_type, program_id=program_id)]
    if not applicable:
        return []
    ids = [t["id"] for t in applicable]
    sigs = await db.agreement_signatures.find({"client_id": client_id, "template_id": {"$in": ids}}, {"_id": 0}).to_list(1000)
    signed_versions = {(x.get("template_id"), int(x.get("template_version") or 0)) for x in sigs}
    return [t for t in applicable if (t["id"], int(t.get("version") or 1)) not in signed_versions]


async def _require_agreements_signed(client_id: str, *, service_type: Optional[str] = None, program_id: Optional[str] = None) -> None:
    missing = await _unsigned_required_agreements(client_id, service_type=service_type, program_id=program_id)
    if missing:
        names = ", ".join((t.get("title") or t.get("name") or "agreement") for t in missing[:3])
        raise HTTPException(status_code=409, detail=f"Required agreement must be signed before continuing: {names}")


@api.get("/admin/agreement-templates")
async def admin_agreement_templates(_: dict = Depends(require_admin_and_permission("settings"))):
    return await db.agreement_templates.find({}, {"_id": 0}).sort([("active", -1), ("name", 1)]).to_list(500)


@api.post("/admin/agreement-templates")
async def admin_create_agreement_template(body: AgreementTemplateIn, user: dict = Depends(require_admin_and_permission("settings"))):
    if body.scope_type != "general" and not (body.scope_value or "").strip():
        raise HTTPException(status_code=400, detail="A service/program scope value is required")
    ts = now_iso()
    doc = {"id": str(uuid.uuid4()), **body.model_dump(), "scope_value": (body.scope_value or "").strip() or None,
           "version": 1, "created_at": ts, "updated_at": ts, "created_by": user.get("id")}
    await db.agreement_templates.insert_one(doc.copy())
    doc.pop("_id", None)
    return doc


@api.put("/admin/agreement-templates/{template_id}")
async def admin_update_agreement_template(template_id: str, body: AgreementTemplateIn, user: dict = Depends(require_admin_and_permission("settings"))):
    existing = await db.agreement_templates.find_one({"id": template_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Agreement template not found")
    patch = body.model_dump()
    patch["scope_value"] = (body.scope_value or "").strip() or None
    signature_meaning_changed = any(existing.get(k) != patch.get(k) for k in ("title", "body", "scope_type", "scope_value"))
    if signature_meaning_changed:
        patch["version"] = int(existing.get("version") or 1) + 1
    patch["updated_at"] = now_iso(); patch["updated_by"] = user.get("id")
    await db.agreement_templates.update_one({"id": template_id}, {"$set": patch})
    return await db.agreement_templates.find_one({"id": template_id}, {"_id": 0})


@api.get("/portal/agreements")
async def portal_agreements(user: dict = Depends(get_current_user)):
    if user.get("role") != "client" or not user.get("client_id"):
        raise HTTPException(status_code=403, detail="Client account required")
    templates = await db.agreement_templates.find({"active": True}, {"_id": 0}).sort("name", 1).to_list(500)
    sigs = await db.agreement_signatures.find({"client_id": user["client_id"]}, {"_id": 0}).sort("signed_at", -1).to_list(1000)
    sig_by_key = {(x.get("template_id"), int(x.get("template_version") or 0)): x for x in sigs}
    out = []
    for t in templates:
        key = (t["id"], int(t.get("version") or 1))
        sig = sig_by_key.get(key)
        out.append({"id": t["id"], "name": t.get("name"), "title": t.get("title"), "body": t.get("body"),
                    "scope_type": t.get("scope_type"), "scope_value": t.get("scope_value"), "version": t.get("version", 1),
                    "required": bool(t.get("required")), "signed": bool(sig), "signature": sig})
    return {"agreements": out}


@api.post("/portal/agreements/{template_id}/sign")
async def portal_sign_agreement(template_id: str, body: AgreementSignIn, request: Request, user: dict = Depends(get_current_user)):
    if user.get("role") != "client" or not user.get("client_id"):
        raise HTTPException(status_code=403, detail="Client account required")
    template = await db.agreement_templates.find_one({"id": template_id, "active": True}, {"_id": 0})
    if not template:
        raise HTTPException(status_code=404, detail="Agreement not found")
    if body.dog_id:
        dog = await db.dogs.find_one({"id": body.dog_id, "owner_id": user["client_id"]}, {"_id": 0, "id": 1})
        if not dog:
            raise HTTPException(status_code=404, detail="Dog not found")
    version = int(template.get("version") or 1)
    existing = await db.agreement_signatures.find_one({"client_id": user["client_id"], "template_id": template_id, "template_version": version}, {"_id": 0})
    if existing:
        return existing
    ts = now_iso()
    doc = {
        "id": str(uuid.uuid4()), "client_id": user["client_id"], "dog_id": body.dog_id,
        "template_id": template_id, "template_version": version,
        "template_snapshot": {"name": template.get("name"), "title": template.get("title"), "body": template.get("body"),
                              "scope_type": template.get("scope_type"), "scope_value": template.get("scope_value")},
        "typed_name": body.typed_name.strip(), "signed_at": ts, "ip": _client_ip(request),
        "user_agent": (request.headers.get("user-agent") or "")[:500],
    }
    await db.agreement_signatures.insert_one(doc.copy())
    doc.pop("_id", None)
    return doc


class WaiverSignIn(BaseModel):
    typed_name: str = Field(min_length=2)
    accepted: bool = True
    dog_names: Optional[str] = ""  # free-text list of dogs covered

@api.get("/waivers/me")
async def my_waiver(user: dict = Depends(get_current_user)):
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    cid = user.get("client_id")
    if not cid:
        return {"signed": False}
    settings = await get_settings()
    current_version = int(settings.get("waiver_version", 1))
    sig = await db.waiver_signatures.find_one(
        {"client_id": cid}, {"_id": 0}, sort=[("signed_at", -1)]
    )
    if not sig:
        return {"signed": False, "current_version": current_version}
    return {
        "signed": True,
        "current_version": current_version,
        "signature": sig,
        "needs_resign": int(sig.get("waiver_version", 1)) < current_version,
    }

@api.post("/waivers/sign")
async def sign_waiver(body: WaiverSignIn, request: Request, user: dict = Depends(get_current_user)):
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    cid = user.get("client_id")
    if not cid:
        raise HTTPException(status_code=400, detail="No client record linked to your account")
    if not body.accepted:
        raise HTTPException(status_code=400, detail="You must accept the terms to sign")
    settings = await get_settings()
    sig = {
        "id": str(uuid.uuid4()),
        "client_id": cid,
        "client_name": user.get("name", ""),
        "typed_name": body.typed_name.strip(),
        "dog_names": body.dog_names or "",
        "waiver_version": int(settings.get("waiver_version", 1)),
        "waiver_text_snapshot": settings.get("waiver_text", ""),
        "ip": request.headers.get("x-forwarded-for", request.client.host if request.client else ""),
        "user_agent": request.headers.get("user-agent", ""),
        "signed_at": now_iso(),
    }
    await db.waiver_signatures.insert_one(sig)
    sig.pop("_id", None)
    return sig

@api.get("/waivers")
async def list_waivers(_: dict = Depends(require_admin)):
    items = await db.waiver_signatures.find({}, {"_id": 0}).sort("signed_at", -1).to_list(2000)
    return items

@api.get("/clients/{client_id}/waiver")
async def client_waiver(client_id: str, _: dict = Depends(require_admin)):
    sig = await db.waiver_signatures.find_one({"client_id": client_id}, {"_id": 0}, sort=[("signed_at", -1)])
    return sig or {"signed": False}


# -------- Incident Reports --------
class IncidentIn(BaseModel):
    dog_id: str
    date: str           # YYYY-MM-DD
    time: Optional[str] = ""  # HH:MM
    # Sprint 110ev — expanded type set (old values retained for back-compat
    # with existing incident rows). New rows should use the granular options.
    type: str = "other"
    # Sprint 110ev — expanded severity tiers. Old minor/moderate/severe are
    # accepted so prior data stays valid; new rows use low/medium/high/critical.
    severity: str = "low"
    description: str = Field(min_length=3)
    witnesses: Optional[str] = ""
    action_taken: Optional[str] = ""
    photos: List[str] = []
    vet_required: bool = False
    follow_up_required: bool = False
    # Sprint 110ev — Phase 5 expansion
    staff_involved: List[str] = []
    manager_reviewed: bool = False
    client_notified: bool = False
    internal_notes: Optional[str] = ""


INCIDENT_TYPES = (
    # New granular options (preferred)
    "bite", "fight", "injury", "illness", "escape_attempt",
    "resource_guarding", "reactivity", "human_directed_aggression",
    "dog_directed_aggression", "property_damage", "other",
    # Legacy values retained for back-compat
    "escape", "behavior",
)
INCIDENT_SEVERITIES = (
    # New canonical tiers
    "low", "medium", "high", "critical",
    # Legacy tiers
    "minor", "moderate", "severe",
)

class IncidentEditHistoryEntry(BaseModel):
    ts: str
    by: str
    reason: str
    changed_fields: List[str] = []


class IncidentUpdateIn(IncidentIn):
    edit_reason: str = Field(min_length=3, description="Why is this incident being edited?")


class IncidentOut(IncidentIn):
    id: str
    dog_name: str
    client_id: str
    client_name: str
    reported_by: str
    created_at: str
    edit_history: List[IncidentEditHistoryEntry] = []

@api.get("/incidents", response_model=List[IncidentOut])
async def list_incidents(_: dict = Depends(require_admin_and_permission("incidents")), dog_id: Optional[str] = None, include_archived: bool = False):
    q: Dict[str, Any] = {"dog_id": dog_id} if dog_id else {}
    if not include_archived:
        q["archived"] = {"$ne": True}
    items = await db.incidents.find(q, {"_id": 0}).sort("date", -1).to_list(2000)
    return items

@api.post("/incidents", response_model=IncidentOut)
async def create_incident(body: IncidentIn, user: dict = Depends(require_admin_and_permission("incidents"))):
    if body.type not in INCIDENT_TYPES:
        raise HTTPException(status_code=400, detail=f"Unknown incident type '{body.type}'. Allowed: {list(INCIDENT_TYPES)}")
    if body.severity not in INCIDENT_SEVERITIES:
        raise HTTPException(status_code=400, detail=f"Unknown severity '{body.severity}'. Allowed: {list(INCIDENT_SEVERITIES)}")
    dog = await db.dogs.find_one({"id": body.dog_id}, {"_id": 0})
    if not dog:
        raise HTTPException(status_code=404, detail="Dog not found")
    client = await db.clients.find_one({"id": dog["owner_id"]}, {"_id": 0})
    doc = body.model_dump()
    doc.update({
        "id": str(uuid.uuid4()),
        "dog_name": dog["name"],
        "client_id": dog["owner_id"],
        "client_name": (client or {}).get("name", ""),
        "reported_by": user.get("name", "Admin"),
        "created_at": now_iso(),
    })
    await db.incidents.insert_one(doc)
    doc.pop("_id", None)
    return doc

@api.put("/incidents/{incident_id}", response_model=IncidentOut)
async def update_incident(incident_id: str, body: IncidentUpdateIn, user: dict = Depends(require_admin_and_permission("incidents"))):
    existing = await db.incidents.find_one({"id": incident_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Incident not found")
    update = body.model_dump(exclude={"edit_reason"})
    # Sprint 110ff — incident edits previously carried no explanation and no
    # visible history, so a quietly downgraded severity looked identical to
    # a typo fix. A reason is now required, and each edit appends to a
    # lightweight history the owner can review without digging through the
    # separate audit log.
    changed_fields = sorted(k for k, v in update.items() if existing.get(k) != v)
    history_entry = {
        "ts": now_iso(),
        "by": user.get("name") or user.get("email") or "admin",
        "reason": body.edit_reason.strip(),
        "changed_fields": changed_fields,
    }
    history = list(existing.get("edit_history") or [])
    history.append(history_entry)
    update["edit_history"] = history
    await db.incidents.update_one({"id": incident_id}, {"$set": update})
    existing.update(update)
    return existing

@api.delete("/incidents/{incident_id}")
async def delete_incident(incident_id: str, user: dict = Depends(require_admin_and_permission("delete_records"))):
    # Sprint 110ff — incidents are a legal/liability record (bite reports,
    # injuries). Deleting one used to be a hard, unrecoverable delete_one
    # with no backup; the audit log could only show THAT something was
    # deleted, not what it said. Archive in place instead so the full
    # record is still recoverable (see POST .../restore) — same pattern
    # already used for clients/dogs elsewhere in this file.
    existing = await db.incidents.find_one({"id": incident_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Incident not found")
    await db.incidents.update_one({"id": incident_id}, {"$set": {
        "archived": True,
        "archived_at": now_iso(),
        "archived_by": user.get("name") or user.get("email") or "admin",
    }})
    return {"ok": True}


@api.post("/incidents/{incident_id}/restore", response_model=IncidentOut)
async def restore_incident(incident_id: str, _: dict = Depends(require_admin)):
    existing = await db.incidents.find_one({"id": incident_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Incident not found")
    await db.incidents.update_one({"id": incident_id}, {"$unset": {
        "archived": "", "archived_at": "", "archived_by": "",
    }})
    existing.pop("archived", None)
    existing.pop("archived_at", None)
    existing.pop("archived_by", None)
    return existing


# -------- Financially locked booking corrections (Admin) --------

async def booking_financial_adjustment(
    booking_id: str, body: BookingFinancialAdjustmentIn, user: dict = Depends(require_admin_and_permission("delete_records")),
):
    owner, keys, client_id, operation_id = await _acquire_booking_financial_correction_guard(booking_id)
    try:
        return await _booking_financial_adjustment_locked(booking_id, body, user)
    finally:
        await _release_booking_financial_correction_guard(owner, keys, client_id, operation_id)


async def _booking_financial_adjustment_locked(
    booking_id: str, body: BookingFinancialAdjustmentIn, user: dict,
):
    booking, booking_collection, _archived = await _load_booking_for_financial_correction(booking_id)
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    if not _booking_is_financially_locked(booking):
        raise HTTPException(status_code=409, detail="This booking is not financially locked; edit it before checkout instead.")

    amount = round(float(body.amount), 2)
    current_total = round(float(booking.get("actual_price") or 0), 2)
    current_paid = round(float(booking.get("amount_paid") or 0), 2)
    current_due = round(float(booking.get("balance_due") or _booking_balance_due(booking)), 2)
    before = {"actual_price": current_total, "amount_paid": current_paid, "balance_due": current_due, "payment_status": booking.get("payment_status")}

    if body.kind == "charge":
        new_total = round(current_total + amount, 2)
        new_due = round(current_due + amount, 2)
        new_status = "paid_partial" if current_paid > 0 else "unpaid"
        balance_delta = amount
        ledger_amount = amount
        ledger_note = f"Post-checkout charge adjustment · {body.reason.strip()}"
    else:
        if current_due <= 0:
            raise HTTPException(status_code=409, detail="There is no unpaid balance to reduce. Use Refund when money has already been collected.")
        applied = min(amount, current_due)
        new_total = round(max(current_paid, current_total - applied), 2)
        new_due = round(max(0.0, current_due - applied), 2)
        new_status = (
            "paid" if new_due <= 0 and current_paid > 0
            else "comped" if new_total <= 0
            else "paid_partial" if current_paid > 0
            else "unpaid"
        )
        amount = applied
        balance_delta = -applied
        ledger_amount = -applied
        ledger_note = f"Post-checkout {body.kind} · {body.reason.strip()}"

    update = {
        "actual_price": new_total,
        "balance_due": new_due,
        "payment_status": new_status,
        "cash_revenue": _cash_revenue({**booking, "actual_price": new_total, "balance_due": new_due, "payment_status": new_status}),
        "financial_adjustment_total": round(float(booking.get("financial_adjustment_total") or 0) + (amount if body.kind == "charge" else -amount), 2),
        "financial_revision": int(booking.get("financial_revision") or 0) + 1,
        "financial_locked": True,
        "financial_locked_at": booking.get("financial_locked_at") or now_iso(),
    }
    balance_applied = False
    ledger_ids: List[str] = []
    event_id = None
    try:
        if booking.get("client_id") and abs(balance_delta) > 0.005:
            await _adjust_client_balance(booking["client_id"], balance_delta)
            balance_applied = True
            ledger_row = await _write_ledger_row(
                client_id=booking["client_id"], type_="adjustment" if body.kind != "charge" else "charge",
                amount=ledger_amount, notes=ledger_note, booking_id=booking_id,
                created_by=user.get("id") or "admin",
            )
            ledger_ids.append(ledger_row["id"])
        result = await booking_collection.update_one({"id": booking_id}, {"$set": update})
        if result.matched_count != 1:
            raise RuntimeError("Booking disappeared during the adjustment")
        after = {"actual_price": new_total, "amount_paid": current_paid, "balance_due": new_due, "payment_status": new_status}
        event = await _record_booking_financial_event(booking, kind=body.kind, amount=amount, reason=body.reason, user=user, before=before, after=after)
        event_id = event.get("id")
    except Exception as exc:
        await booking_collection.replace_one({"id": booking_id}, booking, upsert=False)
        if booking.get("client_id") and balance_applied:
            await db.clients.update_one({"id": booking["client_id"]}, {"$inc": {"account_balance": -float(balance_delta)}})
        if ledger_ids:
            await db.payment_ledger.delete_many({"id": {"$in": ledger_ids}})
        if event_id:
            await db.booking_financial_events.delete_one({"id": event_id})
        logger.exception("Financial adjustment rolled back for booking %s", booking_id)
        raise HTTPException(status_code=500, detail="The adjustment could not be saved safely. No financial changes were kept.") from exc
    booking.update(update)
    return booking


async def booking_refund(booking_id: str, body: BookingRefundIn, user: dict = Depends(require_admin_and_permission("delete_records"))):
    owner, keys, client_id, operation_id = await _acquire_booking_financial_correction_guard(booking_id)
    try:
        return await _booking_refund_locked(booking_id, body, user)
    finally:
        await _release_booking_financial_correction_guard(owner, keys, client_id, operation_id)


async def _booking_refund_locked(booking_id: str, body: BookingRefundIn, user: dict):
    booking, booking_collection, _archived = await _load_booking_for_financial_correction(booking_id)
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    if not _booking_is_financially_locked(booking):
        raise HTTPException(status_code=409, detail="This booking has not been checked out.")

    # Payment rebuild Phase 1 — claim the idempotency key BEFORE any
    # mutation (and before the refundable-amount check below, so a genuine
    # retry resolves to the ORIGINAL result rather than being re-validated
    # against numbers that may have since changed). This is claim-before-
    # mutate, not check-then-act: a "check first, mutate, then insert the
    # unique key" sequence has a race window where two simultaneous
    # requests both pass the check and both mutate before either insert
    # resolves. Only the request that wins this insert may mutate anything.
    claim_id = None
    if body.refund_idempotency_key:
        claim_id = str(uuid.uuid4())
        try:
            await db.refund_idempotency_claims.insert_one({
                "id": claim_id, "refund_idempotency_key": body.refund_idempotency_key,
                "booking_id": booking_id, "status": "processing", "event_id": None,
                "created_at": now_iso(), "updated_at": now_iso(),
            })
        except DuplicateKeyError:
            existing_claim = await db.refund_idempotency_claims.find_one(
                {"refund_idempotency_key": body.refund_idempotency_key}, {"_id": 0},
            )
            if existing_claim and existing_claim.get("status") == "completed":
                current = await booking_collection.find_one({"id": booking_id}, {"_id": 0})
                return current or booking
            raise HTTPException(status_code=409, detail="This refund is already being processed. Wait a moment and try again.")

    try:
        originally_paid = round(float(booking.get("amount_paid") or booking.get("cash_revenue") or 0), 2)
        # Payment rebuild Phase 2 — the booking's own amount_paid is a
        # frozen checkout-time snapshot; a later invoice top-up (Phase 2)
        # never rewrites it, so a refund against post-closeout top-up money
        # would otherwise be incorrectly capped at the original checkout
        # amount. invoice.amount_paid stays authoritative through any
        # number of top-ups/voids (a void applies the inverse delta, so a
        # voided top-up already contributes nothing here — no separate
        # bookkeeping needed). Only used for a SINGLE-booking invoice —
        # never the combined total of a multi-booking group invoice, so one
        # dog's refund can never be inflated by another dog's payment
        # (safe today because a Phase-2 top-up against a group invoice can
        # never occur — group invoices always have balance=0 at creation).
        invoice_for_refund_ceiling = await db.invoices.find_one(
            {"booking_ids": booking_id}, {"_id": 0, "id": 1, "booking_ids": 1, "amount_paid": 1}
        )
        if invoice_for_refund_ceiling and len(invoice_for_refund_ceiling.get("booking_ids") or []) == 1:
            invoice_amount_paid = round(float(invoice_for_refund_ceiling.get("amount_paid") or 0), 2)
            # Stripe Online (Phase 3A) — original Stripe-collected dollars can
            # NEVER be refunded through this local-only mechanism; they stay
            # permanently in the Stripe refund lane (POST /payments/{id}/
            # stripe-refund), regardless of whether any of them have already
            # been refunded there. Sum only ORIGINAL positive stripe_online
            # collection Payment rows, explicitly excluding reversal rows by
            # their canonical source.kind — never inferred from sign alone.
            stripe_gross = 0.0
            async for p in db.payments.find(
                {
                    "invoice_id": invoice_for_refund_ceiling["id"], "method": "stripe_online",
                    "status": "completed", "amount": {"$gt": 0}, "source.kind": {"$ne": "stripe_refund"},
                },
                {"_id": 0, "amount": 1},
            ):
                stripe_gross += float(p.get("amount") or 0)
            originally_paid = round(invoice_amount_paid - round(stripe_gross, 2), 2)
        already_refunded = round(float(booking.get("financial_refund_total") or 0), 2)
        refundable = round(max(0.0, originally_paid - already_refunded), 2)
        amount = round(float(body.amount), 2)
        if amount > refundable + 0.005:
            raise HTTPException(status_code=409, detail=f"Refund cannot exceed the remaining refundable cash (${refundable:.2f}).")
        await _require_register_day_open(business_today().isoformat())

        # Preserve the original invoice and original payment exactly as checked out.
        # The refund is a new negative cash event on today's books. Rewriting the
        # old booking would move historical revenue and then the refund row would
        # subtract it again, producing a double-counted loss.
        old_total = round(float(booking.get("actual_price") or 0), 2)
        old_due = round(float(booking.get("balance_due") or 0), 2)
        old_tax = round(float(booking.get("tax_amount") or 0), 2)
        tax_refund = round(old_tax * min(1.0, amount / originally_paid), 2) if originally_paid > 0 else 0.0
        new_refund_total = round(already_refunded + amount, 2)
        update = {
            "financial_refund_total": new_refund_total,
            "financial_refund_status": "full" if new_refund_total >= originally_paid - 0.005 else "partial",
            "financial_last_refund_at": now_iso(),
            "financial_revision": int(booking.get("financial_revision") or 0) + 1,
            "financial_locked": True,
        }
        refund_row = {
            "id": str(uuid.uuid4()), "date": business_today().isoformat(),
            "description": f"Booking refund · {booking.get('dog_name') or ''} · {body.reason.strip()}",
            "amount": -amount, "tax_amount": -tax_refund, "category": "Refund", "notes": body.reason.strip(),
            "payment_method": _normalize_payment_method(body.payment_method, store=True),
            "client_id": booking.get("client_id"), "client_name": booking.get("client_name"),
            "booking_id": booking_id, "source_kind": "refund", "created_at": now_iso(),
            "created_by": user.get("id"), "logged_by": user.get("name") or user.get("email") or "admin",
        }
        ledger_ids: List[str] = []
        event_id = None
        try:
            await db.retail_sales.insert_one(refund_row.copy())
            if booking.get("client_id"):
                # The invoice reduction and cash return are separate append-only ledger
                # entries with a net-zero client-tab effect.
                row1 = await _write_ledger_row(client_id=booking["client_id"], type_="adjustment", amount=-amount, notes=f"Refund invoice adjustment · {body.reason.strip()}", booking_id=booking_id, created_by=user.get("id") or "admin")
                row2 = await _write_ledger_row(client_id=booking["client_id"], type_="refund", amount=amount, method=body.payment_method, notes=f"Cash returned · {body.reason.strip()}", booking_id=booking_id, created_by=user.get("id") or "admin")
                ledger_ids.extend([row1["id"], row2["id"]])
            result = await booking_collection.update_one({"id": booking_id}, {"$set": update})
            if result.matched_count != 1:
                raise RuntimeError("Booking disappeared during the refund")
            before = {"actual_price": old_total, "amount_paid": originally_paid, "balance_due": old_due, "payment_status": booking.get("payment_status"), "refunded": already_refunded}
            after = {"actual_price": old_total, "amount_paid": originally_paid, "balance_due": old_due, "payment_status": booking.get("payment_status"), "refunded": new_refund_total}
            event = await _record_booking_financial_event(booking, kind="refund", amount=amount, reason=body.reason, user=user, before=before, after=after, payment_method=body.payment_method)
            event_id = event.get("id")
            try:
                await _apply_refund_to_invoice(
                    booking_id=booking_id, amount=amount, method=body.payment_method,
                    reason=body.reason, event_id=event_id, user=user, ts=now_iso(),
                )
            except Exception as exc:
                logger.warning("invoice refund-payment recording failed for booking %s: %s", booking_id, exc)
        except Exception as exc:
            await booking_collection.replace_one({"id": booking_id}, booking, upsert=False)
            await db.retail_sales.delete_one({"id": refund_row["id"]})
            if ledger_ids:
                await db.payment_ledger.delete_many({"id": {"$in": ledger_ids}})
            if event_id:
                await db.booking_financial_events.delete_one({"id": event_id})
            logger.exception("Booking refund rolled back for %s", booking_id)
            raise HTTPException(status_code=500, detail="The refund could not be saved safely. No refund was recorded.") from exc
        if claim_id:
            await db.refund_idempotency_claims.update_one(
                {"id": claim_id}, {"$set": {"status": "completed", "event_id": event_id, "updated_at": now_iso()}},
            )
        booking.update(update)
        return booking
    except Exception:
        if claim_id:
            await db.refund_idempotency_claims.delete_one({"id": claim_id})
        raise


async def reopen_booking_checkout(booking_id: str, body: BookingReopenCheckoutIn, user: dict = Depends(require_admin_and_permission("delete_records"))):
    owner, keys, client_id, operation_id = await _acquire_booking_financial_correction_guard(booking_id)
    try:
        return await _reopen_booking_checkout_locked(booking_id, body, user)
    finally:
        await _release_booking_financial_correction_guard(owner, keys, client_id, operation_id)


async def _reopen_booking_checkout_locked(booking_id: str, body: BookingReopenCheckoutIn, user: dict):
    booking, booking_collection, archived = await _load_booking_for_financial_correction(booking_id)
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    if archived:
        raise HTTPException(status_code=409, detail="Archived bookings cannot be reopened. Use an adjustment or refund instead.")
    if not _booking_is_financially_locked(booking):
        raise HTTPException(status_code=409, detail="This checkout is already open.")
    paid = float(booking.get("amount_paid") or booking.get("cash_revenue") or 0)
    credits = float(booking.get("credits_deducted") or 0)
    refunds = float(booking.get("financial_refund_total") or 0)
    if paid > 0.005 or credits > 0.005 or refunds > 0.005:
        raise HTTPException(
            status_code=409,
            detail="This checkout has money or credits attached and cannot be reopened safely. Use an adjustment or refund instead.",
        )
    due = round(float(booking.get("balance_due") or _booking_balance_due(booking)), 2)
    ledger_rows = await db.payment_ledger.find({"booking_id": booking_id}, {"_id": 0, "amount": 1}).to_list(500)
    ledger_net = round(sum(float(row.get("amount") or 0) for row in ledger_rows), 2)
    balance_applied = False
    ledger_row_id = None
    ts = now_iso()
    history = list(booking.get("financial_reopen_history") or [])
    history.append({"at": ts, "by": user.get("id"), "by_name": user.get("name") or user.get("email"), "reason": body.reason.strip(), "prior_total": booking.get("actual_price"), "prior_status": booking.get("payment_status")})
    set_update = {
        "status": "approved", "financial_locked": False, "financial_reopened_at": ts,
        "financial_reopened_reason": body.reason.strip(), "financial_reopen_history": history,
        "financial_revision": int(booking.get("financial_revision") or 0) + 1,
    }
    unset_update = {k: "" for k in [
        "checked_out_at", "checked_out_by", "checked_out_by_name", "checked_out_lat", "checked_out_lng",
        "checked_out_accuracy_m", "actual_price", "payment_status", "payment_method", "paid_at",
        "amount_paid", "balance_due", "cash_revenue", "tax_amount", "tax_rate_pct",
        "taxable_cash_amount", "additional_cash_charge", "money_modifier_breakdown",
    ]}
    event_id = None
    try:
        if abs(ledger_net) > 0.005 and booking.get("client_id"):
            await _adjust_client_balance(booking["client_id"], -ledger_net)
            balance_applied = True
            reversal = await _write_ledger_row(client_id=booking["client_id"], type_="adjustment", amount=-ledger_net, notes=f"Reopened checkout · {body.reason.strip()}", booking_id=booking_id, created_by=user.get("id") or "admin")
            ledger_row_id = reversal["id"]
        result = await booking_collection.update_one({"id": booking_id}, {"$set": set_update, "$unset": unset_update})
        if result.matched_count != 1:
            raise RuntimeError("Booking disappeared while reopening checkout")
        before = {"actual_price": booking.get("actual_price"), "amount_paid": booking.get("amount_paid"), "balance_due": due, "payment_status": booking.get("payment_status")}
        after = {"actual_price": None, "amount_paid": None, "balance_due": None, "payment_status": None}
        event = await _record_booking_financial_event(booking, kind="reopen", amount=0, reason=body.reason, user=user, before=before, after=after)
        event_id = event.get("id")
    except Exception as exc:
        await booking_collection.replace_one({"id": booking_id}, booking, upsert=False)
        if booking.get("client_id") and balance_applied:
            await db.clients.update_one({"id": booking["client_id"]}, {"$inc": {"account_balance": float(ledger_net)}})
        if ledger_row_id:
            await db.payment_ledger.delete_one({"id": ledger_row_id})
        if event_id:
            await db.booking_financial_events.delete_one({"id": event_id})
        logger.exception("Checkout reopen rolled back for %s", booking_id)
        raise HTTPException(status_code=500, detail="Checkout could not be reopened safely. No changes were kept.") from exc
    booking.update(set_update)
    for key in unset_update:
        booking.pop(key, None)
    return booking


# -------- Booking Edit (Admin) --------
class BookingPatchIn(BaseModel):
    notes: Optional[str] = None
    date: Optional[str] = None
    end_date: Optional[str] = None
    kennel: Optional[str] = None
    dropoff_time: Optional[str] = None
    pickup_time: Optional[str] = None
    time: Optional[str] = None  # appointment time for training/grooming/photography
    # Sprint 110eu — Phase 4: Kennel/Daycare board assignments
    room: Optional[str] = None
    crate: Optional[str] = None
    yard_group: Optional[str] = None
    training_group: Optional[str] = None

async def patch_booking(booking_id: str, body: BookingPatchIn, _: dict = Depends(require_admin)):
    booking = await db.bookings.find_one({"id": booking_id}, {"_id": 0})
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    update = {k: v for k, v in body.model_dump(exclude_unset=True).items() if v is not None}
    _assert_booking_financial_edit_allowed(booking, update.keys())
    if update:
        if update.get("crate"):
            conflict = await _crate_conflict(
                booking_id,
                update.get("date", booking.get("date")),
                update.get("end_date", booking.get("end_date")),
                update["crate"],
            )
            if conflict:
                raise HTTPException(
                    status_code=409,
                    detail=f"{update['crate']} is already assigned to {conflict.get('dog_name', 'another dog')} on overlapping dates.",
                )
        capacity_fields = {"kennel", "time", "dropoff_time", "pickup_time", "date", "end_date"}
        if capacity_fields.intersection(update):
            return await _update_booking_with_capacity(booking, update)
        await db.bookings.update_one({"id": booking_id}, {"$set": update})
        booking.update(update)
    return booking


# -------- Dog Lifetime Stats --------
@api.get("/dogs/{dog_id}/stats")
async def dog_stats(dog_id: str, _: dict = Depends(require_admin)):
    dog = await db.dogs.find_one({"id": dog_id}, {"_id": 0})
    if not dog:
        raise HTTPException(status_code=404, detail="Dog not found")
    bookings = await _booking_rows_anywhere({"dog_id": dog_id}, {"_id": 0}, limit=5000, sort_field="date")
    daycare_days = 0
    boarding_nights = 0
    training_sessions = 0
    last_visit = None
    today = business_today().isoformat()
    for b in bookings:
        if b["status"] in ("cancelled", "rejected"):
            continue
        days = _dates_in_range(b["date"], b.get("end_date"))
        past_days = [d for d in days if d <= today]
        if b["service_type"] == "daycare":
            daycare_days += len(past_days)
        elif b["service_type"] == "boarding":
            # Boarding stats are billable nights, not inclusive presence dates.
            # July 1 → July 4 is 3 nights even though the dog is present on 4 dates.
            checkout_cutoff = min(b.get("end_date") or b.get("date"), today)
            boarding_nights += _billable_boarding_nights(b.get("date"), checkout_cutoff, legacy_minimum=0)
        elif b["service_type"] == "training":
            training_sessions += len(past_days)
        if past_days:
            last_visit = max(past_days) if not last_visit else max(last_visit, max(past_days))
    incidents_count = await db.incidents.count_documents({"dog_id": dog_id})
    homework_completed = await db.homework.count_documents({"dog_id": dog_id, "status": "completed"})
    homework_assigned = await db.homework.count_documents({"dog_id": dog_id, "status": "assigned"})
    return {
        "dog_id": dog_id,
        "daycare_days": daycare_days,
        "boarding_nights": boarding_nights,
        "training_sessions": training_sessions,
        "last_visit": last_visit,
        "incidents": incidents_count,
        "homework_completed": homework_completed,
        "homework_assigned": homework_assigned,
    }


# -------- Search --------
def _search_re(q: str):
    return {"$regex": re.escape(q), "$options": "i"}


@api.get("/search")
async def search(q: str, user: dict = Depends(require_admin)):
    """Global search — clients, dogs, bookings, invoices, payments, shop
    orders, and prepaid-visit purchases (credit lots). Each result kind is
    independently gated by the same permission that governs viewing that
    resource elsewhere in the app, so a role that can't see financial data
    via its normal screens can't see it via search either. Uses indexed
    Mongo regex queries with small per-kind limits rather than pulling
    whole collections into memory — this used to load every client and
    every dog on every keystroke."""
    q = q.strip()
    empty = {"clients": [], "dogs": [], "bookings": [], "invoices": [],
              "payments": [], "shop_orders": [], "prepaid_purchases": []}
    if len(q) < 1:
        return empty
    perms = _perms_for(user)
    rx = _search_re(q)
    ref_rx = {"$regex": f"^{re.escape(q)}", "$options": "i"}  # for id-prefix "reference number" lookups

    out = dict(empty)

    # ── Clients ──────────────────────────────────────────────────────────
    matched_clients = []
    if perms.get("clients_view"):
        matched_clients = await db.clients.find(
            {"$or": [{"name": rx}, {"email": rx}, {"phone": rx}]}, {"_id": 0},
        ).limit(8).to_list(8)
        out["clients"] = [
            {"id": c["id"], "name": c["name"], "email": c.get("email"), "phone": c.get("phone")}
            for c in matched_clients
        ]
    client_ids_by_search = {c["id"] for c in matched_clients}
    client_name_by_id = {c["id"]: c["name"] for c in matched_clients}
    # Resolve names for clients we'll reference below but didn't match directly
    async def _client_names_for(ids):
        missing = [i for i in ids if i and i not in client_name_by_id]
        if not missing:
            return
        rows = await db.clients.find({"id": {"$in": missing}}, {"_id": 0, "id": 1, "name": 1}).to_list(len(missing))
        for r in rows:
            client_name_by_id[r["id"]] = r["name"]

    # ── Dogs ─────────────────────────────────────────────────────────────
    matched_dogs = []
    if perms.get("dogs_view"):
        matched_dogs = await db.dogs.find(
            {"$or": [{"name": rx}, {"breed": rx}]}, {"_id": 0},
        ).limit(8).to_list(8)
        owner_ids = [d.get("owner_id") for d in matched_dogs if d.get("owner_id")]
        await _client_names_for(owner_ids)
        today = business_today().isoformat()
        # Phase 6 — batch the upcoming-booking lookup. Global search used to
        # execute one extra Mongo query per dog result (up to eight on every
        # keystroke). One indexed query now serves the whole result set.
        dog_ids = [d.get("id") for d in matched_dogs if d.get("id")]
        upcoming_by_dog: Dict[str, Dict[str, Any]] = {}
        if dog_ids:
            upcoming_rows = await db.bookings.find(
                {"dog_id": {"$in": dog_ids}, "date": {"$gte": today},
                 "status": {"$in": ["approved", "pending"]}},
                {"_id": 0, "dog_id": 1, "date": 1, "service_type": 1},
            ).sort("date", 1).to_list(200)
            for row in upcoming_rows:
                did = row.get("dog_id")
                if did and did not in upcoming_by_dog:
                    upcoming_by_dog[did] = row
        for d in matched_dogs:
            nb = upcoming_by_dog.get(d.get("id"))
            upcoming = f"{nb['service_type'].title()} {nb['date']}" if nb else None
            out["dogs"].append({
                "id": d["id"], "name": d["name"], "breed": d.get("breed"),
                "owner_id": d.get("owner_id"), "owner_name": client_name_by_id.get(d.get("owner_id"), ""),
                "upcoming": upcoming,
            })

    # ── Bookings — match by dog/client name (denormalized) or id prefix ──
    booking_or = [{"dog_name": rx}, {"client_name": rx}]
    if len(q) >= 3:
        booking_or.append({"id": ref_rx})
    # Both collections: a booking reference pasted from an old receipt or
    # email must still resolve after the row was archived.
    matched_bookings = await _booking_rows_anywhere({"$or": booking_or}, {"_id": 0}, limit=8, sort_field="date", sort_desc=True)
    for b in matched_bookings:
        out["bookings"].append({
            "id": b["id"], "dog_id": b.get("dog_id"), "dog_name": b.get("dog_name"),
            "client_id": b.get("client_id"), "client_name": b.get("client_name"),
            "service_type": b.get("service_type"), "date": b.get("date"), "end_date": b.get("end_date"),
            "status": b.get("status"), "reference": b["id"][:8].upper(),
        })

    # ── Invoices / Bills — financial, gated on finance_reports ──────────
    if perms.get("finance_reports"):
        inv_or = [{"client_name": rx}]
        if len(q) >= 3:
            inv_or.append({"id": ref_rx})
        matched_invoices = await db.invoices.find(
            {"$or": inv_or, "status": {"$ne": "VOID"}}, {"_id": 0},
        ).sort("date", -1).limit(8).to_list(8)
        for inv in matched_invoices:
            out["invoices"].append({
                "id": inv["id"], "client_id": inv.get("client_id"), "client_name": inv.get("client_name"),
                "total": inv.get("total"), "balance": inv.get("balance"), "status": inv.get("status"),
                "date": inv.get("date"), "reference": inv["id"][:8].upper(),
            })

        # ── Payments — no denormalized client_name, so resolve via matched clients ──
        pay_or = []
        if client_ids_by_search:
            pay_or.append({"client_id": {"$in": list(client_ids_by_search)}})
        if len(q) >= 3:
            pay_or.append({"id": ref_rx})
        if pay_or:
            matched_payments = await db.payments.find({"$or": pay_or}, {"_id": 0}).sort("date", -1).limit(8).to_list(8)
            payer_ids = [p.get("client_id") for p in matched_payments if p.get("client_id")]
            await _client_names_for(payer_ids)
            for p in matched_payments:
                out["payments"].append({
                    "id": p["id"], "client_id": p.get("client_id"),
                    "client_name": client_name_by_id.get(p.get("client_id"), ""),
                    "amount": p.get("amount"), "method": p.get("method"), "status": p.get("status"),
                    "date": p.get("date"), "reference": p["id"][:8].upper(),
                })

    # ── Shop orders — gated on take_payments, matching the real fulfillment endpoint ──
    if perms.get("take_payments"):
        order_or = [{"client_name": rx}]
        if len(q) >= 3:
            order_or.append({"id": ref_rx})
        matched_orders = await db.shop_orders.find({"$or": order_or}, {"_id": 0}).sort("created_at", -1).limit(8).to_list(8)
        for o in matched_orders:
            out["shop_orders"].append({
                "id": o["id"], "client_id": o.get("client_id"), "client_name": o.get("client_name"),
                "total": o.get("total"), "status": o.get("status"),
                "fulfillment_status": o.get("fulfillment_status"), "pickup_status": o.get("pickup_status"),
                "reference": o["id"][:8].upper(),
            })

    # ── Prepaid-visit purchases (credit lots) — financial, gated on finance_reports ──
    if perms.get("finance_reports"):
        lot_or = []
        if client_ids_by_search:
            lot_or.append({"client_id": {"$in": list(client_ids_by_search)}})
        lot_or.append({"pack_name": rx})
        lot_or.append({"program_name": rx})
        matched_lots = await db.credit_lots.find({"$or": lot_or}, {"_id": 0}).sort("purchased_at", -1).limit(8).to_list(8)
        lot_client_ids = [l.get("client_id") for l in matched_lots if l.get("client_id")]
        await _client_names_for(lot_client_ids)
        for lot in matched_lots:
            out["prepaid_purchases"].append({
                "id": lot["id"], "client_id": lot.get("client_id"),
                "client_name": client_name_by_id.get(lot.get("client_id"), ""),
                "pack_name": lot.get("pack_name") or lot.get("program_name"),
                "qty_total": lot.get("qty_total"), "qty_remaining": lot.get("qty_remaining"),
                "price_paid": lot.get("price_paid"),
            })

    return out


