class TrainingDayTrainerAssignmentIn(BaseModel):
    assigned_trainer_id: Optional[str] = None


@api.patch("/admin/training/today/{booking_id}/trainer")
async def assign_training_booking_trainer(
    booking_id: str, body: TrainingDayTrainerAssignmentIn,
    user: dict = Depends(require_admin_and_permission("manage_training_sessions")),
):
    """Assign/reassign one TODAY training booking to the trainer responsible.

    Kept on the existing booking instead of inventing a second daily schedule.
    Only an Admin may change ownership; the target must be active staff with
    manage_training_sessions.  Every change is appended to an audit history.
    """
    if user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin access required to assign today's training dogs.")
    booking = await db.bookings.find_one({"id": booking_id}, {"_id": 0})
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    if booking.get("service_type") != "training":
        raise HTTPException(status_code=422, detail="Only training bookings can be assigned to a trainer.")
    today = business_today().isoformat()
    if not _booking_covers_training_day(booking, today):
        raise HTTPException(status_code=409, detail="This assignment endpoint is for today's training roster only.")

    trainer_id = body.assigned_trainer_id or None
    trainer_name = None
    if trainer_id:
        trainer = await db.users.find_one(
            {"id": trainer_id, "role": {"$in": ["admin", "employee"]}, "active": {"$ne": False}},
            {"_id": 0},
        )
        if not trainer or not _perms_for(trainer).get("manage_training_sessions"):
            raise HTTPException(status_code=422, detail="Assigned trainer is not active or cannot run training sessions.")
        trainer_name = trainer.get("display_name") or trainer.get("name") or trainer.get("email") or "Trainer"

    event = {
        "at": now_iso(), "business_date": today,
        "assigned_trainer_id": trainer_id, "assigned_trainer_name": trainer_name,
        "by_user_id": user.get("id"), "by_user_name": user.get("name") or user.get("email") or "Admin",
    }
    assignment_path = f"training_daily_assignments.{today}"
    update_doc: Dict[str, Any] = {"$push": {"training_assignment_history": event}}
    if trainer_id:
        update_doc["$set"] = {assignment_path: {
            "assigned_trainer_id": trainer_id,
            "assigned_trainer_name": trainer_name,
            "assigned_at": event["at"],
            "assigned_by": user.get("id"),
        }}
    else:
        update_doc["$unset"] = {assignment_path: ""}
    await db.bookings.update_one({"id": booking_id}, update_doc)
    return {
        "booking_id": booking_id, "business_date": today,
        "assigned_trainer_id": trainer_id, "assigned_trainer": trainer_name,
        "assignment_source": "daily" if trainer_id else "unassigned",
    }


async def get_training_context_for_booking(booking_id: str, _: dict = Depends(require_admin_and_permission("manage_training_sessions"))):
    """Return the active training-program context for the dog on this booking,
    so the check-in flow can decide whether to surface the Training Tracker."""
    booking = await db.bookings.find_one({"id": booking_id}, {"_id": 0})
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    dog_id = booking.get("dog_id")
    if not dog_id:
        return {"has_program": False, "reason": "no_dog_on_booking"}
    # Online School hardening audit — booking check-in is a trainer-led
    # flow; it must resolve the dog's trainer-led enrollment even when an
    # online_school enrollment is also active, rather than nondeterministically
    # picking whichever Mongo returns first.
    enrollment = await db.dog_programs.find_one(
        {"dog_id": dog_id, "status": "active", "delivery_channel": {"$in": list(STAFF_SCHOOL_DELIVERY_CHANNELS)}}, {"_id": 0},
    )
    if not enrollment:
        legacy = await db.dog_programs.find_one(
            {"dog_id": dog_id, "status": "active",
             "delivery_channel": {"$nin": list(SCHOOL_DELIVERY_CHANNELS)}},
            {"_id": 0},
        )
        if legacy:
            return {
                "has_program": False, "reason": "legacy_curriculum_requires_migration", "dog_id": dog_id,
                "legacy_enrollment_id": legacy.get("id"), "legacy_program_id": legacy.get("program_id"),
                "legacy_program_name": (legacy.get("program_snapshot") or {}).get("name") or "Retired legacy training",
            }
        return {"has_program": False, "reason": "no_active_enrollment", "dog_id": dog_id}
    ctx = await _build_training_context(enrollment)
    dog = await db.dogs.find_one({"id": dog_id}, {"_id": 0, "name": 1, "id": 1}) or {}
    ctx["dog"] = {"id": dog_id, "name": dog.get("name") or ""}
    ctx["booking_id"] = booking_id
    return ctx


@api.get("/dogs/{dog_id}/programs/{enrollment_id}/training-context")
async def get_training_context_direct(dog_id: str, enrollment_id: str, _: dict = Depends(require_admin_and_permission("manage_training_sessions"))):
    """Direct fetch (Care Board / dog profile entry points — no booking)."""
    enrollment = await db.dog_programs.find_one(
        {"id": enrollment_id, "dog_id": dog_id}, {"_id": 0},
    )
    if not enrollment:
        raise HTTPException(status_code=404, detail="Enrollment not found")
    # Online School hardening audit — this endpoint is id-scoped (already
    # safe against cross-enrollment leakage), but is a trainer scorecard
    # view. Defense in depth: reject explicitly rather than rendering
    # trainer goal_progress/scores for a self-guided enrollment.
    if enrollment.get("delivery_channel") not in STAFF_SCHOOL_DELIVERY_CHANNELS:
        raise HTTPException(status_code=409, detail="This enrollment is not an active In-Person/Hybrid School training record. Legacy training is read-only and must be migrated before it can continue.")
    ctx = await _build_training_context(enrollment)
    dog = await db.dogs.find_one({"id": dog_id}, {"_id": 0, "name": 1, "id": 1}) or {}
    ctx["dog"] = {"id": dog_id, "name": dog.get("name") or ""}
    return ctx


@api.get("/dogs/{dog_id}/programs/{enrollment_id}/session-log")
async def list_training_session_log(
    dog_id: str, enrollment_id: str, limit: int = 50,
    _: dict = Depends(require_admin_and_permission("manage_training_sessions")),
):
    """Activity feed for the dog/enrollment. Newest first.

    A migrated School enrollment carries ``legacy_history_enrollment_ids`` so
    the trainer can still see the dog's pre-migration session history without
    making those retired rows current/assignable again.
    """
    enrollment = await db.dog_programs.find_one({"id": enrollment_id, "dog_id": dog_id}, {"_id": 0, "legacy_history_enrollment_ids": 1})
    if not enrollment:
        raise HTTPException(status_code=404, detail="Enrollment not found")
    lineage_ids = [enrollment_id] + [
        eid for eid in (enrollment.get("legacy_history_enrollment_ids") or []) if eid and eid != enrollment_id
    ]
    cur = db.training_session_log.find(
        {"dog_id": dog_id, "enrollment_id": {"$in": lineage_ids}}, {"_id": 0},
    ).sort("at", -1).limit(max(1, min(limit, 500)))
    return await cur.to_list(500)


@api.get("/admin/training/trainer-scorecard")
async def trainer_scorecard(days: int = 30, _: dict = Depends(require_admin_and_permission("manage_training_content"))):
    """Sprint 110di-71 — Per-trainer 30-day rollup from training_session_log.
    Counts sessions logged, distinct dogs worked with, skills moved to mastered
    (status transitions to 'mastered' OR score crossing into 4-5), and module
    advances. Window is `days` rolling back from now (default 30, max 365)."""
    days = max(1, min(int(days or 30), 365))
    since = datetime.now(timezone.utc) - timedelta(days=days)
    since_iso = since.isoformat()

    cur = db.training_session_log.find(
        {"at": {"$gte": since_iso}}, {"_id": 0},
    )
    sessions = await cur.to_list(10000)

    # Sprint 110di-72 — Resolve dog + enrollment names once so per-dog
    # breakdowns can show real names. Single batched query each.
    all_dog_ids = list({s.get("dog_id") for s in sessions if s.get("dog_id")})
    all_eids = list({s.get("enrollment_id") for s in sessions if s.get("enrollment_id")})
    dog_rows = await db.dogs.find(
        {"id": {"$in": all_dog_ids}}, {"_id": 0, "id": 1, "name": 1, "owner_id": 1},
    ).to_list(5000) if all_dog_ids else []
    dog_lookup = {d["id"]: d for d in dog_rows}
    owner_ids = list({d.get("owner_id") for d in dog_rows if d.get("owner_id")})
    client_rows = await db.clients.find(
        {"id": {"$in": owner_ids}}, {"_id": 0, "id": 1, "name": 1},
    ).to_list(5000) if owner_ids else []
    client_lookup = {c["id"]: c.get("name") for c in client_rows}
    enr_rows = await db.dog_programs.find(
        {"id": {"$in": all_eids}}, {"_id": 0, "id": 1, "program_snapshot.name": 1},
    ).to_list(5000) if all_eids else []
    enr_lookup = {e["id"]: ((e.get("program_snapshot") or {}).get("name") or "") for e in enr_rows}

    by_trainer: Dict[str, Dict] = {}
    for s in sessions:
        key = (s.get("by_email") or s.get("by_user") or "unknown").lower()
        bucket = by_trainer.setdefault(key, {
            "trainer_key": key,
            "trainer_name": s.get("by_user") or s.get("by_email") or "Unknown",
            "trainer_email": s.get("by_email"),
            "session_count": 0,
            "dogs": {},
            "skills_mastered": 0,
            "modules_advanced": 0,
            "last_session_at": None,
            "session_notes": 0,
        })
        bucket["session_count"] += 1
        # Per-dog sub-bucket
        dog_id = s.get("dog_id")
        if dog_id:
            dbucket = bucket["dogs"].setdefault(dog_id, {
                "dog_id": dog_id,
                "dog_name": (dog_lookup.get(dog_id) or {}).get("name") or "Dog",
                "client_name": client_lookup.get((dog_lookup.get(dog_id) or {}).get("owner_id")) or "",
                "enrollment_id": s.get("enrollment_id"),
                "program_name": enr_lookup.get(s.get("enrollment_id")) or "",
                "session_count": 0,
                "skills_moved": 0,
                "skills_mastered": 0,
                "modules_advanced": 0,
                "last_session_at": None,
                "recent_diffs": [],
            })
            dbucket["session_count"] += 1
            if s.get("advanced_module"):
                dbucket["modules_advanced"] += 1
            at = s.get("at")
            if at and (not dbucket["last_session_at"] or at > dbucket["last_session_at"]):
                dbucket["last_session_at"] = at
        for d in (s.get("goal_updates") or []):
            prior = (d.get("prior_status") or "")
            new = (d.get("new_status") or "")
            prior_score = int(d.get("prior_score") or 0)
            new_score = int(d.get("new_score") or 0)
            mastered_event = (new == "mastered" and prior != "mastered") or (new_score >= 4 and prior_score < 4)
            moved = prior != new or prior_score != new_score
            if mastered_event:
                bucket["skills_mastered"] += 1
            if dog_id:
                dbucket = bucket["dogs"].get(dog_id)
                if dbucket is not None:
                    if mastered_event:
                        dbucket["skills_mastered"] += 1
                    if moved:
                        dbucket["skills_moved"] += 1
                        # Keep last 5 diff blurbs newest-first
                        if len(dbucket["recent_diffs"]) < 5:
                            dbucket["recent_diffs"].append({
                                "goal_id": d.get("goal_id"),
                                "prior_status": prior, "new_status": new,
                                "prior_score": prior_score, "new_score": new_score,
                                "at": s.get("at"),
                            })
        if s.get("advanced_module"):
            bucket["modules_advanced"] += 1
        if (s.get("session_note") or "").strip():
            bucket["session_notes"] += 1
        at = s.get("at")
        if at and (not bucket["last_session_at"] or at > bucket["last_session_at"]):
            bucket["last_session_at"] = at

    rows = []
    for b in by_trainer.values():
        dogs_list = sorted(
            b["dogs"].values(),
            key=lambda x: (-x["session_count"], -(x["skills_mastered"] or 0)),
        )
        rows.append({
            "trainer_key": b["trainer_key"],
            "trainer_name": b["trainer_name"],
            "trainer_email": b["trainer_email"],
            "session_count": b["session_count"],
            "unique_dogs": len(b["dogs"]),
            "skills_mastered": b["skills_mastered"],
            "modules_advanced": b["modules_advanced"],
            "session_notes": b["session_notes"],
            "last_session_at": b["last_session_at"],
            "dogs": dogs_list,
        })
    rows.sort(key=lambda r: (-r["session_count"], -r["skills_mastered"]))

    return {
        "days": days,
        "since": since_iso,
        "trainers": rows,
        "totals": {
            "trainers": len(rows),
            "sessions": sum(r["session_count"] for r in rows),
            "skills_mastered": sum(r["skills_mastered"] for r in rows),
            "modules_advanced": sum(r["modules_advanced"] for r in rows),
        },
    }





