# Run-sheet/dashboard helper: which dogs have which active programs
@api.get("/programs/active-summary")
async def active_summary(_: dict = Depends(require_admin_and_permission("manage_training_sessions"))):
    # Online School hardening audit — this is a trainer-led run-sheet
    # summary; online_school enrollments are excluded so they don't
    # double-count a dog or misreport program-type totals for trainer ops.
    cursor = db.dog_programs.find(
        {"status": "active", "delivery_channel": {"$in": list(STAFF_SCHOOL_DELIVERY_CHANNELS)}}, {"_id": 0}
    ).sort("started_at", -1)
    rows = await cursor.to_list(500)
    by_type: Dict[str, int] = {}
    for r in rows:
        t = (r.get("program_snapshot") or {}).get("type", "unknown")
        by_type[t] = by_type.get(t, 0) + 1
    return {"total": len(rows), "by_type": by_type, "active": [_enrollment_summary(r) for r in rows[:20]]}


@api.get("/programs/pipeline")
async def programs_pipeline(
    _: dict = Depends(require_admin_and_permission("manage_training_sessions")),
    status: Optional[str] = None,
    type: Optional[str] = None,
    search: Optional[str] = None,
    trainer: Optional[str] = None,
    stalled_days: Optional[int] = None,
):
    """All-dogs training overview. Joins enrollments → dogs → clients with computed
    progress, days_since_start, days_to_target. Supports filtering.

    Sprint 110di-72 — Enriched with last_session_at + last_trainer (from
    training_session_log) so the Training Hub can flag stalled dogs and show
    who last worked each one. `stalled_days` filter restricts to dogs whose
    most recent session is older than N days (or never)."""
    # Online School hardening audit — the Training Hub pipeline is a
    # trainer-led operational view (last_trainer, stalled-days, etc. have
    # no meaning for self-guided enrollments). Excluded unconditionally,
    # regardless of the caller-supplied status filter.
    query: Dict = {"delivery_channel": {"$in": list(STAFF_SCHOOL_DELIVERY_CHANNELS)}}
    if status:
        query["status"] = status
    rows = await db.dog_programs.find(query, {"_id": 0}).to_list(2000)
    if type:
        rows = [r for r in rows if (r.get("program_snapshot") or {}).get("type") == type]

    # Batch-load all dogs + clients referenced by these enrollments in just
    # two queries instead of N+1 round trips. Strip heavy photo fields from
    # dogs since pipeline only renders the small thumbnail.
    dog_ids = list({r["dog_id"] for r in rows if r.get("dog_id")})
    dogs_list = await db.dogs.find(
        {"id": {"$in": dog_ids}},
        {"_id": 0, "photos": 0, "training_logs": 0, "feeding_schedule": 0, "medications": 0},
    ).to_list(2000) if dog_ids else []
    dog_map = {d["id"]: d for d in dogs_list}

    client_ids = list({d.get("owner_id") for d in dogs_list if d.get("owner_id")})
    clients_list = await db.clients.find(
        {"id": {"$in": client_ids}}, {"_id": 0, "name": 1, "id": 1}
    ).to_list(2000) if client_ids else []
    client_map = {c["id"]: c for c in clients_list}

    # Sprint 110di-72 — pull the most-recent training_session_log row per
    # enrollment so we can show "last trainer + when". One sort+limit per
    # enrollment is fine at this scale; if it grows we can switch to a
    # facet aggregation.
    last_session_by_eid: Dict[str, Dict] = {}
    eids = list({r["id"] for r in rows if r.get("id")})
    if eids:
        log_cur = db.training_session_log.find(
            {"enrollment_id": {"$in": eids}},
            {"_id": 0, "enrollment_id": 1, "at": 1, "by_user": 1, "by_email": 1},
        ).sort("at", -1)
        async for log_row in log_cur:
            eid = log_row.get("enrollment_id")
            if eid and eid not in last_session_by_eid:
                last_session_by_eid[eid] = log_row

    today = business_today()
    out = []
    for r in rows:
        dog = dog_map.get(r["dog_id"])
        if not dog:
            continue
        client = client_map.get(dog.get("owner_id")) if dog.get("owner_id") else None
        if search:
            haystack = f"{dog.get('name','')} {(client or {}).get('name','')} {r['program_snapshot'].get('name','')}".lower()
            if search.lower() not in haystack:
                continue
        summary = _enrollment_summary(r)
        # days since / until
        days_since = None
        days_to_target = None
        try:
            if summary.get("started_at"):
                days_since = (today - date.fromisoformat(summary["started_at"])).days
            if summary.get("target_completion_date"):
                days_to_target = (date.fromisoformat(summary["target_completion_date"]) - today).days
        except Exception:
            pass
        last_log = last_session_by_eid.get(r["id"]) or {}
        last_at = last_log.get("at")
        days_since_session = None
        if last_at:
            try:
                days_since_session = (datetime.now(timezone.utc) - datetime.fromisoformat(last_at)).days
            except Exception:
                pass
        # Trainer filter — match against by_user OR by_email
        if trainer:
            t = trainer.lower()
            hay = f"{last_log.get('by_user','')} {last_log.get('by_email','')}".lower()
            if t not in hay:
                continue
        is_stalled = False
        if stalled_days is not None and stalled_days >= 0:
            if days_since_session is None or days_since_session >= stalled_days:
                is_stalled = True
            else:
                # filter requested — skip rows that are NOT stalled
                continue
        elif days_since_session is None or days_since_session >= 14:
            # default "stalled" tag: no session for 14+ days
            is_stalled = True
        out.append({
            **summary,
            "dog_id": dog["id"],
            "dog_name": dog.get("name"),
            "dog_photo": dog.get("photo") or "",
            "client_id": (client or {}).get("id"),
            "client_name": (client or {}).get("name"),
            "days_since_start": days_since,
            "days_to_target": days_to_target,
            "last_session_at": last_at,
            "last_trainer_name": last_log.get("by_user"),
            "last_trainer_email": last_log.get("by_email"),
            "days_since_session": days_since_session,
            "is_stalled": is_stalled,
        })

    # Sort: active first, then overdue (negative days_to_target), then by recency
    def sort_key(x):
        active = 0 if x["status"] == "active" else 1
        overdue = 0 if (x.get("days_to_target") is not None and x["days_to_target"] < 0) else 1
        return (active, overdue, -(x.get("days_since_start") or 0))
    out.sort(key=sort_key)
    return out


# Registered AFTER every literal /programs/<name> GET route (meta,
# active-summary, pipeline) so the path parameter can never shadow them.
# The Course Builder's editors open programs by id; the list endpoint's
# bounded response must never decide whether a program is editable.
@api.get("/programs/{program_id}")
async def get_program(program_id: str, _: dict = Depends(require_admin_and_permission("manage_training_content"))):
    program = await db.programs.find_one({"id": program_id}, {"_id": 0})
    if not program:
        raise HTTPException(status_code=404, detail="Program not found")
    return program


# ----- Dog tags (lightweight, per-dog) -----
class TagsIn(BaseModel):
    tags: List[str] = []


@api.put("/dogs/{dog_id}/tags")
async def update_dog_tags(dog_id: str, body: TagsIn, _: dict = Depends(require_admin)):
    dog = await db.dogs.find_one({"id": dog_id}, {"_id": 0})
    if not dog:
        raise HTTPException(status_code=404, detail="Dog not found")
    cleaned = sorted({t.strip() for t in body.tags if t and t.strip()})
    await db.dogs.update_one({"id": dog_id}, {"$set": {"tags": cleaned}})
    return {"tags": cleaned}


@api.get("/dogs/tags/all")
async def all_dog_tags(_: dict = Depends(require_admin)):
    """Distinct tags currently in use, with counts."""
    pipeline = [
        {"$unwind": {"path": "$tags", "preserveNullAndEmptyArrays": False}},
        {"$group": {"_id": "$tags", "count": {"$sum": 1}}},
        {"$sort": {"count": -1, "_id": 1}},
    ]
    rows = await db.dogs.aggregate(pipeline).to_list(500)
    return [{"tag": r["_id"], "count": r["count"]} for r in rows]


# -------- Run Sheet --------
@api.get("/run-sheet")
async def run_sheet(_: dict = Depends(require_admin), date_str: Optional[str] = None):
    target = date_str or business_today().isoformat()
    bookings = await db.bookings.find(
        {"status": {"$in": ["approved", "pending", "completed"]}}, {"_id": 0}
    ).to_list(2000)
    relevant = []
    for b in bookings:
        days = _dates_in_range(b["date"], b.get("end_date"))
        if target in days:
            relevant.append(b)

    # Enrich with dog care data + client
    out = []
    for b in relevant:
        dog = await db.dogs.find_one({"id": b["dog_id"]}, {"_id": 0})
        client = await db.clients.find_one({"id": b["client_id"]}, {"_id": 0})
        active_program_name = None
        if dog and dog.get("active_program_id"):
            enr = await db.dog_programs.find_one({"id": dog["active_program_id"]}, {"_id": 0})
            if enr and enr.get("status") == "active":
                active_program_name = (enr.get("program_snapshot") or {}).get("name")
        out.append({
            **b,
            "dog": dog,
            "client_phone": (client or {}).get("phone", ""),
            "client_emerg": (client or {}).get("emerg", ""),
            "active_program_name": active_program_name,
        })
    # Sort: boarding first, then daycare, then grooming, then training; secondary by dropoff_time
    order = {"boarding": 0, "daycare": 1, "grooming": 2, "training": 3}
    out.sort(key=lambda x: (order.get(x["service_type"], 9), x.get("dropoff_time") or "z"))
    return {"date": target, "bookings": out}


