# ─────────────── Sprint 110bp · CSV import for trivia questions ───────────────
# Bulk-load operator-written questions from a spreadsheet. Idempotent: each
# row is keyed by uuid5(question_text) so re-uploading the same CSV updates
# rather than duplicates.

TRIVIA_CSV_NAMESPACE = uuid.UUID("5e8e4dac-aaaa-4111-9999-547269766961")
TRIVIA_CSV_HEADERS = [
    "question", "choice_a", "choice_b", "choice_c", "choice_d",
    "correct_letter", "difficulty", "tag",
]
TRIVIA_CSV_TEMPLATE_ROWS = [
    {
        "question": "Which dog breed is famously known for its distinct black spots on a white coat?",
        "choice_a": "Dalmatian", "choice_b": "Great Dane",
        "choice_c": "Border Collie", "choice_d": "Boxer",
        "correct_letter": "A", "difficulty": "easy", "tag": "breeds",
    },
    {
        "question": "What is the technical name for the moisture-retaining skin that covers a dog's nose?",
        "choice_a": "Tapetum", "choice_b": "Rhinarium",
        "choice_c": "Vibrissae", "choice_d": "Philtrum",
        "correct_letter": "B", "difficulty": "medium", "tag": "anatomy",
    },
]


@api.get("/admin/trivia/import-csv/template")
async def trivia_import_csv_template(_: dict = Depends(require_admin)):
    """Download a CSV template with two example rows."""
    import io as _io
    buf = _io.StringIO()
    writer = csv.DictWriter(buf, fieldnames=TRIVIA_CSV_HEADERS)
    writer.writeheader()
    for row in TRIVIA_CSV_TEMPLATE_ROWS:
        writer.writerow(row)
    return Response(
        content=buf.getvalue(),
        media_type="text/csv",
        headers={"Content-Disposition": 'attachment; filename="trivia-import-template.csv"'},
    )


@api.post("/admin/trivia/import-csv")
async def trivia_import_csv(
    file: UploadFile = File(...),
    _: dict = Depends(require_admin_and_permission("manage_engagement_content")),
):
    """Bulk-import trivia questions from a CSV file.

    Required headers: question, choice_a..d, correct_letter (A/B/C/D),
    difficulty (easy/medium/hard), tag (breeds/behavior/health/history/
    anatomy/training/fun/myth).

    Rows with missing/invalid data are skipped and reported back to the caller.
    Each question is keyed by uuid5(question_text) → re-uploading updates
    instead of duplicating.
    """
    import io as _io
    raw = await file.read()
    try:
        text = raw.decode("utf-8-sig")  # handle Excel's BOM
    except UnicodeDecodeError:
        text = raw.decode("latin-1", errors="replace")
    reader = csv.DictReader(_io.StringIO(text))
    if not reader.fieldnames:
        raise HTTPException(status_code=400, detail="CSV has no headers")
    missing = [h for h in TRIVIA_CSV_HEADERS if h not in reader.fieldnames]
    if missing:
        raise HTTPException(
            status_code=400,
            detail=f"Missing required headers: {', '.join(missing)}",
        )

    created = 0
    updated = 0
    skipped: List[dict] = []
    for line_no, row in enumerate(reader, start=2):  # row 1 is the header
        q = (row.get("question") or "").strip()
        choices = [
            (row.get("choice_a") or "").strip(),
            (row.get("choice_b") or "").strip(),
            (row.get("choice_c") or "").strip(),
            (row.get("choice_d") or "").strip(),
        ]
        letter = (row.get("correct_letter") or "").strip().upper()
        diff = (row.get("difficulty") or "medium").strip().lower()
        tag = (row.get("tag") or "fun").strip().lower()

        if not q:
            skipped.append({"line": line_no, "reason": "empty question"})
            continue
        if any(not c for c in choices):
            skipped.append({"line": line_no, "reason": "all 4 choices required"})
            continue
        if letter not in {"A", "B", "C", "D"}:
            skipped.append({"line": line_no, "reason": "correct_letter must be A/B/C/D"})
            continue
        if len({c.lower() for c in choices}) != 4:
            skipped.append({"line": line_no, "reason": "choices must be unique"})
            continue
        if diff not in TRIVIA_DIFFICULTIES:
            diff = "medium"
        if tag not in TRIVIA_TAGS:
            tag = "fun"
        ci = "ABCD".index(letter)
        qid = str(uuid.uuid5(TRIVIA_CSV_NAMESPACE, q))
        doc = {
            "id": qid,
            "question": q[:200],
            "choices": [c[:80] for c in choices],
            "correct_index": ci,
            "difficulty": diff,
            "tag": tag,
            "source": "manual",
            "active": True,
            "curated": True,
            "created_at": now_iso(),
            "times_used": 0,
        }
        existing = await db.trivia_questions.find_one({"id": qid}, {"_id": 0})
        if existing:
            doc["times_used"] = existing.get("times_used", 0)
            doc["created_at"] = existing.get("created_at", doc["created_at"])
            await db.trivia_questions.update_one({"id": qid}, {"$set": doc})
            updated += 1
        else:
            await db.trivia_questions.insert_one(doc)
            created += 1
    return {
        "created": created,
        "updated": updated,
        "skipped": skipped,
        "skipped_count": len(skipped),
    }


# ─────────────── Sprint 110aw · Sales tax collected report ───────────────
# Year-to-date / arbitrary-window tax tally for sales-tax filing. Combines
# booking-level `tax_amount` and retail-level `tax_amount`.

async def _legacy_void_tax_reversals(start_date: str, end_date: str) -> List[Dict[str, Any]]:
    """Step 4B-1 — read-time tax reversal for HISTORICAL POS void rows.

    Void offset rows written before this fix reversed the sale amount but
    physically carry no ``tax_amount``, so tax reports overstated liability
    on voided taxable sales. New void rows now store the exact negated
    original tax explicitly (see void_pos_sale); rows from before then are
    reconstructed here from the authoritative ORIGINAL retail row via the
    ``reversed_retail_sales_id`` linkage — the stored original tax amount,
    never today's tax rate. No migration/backfill: history self-heals on read.

    Double-count guard: only rows WITHOUT a ``tax_amount`` key qualify (new
    rows always write the key, 0.0 included, marking themselves tax-explicit).
    POS voids are always full reversals, but the amount is verified against
    the original anyway; anything that doesn't match exactly is skipped
    rather than guessed. Pure read-time computation — running a report twice
    can never accumulate a second reversal.
    """
    voids = await db.retail_sales.find(
        {
            "date": {"$gte": start_date, "$lte": end_date},
            "source_kind": "pos_sale_void",
            "tax_amount": {"$exists": False},
            "reversed_retail_sales_id": {"$nin": [None, ""]},
        },
        {"_id": 0, "id": 1, "date": 1, "amount": 1, "reversed_retail_sales_id": 1,
         "description": 1, "client_name": 1},
    ).to_list(10000)
    if not voids:
        return []
    originals = {
        r["id"]: r
        for r in await db.retail_sales.find(
            {"id": {"$in": [v["reversed_retail_sales_id"] for v in voids]},
             "tax_amount": {"$gt": 0}},
            {"_id": 0, "id": 1, "amount": 1, "tax_amount": 1, "tax_rate_pct": 1},
        ).to_list(10000)
    }
    out: List[Dict[str, Any]] = []
    for v in voids:
        o = originals.get(v["reversed_retail_sales_id"])
        if not o:
            continue  # original untaxed or missing — nothing to reverse
        if abs(float(v.get("amount") or 0) + float(o.get("amount") or 0)) > 0.01:
            continue  # not an exact full reversal — never guess partial tax
        out.append({
            "id": f"reconstructed-{v['id']}", "date": v.get("date"),
            "description": v.get("description") or "POS void (reconstructed tax reversal)",
            "amount": float(v.get("amount") or 0),
            "tax_amount": -round(float(o.get("tax_amount") or 0), 2),
            "tax_rate_pct": float(o.get("tax_rate_pct") or 0),
            "client_name": v.get("client_name"),
            "reconstructed": True,
        })
    return out


async def _legacy_stripe_refund_tax_reversals(start_date: str, end_date: str) -> List[Dict[str, Any]]:
    """Step 4B-9 — read-time tax reversal for HISTORICAL Stripe refund rows.

    Reversal rows written before this fix carry no ``tax_amount``. When the
    linked original shop-order row has stored tax AND the CUMULATIVE
    refunded amount across all of that payment's reversal rows covers the
    full original charge, the exact original tax is reconstructed — once,
    attributed to the refund row that completed the full reversal (only
    when that completing row falls inside the report window and is itself
    keyless). Partials without line-item identity are never guessed.
    Explicit-era rows (tax_amount key present, incl. 0.0) are the marker
    that the writer already decided — those payments are skipped, so an
    explicit reversal can never be doubled. Pure read-time computation.
    """
    keyless = await db.retail_sales.find(
        {"date": {"$gte": start_date, "$lte": end_date},
         "source_kind": "stripe_refund", "tax_amount": {"$exists": False},
         "reversed_payment_id": {"$nin": [None, ""]}},
        {"_id": 0, "id": 1, "date": 1, "amount": 1, "reversed_payment_id": 1, "created_at": 1},
    ).to_list(10000)
    if not keyless:
        return []
    pay_ids = list({r["reversed_payment_id"] for r in keyless})
    originals = {
        r["payment_id"]: r
        for r in await db.retail_sales.find(
            {"payment_id": {"$in": pay_ids}, "tax_amount": {"$gt": 0},
             "amount": {"$gt": 0}},
            {"_id": 0, "payment_id": 1, "amount": 1, "tax_amount": 1, "tax_rate_pct": 1},
        ).to_list(10000)
    }
    if not originals:
        return []
    all_reversals = await db.retail_sales.find(
        {"source_kind": "stripe_refund", "reversed_payment_id": {"$in": list(originals.keys())}},
        {"_id": 0, "id": 1, "date": 1, "amount": 1, "tax_amount": 1,
         "reversed_payment_id": 1, "created_at": 1},
    ).to_list(10000)
    by_payment: Dict[str, List[Dict[str, Any]]] = {}
    for r in all_reversals:
        by_payment.setdefault(r["reversed_payment_id"], []).append(r)

    out: List[Dict[str, Any]] = []
    window_keyless_ids = {r["id"] for r in keyless}
    for pay_id, rows in by_payment.items():
        if any("tax_amount" in r and abs(float(r.get("tax_amount") or 0)) >= 0.005 for r in rows):
            continue  # tax already explicitly reversed by the modern writer
        orig = originals[pay_id]
        original_amount = round(float(orig.get("amount") or 0), 2)
        rows.sort(key=lambda r: r.get("created_at") or "")
        running = 0.0
        completing = None
        for r in rows:
            running = round(running + abs(float(r.get("amount") or 0)), 2)
            if running >= original_amount - 0.005:
                completing = r
                break
        if completing is None:
            continue  # cumulative refunds haven't reached full — never guess
        if completing["id"] not in window_keyless_ids:
            continue  # completing row outside window, or tax-explicit era
        out.append({
            "id": f"reconstructed-stripe-{completing['id']}", "date": completing.get("date"),
            "description": "Stripe refund (reconstructed tax reversal)",
            "amount": float(completing.get("amount") or 0),
            "tax_amount": -round(float(orig.get("tax_amount") or 0), 2),
            "tax_rate_pct": float(orig.get("tax_rate_pct") or 0),
            "reconstructed": True,
        })
    return out


async def _sales_tax_window_summary(sd: str, ed: str) -> Dict[str, Any]:
    """Canonical net sales-tax liability for a business-date window.

    Step 4C — extracted verbatim from the /admin/sales-tax/summary endpoint
    so the filing tracker and the summary report can never drift apart.
    This is THE source of truth for filing-period tax liability: booking tax
    + signed retail tax rows + the 4B-1/4B-9 read-time reconstructions.
    total_tax_collected is NET liability (collected − reversed); the
    gross/reversed split below is derived from the very same rows, never a
    second formula.
    """
    # Booking-level tax
    bk_rows = await _booking_rows_anywhere(
        {
            "date": {"$gte": sd, "$lte": ed},
            "tax_amount": {"$exists": True, "$gt": 0},
            "status": {"$in": ["completed", "approved"]},
        },
        {"_id": 0, "id": 1, "date": 1, "service_type": 1, "actual_price": 1, "tax_amount": 1, "tax_rate_pct": 1, "client_name": 1, "dog_name": 1},
        limit=50000,
        sort_field="date",
    )
    # Step 4B-1 — include NEGATIVE tax rows too ($gt: 0 used to silently drop
    # every reversal: booking-refund tax rows and the new explicit void
    # reversals). Net tax liability = tax collected − tax reversed.
    rt_rows = await db.retail_sales.find(
        {"date": {"$gte": sd, "$lte": ed}, "tax_amount": {"$exists": True, "$nin": [0, None]}},
        {"_id": 0, "id": 1, "date": 1, "description": 1, "amount": 1, "tax_amount": 1, "tax_rate_pct": 1, "client_name": 1},
    ).to_list(10000)
    # Historical void rows without a stored tax_amount: reconstruct their
    # reversal from the original sale's stored tax (full-reversal rows only).
    rt_rows += await _legacy_void_tax_reversals(sd, ed)
    # Step 4B-9 — same treatment for historical FULL Stripe refunds.
    rt_rows += await _legacy_stripe_refund_tax_reversals(sd, ed)
    bk_total = round(sum(float(r.get("tax_amount") or 0) for r in bk_rows), 2)
    rt_total = round(sum(float(r.get("tax_amount") or 0) for r in rt_rows), 2)
    # Month breakdown
    by_month: Dict[str, Dict[str, float]] = {}
    for r in bk_rows:
        ym = (r.get("date") or "")[:7]
        slot = by_month.setdefault(ym, {"bookings": 0.0, "retail": 0.0})
        slot["bookings"] += float(r.get("tax_amount") or 0)
    for r in rt_rows:
        ym = (r.get("date") or "")[:7]
        slot = by_month.setdefault(ym, {"bookings": 0.0, "retail": 0.0})
        slot["retail"] += float(r.get("tax_amount") or 0)
    months = [
        {"month": k, "bookings_tax": round(v["bookings"], 2),
         "retail_tax": round(v["retail"], 2),
         "total_tax": round(v["bookings"] + v["retail"], 2)}
        for k, v in sorted(by_month.items())
    ]
    # Derived gross/reversal split of the SAME rows (booking tax rows are
    # all positive by query; retail rows are signed).
    rt_pos = round(sum(float(r.get("tax_amount") or 0) for r in rt_rows
                       if float(r.get("tax_amount") or 0) > 0), 2)
    rt_neg = round(sum(float(r.get("tax_amount") or 0) for r in rt_rows
                       if float(r.get("tax_amount") or 0) < 0), 2)
    return {
        "start_date": sd,
        "end_date": ed,
        "bookings_tax_total": bk_total,
        "retail_tax_total": rt_total,
        "total_tax_collected": round(bk_total + rt_total, 2),
        "gross_tax_charged": round(bk_total + rt_pos, 2),
        "tax_reversed": rt_neg,  # ≤ 0
        "booking_count": len(bk_rows),
        "retail_count": len(rt_rows),
        "by_month": months,
    }


@api.get("/admin/sales-tax/summary")
async def sales_tax_summary(
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    _: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Return tax collected in the window. Defaults to current calendar year.
    Splits booking-tax vs retail-tax + breakdown by month."""
    today = business_today()
    sd = start_date or f"{today.year}-01-01"
    ed = end_date or today.isoformat()
    return await _sales_tax_window_summary(sd, ed)


# ─────────────── Step 4C · Ohio Sales Tax Due & Filing Tracker ───────────────
# Owner-facing filing-period tracker. Liability dollars ALWAYS come from
# _sales_tax_window_summary (the 4B-1/4B-9 canonical source); the pure
# period/deadline/status math lives in sales_tax_tracker.py. Persistent
# facts: one settings doc (db.settings id "sales_tax_filing") + one
# sales_tax_filings record per period (snapshot frozen at filing time,
# payment EVENTS appended, audit log, no destructive deletes).
import sales_tax_tracker as stt

SALES_TAX_SETTINGS_ID = "sales_tax_filing"


async def _get_sales_tax_filing_settings() -> Optional[Dict[str, Any]]:
    row = await db.settings.find_one({"id": SALES_TAX_SETTINGS_ID}, {"_id": 0})
    if not row or row.get("filing_frequency") not in stt.FILING_FREQUENCIES:
        return None
    return row


class SalesTaxSettingsIn(BaseModel):
    filing_frequency: str  # monthly | semiannual | custom
    tracking_start_date: Optional[str] = None  # first day of first tracked period
    effective_date: Optional[str] = None
    vendor_license_ref: Optional[str] = None
    timely_discount_enabled: bool = False
    notes: Optional[str] = None
    # custom / special Ohio assignment (escape hatch, single explicit period)
    custom: Optional[Dict[str, Any]] = None
    # per-period explicit due-date overrides: {period_key: {date, reason}}
    due_date_overrides: Optional[Dict[str, Dict[str, str]]] = None


@api.get("/admin/sales-tax/filing-settings")
async def get_sales_tax_filing_settings(_: dict = Depends(require_admin_and_permission("finance_reports"))):
    row = await _get_sales_tax_filing_settings()
    return {"configured": row is not None, "settings": row,
            "frequencies": list(stt.FILING_FREQUENCIES),
            "timely_discount_rate_pct": stt.OHIO_TIMELY_DISCOUNT_RATE_PCT}


@api.put("/admin/sales-tax/filing-settings")
async def put_sales_tax_filing_settings(
    body: SalesTaxSettingsIn,
    user: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Save the Ohio-ASSIGNED filing schedule. Never auto-defaulted: the
    Department of Taxation assigns the interval, so the owner must save it
    explicitly (the UI may recommend Monthly, but nothing is silently stored)."""
    if body.filing_frequency not in stt.FILING_FREQUENCIES:
        raise HTTPException(status_code=400, detail="Invalid filing frequency")
    if body.filing_frequency == "custom":
        c = body.custom or {}
        for k in ("period_start", "period_end", "due_date"):
            try:
                date.fromisoformat(str(c.get(k)))
            except Exception:
                raise HTTPException(status_code=400, detail=f"Custom schedule needs a valid {k}")
    else:
        try:
            date.fromisoformat(str(body.tracking_start_date))
        except Exception:
            raise HTTPException(status_code=400, detail="tracking_start_date (YYYY-MM-DD) is required")
    for ov in (body.due_date_overrides or {}).values():
        try:
            date.fromisoformat(str(ov.get("date")))
        except Exception:
            raise HTTPException(status_code=400, detail="Due-date override needs a valid date")
    existing = await db.settings.find_one({"id": SALES_TAX_SETTINGS_ID}, {"_id": 0}) or {}
    doc = {
        "id": SALES_TAX_SETTINGS_ID,
        "jurisdiction": "OH",
        "filing_frequency": body.filing_frequency,
        "tracking_start_date": body.tracking_start_date,
        "effective_date": body.effective_date,
        "vendor_license_ref": (body.vendor_license_ref or "").strip() or None,
        "timely_discount_enabled": bool(body.timely_discount_enabled),
        "timely_discount_rate_pct": stt.OHIO_TIMELY_DISCOUNT_RATE_PCT,
        "notes": (body.notes or "").strip() or None,
        "custom": body.custom if body.filing_frequency == "custom" else None,
        "due_date_overrides": body.due_date_overrides or {},
        "created_at": existing.get("created_at") or now_iso(),
        "updated_at": now_iso(),
        "updated_by": user.get("id"),
    }
    await db.settings.update_one({"id": SALES_TAX_SETTINGS_ID}, {"$set": doc}, upsert=True)
    return {"configured": True, "settings": doc}


async def _sales_tax_period_liability(period: Dict[str, Any]) -> Dict[str, Any]:
    return await _sales_tax_window_summary(period["period_start"], period["period_end"])


def _stt_custom_periods(settings: Dict[str, Any]) -> List[Dict[str, Any]]:
    c = settings.get("custom") or {}
    return [{
        "period_key": f"custom-{c.get('period_start')}",
        "label": c.get("label") or f"Custom period {c.get('period_start')} – {c.get('period_end')}",
        "period_start": c.get("period_start"), "period_end": c.get("period_end"),
        "custom_due_date": c.get("due_date"), "custom_note": c.get("note"),
    }]


async def _sales_tax_tracker_payload() -> Dict[str, Any]:
    """Assemble the full tracker view: settings, per-period liability
    (canonical helper), filing records, derived statuses, primary card."""
    today = business_today()
    settings = await _get_sales_tax_filing_settings()
    filings = await db.sales_tax_filings.find({}, {"_id": 0}).to_list(1000)
    filings_by_key = {f["period_key"]: f for f in filings}

    if not settings:
        # Setup-required: liability for the current calendar month may still
        # be shown, but no due date is asserted.
        cur = stt.period_for_date("monthly", today)
        liab = await _sales_tax_period_liability(cur)
        return {
            "configured": False, "setup_required": True, "today": today.isoformat(),
            "unconfigured_preview": {
                **cur, "liability": liab["total_tax_collected"], "detail": liab,
                "note": "Filing schedule needs setup — due dates are unknown until "
                        "Ohio's assigned filing frequency is configured.",
            },
            "periods": [], "primary": None, "current": None,
        }

    freq = settings["filing_frequency"]
    overrides = settings.get("due_date_overrides") or {}
    if freq == "custom":
        periods = _stt_custom_periods(settings)
        tracking_start = periods[0]["period_start"]
    else:
        tracking_start = settings["tracking_start_date"]
        periods = stt.iter_periods(freq, tracking_start, today)

    states: List[Dict[str, Any]] = []
    for p in periods:
        liab = await _sales_tax_period_liability(p)
        ov = overrides.get(p["period_key"])
        if p.get("custom_due_date") and not ov:
            ov = {"date": p["custom_due_date"], "reason": settings.get("custom", {}).get("note") or "Ohio special assignment"}
        st = stt.derive_period_state(
            p, filings_by_key.get(p["period_key"]), today, tracking_start,
            due_override=ov, current_liability=liab["total_tax_collected"])
        st["liability"] = liab["total_tax_collected"]
        st["liability_detail"] = liab
        if st["status"] in ("open", "ready_to_file", "overdue"):
            disc = stt.timely_discount_amount(
                st["liability"], bool(settings.get("timely_discount_enabled")))
            st["projected_timely_discount"] = disc
            st["projected_amount_to_remit"] = stt.amount_to_remit(st["liability"], [], disc)
        st["urgency"] = stt.urgency_for(st, today)
        states.append(st)

    primary = stt.pick_primary_period(states)
    current = next((s for s in states if s["status"] == "open"), None)
    needs_review = [s["period_key"] for s in states if s.get("needs_review")]
    return {
        "configured": True, "setup_required": False, "today": today.isoformat(),
        "settings": settings, "periods": states,
        "primary": primary, "current": current,
        "needs_review_periods": needs_review,
        "late_warning": ("Late filing/payment may result in penalties or interest."
                         if any(s["status"] == "overdue" for s in states) else None),
    }


@api.get("/admin/sales-tax/tracker")
async def sales_tax_tracker(_: dict = Depends(require_admin_and_permission("finance_reports"))):
    return await _sales_tax_tracker_payload()


class SalesTaxFilingIn(BaseModel):
    period_key: str
    filed_date: str
    is_zero_return: bool = False
    # Owner-entered figures; liability defaults to the canonical ledger number.
    filed_liability: Optional[float] = None
    adjustments: List[Dict[str, Any]] = []
    apply_timely_discount: Optional[bool] = None  # default: setting + timeliness
    amount_paid: Optional[float] = None  # optional first payment in same action
    payment_date: Optional[str] = None
    payment_reference: Optional[str] = None
    confirmation_ref: Optional[str] = None
    notes: Optional[str] = None


@api.post("/admin/sales-tax/filings")
async def record_sales_tax_filing(
    body: SalesTaxFilingIn,
    user: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Record that the owner filed the Ohio return externally (this app
    never files with Ohio). Freezes a snapshot of the ledger-calculated
    liability + adjustments + remit at filing time; later ledger changes
    surface as needs_review variance, never as silent rewrites."""
    settings = await _get_sales_tax_filing_settings()
    if not settings:
        raise HTTPException(status_code=409, detail="Configure the sales-tax filing schedule first")
    try:
        date.fromisoformat(body.filed_date)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid filed_date")
    freq = settings["filing_frequency"]
    periods = (_stt_custom_periods(settings) if freq == "custom"
               else stt.iter_periods(freq, settings["tracking_start_date"], business_today()))
    # Historical periods before tracking start may also be filed manually:
    if freq != "custom" and not any(p["period_key"] == body.period_key for p in periods):
        try:
            anchor = (f"{body.period_key}-01" if freq == "monthly"
                      else f"{body.period_key[:4]}-{'01' if body.period_key.endswith('H1') else '07'}-01")
            p = stt.period_for_date(freq, date.fromisoformat(anchor))
            assert p["period_key"] == body.period_key
            periods = [p] + periods
        except Exception:
            raise HTTPException(status_code=400, detail="Unknown filing period")
    period = next((p for p in periods if p["period_key"] == body.period_key), None)
    if period is None:
        raise HTTPException(status_code=400, detail="Unknown filing period")
    if await db.sales_tax_filings.find_one({"period_key": body.period_key}):
        raise HTTPException(status_code=409, detail="A filing is already recorded for this period")

    liab_detail = await _sales_tax_period_liability(period)
    ledger_liability = liab_detail["total_tax_collected"]
    filed_liability = round(float(body.filed_liability), 2) if body.filed_liability is not None else ledger_liability

    ov = (settings.get("due_date_overrides") or {}).get(body.period_key)
    stat_due = (period.get("custom_due_date") or stt.statutory_due_date(period["period_end"]))
    effective_due = (ov or {}).get("date") or stat_due

    adjustments = [
        {"label": str(a.get("label") or "Filing adjustment"),
         "amount": round(float(a.get("amount") or 0), 2),
         "note": (str(a.get("note")) if a.get("note") else None)}
        for a in (body.adjustments or [])
    ]
    timely = body.filed_date <= effective_due
    want_discount = (bool(settings.get("timely_discount_enabled")) and timely
                     if body.apply_timely_discount is None
                     else bool(body.apply_timely_discount) and timely)
    discount = stt.timely_discount_amount(filed_liability, want_discount)
    remit = 0.0 if body.is_zero_return else stt.amount_to_remit(filed_liability, adjustments, discount)

    now = now_iso()
    filing = {
        "id": str(uuid.uuid4()),
        "period_key": body.period_key,
        "period_start": period["period_start"], "period_end": period["period_end"],
        "period_label": period["label"], "frequency": freq,
        "statutory_due_date": stat_due,
        "due_date_override": (ov or {}).get("date"),
        "filed_date": body.filed_date,
        "is_zero_return": bool(body.is_zero_return),
        "snapshot": {
            "liability": filed_liability,
            "ledger_liability_at_filing": ledger_liability,
            "ledger_detail_at_filing": {
                k: liab_detail[k] for k in
                ("bookings_tax_total", "retail_tax_total", "total_tax_collected",
                 "gross_tax_charged", "tax_reversed")},
            "adjustments": adjustments,
            "timely_discount": discount,
            "amount_to_remit": remit,
            "due_date": effective_due,
            "computed_at": now,
        },
        "confirmation_ref": (body.confirmation_ref or "").strip() or None,
        "notes": (body.notes or "").strip() or None,
        "payments": [],
        "recorded_by": user.get("id"),
        "created_at": now, "updated_at": now,
        "audit_log": [{"at": now, "by": user.get("id"), "action": "filing_recorded",
                       "detail": f"liability={filed_liability} remit={remit} zero={body.is_zero_return}"}],
    }
    try:
        await db.sales_tax_filings.insert_one({**filing})
    except DuplicateKeyError:
        raise HTTPException(status_code=409, detail="A filing is already recorded for this period")
    if body.amount_paid is not None and not body.is_zero_return:
        await _append_sales_tax_payment(
            filing["id"], float(body.amount_paid),
            body.payment_date or body.filed_date, body.payment_reference, None, user)
    return await _sales_tax_tracker_payload()


class SalesTaxPaymentIn(BaseModel):
    amount: float
    payment_date: str
    reference: Optional[str] = None
    note: Optional[str] = None
    allow_duplicate: bool = False


async def _append_sales_tax_payment(filing_id: str, amount: float, payment_date: str,
                                    reference: Optional[str], note: Optional[str],
                                    user: dict, allow_duplicate: bool = False) -> Dict[str, Any]:
    filing = await db.sales_tax_filings.find_one({"id": filing_id}, {"_id": 0})
    if not filing:
        raise HTTPException(status_code=404, detail="Filing not found")
    try:
        date.fromisoformat(payment_date)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid payment_date")
    amount = round(float(amount), 2)
    if amount <= 0:
        raise HTTPException(status_code=400, detail="Payment amount must be positive")
    # Duplicate-submission guard: an identical amount+date+reference already
    # on this filing is almost always a double click — require explicit intent.
    for p in filing.get("payments") or []:
        if (abs(float(p.get("amount") or 0) - amount) < 0.005
                and p.get("payment_date") == payment_date
                and (p.get("reference") or None) == ((reference or "").strip() or None)
                and not allow_duplicate):
            raise HTTPException(status_code=409, detail="An identical payment is already recorded for this filing (pass allow_duplicate to record it anyway)")
    now = now_iso()
    event = {"id": str(uuid.uuid4()), "amount": amount, "payment_date": payment_date,
             "reference": (reference or "").strip() or None,
             "note": (note or "").strip() or None,
             "recorded_by": user.get("id"), "recorded_at": now}
    await db.sales_tax_filings.update_one(
        {"id": filing_id},
        {"$push": {"payments": event,
                   "audit_log": {"at": now, "by": user.get("id"),
                                 "action": "payment_recorded",
                                 "detail": f"amount={amount} date={payment_date} ref={event['reference']}"}},
         "$set": {"updated_at": now}})
    return event


@api.post("/admin/sales-tax/filings/{filing_id}/payments")
async def record_sales_tax_payment(
    filing_id: str,
    body: SalesTaxPaymentIn,
    user: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Append a payment EVENT to a recorded filing (never overwrites prior
    payments). Partial payments leave the filing in filed_payment_pending."""
    await _append_sales_tax_payment(filing_id, body.amount, body.payment_date,
                                    body.reference, body.note, user,
                                    allow_duplicate=body.allow_duplicate)
    return await _sales_tax_tracker_payload()


class SalesTaxFilingPatchIn(BaseModel):
    confirmation_ref: Optional[str] = None
    notes: Optional[str] = None
    reason: Optional[str] = None


@api.patch("/admin/sales-tax/filings/{filing_id}")
async def patch_sales_tax_filing(
    filing_id: str,
    body: SalesTaxFilingPatchIn,
    user: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Limited corrections only: confirmation reference and notes, always
    audit-logged. The filing snapshot and payment history are immutable —
    financial-record convention (no invisible edits, no destructive deletes)."""
    filing = await db.sales_tax_filings.find_one({"id": filing_id}, {"_id": 0})
    if not filing:
        raise HTTPException(status_code=404, detail="Filing not found")
    sets: Dict[str, Any] = {}
    changes = []
    if body.confirmation_ref is not None:
        sets["confirmation_ref"] = body.confirmation_ref.strip() or None
        changes.append(f"confirmation_ref→{sets['confirmation_ref']}")
    if body.notes is not None:
        sets["notes"] = body.notes.strip() or None
        changes.append("notes updated")
    if not sets:
        raise HTTPException(status_code=400, detail="Nothing to update")
    now = now_iso()
    sets["updated_at"] = now
    await db.sales_tax_filings.update_one(
        {"id": filing_id},
        {"$set": sets,
         "$push": {"audit_log": {"at": now, "by": user.get("id"), "action": "filing_corrected",
                                 "detail": "; ".join(changes) + (f" (reason: {body.reason})" if body.reason else "")}}})
    return await _sales_tax_tracker_payload()


# ─────────────── Sprint 110aw · Year-end payroll export (1099/W2 prep) ───────────────
# Single endpoint returning a CSV that an accountant / QuickBooks / Gusto can
# ingest. Per-employee: name, email, total hours, gross wages (rate × hours)
# for the requested calendar year. Optionally includes a per-employee detail
# section breaking out each clocked entry.
from fastapi.responses import StreamingResponse
import io
import csv


@api.get("/admin/payroll/year-end.csv")
async def payroll_year_end_csv(
    year: Optional[int] = None,
    detail: bool = False,
    user: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Year-end gross-wages CSV. Pass `?detail=true` to also dump every
    clocked-in/out entry for the year (handy for 1099/W2 reconciliation).

    Sprint 110di-24 — Permission Matrix wiring: payroll + data_export both
    required so the toggles in the matrix actually gate this export."""
    perms = _perms_for(user)
    if not perms.get("payroll") or not perms.get("data_export"):
        raise HTTPException(status_code=403, detail="Missing permission: payroll + data_export")
    y = int(year or business_today().year)
    start_iso = f"{y}-01-01T00:00:00"
    end_iso = f"{y + 1}-01-01T00:00:00"
    # All clocked-in entries with a clock-out in the year
    entries = await db.time_clock_entries.find(
        {
            "clock_in_at": {"$gte": start_iso, "$lt": end_iso},
            "clock_out_at": {"$ne": None, "$exists": True},
        },
        {"_id": 0},
    ).to_list(10000)
    uids = list({e["user_id"] for e in entries if e.get("user_id")})
    users = await db.users.find(
        {"id": {"$in": uids}},
        {
            "_id": 0, "id": 1, "name": 1, "display_name": 1, "email": 1,
            "phone": 1, "hourly_rate": 1, "active": 1, "is_owner": 1,
            "tax_status": 1, "address_street": 1, "address_city": 1,
            "address_state": 1, "address_zip": 1,
        },
    ).to_list(500) if uids else []
    # Sprint 110bf — sole-prop owner does NOT get a 1099/W2; their pay is a draw
    user_by_id = {u["id"]: u for u in users if not u.get("is_owner")}

    # Aggregate per-employee
    per_user: Dict[str, Dict[str, Any]] = {}
    for e in entries:
        uid = e.get("user_id")
        if not uid:
            continue
        if uid not in user_by_id:
            # Owner (filtered above) or deleted user — skip from 1099/W2 export.
            continue
        try:
            t_in = datetime.fromisoformat((e["clock_in_at"] or "").replace("Z", "+00:00"))
            t_out = datetime.fromisoformat((e["clock_out_at"] or "").replace("Z", "+00:00"))
            hrs = max(0.0, (t_out - t_in).total_seconds() / 3600.0)
        except Exception:
            hrs = 0.0
        row = per_user.setdefault(uid, {"hours": 0.0, "gross": 0.0, "entries": 0})
        u = user_by_id.get(uid, {})
        rate = float(u.get("hourly_rate") or 0)
        row["hours"] += hrs
        row["gross"] += hrs * rate
        row["entries"] += 1

    # Sprint 110bu — group by tax_status so the CPA sees W-2 / 1099 / other
    # separately, each with its own sub-total.
    GROUP_ORDER = [
        ("w2",    "W-2 EMPLOYEES",         "Issue W-2 by Jan 31"),
        ("1099",  "1099-NEC CONTRACTORS",  "Issue 1099-NEC if total ≥ $600"),
        ("other", "OTHER / UNCLASSIFIED",  "Set tax_status in Staff → Edit before filing"),
    ]
    grouped: Dict[str, List[str]] = {k: [] for k, _, _ in GROUP_ORDER}
    for uid in per_user.keys():
        u = user_by_id.get(uid, {})
        status = (u.get("tax_status") or "1099").lower()
        if status not in grouped:
            status = "other"
        grouped[status].append(uid)

    # Build the CSV
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow([f"Year-end payroll summary — {y}"])
    w.writerow([])

    grand_hours = 0.0
    grand_gross = 0.0
    grand_entries = 0
    for status_code, label, hint in GROUP_ORDER:
        uids_in_group = grouped[status_code]
        if not uids_in_group:
            continue
        w.writerow([label, hint])
        w.writerow([
            "Employee", "Email", "Phone", "Street", "City", "State", "Zip",
            "Hourly rate", "Active", "Total hours", "Gross wages (USD)",
            "Clocked entries",
        ])
        sub_hours = 0.0
        sub_gross = 0.0
        sub_entries = 0
        for uid in sorted(uids_in_group,
                          key=lambda i: (user_by_id.get(i, {}).get("name") or "").lower()):
            u = user_by_id.get(uid, {})
            agg = per_user[uid]
            w.writerow([
                u.get("display_name") or u.get("name") or "(unknown)",
                u.get("email", ""),
                u.get("phone", ""),
                u.get("address_street", ""),
                u.get("address_city", ""),
                u.get("address_state", ""),
                u.get("address_zip", ""),
                f"{float(u.get('hourly_rate') or 0):.2f}",
                "Yes" if u.get("active", True) else "No",
                f"{agg['hours']:.2f}",
                f"{agg['gross']:.2f}",
                agg["entries"],
            ])
            sub_hours += agg["hours"]
            sub_gross += agg["gross"]
            sub_entries += agg["entries"]
        w.writerow([
            f"  Subtotal — {label}", "", "", "", "", "", "", "", "",
            f"{sub_hours:.2f}", f"{sub_gross:.2f}", sub_entries,
        ])
        w.writerow([])
        grand_hours += sub_hours
        grand_gross += sub_gross
        grand_entries += sub_entries

    w.writerow([
        "GRAND TOTAL", "", "", "", "", "", "", "", "",
        f"{grand_hours:.2f}", f"{grand_gross:.2f}", grand_entries,
    ])

    if detail and entries:
        w.writerow([])
        w.writerow(["DETAIL — every clocked entry"])
        w.writerow(["Employee", "Clock-in", "Clock-out", "Hours", "Rate", "Gross"])
        for e in sorted(entries, key=lambda r: (r.get("user_id"), r.get("clock_in_at") or "")):
            if e.get("user_id") not in user_by_id:
                continue
            u = user_by_id.get(e.get("user_id"), {})
            try:
                t_in = datetime.fromisoformat((e["clock_in_at"] or "").replace("Z", "+00:00"))
                t_out = datetime.fromisoformat((e["clock_out_at"] or "").replace("Z", "+00:00"))
                hrs = max(0.0, (t_out - t_in).total_seconds() / 3600.0)
            except Exception:
                hrs = 0.0
            rate = float(u.get("hourly_rate") or 0)
            w.writerow([
                u.get("display_name") or u.get("name") or "(unknown)",
                e.get("clock_in_at", ""),
                e.get("clock_out_at", ""),
                f"{hrs:.2f}",
                f"{rate:.2f}",
                f"{hrs * rate:.2f}",
            ])

    buf.seek(0)
    fname = f"sit-happens-payroll-{y}.csv"
    return StreamingResponse(
        iter([buf.getvalue()]),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename={fname}"},
    )


# Sprint 110o — Auto-backup feature removed (never worked reliably across the
# unprivileged Docker container ↔ Bazzite host boundary). Admin uses manual
# Download Backup / Restore and the host-side rclone systemd timer instead.



# -------- User credential migration (admin-only) --------
# Use this when moving an instance to a new host and you want clients to keep
# their existing passwords (bcrypt hashes are portable as long as both ends use
# the same bcrypt implementation, which they do).
#
# Flow:
#   1. Admin hits GET  /api/admin/users/export-with-hashes on the SOURCE instance
#      → downloads a JSON file containing { users: [ {id, email, name, role, client_id, password_hash, ...} ] }
#   2. Admin hits POST /api/admin/users/import-with-hashes on the TARGET instance
#      → uploads that JSON. Existing users (by email) are updated, new ones inserted.
#
# Security: requires admin auth on both ends. The hash itself is not the
# password — it's already what the DB stores; exposing it is equivalent to
# stealing the DB file, which the admin can already do.
class UserImportIn(BaseModel):
    users: List[Dict[str, Any]]
    mode: str = "merge"  # "merge" = upsert by email; "replace_clients_only" = also wipe non-admin users first


@api.get("/admin/users/export-with-hashes")
async def admin_users_export_with_hashes(user: dict = Depends(require_owner)):
    """Export every user record INCLUDING password_hash. Admin-only.
    Use this to migrate logins between hosts so clients keep their passwords.

    Sprint 110di-24 — Gated on `data_export` so the Permission Matrix can
    revoke this from a delegated admin."""
    perms = _perms_for(user)
    if not perms.get("data_export"):
        raise HTTPException(status_code=403, detail="Missing permission: data_export")
    users = await db.users.find({}, {"_id": 0}).to_list(5000)
    return {
        "version": BACKUP_VERSION,
        "exported_at": now_iso(),
        "user_count": len(users),
        "users": users,
    }


@api.post("/admin/users/import-with-hashes")
async def admin_users_import_with_hashes(body: UserImportIn, current: dict = Depends(require_owner)):
    """Import users (with hashes) from an export-with-hashes dump.
    Safety: never touches the calling admin's own user record. Existing users
    with the same email are updated in place (preserves their `id`). New users
    are inserted as-is."""
    inserted = 0
    updated = 0
    skipped_no_email = 0
    skipped_self = 0

    if body.mode == "replace_clients_only":
        # Wipe everyone EXCEPT the calling admin so we don't lock ourselves out.
        await db.users.delete_many({"id": {"$ne": current["id"]}})

    for u in body.users:
        email = (u.get("email") or "").strip().lower()
        if not email:
            skipped_no_email += 1
            continue
        if email == (current.get("email") or "").lower():
            skipped_self += 1
            continue
        # Defensive: only keep known fields
        doc = {
            "email": email,
            "password_hash": u.get("password_hash"),
            "name": u.get("name") or "",
            "role": u.get("role") or "client",
            "client_id": u.get("client_id"),
            "created_at": u.get("created_at") or now_iso(),
        }
        if not doc["password_hash"]:
            skipped_no_email += 1  # tracked as skipped — useless without a hash
            continue
        existing = await db.users.find_one({"email": email}, {"_id": 0, "id": 1})
        if existing:
            await db.users.update_one({"email": email}, {"$set": doc})
            updated += 1
        else:
            doc["id"] = u.get("id") or str(uuid.uuid4())
            await db.users.insert_one(doc)
            inserted += 1

    return {
        "ok": True,
        "inserted": inserted,
        "updated": updated,
        "skipped_no_email_or_hash": skipped_no_email,
        "skipped_self": skipped_self,
    }




