    rows = await db.awarded_trophies.find(
        query,
        {"_id": 0},
    ).sort("awarded_at", -1).to_list(10000)
    out: Dict[str, list] = {}
    for r in _serialize_awarded(rows):
        out.setdefault(r.get("recipient_id"), []).append(r)
    return out


