class EndOfDayCloseoutIn(BaseModel):
    date: Optional[str] = None
    notes: Optional[str] = ""
    cash_counted: float = Field(ge=0)
    rollover_confirmed: bool = False
    confirmed_rollover_cash: Optional[float] = Field(default=None, ge=0)
    card_batch: Optional[float] = None
    venmo_paypal: Optional[float] = None  # legacy combined transfer field
    venmo_total: Optional[float] = None
    paypal_total: Optional[float] = None
    check_total: Optional[float] = None


@api.post("/admin/end-of-day/closeout")
async def admin_end_of_day_closeout(body: EndOfDayCloseoutIn, user: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Persist an end-of-day closeout with an explicit next-day rollover.

    Cash counted is mandatory. The operator must confirm the exact amount that
    will be suggested as the next opening balance so a blank field can never
    silently turn into a zero-dollar morning drawer.
    """
    d = _validated_register_date(body.date)
    snapshot = await _admin_end_of_day_snapshot(d)
    if await _active_register_closeout(d):
        raise HTTPException(status_code=409, detail="This register is already closed. Reopen the day before saving a replacement closeout.")
    counted = round(float(body.cash_counted), 2)
    if not body.rollover_confirmed or body.confirmed_rollover_cash is None:
        raise HTTPException(status_code=400, detail="Confirm the exact cash amount that will carry forward to the next day.")
    confirmed = round(float(body.confirmed_rollover_cash), 2)
    if abs(confirmed - counted) > 0.005:
        raise HTTPException(status_code=400, detail="Confirmed rollover cash must exactly match the actual cash counted.")
    register_snapshot = await _register_day_summary(d)
    expected_cash = round(float((register_snapshot.get("totals") or {}).get("expected_cash") or 0), 2)
    # Owner rule (2026-08-31): a drawer that doesn't balance never closes
    # silently — an over/short needs a written explanation on the closeout.
    if abs(counted - expected_cash) > 0.005 and len((body.notes or "").strip()) < 3:
        raise HTTPException(
            status_code=400,
            detail=f"The drawer is {'over' if counted > expected_cash else 'short'} ${abs(counted - expected_cash):.2f} vs the expected ${expected_cash:.2f}. Add a closeout note explaining the difference before closing.",
        )
    doc = {
        "id": str(uuid.uuid4()),
        "date": snapshot.get("date"),
        "created_at": now_iso(),
        "created_by": user.get("id"),
        "created_by_name": user.get("name") or user.get("email") or "admin",
        "snapshot": snapshot,
        "notes": (body.notes or "").strip()[:1000],
        "cash_counted": counted,
        "rollover_cash": counted,
        "rollover_confirmed": True,
        "expected_cash": expected_cash,
        "cash_over_short": round(counted - expected_cash, 2),
        "status": "closed",
        "card_batch": round(float(body.card_batch), 2) if body.card_batch is not None else None,
        "venmo_paypal": round(float(body.venmo_paypal), 2) if body.venmo_paypal is not None else None,
        "venmo_total": round(float(body.venmo_total), 2) if body.venmo_total is not None else None,
        "paypal_total": round(float(body.paypal_total), 2) if body.paypal_total is not None else None,
        "check_total": round(float(body.check_total), 2) if body.check_total is not None else None,
        "register_snapshot": register_snapshot,
        "all_clear": bool(snapshot.get("all_clear")),
    }
    await db.daily_closeouts.insert_one(doc.copy())
    await db.cash_drawer_sessions.update_one(
        {"date": d},
        {"$set": {
            "closed_at": doc["created_at"],
            "closed_by": doc["created_by"],
            "closed_by_name": doc["created_by_name"],
            "closing_cash_counted": counted,
            "closeout_id": doc["id"],
            "rollover_cash": counted,
            "rollover_closeout_id": doc["id"],
        }},
        upsert=True,
    )
    doc.pop("_id", None)
    return doc


async def booking_history(booking_id: str, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Booking change history from audit log + payment ledger. No writes."""
    audits = await db.audit_log.find({"record_id": booking_id}, {"_id": 0}).sort("ts", -1).to_list(200)
    ledger = await db.payment_ledger.find({"booking_id": booking_id}, {"_id": 0}).sort("created_at", -1).to_list(200)
    financial_events = await db.booking_financial_events.find({"booking_id": booking_id}, {"_id": 0}).sort("created_at", -1).to_list(200)
    return {"booking_id": booking_id, "audit": audits, "ledger": ledger, "financial_events": financial_events}


# ── Payment rebuild Phase 1 — read-only Invoice/Payment endpoints ──────────
# No writes here — invoices/payments are only ever created by the checkout/
# refund hooks above. These exist purely to surface what was recorded.

async def get_booking_invoice(booking_id: str, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Resolves to the canonical invoice for this booking — since a group
    invoice's booking_ids array contains every dog in the group, this
    naturally resolves the same way regardless of which booking in the
    group is queried. Returns None (not a 404) when no invoice exists yet
    (e.g. a pre-Phase-1 booking, or a $0 visit that never got one)."""
    invoice = await db.invoices.find_one({"booking_ids": booking_id}, {"_id": 0})
    if not invoice:
        return None
    payments = await db.payments.find({"invoice_id": invoice["id"]}, {"_id": 0}).sort("created_at", 1).to_list(200)
    invoice["payments"] = payments
    return invoice


@api.get("/invoices/{invoice_id}")
async def get_invoice(invoice_id: str, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    payments = await db.payments.find({"invoice_id": invoice_id}, {"_id": 0}).sort("created_at", 1).to_list(200)
    invoice["payments"] = payments
    return invoice


@api.get("/clients/{client_id}/invoices")
async def list_client_invoices(client_id: str, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    invoices = await db.invoices.find({"client_id": client_id}, {"_id": 0}).sort("created_at", -1).to_list(500)
    return invoices


@api.get("/clients/{client_id}/open-invoices")
async def list_client_open_invoices(client_id: str, user: dict = Depends(require_employee_or_admin)):
    """Operational invoice lookup for the payment workflow — least privilege.

    Front Desk staff hold take_payments (and can POST
    /invoices/{id}/payments) but not finance_reports, so the full invoice
    listing above was unreachable and the payment UI mistook the 403 for
    "no invoice", fell through to the tab-payment path, and was then
    correctly rejected because an AR-backed invoice existed. This returns
    ONLY what collecting a payment needs: the client's UNPAID invoices,
    trimmed to identity/balance fields — no line items, no historical or
    financial-reporting data. Gated by the same permission as the payment
    action itself.
    """
    if not _perms_for(user).get("take_payments"):
        raise HTTPException(status_code=403, detail="You don't have permission to take payments.")
    invoices = await db.invoices.find(
        {"client_id": client_id, "balance": {"$gt": 0.005}},
        {"_id": 0, "id": 1, "status": 1, "total": 1, "amount_paid": 1, "balance": 1, "created_at": 1, "due_date": 1},
    ).sort("created_at", -1).to_list(100)
    open_rows = [
        {**inv, "invoice_number": (inv.get("id") or "")[:8].upper()}
        for inv in invoices
        if (inv.get("status") or "").upper() not in ("VOID", "REFUNDED", "PARTIALLY_REFUNDED")
    ]
    return {"invoices": open_rows}


# ── Payment rebuild Phase 2 — Cash + manual payments + register ────────────

@api.post("/invoices/{invoice_id}/payments")
async def create_invoice_payment(invoice_id: str, body: InvoicePaymentIn, user: dict = Depends(require_employee_or_admin)):
    """Top-up payments ONLY — collects an ADDITIONAL manual payment against
    an invoice that already has a balance. Never runs during checkout;
    Phase 1's checkout-time Payment row(s) (created by
    _create_invoice_for_bookings) are untouched by this endpoint."""
    if not _perms_for(user).get("take_payments"):
        raise HTTPException(status_code=403, detail="You don't have permission to take payments.")

    invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    if invoice.get("status") == "VOID":
        raise HTTPException(status_code=400, detail="This invoice is void and cannot accept payments.")

    # Refund-activity guard — checked before ANY mutation. Phase 1 never
    # increases invoice.balance on a refund (amount_paid/balance stay as
    # they were, only refunded_total/status move), so trusting a stale
    # balance here could accept money that was already refunded.
    refunded_total = float(invoice.get("refunded_total") or 0)
    if refunded_total > 0.005 or invoice.get("status") in ("REFUNDED", "PARTIALLY_REFUNDED"):
        raise HTTPException(
            status_code=400,
            detail="This invoice has refund activity and cannot accept additional payments through the standard payment flow. Reconcile the invoice before taking another payment.",
        )

    method = body.method
    amount = round(float(body.amount), 2)
    if method == "other" and not (body.notes or "").strip():
        raise HTTPException(status_code=400, detail="A note is required when the payment method is Other.")
    if method == "cash":
        if body.tendered_amount is None:
            raise HTTPException(status_code=400, detail="Cash received (tendered_amount) is required for cash payments.")
        if float(body.tendered_amount) < amount - 0.005:
            raise HTTPException(status_code=400, detail="Cash received cannot be less than the amount due.")
    elif body.tendered_amount is not None:
        raise HTTPException(status_code=400, detail="tendered_amount only applies to cash payments.")

    business_date = business_today().isoformat()
    await _require_register_day_open(business_date)
    if method == "cash":
        drawer_open = await db.cash_drawer_sessions.find_one({"date": business_date}, {"_id": 0, "date": 1})
        if not drawer_open:
            raise HTTPException(status_code=400, detail="Open the register before taking cash payments.")

    # Idempotency — claim first, verify resource + payload match on replay
    # (same key against a different invoice, or a different amount/method/
    # tendered_amount/notes, is a 409 conflict, never a silent replay).
    fingerprint = _request_fingerprint(invoice_id, amount, method, body.tendered_amount, (body.notes or "").strip())
    claim_id = str(uuid.uuid4())
    ts = now_iso()
    try:
        await db.payment_topup_claims.insert_one({
            "id": claim_id, "idempotency_key": body.idempotency_key, "invoice_id": invoice_id,
            "status": "processing", "payment_id": None, "request_fingerprint": fingerprint,
            "created_at": ts, "updated_at": ts,
        })
    except DuplicateKeyError:
        existing_claim = await db.payment_topup_claims.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if not existing_claim or existing_claim.get("invoice_id") != invoice_id or existing_claim.get("request_fingerprint") != fingerprint:
            raise HTTPException(status_code=409, detail="This idempotency key was already used for a different payment request.")
        if existing_claim.get("status") == "completed":
            payment = await db.payments.find_one({"id": existing_claim.get("payment_id")}, {"_id": 0})
            invoice_now = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
            return {"ok": True, "payment": payment, "invoice": invoice_now}
        raise HTTPException(status_code=409, detail="This payment is already being processed. Wait a moment and try again.")

    invoice_delta_applied = False
    ledger_id: Optional[str] = None
    adjust_balance_applied = False
    payment_id: Optional[str] = None
    retail_sales_id: Optional[str] = None
    try:
        # AR reconciliation — before the atomic invoice delta, so a
        # rejection here mutates nothing at all.
        ar_status = await _invoice_ar_status(invoice)
        if ar_status["ar_backed"]:
            if not ar_status["reconciled"]:
                raise HTTPException(status_code=409, detail="This invoice's AR history needs reconciliation before a payment can be recorded here.")
            client = await db.clients.find_one({"id": invoice.get("client_id")}, {"_id": 0, "account_balance": 1})
            if float((client or {}).get("account_balance") or 0) < amount - 0.005:
                raise HTTPException(status_code=409, detail="This invoice's AR balance needs reconciliation before this payment can be recorded.")

        # Atomic invoice delta — the authoritative overpayment guard. Stripe
        # Online (Phase 3A) — stripe_active_attempt_id absent/null is REQUIRED
        # in this SAME filter (never a separate precheck): whichever side
        # (this manual payment, or a Stripe reservation acquisition) reaches
        # this atomic condition first wins; the other's write simply doesn't
        # match. No TOCTOU window between "check" and "mutate" because there
        # is no separate check — the invoice document itself is the lock.
        result = await db.invoices.find_one_and_update(
            {
                "id": invoice_id, "status": {"$ne": "VOID"}, "balance": {"$gte": amount - 0.005},
                "stripe_active_attempt_id": None,
            },
            {"$inc": {"amount_paid": amount, "balance": -amount}, "$set": {"updated_at": ts}},
            return_document=ReturnDocument.AFTER,
        )
        if result is None:
            fresh = await db.invoices.find_one({"id": invoice_id}, {"_id": 0, "balance": 1, "stripe_active_attempt_id": 1})
            if fresh and fresh.get("stripe_active_attempt_id"):
                raise HTTPException(status_code=409, detail="This invoice has an online Stripe payment in progress or unresolved — it cannot accept a manual payment until that resolves.")
            bal = float((fresh or {}).get("balance") or 0)
            raise HTTPException(status_code=409, detail=f"Payment exceeds remaining balance of ${bal:.2f}.")
        invoice_delta_applied = True

        if ar_status["ar_backed"]:
            ledger_row = await _write_ledger_row(
                client_id=invoice.get("client_id"), type_="payment", amount=-amount, method=method,
                notes=f"Invoice payment · {invoice_id}", booking_id=None, invoice_id=invoice_id,
                created_by=user.get("email") or user.get("id") or "admin", ts=ts,
            )
            ledger_id = ledger_row["id"]
            await _adjust_client_balance(invoice.get("client_id"), -amount)
            adjust_balance_applied = True

        change_given = round(float(body.tendered_amount) - amount, 2) if method == "cash" else None
        payment_row = {
            "id": str(uuid.uuid4()), "invoice_id": invoice_id, "client_id": invoice.get("client_id"),
            "amount": amount, "method": method, "is_credit": False, "date": business_date,
            "employee_id": user.get("id"), "employee_name": user.get("name") or user.get("email"),
            "processor": None, "processor_payment_id": None, "status": "completed",
            "notes": (body.notes or "").strip(), "refunded_amount": 0.0,
            "source": {"kind": "manual_topup"}, "booking_id": None, "ledger_id": ledger_id,
            "idempotency_ref": f"invoice_payment:{invoice_id}:{body.idempotency_key}",
            "created_at": ts, "updated_at": ts,
            "tendered_amount": round(float(body.tendered_amount), 2) if method == "cash" else None,
            "change_given": change_given, "business_date": business_date,
        }
        await db.payments.insert_one(payment_row.copy())
        payment_id = payment_row["id"]

        retail_row = {
            "id": str(uuid.uuid4()), "date": business_date, "amount": amount, "payment_method": method,
            "client_id": invoice.get("client_id"), "client_name": invoice.get("client_name"),
            "invoice_id": invoice_id, "payment_id": payment_id,
            "source_kind": "invoice_payment", "description": f"Invoice payment · {invoice_id}",
            "created_at": ts, "created_by": user.get("id"), "logged_by": user.get("name") or user.get("email") or "admin",
        }
        await db.retail_sales.insert_one(retail_row.copy())
        retail_sales_id = retail_row["id"]

        new_balance = round(float(result.get("balance") or 0), 2)
        if new_balance <= 0.005:
            new_balance = 0.0
        new_amount_paid = round(float(result.get("amount_paid") or 0), 2)
        new_status = _derive_invoice_status(
            result, amount_paid=new_amount_paid, balance=new_balance,
            credit_applied=float(result.get("credit_applied") or 0),
        )
        await db.invoices.update_one(
            {"id": invoice_id}, {"$set": {"status": new_status, "balance": new_balance, "updated_at": ts}},
        )
    except Exception:
        # Compensating rollback, in reverse order — mirrors
        # _booking_refund_locked's established discipline. The claim is
        # only released/deleted AFTER rollback completes.
        if retail_sales_id:
            await db.retail_sales.delete_one({"id": retail_sales_id})
        if payment_id:
            await db.payments.delete_one({"id": payment_id})
        if adjust_balance_applied:
            await _adjust_client_balance(invoice.get("client_id"), amount)
        if ledger_id:
            await db.payment_ledger.delete_one({"id": ledger_id})
        if invoice_delta_applied:
            await db.invoices.update_one({"id": invoice_id}, {"$inc": {"amount_paid": -amount, "balance": amount}})
        await db.payment_topup_claims.delete_one({"id": claim_id})
        raise

    await db.payment_topup_claims.update_one(
        {"id": claim_id}, {"$set": {"status": "completed", "payment_id": payment_id, "updated_at": now_iso()}},
    )
    final_invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
    final_payment = await db.payments.find_one({"id": payment_id}, {"_id": 0})

    # Front-desk POS hardware integration — best-effort, additive, issued
    # only AFTER the top-up already fully committed above. A failure here
    # never affects the payment that already succeeded.
    pos_print_receipt_token = None
    pos_open_drawer_token = None
    try:
        rs_for_print = await get_receipt_settings()
        if rs_for_print.get("auto_print_receipts"):
            pos_print_receipt_token = await _issue_pos_token(
                action="print_receipt", workstation_id=body.workstation_id,
                invoice_id=invoice_id, payment_ids=[payment_id],
            )
        if method == "cash":
            pos_open_drawer_token = await _issue_pos_token(
                action="open_drawer", workstation_id=body.workstation_id, invoice_id=invoice_id,
            )
    except Exception as exc:
        logger.warning("POS token issuance failed for invoice payment %s: %s", payment_id, exc)
    try:
        asyncio.create_task(_maybe_auto_email_receipt(
            "invoice", invoice_id, invoice.get("client_id"), claim_key=f"invoice_payment:{payment_id}",
        ))
    except Exception as exc:
        logger.warning("auto-email receipt spawn failed for invoice payment %s: %s", payment_id, exc)

    return {
        "ok": True, "payment": final_payment, "invoice": final_invoice,
        "pos_invoice_id": invoice_id,
        "pos_print_receipt_token": pos_print_receipt_token,
        "pos_open_drawer_token": pos_open_drawer_token,
    }


@api.post("/payments/{payment_id}/void")
async def void_payment(payment_id: str, body: PaymentVoidIn, user: dict = Depends(require_admin_and_permission("delete_records"))):
    """Reverses a manual top-up payment — exactly once, and only while its
    business day is still open. Never usable on checkout-time or refund
    Payment rows (scope-guarded to source.kind=='manual_topup'). This is
    NOT a general reversal engine: once refund activity exists on the
    invoice, this endpoint refuses and directs the admin to the existing
    financial-correction/reconciliation workflow instead."""
    original = await db.payments.find_one({"id": payment_id}, {"_id": 0})
    if not original:
        raise HTTPException(status_code=404, detail="Payment not found")
    if (original.get("source") or {}).get("kind") != "manual_topup":
        raise HTTPException(status_code=400, detail="Only manual top-up payments can be voided here.")

    invoice = await db.invoices.find_one({"id": original.get("invoice_id")}, {"_id": 0})
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    refunded_total = float(invoice.get("refunded_total") or 0)
    if refunded_total > 0.005 or invoice.get("status") in ("REFUNDED", "PARTIALLY_REFUNDED"):
        raise HTTPException(
            status_code=409,
            detail="This invoice has refund activity; voiding is not available. Use the financial-correction/reconciliation workflow instead.",
        )

    business_date = original.get("business_date") or original.get("date")
    active_closeout = await _active_register_closeout(business_date) if business_date else None
    if active_closeout:
        raise HTTPException(
            status_code=409,
            detail="This payment's business day has been closed out. Use the refund/financial-correction workflow instead.",
        )

    # Structural one-void-per-payment invariant — payment_id is UNIQUE in
    # payment_void_claims, so a second void attempt against the same
    # payment (even with a different idempotency_key) hits DuplicateKeyError
    # on THAT index, not just the idempotency_key one.
    fingerprint = _request_fingerprint(payment_id, body.reason.strip())
    claim_id = str(uuid.uuid4())
    ts = now_iso()
    try:
        await db.payment_void_claims.insert_one({
            "id": claim_id, "idempotency_key": body.idempotency_key, "payment_id": payment_id,
            "status": "processing", "reversal_payment_id": None, "request_fingerprint": fingerprint,
            "created_at": ts, "updated_at": ts,
        })
    except DuplicateKeyError:
        # Two DIFFERENT unique indexes can fire here: idempotency_key (a
        # genuine retry) or payment_id (a SECOND void attempt against an
        # already-claimed payment, even under a brand-new key — the
        # structural one-void-per-payment invariant). Only an exact match
        # on key + payment_id + payload replays; anything else — including
        # a different key against an already-claimed payment_id — is a 409
        # conflict, never a silent replay.
        by_key = await db.payment_void_claims.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if by_key and by_key.get("payment_id") == payment_id and by_key.get("request_fingerprint") == fingerprint:
            if by_key.get("status") == "completed":
                payment = await db.payments.find_one({"id": payment_id}, {"_id": 0})
                invoice_now = await db.invoices.find_one({"id": original.get("invoice_id")}, {"_id": 0})
                return {"ok": True, "payment": payment, "invoice": invoice_now}
            raise HTTPException(status_code=409, detail="This void is already being processed. Wait a moment and try again.")
        raise HTTPException(status_code=409, detail="This payment has already been voided, or this idempotency key was already used for a different request.")

    status_transitioned = False
    reversal_payment_id: Optional[str] = None
    reversal_ledger_id: Optional[str] = None
    balance_reversed = False
    retail_reversed = False
    invoice_delta_applied = False
    try:
        # Atomic status transition — the void may only begin when the
        # original payment is still "completed". A race loses cleanly here.
        flipped = await db.payments.find_one_and_update(
            {"id": payment_id, "status": "completed", "source.kind": "manual_topup"},
            {"$set": {"status": "voided", "voided_at": ts}},
        )
        if flipped is None:
            raise HTTPException(status_code=409, detail="This payment has already been voided or is no longer eligible.")
        status_transitioned = True

        amount = float(original.get("amount") or 0)
        client_id = original.get("client_id")
        invoice_id = original.get("invoice_id")

        if original.get("ledger_id"):
            reversal_ledger_row = await _write_ledger_row(
                client_id=client_id, type_="adjustment", amount=amount, method="",
                notes=f"Void reversal of payment {payment_id} · {body.reason.strip()}",
                booking_id=None, invoice_id=invoice_id,
                created_by=user.get("email") or user.get("id") or "admin", ts=ts,
            )
            reversal_ledger_id = reversal_ledger_row["id"]
            await _adjust_client_balance(client_id, amount)
            balance_reversed = True

        original_retail = await db.retail_sales.find_one({"payment_id": payment_id}, {"_id": 0})

        reversal_row = {
            "id": str(uuid.uuid4()), "invoice_id": invoice_id, "client_id": client_id,
            "amount": -amount, "method": original.get("method"), "is_credit": False,
            "date": business_date, "employee_id": user.get("id"), "employee_name": user.get("name") or user.get("email"),
            "processor": None, "processor_payment_id": None, "status": "completed",
            "notes": f"Void of payment {payment_id} · {body.reason.strip()}", "refunded_amount": 0.0,
            "source": {"kind": "manual_topup_void", "voided_payment_id": payment_id},
            "booking_id": None, "ledger_id": None,
            "idempotency_ref": f"invoice_payment_void:{payment_id}:{body.idempotency_key}",
            "created_at": ts, "updated_at": ts,
            "tendered_amount": None, "change_given": None, "business_date": business_date,
        }
        await db.payments.insert_one(reversal_row.copy())
        reversal_payment_id = reversal_row["id"]

        if original_retail:
            offset_row = {
                "id": str(uuid.uuid4()), "date": business_date, "amount": -amount,
                "payment_method": original.get("method"), "client_id": client_id,
                "client_name": original_retail.get("client_name"), "invoice_id": invoice_id,
                "payment_id": reversal_payment_id, "reversed_payment_id": payment_id,
                "source_kind": "invoice_payment_void",
                "description": f"Void of invoice payment · {payment_id}",
                "created_at": ts, "created_by": user.get("id"), "logged_by": user.get("name") or user.get("email") or "admin",
            }
            await db.retail_sales.insert_one(offset_row.copy())
            retail_reversed = True

        await db.invoices.update_one({"id": invoice_id}, {"$inc": {"amount_paid": -amount, "balance": amount}})
        invoice_delta_applied = True
        fresh_invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
        new_balance = round(float(fresh_invoice.get("balance") or 0), 2)
        if new_balance <= 0.005:
            new_balance = 0.0
        new_amount_paid = round(float(fresh_invoice.get("amount_paid") or 0), 2)
        new_status = _derive_invoice_status(
            fresh_invoice, amount_paid=new_amount_paid, balance=new_balance,
            credit_applied=float(fresh_invoice.get("credit_applied") or 0),
        )
        await db.invoices.update_one(
            {"id": invoice_id}, {"$set": {"status": new_status, "balance": new_balance, "updated_at": ts}},
        )
    except Exception:
        if invoice_delta_applied:
            await db.invoices.update_one({"id": original.get("invoice_id")}, {"$inc": {"amount_paid": float(original.get("amount") or 0), "balance": -float(original.get("amount") or 0)}})
        if retail_reversed:
            await db.retail_sales.delete_one({"payment_id": reversal_payment_id})
        if reversal_payment_id:
            await db.payments.delete_one({"id": reversal_payment_id})
        if balance_reversed:
            await _adjust_client_balance(original.get("client_id"), -float(original.get("amount") or 0))
        if reversal_ledger_id:
            await db.payment_ledger.delete_one({"id": reversal_ledger_id})
        if status_transitioned:
            await db.payments.update_one({"id": payment_id}, {"$set": {"status": "completed"}, "$unset": {"voided_at": ""}})
        await db.payment_void_claims.delete_one({"id": claim_id})
        raise

    await db.payment_void_claims.update_one(
        {"id": claim_id}, {"$set": {"status": "completed", "reversal_payment_id": reversal_payment_id, "updated_at": now_iso()}},
    )
    final_invoice = await db.invoices.find_one({"id": original.get("invoice_id")}, {"_id": 0})
    final_payment = await db.payments.find_one({"id": payment_id}, {"_id": 0})
    return {"ok": True, "payment": final_payment, "invoice": final_invoice}


# ─────────────────────────────────────────────────────────────────────────────
# Stripe Online Payments (Phase 3A) — hosted Checkout Sessions only. NO
# Stripe Terminal, NO saved cards / off-session charging, NO frontend Stripe
# SDK — the browser only ever navigates to session.url and later polls our
# own status endpoint. The browser is NEVER financial authority: only a
# verified webhook (or the on-demand Stripe-side verification below) ever
# applies money. Every write here reuses the existing Invoice/Payment/
# payment_ledger/account_balance/retail_sales architecture exactly the way
# the manual top-up path (create_invoice_payment, above) already does —
# this is additive, not a second accounting engine.
#
# Concurrency safety (the accepted design, after several review passes):
#   - stripe_active_attempt_id / stripe_reserved_amount_cents /
#     stripe_last_applied_attempt_id live directly ON the Invoice document,
#     so the SAME atomic find_one_and_update that already guards balance can
#     also guard Stripe exclusivity — no separate reservation collection,
#     no read-then-write gap, no Mongo multi-document transaction.
#   - Every downstream write (ledger, client.account_balance, Payment,
#     retail_sales) carries its own independent, database-enforced
#     duplicate-protection marker, so a crash-and-retry anywhere in the
#     sequence can resume without ever double-applying a single write.
#   - No TTL index anywhere in this section — time alone never proves money
#     didn't move; a stale-looking pending attempt is actively re-verified
#     against Stripe before anything is released.
# ─────────────────────────────────────────────────────────────────────────────

STRIPE_ATTEMPT_BLOCKING_STATUSES = ("pending", "reconciliation_required")
STRIPE_ATTEMPT_TERMINAL_STATUSES = ("applied", "failed", "expired", "canceled")
STRIPE_REFUND_TERMINAL_STATUSES = ("succeeded", "failed", "canceled")


def _require_stripe_online_enabled():
    if not STRIPE_ONLINE_ENABLED or not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=400, detail="Online card payments are not enabled.")


def _stripe_amount_cents(amount: float) -> int:
    return int(round(float(amount) * 100))


def _app_public_url() -> str:
    return (os.environ.get("APP_PUBLIC_URL") or "http://localhost:3000").rstrip("/")


class StripeCheckoutSessionIn(BaseModel):
    """Body for POST /portal/invoices/{invoice_id}/stripe-checkout-session.
    `amount` omitted means PAY FULL BALANCE; a value means PAY OTHER AMOUNT —
    either way it is only ever a ceiling suggestion from the client. The
    authoritative amount actually charged is re-validated server-side
    against the invoice's live `balance` at the moment this runs, never
    trusted beyond that ceiling."""
    amount: Optional[float] = Field(default=None, gt=0, le=100000)
    idempotency_key: str = Field(min_length=8, max_length=128)


class StripeRefundIn(BaseModel):
    amount: float = Field(gt=0, le=100000)
    reason: Optional[str] = Field(default=None, max_length=500)
    idempotency_key: str = Field(min_length=8, max_length=128)


class ShopRefundLineIn(BaseModel):
    item_id: str = Field(min_length=1, max_length=128)
    quantity: int = Field(ge=1, le=50)


class ShopStripeRefundIn(BaseModel):
    lines: List[ShopRefundLineIn] = Field(min_length=1, max_length=40)
    reason: str = Field(min_length=3, max_length=500)
    restock_products: bool = True
    idempotency_key: str = Field(min_length=8, max_length=128)


# ── Atomic Invoice-pointer reservation ──────────────────────────────────────

async def _acquire_stripe_reservation(invoice_id: str, attempt_id: str, amount_cents: int) -> Optional[dict]:
    """Atomically acquires the Invoice-pointer reservation — the ONLY
    exclusivity mechanism (never a separate find-then-insert). Returns the
    updated invoice on success; None if another attempt already holds this
    invoice, the invoice is VOID, or balance is insufficient. Never touches
    `balance` itself — only the pointer fields."""
    amount = round(amount_cents / 100.0, 2)
    return await db.invoices.find_one_and_update(
        {
            "id": invoice_id,
            "status": {"$ne": "VOID"},
            "balance": {"$gte": amount - 0.005},
            "stripe_active_attempt_id": None,
        },
        {"$set": {
            "stripe_active_attempt_id": attempt_id,
            "stripe_reserved_amount_cents": amount_cents,
            "updated_at": now_iso(),
        }},
        return_document=ReturnDocument.AFTER,
    )


async def _release_stripe_reservation_if_owned(invoice_id: str, attempt_id: str) -> None:
    """Conditionally clears the reservation ONLY if it still names this exact
    attempt — safe to call any number of times, can never clear a different,
    newer reservation. Used for failed/expired/canceled attempts (no money
    ever moved) and, separately, as the FINAL step after every downstream
    write of a successful apply has been independently confirmed complete —
    never merely because the invoice balance mutation succeeded."""
    await db.invoices.update_one(
        {"id": invoice_id, "stripe_active_attempt_id": attempt_id},
        {"$unset": {"stripe_active_attempt_id": "", "stripe_reserved_amount_cents": ""},
         "$set": {"updated_at": now_iso()}},
    )


# ── Resumable, crash-safe local application ─────────────────────────────────

async def _apply_stripe_payment(attempt: dict) -> dict:
    """The ONE local-application sequence for a Stripe-confirmed payment.
    Safe to call any number of times for the SAME attempt — every step is
    independently idempotent via its own durable marker, so a crash between
    any two steps is recoverable by simply calling this again; no step's
    completion is ever inferred from a different step's outcome. Mirrors
    create_invoice_payment's existing AR/ledger/balance/Payment/retail_sales
    pattern — reuses the same helpers, not a second accounting engine.

    Raises HTTPException (never swallowed) if the invoice's AR history isn't
    reconciled, or if the reservation was lost to something other than this
    attempt — both cases leave the caller's attempt in reconciliation_required
    with the reservation still held, per the approved design."""
    attempt_id = attempt["id"]
    invoice_id = attempt["invoice_id"]
    amount = round(attempt["amount_cents"] / 100.0, 2)
    ts = now_iso()
    business_date = business_today().isoformat()

    invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
    if not invoice:
        raise HTTPException(status_code=500, detail="Invoice missing during Stripe apply")

    # AR reconciliation — reused exactly as create_invoice_payment already
    # computes it, checked BEFORE any mutation (zero mutation on rejection).
    # Skipped when Step A already committed for THIS attempt (a crash-retry
    # resuming Step B): by then the invoice's balance already reflects this
    # attempt's own decrement with no matching ledger row yet, so re-running
    # this check against the post-Step-A invoice would always — incorrectly
    # — read as unreconciled. The gate only needs to hold once, before the
    # first mutation ever happens.
    already_applied_this_attempt = invoice.get("stripe_last_applied_attempt_id") == attempt_id
    ar_status = await _invoice_ar_status(invoice)
    if not already_applied_this_attempt and ar_status["ar_backed"] and not ar_status["reconciled"]:
        raise HTTPException(status_code=409, detail="This invoice's AR history needs reconciliation before this Stripe payment can be applied.")

    # ── Step A — invoice money mutation, idempotent via
    # stripe_last_applied_attempt_id. Never cleared for this attempt once set —
    # that is the durable proof "this attempt's decrement already happened." ──
    if invoice.get("stripe_last_applied_attempt_id") != attempt_id:
        result = await db.invoices.find_one_and_update(
            {
                "id": invoice_id,
                "status": {"$ne": "VOID"},
                "stripe_active_attempt_id": attempt_id,
                "stripe_last_applied_attempt_id": {"$ne": attempt_id},
                "balance": {"$gte": amount - 0.005},
            },
            {
                "$inc": {"amount_paid": amount, "balance": -amount},
                "$set": {"stripe_last_applied_attempt_id": attempt_id, "updated_at": ts},
            },
            return_document=ReturnDocument.AFTER,
        )
        if result is None:
            fresh = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
            if not fresh or fresh.get("stripe_last_applied_attempt_id") != attempt_id:
                # Genuinely wrong — reservation lost/invoice voided/balance
                # moved out from under us. Never silently proceed.
                raise HTTPException(status_code=409, detail="Stripe invoice reservation was lost before the payment could be applied — reconciliation required.")
            invoice = fresh  # already applied by an earlier (crashed) run — resume below
        else:
            invoice = result

    # ── Step B1 — AR ledger row, independently idempotent via a unique
    # partial index on stripe_attempt_id (never inferred from another write) ──
    ledger_id: Optional[str] = None
    if ar_status["ar_backed"]:
        existing_ledger = await db.payment_ledger.find_one({"stripe_attempt_id": attempt_id}, {"_id": 0})
        if existing_ledger:
            ledger_id = existing_ledger["id"]
        else:
            ledger_row = {
                "id": str(uuid.uuid4()), "client_id": invoice.get("client_id"), "type": "payment",
                "amount": -amount, "method": "stripe_online",
                "notes": f"Stripe online payment · {invoice_id}", "booking_id": None,
                "invoice_id": invoice_id, "stripe_attempt_id": attempt_id,
                "created_by": "stripe_webhook", "created_at": ts,
                "operation_id": _checkout_operation_id_ctx.get(),
            }
            try:
                await db.payment_ledger.insert_one(ledger_row.copy())
                ledger_id = ledger_row["id"]
            except DuplicateKeyError:
                existing_ledger = await db.payment_ledger.find_one({"stripe_attempt_id": attempt_id}, {"_id": 0})
                ledger_id = existing_ledger["id"] if existing_ledger else None

        # ── Step B2 — client.account_balance, independently idempotent via
        # its OWN attempt marker, mutated in the SAME atomic update as the
        # $inc. Never gated on whether the ledger insert was fresh. ──
        await db.clients.find_one_and_update(
            {"id": invoice.get("client_id"), "stripe_ar_adjustments_applied": {"$ne": attempt_id}},
            {"$inc": {"account_balance": -amount}, "$addToSet": {"stripe_ar_adjustments_applied": attempt_id}},
        )

    # ── Step B3 — canonical Payment row, reusing the EXISTING, already
    # unique-index-backed _insert_payment_row check-before-insert helper ──
    payment_row = await _insert_payment_row({
        "id": str(uuid.uuid4()), "invoice_id": invoice_id, "client_id": invoice.get("client_id"),
        "amount": amount, "method": "stripe_online", "is_credit": False, "date": business_date,
        "employee_id": None, "employee_name": None,
        "processor": "stripe", "processor_payment_id": attempt.get("stripe_payment_intent_id"),
        "status": "completed", "notes": "", "refunded_amount": 0.0,
        "source": {
            "kind": "stripe_online_payment",
            "stripe_attempt_id": attempt_id,
            "stripe_checkout_session_id": attempt.get("stripe_checkout_session_id"),
            "stripe_payment_intent_id": attempt.get("stripe_payment_intent_id"),
            "stripe_customer_id": attempt.get("stripe_customer_id"),
            "card_brand": attempt.get("card_brand"), "card_last4": attempt.get("card_last4"),
        },
        "booking_id": None, "ledger_id": ledger_id,
        "idempotency_ref": f"stripe_attempt:{attempt_id}",
        "created_at": ts, "updated_at": ts,
        "tendered_amount": None, "change_given": None, "business_date": business_date,
    })
    payment_id = payment_row["id"]

    # ── Step B4 — retail_sales revenue row, independently resumable by the
    # canonical Payment id (unique partial index) — never gated on whether
    # THIS invocation was the one that inserted the Payment row. ──
    existing_retail = await db.retail_sales.find_one({"payment_id": payment_id}, {"_id": 0})
    if not existing_retail:
        retail_row = {
            "id": str(uuid.uuid4()), "date": business_date, "amount": amount, "payment_method": "stripe_online",
            "client_id": invoice.get("client_id"), "client_name": invoice.get("client_name"),
            "invoice_id": invoice_id, "payment_id": payment_id,
            "source_kind": "stripe_online_payment", "description": f"Stripe online payment · {invoice_id}",
            "created_at": ts, "created_by": "stripe_webhook", "logged_by": "Stripe",
        }
        try:
            await db.retail_sales.insert_one(retail_row.copy())
        except DuplicateKeyError:
            pass  # already inserted by a concurrent/prior run

    # ── Step B5 — invoice status recompute. Always safe to rerun — a pure
    # function of the invoice's current fields, no marker needed. ──
    fresh_invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
    new_balance = round(float(fresh_invoice.get("balance") or 0), 2)
    if new_balance <= 0.005:
        new_balance = 0.0
    new_status = _derive_invoice_status(
        fresh_invoice, amount_paid=round(float(fresh_invoice.get("amount_paid") or 0), 2),
        balance=new_balance, credit_applied=float(fresh_invoice.get("credit_applied") or 0),
    )
    await db.invoices.update_one({"id": invoice_id}, {"$set": {"status": new_status, "balance": new_balance, "updated_at": ts}})

    # ── Every Step B write independently confirmed complete — mark applied,
    # THEN (only then) release the reservation. Never the reverse order. ──
    await db.stripe_payment_attempts.update_one(
        {"id": attempt_id}, {"$set": {"status": "applied", "applied_payment_id": payment_id, "updated_at": now_iso()}},
    )
    await _release_stripe_reservation_if_owned(invoice_id, attempt_id)

    return await db.invoices.find_one({"id": invoice_id}, {"_id": 0})


async def _verify_and_reconcile_stripe_session(attempt: dict) -> dict:
    """No-TTL replacement for time-based release: called instead of ever
    releasing a 'pending' reservation just because expires_at has passed.
    Actively retrieves the real Checkout Session state from Stripe before
    deciding anything. Only ever meaningful for `pending` — paid_unapplied/
    reconciliation_required never expire by clock, so this is a no-op for
    those (checked by the caller too, but re-checked here defensively)."""
    if attempt.get("status") != "pending":
        return attempt
    # .to_dict(): StripeObject doesn't support .get() (see stripe_webhook).
    session = stripe.checkout.Session.retrieve(attempt["stripe_checkout_session_id"]).to_dict()
    if session.get("payment_status") == "paid":
        try:
            await _apply_stripe_payment(attempt)
        except HTTPException:
            await db.stripe_payment_attempts.find_one_and_update(
                {"id": attempt["id"], "status": {"$nin": list(STRIPE_ATTEMPT_TERMINAL_STATUSES)}},
                {"$set": {"status": "reconciliation_required", "updated_at": now_iso()}},
            )
    else:
        # Stripe itself confirms no successful payment occurred — safe to expire.
        result = await db.stripe_payment_attempts.find_one_and_update(
            {"id": attempt["id"], "status": "pending"},
            {"$set": {"status": "expired", "updated_at": now_iso()}},
        )
        if result is not None:
            await _release_stripe_reservation_if_owned(attempt["invoice_id"], attempt["id"])
    return await db.stripe_payment_attempts.find_one({"id": attempt["id"]}, {"_id": 0})


# ── Client portal endpoints ─────────────────────────────────────────────────

@api.get("/portal/invoices")
async def portal_invoices(user: dict = Depends(get_current_user)):
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    cid = user.get("client_id")
    invoices = []
    if cid:
        rows = await db.invoices.find(
            {"client_id": cid, "status": {"$ne": "VOID"}}, {"_id": 0},
        ).sort("created_at", -1).to_list(200)
        # Hand-picked fields only — never the raw invoice document, so
        # internal Stripe reservation-pointer fields can never leak here.
        for inv in rows:
            invoices.append({
                "id": inv["id"],
                "invoice_number": inv["id"][:8].upper(),
                "date": inv.get("date"),
                "total": inv.get("total"),
                "credit_applied": inv.get("credit_applied"),
                "amount_paid": inv.get("amount_paid"),
                "balance": inv.get("balance"),
                "status": inv.get("status"),
            })
    return {"invoices": invoices, "stripe_online_enabled": bool(STRIPE_ONLINE_ENABLED and STRIPE_SECRET_KEY)}


@api.post("/portal/invoices/{invoice_id}/stripe-checkout-session")
async def create_stripe_checkout_session(invoice_id: str, body: StripeCheckoutSessionIn, user: dict = Depends(get_current_user)):
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    _require_stripe_online_enabled()
    cid = user.get("client_id")
    invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0})
    if not invoice or invoice.get("client_id") != cid:
        raise HTTPException(status_code=404, detail="Invoice not found")
    if invoice.get("status") == "VOID":
        raise HTTPException(status_code=400, detail="This invoice is void.")

    balance = round(float(invoice.get("balance") or 0), 2)
    amount = round(float(body.amount), 2) if body.amount is not None else balance
    if amount <= 0.005 or balance <= 0.005:
        raise HTTPException(status_code=400, detail="Nothing is due on this invoice.")
    if amount > balance + 0.005:
        raise HTTPException(status_code=400, detail=f"Amount cannot exceed the current balance of ${balance:.2f}.")
    amount_cents = _stripe_amount_cents(amount)

    # Claim-first, exactly like every other idempotent endpoint in this codebase.
    fingerprint = _request_fingerprint(invoice_id, cid, amount_cents)
    attempt_id = str(uuid.uuid4())
    ts = now_iso()
    try:
        await db.stripe_payment_attempts.insert_one({
            "id": attempt_id, "idempotency_key": body.idempotency_key, "request_fingerprint": fingerprint,
            "invoice_id": invoice_id, "client_id": cid, "amount_cents": amount_cents,
            "status": "pending",
            "stripe_checkout_session_id": None, "stripe_checkout_session_url": None,
            "stripe_payment_intent_id": None, "stripe_customer_id": None,
            "card_brand": None, "card_last4": None, "applied_payment_id": None,
            "created_at": ts, "updated_at": ts, "expires_at": None,
        })
    except DuplicateKeyError:
        existing = await db.stripe_payment_attempts.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if not existing or existing.get("invoice_id") != invoice_id or existing.get("request_fingerprint") != fingerprint:
            raise HTTPException(status_code=409, detail="This idempotency key was already used for a different request.")
        if existing.get("stripe_checkout_session_url"):
            return {"url": existing["stripe_checkout_session_url"], "attempt_id": existing["id"]}
        if existing.get("status") in STRIPE_ATTEMPT_TERMINAL_STATUSES:
            raise HTTPException(status_code=409, detail="This payment attempt has already been resolved.")
        # A genuine retry interrupted before a session existed — resume
        # using this SAME attempt_id rather than creating a second one.
        attempt_id = existing["id"]

    reserved_invoice = await _acquire_stripe_reservation(invoice_id, attempt_id, amount_cents)
    if reserved_invoice is None:
        current_invoice = await db.invoices.find_one({"id": invoice_id}, {"_id": 0, "stripe_active_attempt_id": 1})
        if not (current_invoice and current_invoice.get("stripe_active_attempt_id") == attempt_id):
            # Not already ours — a genuine conflict. Clean up our own
            # never-used claim row (only if it never got a session either).
            await db.stripe_payment_attempts.delete_one({"id": attempt_id, "stripe_checkout_session_id": None})
            raise HTTPException(status_code=409, detail="This invoice already has an active online payment or unresolved Stripe charge in progress.")
        # else: already ours from a prior partial run — proceed using it.

    expires_at = datetime.now(timezone.utc) + timedelta(seconds=STRIPE_CHECKOUT_EXPIRES_SECONDS)
    client = await db.clients.find_one({"id": cid}, {"_id": 0, "id": 1, "name": 1, "email": 1, "stripe_customer_id": 1})
    stripe_customer_id = (client or {}).get("stripe_customer_id")
    try:
        if not stripe_customer_id:
            customer = stripe.Customer.create(
                name=(client or {}).get("name") or None,
                email=(client or {}).get("email") or None,
                metadata={"sithappens_client_id": cid},
            )
            stripe_customer_id = customer["id"]
            await db.clients.update_one({"id": cid}, {"$set": {"stripe_customer_id": stripe_customer_id}})

        session = stripe.checkout.Session.create(
            mode="payment",
            customer=stripe_customer_id,
            line_items=[{
                "price_data": {
                    "currency": "usd",
                    "product_data": {"name": f"Sit Happens invoice #{invoice_id[:8].upper()}"},
                    "unit_amount": amount_cents,
                },
                "quantity": 1,
            }],
            success_url=f"{_app_public_url()}/portal?stripe_attempt={attempt_id}&stripe=success",
            cancel_url=f"{_app_public_url()}/portal?stripe_attempt={attempt_id}&stripe=cancel",
            expires_at=int(expires_at.timestamp()),
            metadata={
                "sithappens_attempt_id": attempt_id, "sithappens_invoice_id": invoice_id,
                "sithappens_client_id": cid,
            },
            idempotency_key=f"stripe_attempt_create:{attempt_id}",
        )
    except Exception as exc:
        # Session-creation itself failed — mark the attempt failed FIRST,
        # then conditionally release the reservation. Never the reverse.
        await db.stripe_payment_attempts.update_one({"id": attempt_id}, {"$set": {"status": "failed", "updated_at": now_iso()}})
        await _release_stripe_reservation_if_owned(invoice_id, attempt_id)
        logger.warning("Stripe Checkout Session creation failed for attempt %s: %s", attempt_id, exc)
        raise HTTPException(status_code=502, detail="Could not start the online payment — please try again.")

    await db.stripe_payment_attempts.update_one(
        {"id": attempt_id},
        {"$set": {
            "stripe_checkout_session_id": session["id"], "stripe_checkout_session_url": session["url"],
            "stripe_customer_id": stripe_customer_id, "expires_at": expires_at.isoformat(), "updated_at": now_iso(),
        }},
    )
    return {"url": session["url"], "attempt_id": attempt_id}


@api.get("/portal/stripe-payment-attempts/{attempt_id}")
async def portal_stripe_attempt_status(attempt_id: str, user: dict = Depends(get_current_user)):
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    attempt = await db.stripe_payment_attempts.find_one({"id": attempt_id}, {"_id": 0})
    if not attempt or attempt.get("client_id") != user.get("client_id"):
        raise HTTPException(status_code=404, detail="Payment attempt not found")

    # No-TTL active verification — never release/trust a stale-looking
    # pending attempt on elapsed time alone; ask Stripe directly.
    if attempt.get("status") == "pending" and attempt.get("expires_at"):
        try:
            if datetime.now(timezone.utc) > datetime.fromisoformat(attempt["expires_at"]):
                attempt = await _verify_and_reconcile_stripe_session(attempt)
        except HTTPException:
            pass  # verification attempt itself failed — client just sees "processing" and can poll again

    return {"status": attempt.get("status"), "invoice_id": attempt.get("invoice_id"), "amount_cents": attempt.get("amount_cents")}


# ── Stripe webhook — the ONLY place that ever applies money ─────────────────

@api.post("/webhooks/stripe")
async def stripe_webhook(request: Request):
    """Uses the RAW request body for signature verification — never a
    Pydantic-typed body, never request.json() beforehand, since either would
    reserialize the bytes Stripe actually signed. Browser success is NEVER
    financial authority; only a verified event here (or the on-demand
    verification path above) ever applies money."""
    raw_body = await request.body()
    sig_header = request.headers.get("stripe-signature")
    if not STRIPE_WEBHOOK_SECRET:
        raise HTTPException(status_code=503, detail="Stripe webhook not configured")
    try:
        event = stripe.Webhook.construct_event(raw_body, sig_header, STRIPE_WEBHOOK_SECRET)
    except (ValueError, stripe.error.SignatureVerificationError):
        raise HTTPException(status_code=400, detail="Invalid Stripe signature")

    event_id = event["id"]
    event_type = event["type"]
    # Event-ID dedup — an observability/efficiency layer only. The actual
    # money-safety guarantee is the attempt/invoice idempotency markers
    # below, which stay correct even if this insert is skipped or races.
    try:
        await db.stripe_webhook_events.insert_one({"id": event_id, "type": event_type, "received_at": now_iso()})
    except DuplicateKeyError:
        pass

    # .to_dict() is required here: stripe-python's StripeObject no longer
    # subclasses dict, so it supports subscript access but NOT .get() —
    # every downstream handler below relies on plain-dict .get() semantics.
    obj = event["data"]["object"].to_dict()
    # Client Shop Phase 2 — same webhook endpoint, routed by metadata: an
    # invoice payment carries sithappens_invoice_id, a shop order carries
    # sithappens_shop_order_id. Never alters the existing invoice-Stripe
    # payment architecture below — a shop-order event takes a completely
    # separate branch into its own handlers.
    is_shop_order = bool((obj.get("metadata") or {}).get("sithappens_shop_order_id"))
    if event_type in ("checkout.session.completed", "checkout.session.async_payment_succeeded"):
        if is_shop_order:
            await _handle_shop_checkout_session_paid_event(obj)
        else:
            await _handle_checkout_session_paid_event(obj)
    elif event_type == "checkout.session.async_payment_failed":
        if is_shop_order:
            await _handle_shop_checkout_session_failed_event(obj)
        else:
            await _handle_checkout_session_failed_event(obj)
    elif event_type == "checkout.session.expired":
        if is_shop_order:
            await _handle_shop_checkout_session_expired_event(obj)
        else:
            await _handle_checkout_session_expired_event(obj)
    elif event_type in ("refund.created", "refund.updated", "refund.failed"):
        await _handle_refund_event(obj)
    elif event_type in ("charge.dispute.created", "charge.dispute.updated", "charge.dispute.closed"):
        await _handle_stripe_dispute_event(obj)
    elif event_type in ("charge.succeeded", "payout.paid", "payout.failed", "payout.canceled"):
        await _handle_stripe_reconciliation_event(event_type, obj)
    return {"ok": True}


async def _handle_checkout_session_paid_event(session_obj: dict) -> None:
    session_id = session_obj.get("id")
    attempt = await db.stripe_payment_attempts.find_one({"stripe_checkout_session_id": session_id}, {"_id": 0})
    if not attempt:
        return  # unknown session — defensive, should not normally happen
    if session_obj.get("payment_status") != "paid":
        return  # completed but not yet actually paid (async method pending) — wait for a later event
    payment_intent_id = session_obj.get("payment_intent")
    if payment_intent_id and not attempt.get("stripe_payment_intent_id"):
        await db.stripe_payment_attempts.update_one({"id": attempt["id"]}, {"$set": {"stripe_payment_intent_id": payment_intent_id}})
        attempt["stripe_payment_intent_id"] = payment_intent_id
    if attempt.get("status") in STRIPE_ATTEMPT_TERMINAL_STATUSES:
        return  # already resolved — monotonic, never regress
    try:
        await _apply_stripe_payment(attempt)
    except HTTPException:
        await db.stripe_payment_attempts.find_one_and_update(
            {"id": attempt["id"], "status": {"$nin": list(STRIPE_ATTEMPT_TERMINAL_STATUSES)}},
            {"$set": {"status": "reconciliation_required", "updated_at": now_iso()}},
        )
        raise  # non-2xx so Stripe retries delivery — safe, apply is idempotent


async def _handle_checkout_session_failed_event(session_obj: dict) -> None:
    attempt = await db.stripe_payment_attempts.find_one({"stripe_checkout_session_id": session_obj.get("id")}, {"_id": 0})
    if not attempt or attempt.get("status") != "pending":
        return
    result = await db.stripe_payment_attempts.find_one_and_update(
        {"id": attempt["id"], "status": "pending"}, {"$set": {"status": "failed", "updated_at": now_iso()}},
    )
    if result is not None:
        await _release_stripe_reservation_if_owned(attempt["invoice_id"], attempt["id"])


async def _handle_checkout_session_expired_event(session_obj: dict) -> None:
    attempt = await db.stripe_payment_attempts.find_one({"stripe_checkout_session_id": session_obj.get("id")}, {"_id": 0})
    if not attempt or attempt.get("status") != "pending":
        return
    result = await db.stripe_payment_attempts.find_one_and_update(
        {"id": attempt["id"], "status": "pending"}, {"$set": {"status": "expired", "updated_at": now_iso()}},
    )
    if result is not None:
        await _release_stripe_reservation_if_owned(attempt["invoice_id"], attempt["id"])


# ── Client Shop Phase 2 — shop-order equivalents of the three handlers
# above. Same event semantics, routed to shop_payment_attempts/shop_orders
# instead of stripe_payment_attempts/invoices. ──────────────────────────────

async def _handle_shop_checkout_session_paid_event(session_obj: dict) -> None:
    session_id = session_obj.get("id")
    attempt = await db.shop_payment_attempts.find_one({"stripe_checkout_session_id": session_id}, {"_id": 0})
    if not attempt:
        return  # unknown session — defensive, should not normally happen
    if session_obj.get("payment_status") != "paid":
        return  # completed but not yet actually paid (async method pending) — wait for a later event
    payment_intent_id = session_obj.get("payment_intent")
    if payment_intent_id and not attempt.get("stripe_payment_intent_id"):
        await db.shop_payment_attempts.update_one({"id": attempt["id"]}, {"$set": {"stripe_payment_intent_id": payment_intent_id}})
        attempt["stripe_payment_intent_id"] = payment_intent_id
    if attempt.get("status") in SHOP_PAYMENT_ATTEMPT_TERMINAL_STATUSES:
        return  # already resolved — monotonic, never regress
    try:
        await _apply_shop_payment(attempt, session_obj)
    except HTTPException:
        await db.shop_payment_attempts.find_one_and_update(
            {"id": attempt["id"], "status": {"$nin": list(SHOP_PAYMENT_ATTEMPT_TERMINAL_STATUSES)}},
            {"$set": {"status": "reconciliation_required", "updated_at": now_iso()}},
        )
        raise  # non-2xx so Stripe retries delivery — safe, apply is idempotent


async def _shop_order_already_paid(order_id: str) -> bool:
    """Out-of-order guard: a stale failure/expiry event can arrive AFTER a
    'checkout.session.completed' event already succeeded (Stripe does not
    guarantee webhook delivery order). Once the order is paid, NOTHING may
    regress it — never restore stock, never decrement stock_reserved again,
    never mark it unpaid, never touch fulfillment. Checked as its own read
    (not inferred from the attempt's own status) so it holds even if the
    attempt's status hasn't been flipped to 'applied' yet at the moment
    this races against the paid-event handler."""
    order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0, "status": 1})
    return bool(order and order.get("status") == "paid")


async def _handle_shop_checkout_session_failed_event(session_obj: dict) -> None:
    attempt = await db.shop_payment_attempts.find_one({"stripe_checkout_session_id": session_obj.get("id")}, {"_id": 0})
    if not attempt or attempt.get("status") != "pending":
        return
    if await _shop_order_already_paid(attempt["shop_order_id"]):
        return  # monotonic — payment already succeeded, this stale event is a no-op
    result = await db.shop_payment_attempts.find_one_and_update(
        {"id": attempt["id"], "status": "pending"}, {"$set": {"status": "failed", "updated_at": now_iso()}},
    )
    if result is not None:
        await _release_shop_order_reservation_if_owned(attempt["shop_order_id"], attempt["id"])
        await _release_shop_order_inventory(attempt["shop_order_id"])
        await db.shop_orders.update_one(
            {"id": attempt["shop_order_id"], "status": {"$ne": "paid"}},
            {"$set": {"status": "payment_failed", "updated_at": now_iso()}},
        )


async def _handle_shop_checkout_session_expired_event(session_obj: dict) -> None:
    attempt = await db.shop_payment_attempts.find_one({"stripe_checkout_session_id": session_obj.get("id")}, {"_id": 0})
    if not attempt or attempt.get("status") != "pending":
        return
    if await _shop_order_already_paid(attempt["shop_order_id"]):
        return  # monotonic — payment already succeeded, this stale event is a no-op
    result = await db.shop_payment_attempts.find_one_and_update(
        {"id": attempt["id"], "status": "pending"}, {"$set": {"status": "expired", "updated_at": now_iso()}},
    )
    if result is not None:
        await _release_shop_order_reservation_if_owned(attempt["shop_order_id"], attempt["id"])
        await _release_shop_order_inventory(attempt["shop_order_id"])
        await db.shop_orders.update_one(
            {"id": attempt["shop_order_id"], "status": {"$ne": "paid"}},
            {"$set": {"status": "canceled", "updated_at": now_iso()}},
        )


# ── Stripe refunds — a separate, per-attempt lifecycle (multi-partial-safe) ──


def _shop_line_refund_amount(line: dict, qty: int) -> tuple[float, float]:
    """Return (gross, tax) for the requested additional quantity using the
    frozen order-line totals. Non-final units use a deterministic rounded
    unit share; the final refunded unit(s) absorb the exact remaining
    pennies so a line can never refund above or below its immutable total."""
    total_qty = int(line.get("quantity") or 0)
    qty_refunded = int(line.get("quantity_refunded") or 0)
    amount_refunded = round(float(line.get("amount_refunded") or 0), 2)
    tax_refunded = round(float(line.get("tax_refunded") or 0), 2)
    if total_qty <= 0 or qty <= 0 or qty_refunded + qty > total_qty:
        raise HTTPException(status_code=400, detail=f"Invalid refund quantity for {line.get('name') or 'shop item'}.")

    line_total = round(float(line.get("line_total") or 0), 2)
    line_tax = round(float(line.get("allocated_tax") or 0), 2)
    reaches_final = qty_refunded + qty == total_qty
    if reaches_final:
        gross = round(max(0.0, line_total - amount_refunded), 2)
        tax = round(max(0.0, line_tax - tax_refunded), 2)
    else:
        gross = round(round(line_total / total_qty, 2) * qty, 2)
        tax = round(round(line_tax / total_qty, 2) * qty, 2)
        # Never let a non-final share consume the final penny reserve.
        gross = min(gross, round(max(0.0, line_total - amount_refunded), 2))
        tax = min(tax, round(max(0.0, line_tax - tax_refunded), 2))
    return gross, tax


async def _validate_shop_refund_entitlements(order: dict, line_refunds: list[dict]) -> None:
    """Refuse automatic money refunds when an entitlement cannot be safely
    reversed. Physical products are always refundable; restocking is an
    explicit admin choice. Credit-pack/training-credit lines are whole-line
    refunds only and every backing lot must still be completely unused.
    Online School access is history-preserving and can always be revoked."""
    for planned in line_refunds:
        line = planned["line"]
        kind = line.get("kind")
        if kind == "product":
            continue
        remaining_qty = int(line.get("quantity") or 0) - int(line.get("quantity_refunded") or 0)
        if planned["quantity"] != remaining_qty:
            raise HTTPException(
                status_code=409,
                detail=f"{line.get('name') or 'This entitlement'} must be refunded as the whole remaining line.",
            )
        if kind == "training_program" and line.get("fulfillment_kind") == "online_school":
            continue
        for n in range(int(line.get("quantity") or 0)):
            ref = f"{_shop_inventory_ref(order['id'], line['item_id'])}:unit:{n}"
            lot = await db.credit_lots.find_one({"fulfillment_ref": ref}, {"_id": 0})
            if not lot:
                raise HTTPException(status_code=409, detail=f"The entitlement backing {line.get('name') or 'this line'} could not be verified. Review it before refunding.")
            total = round(float(lot.get("qty_total") or 0), 3)
            remaining = round(float(lot.get("qty_remaining") or 0), 3)
            if lot.get("refund_status") == "refunded":
                continue
            if abs(total - remaining) > 0.0005:
                raise HTTPException(
                    status_code=409,
                    detail=f"{line.get('name') or 'Purchased credits'} has already been used. Automatic refund is blocked so money and credits cannot get out of sync.",
                )


async def _build_shop_refund_plan(order: dict, requested: list[ShopRefundLineIn]) -> dict:
    by_id = {str(l.get("item_id")): l for l in (order.get("lines") or [])}
    seen: set[str] = set()
    planned: list[dict] = []
    gross_total = 0.0
    tax_total = 0.0
    for req in requested:
        if req.item_id in seen:
            raise HTTPException(status_code=400, detail="Each shop-order line may appear only once in a refund request.")
        seen.add(req.item_id)
        line = by_id.get(req.item_id)
        if not line:
            raise HTTPException(status_code=404, detail="One of the selected shop-order lines no longer exists.")
        remaining_qty = int(line.get("quantity") or 0) - int(line.get("quantity_refunded") or 0)
        if req.quantity > remaining_qty:
            raise HTTPException(status_code=400, detail=f"Only {remaining_qty} of {line.get('name') or 'this item'} remain refundable.")
        amount, tax = _shop_line_refund_amount(line, req.quantity)
        if amount <= 0.005:
            raise HTTPException(status_code=400, detail=f"{line.get('name') or 'This line'} has no refundable value remaining.")
        planned.append({
            "line": line,
            "item_id": line["item_id"],
            "kind": line.get("kind"),
            "name": line.get("name"),
            "quantity": int(req.quantity),
            "amount": amount,
            "tax_amount": tax,
        })
        gross_total = round(gross_total + amount, 2)
        tax_total = round(tax_total + tax, 2)
    await _validate_shop_refund_entitlements(order, planned)
    return {"lines": planned, "amount": gross_total, "tax_amount": tax_total}


async def _revoke_shop_credit_line(order: dict, line: dict, attempt_id: str) -> None:
    svc_default = "training" if line.get("kind") == "training_program" else None
    for n in range(int(line.get("quantity") or 0)):
        ref = f"{_shop_inventory_ref(order['id'], line['item_id'])}:unit:{n}"
        lot = await db.credit_lots.find_one({"fulfillment_ref": ref}, {"_id": 0})
        if not lot or lot.get("refund_status") == "refunded":
            continue
        qty = round(float(lot.get("qty_remaining") or 0), 3)
        svc_type = lot.get("service_type") or svc_default or "daycare"
        pool_field = _credit_balance_field(svc_type) or "credits"
        marker = f"{attempt_id}:{ref}"
        # Client aggregate and lot document each have their own durable
        # marker, so a crash between the two converges without double-removal.
        await db.clients.find_one_and_update(
            {"id": order.get("client_id"), "shop_refund_credit_adjustments_applied": {"$ne": marker}},
            {"$inc": {pool_field: -qty}, "$addToSet": {"shop_refund_credit_adjustments_applied": marker}},
        )
        await db.credit_lots.update_one(
            {"fulfillment_ref": ref, "refund_attempts_applied": {"$ne": attempt_id}},
            {"$set": {"qty_remaining": 0, "refund_status": "refunded", "refunded_at": now_iso(), "refunded_by": "Stripe shop refund"},
             "$addToSet": {"refund_attempts_applied": attempt_id}},
        )


async def _revoke_refunded_online_school_line(order: dict, line: dict, attempt_id: str) -> None:
    enrollment_id = line.get("online_school_enrollment_id")
    if not enrollment_id:
        return
    enrollment = await db.dog_programs.find_one({"id": enrollment_id}, {"_id": 0})
    if not enrollment:
        return
    ts = now_iso()
    set_doc = {
        "access_state": "revoked",
        "access_changed_at": ts,
        "access_changed_by": None,
        "access_changed_by_name": "Stripe Shop Refund",
        "access_change_reason": "shop_order_refund",
        "shop_refund_attempt_id": attempt_id,
    }
    if enrollment.get("status") == "active":
        set_doc.update({
            "status": "withdrawn", "withdrawn_at": ts, "withdrawn_by": None,
            "withdrawn_by_name": "Stripe Shop Refund", "withdrawal_reason": "Online Shop purchase refunded",
            "previous_training_state": "active",
        })
    await db.dog_programs.update_one({"id": enrollment_id}, {"$set": set_doc})
    se = await db.school_enrollments.find_one({"enrollment_id": enrollment_id}, {"_id": 0})
    fresh = await db.dog_programs.find_one({"id": enrollment_id}, {"_id": 0})
    if se and fresh:
        await _reconcile_school_enrollment_mirror(fresh, se)


async def _apply_shop_refund_fulfillment(attempt: dict) -> None:
    """History-preserving entitlement/inventory reversal for a successful,
    line-aware Shop refund. Every side effect has an independent stable
    marker so webhook retries and crash recovery can safely re-run it."""
    if not attempt.get("shop_refund"):
        if attempt.get("shop_order_id"):
            # A Dashboard/external refund has money identity but no line
            # identity. Never guess which inventory/credits to reverse.
            await db.shop_orders.update_one(
                {"id": attempt["shop_order_id"]},
                {"$set": {"refund_reconciliation_required": True, "refund_reconciliation_reason": "External Stripe refund has no shop line allocation", "updated_at": now_iso()}},
            )
        return
    order = await db.shop_orders.find_one({"id": attempt.get("shop_order_id")}, {"_id": 0})
    if not order:
        return
    attempt_id = attempt["id"]
    for planned in (attempt.get("line_refunds") or []):
        item_id = planned["item_id"]
        line = next((l for l in (order.get("lines") or []) if l.get("item_id") == item_id), None)
        if not line:
            continue
        kind = line.get("kind")
        if kind == "product" and attempt.get("restock_products"):
            marker = f"shop_refund:{attempt_id}:line:{item_id}"
            qty = float(planned.get("quantity") or 0)
            product = await db.pos_products.find_one_and_update(
                {"id": line.get("ref_id"), "shop_refund_refs_applied": {"$ne": marker}},
                {"$inc": {"stock_on_hand": qty}, "$addToSet": {"shop_refund_refs_applied": marker}, "$set": {"updated_at": now_iso()}},
                return_document=ReturnDocument.BEFORE,
            )
            if product is not None:
                try:
                    await db.inventory_movements.insert_one({
                        "id": str(uuid.uuid4()), "product_id": line.get("ref_id"), "type": "shop_refund",
                        "quantity_delta": round(qty, 3), "stock_before": float(product.get("stock_on_hand") or 0),
                        "stock_after": round(float(product.get("stock_on_hand") or 0) + qty, 3),
                        "reason": f"Online Shop refund {order['id']}", "pos_sale_id": None, "source_ref": marker,
                        "user_id": None, "user_name": "Stripe Shop Refund", "created_at": now_iso(),
                    })
                except DuplicateKeyError:
                    pass
        elif kind == "training_program" and line.get("fulfillment_kind") == "online_school":
            await _revoke_refunded_online_school_line(order, line, attempt_id)
        elif kind in ("credit_pack", "training_program"):
            await _revoke_shop_credit_line(order, line, attempt_id)

        await db.shop_orders.update_one(
            {"id": order["id"], "lines": {"$elemMatch": {"item_id": item_id, "refund_attempts_applied": {"$ne": attempt_id}}}},
            {"$inc": {"lines.$.quantity_refunded": int(planned.get("quantity") or 0),
                      "lines.$.amount_refunded": round(float(planned.get("amount") or 0), 2),
                      "lines.$.tax_refunded": round(float(planned.get("tax_amount") or 0), 2)},
             "$addToSet": {"lines.$.refund_attempts_applied": attempt_id},
             "$set": {"updated_at": now_iso()}},
        )

    amount = round(float(attempt.get("amount_cents") or 0) / 100.0, 2)
    await db.shop_orders.update_one(
        {"id": order["id"], "refund_attempts_applied": {"$ne": attempt_id}},
        {"$inc": {"refunded_amount": amount}, "$addToSet": {"refund_attempts_applied": attempt_id}, "$set": {"updated_at": now_iso()}},
    )
    fresh = await db.shop_orders.find_one({"id": order["id"]}, {"_id": 0, "total": 1, "refunded_amount": 1})
    if fresh:
        total = round(float(fresh.get("total") or 0), 2)
        refunded = round(float(fresh.get("refunded_amount") or 0), 2)
        await db.shop_orders.update_one(
            {"id": order["id"]},
            {"$set": {"refund_status": "full" if total > 0 and refunded >= total - 0.005 else "partial", "updated_at": now_iso()}},
        )


@api.post("/shop-orders/{order_id}/stripe-refund")
async def create_shop_stripe_refund(
    order_id: str, body: ShopStripeRefundIn,
    user: dict = Depends(require_admin_and_permission("delete_records")),
):
    """Line-aware Shop refund. Physical products may be quantity-partial;
    credit/program entitlements must be the whole remaining line. Money is
    still moved only through the canonical Stripe refund/finalizer path."""
    _require_stripe_online_enabled()
    order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
    if not order or order.get("status") != "paid":
        raise HTTPException(status_code=404, detail="Paid shop order not found")
    payment = await db.payments.find_one(
        {"shop_order_id": order_id, "method": "stripe_online", "source.kind": "shop_order_payment", "amount": {"$gt": 0}}, {"_id": 0},
    )
    if not payment:
        raise HTTPException(status_code=409, detail="This order has no canonical Stripe payment to refund.")
    payment_intent_id = (payment.get("source") or {}).get("stripe_payment_intent_id")
    if not payment_intent_id:
        raise HTTPException(status_code=409, detail="This order's Stripe PaymentIntent could not be verified.")

    plan = await _build_shop_refund_plan(order, body.lines)
    already_refunded = round(float(payment.get("refunded_amount") or 0), 2)
    remaining = round(float(payment.get("amount") or 0) - already_refunded, 2)
    amount = round(float(plan["amount"]), 2)
    if amount <= 0.005 or amount > remaining + 0.005:
        raise HTTPException(status_code=409, detail=f"Refund exceeds the payment's remaining refundable amount of ${remaining:.2f}.")
    amount_cents = _stripe_amount_cents(amount)
    tax_cents = _stripe_amount_cents(plan["tax_amount"])
    line_snapshot = [{k: v for k, v in row.items() if k != "line"} for row in plan["lines"]]
    fingerprint = _request_fingerprint(payment["id"], line_snapshot, body.restock_products, body.reason.strip())
    attempt_id = str(uuid.uuid4())
    ts = now_iso()
    attempt_doc = {
        "id": attempt_id, "idempotency_key": body.idempotency_key, "request_fingerprint": fingerprint,
        "payment_id": payment["id"], "invoice_id": None, "shop_order_id": order_id,
        "shop_refund": True, "line_refunds": line_snapshot, "restock_products": bool(body.restock_products),
        "tax_amount_cents": tax_cents, "amount_cents": amount_cents, "reason": body.reason.strip(),
        "status": "pending", "stripe_refund_id": None, "stripe_payment_intent_id": payment_intent_id,
        "applied_refund_payment_id": None, "created_at": ts, "updated_at": ts,
    }
    try:
        await db.stripe_refund_attempts.insert_one(dict(attempt_doc))
    except DuplicateKeyError:
        existing = await db.stripe_refund_attempts.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if not existing or existing.get("request_fingerprint") != fingerprint or existing.get("shop_order_id") != order_id:
            raise HTTPException(status_code=409, detail="This idempotency key was already used for a different refund request.")
        return {"ok": True, "refund_attempt": existing}

    try:
        refund = stripe.Refund.create(
            payment_intent=payment_intent_id, amount=amount_cents,
            metadata={"sithappens_refund_attempt_id": attempt_id, "sithappens_payment_id": payment["id"], "sithappens_shop_order_id": order_id},
            idempotency_key=f"stripe_shop_refund_create:{attempt_id}",
        ).to_dict()
    except Exception as exc:
        await db.stripe_refund_attempts.update_one({"id": attempt_id}, {"$set": {"status": "failed", "updated_at": now_iso()}})
        logger.warning("Stripe Shop Refund.create failed for attempt %s: %s", attempt_id, exc)
        raise HTTPException(status_code=502, detail="Could not create the Stripe shop refund — please try again.")

    await db.stripe_refund_attempts.update_one({"id": attempt_id}, {"$set": {"stripe_refund_id": refund["id"], "updated_at": now_iso()}})
    stripe_status = refund.get("status") or "pending"
    if stripe_status == "succeeded":
        await _finalize_stripe_refund(attempt_id)
    else:
        await db.stripe_refund_attempts.update_one(
            {"id": attempt_id, "status": {"$nin": list(STRIPE_REFUND_TERMINAL_STATUSES)}},
            {"$set": {"status": stripe_status, "updated_at": now_iso()}},
        )
    final = await db.stripe_refund_attempts.find_one({"id": attempt_id}, {"_id": 0})
    return {"ok": True, "refund_attempt": final}


@api.post("/payments/{payment_id}/stripe-refund")
async def create_stripe_refund(payment_id: str, body: StripeRefundIn, user: dict = Depends(require_admin_and_permission("delete_records"))):
    """Admin-only. Validates locally first, claims a dedicated refund
    attempt, then calls Stripe with a stable idempotency key. Local refund
    accounting is finalized ONLY when a status==succeeded is actually
    observed (here, synchronously, or later via the refund webhook) — never
    merely because Refund.create returned without throwing."""
    _require_stripe_online_enabled()
    payment = await db.payments.find_one({"id": payment_id}, {"_id": 0})
    if not payment:
        raise HTTPException(status_code=404, detail="Payment not found")
    if payment.get("method") != "stripe_online" or (payment.get("source") or {}).get("kind") != "stripe_online_payment":
        raise HTTPException(status_code=400, detail="Only a Stripe online payment can be refunded through this endpoint.")
    payment_intent_id = (payment.get("source") or {}).get("stripe_payment_intent_id")
    if not payment_intent_id:
        raise HTTPException(status_code=400, detail="This payment has no associated Stripe charge to refund.")

    already_refunded = round(float(payment.get("refunded_amount") or 0), 2)
    remaining = round(float(payment["amount"]) - already_refunded, 2)
    amount = round(float(body.amount), 2)
    if amount <= 0.005 or amount > remaining + 0.005:
        raise HTTPException(status_code=400, detail=f"Refund cannot exceed the remaining refundable amount of ${remaining:.2f}.")
    amount_cents = _stripe_amount_cents(amount)

    fingerprint = _request_fingerprint(payment_id, amount_cents, (body.reason or "").strip())
    refund_attempt_id = str(uuid.uuid4())
    ts = now_iso()
    try:
        await db.stripe_refund_attempts.insert_one({
            "id": refund_attempt_id, "idempotency_key": body.idempotency_key, "request_fingerprint": fingerprint,
            "payment_id": payment_id, "invoice_id": payment.get("invoice_id"), "amount_cents": amount_cents,
            "reason": (body.reason or "").strip(), "status": "pending",
            "stripe_refund_id": None, "stripe_payment_intent_id": payment_intent_id,
            "applied_refund_payment_id": None, "created_at": ts, "updated_at": ts,
        })
    except DuplicateKeyError:
        existing = await db.stripe_refund_attempts.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if not existing or existing.get("payment_id") != payment_id or existing.get("request_fingerprint") != fingerprint:
            raise HTTPException(status_code=409, detail="This idempotency key was already used for a different refund request.")
        return {"ok": True, "refund_attempt": existing}

    try:
        # .to_dict(): StripeObject doesn't support .get() (see stripe_webhook).
        refund = stripe.Refund.create(
            payment_intent=payment_intent_id, amount=amount_cents,
            metadata={"sithappens_refund_attempt_id": refund_attempt_id, "sithappens_payment_id": payment_id,
                      "sithappens_reason": (body.reason or "").strip()},
            idempotency_key=f"stripe_refund_attempt_create:{refund_attempt_id}",
        ).to_dict()
    except Exception as exc:
        await db.stripe_refund_attempts.update_one({"id": refund_attempt_id}, {"$set": {"status": "failed", "updated_at": now_iso()}})
        logger.warning("Stripe Refund.create failed for attempt %s: %s", refund_attempt_id, exc)
        raise HTTPException(status_code=502, detail="Could not create the Stripe refund — please try again.")

    stripe_status = refund.get("status") or "pending"
    # stripe_refund_id is always safe to record directly. status is NOT —
    # if stripe_status is already "succeeded" here, that status write must
    # happen INSIDE _finalize_stripe_refund's own atomic monotonic guard
    # (find_one_and_update({"status": {"$nin": TERMINAL}}, ...)), never
    # before it. A real live-mode bug: setting status="succeeded" via this
    # plain update_one FIRST made the attempt look already-terminal to
    # _finalize_stripe_refund's own claim, which then no-op'd — Stripe had
    # genuinely refunded the money, but the local reversal (Payment row,
    # ledger, invoice.refunded_total) never ran. Never allow this update to
    # write a terminal status ahead of the function that performs the
    # accompanying money movement.
    await db.stripe_refund_attempts.update_one(
        {"id": refund_attempt_id}, {"$set": {"stripe_refund_id": refund["id"], "updated_at": now_iso()}},
    )
    if stripe_status == "succeeded":
        # Trusted here ONLY because we are reading Stripe's own status field
        # directly — never inferred from the call merely not throwing.
        await _finalize_stripe_refund(refund_attempt_id)
    else:
        await db.stripe_refund_attempts.update_one(
            {"id": refund_attempt_id, "status": {"$nin": list(STRIPE_REFUND_TERMINAL_STATUSES)}},
            {"$set": {"status": stripe_status, "updated_at": now_iso()}},
        )

    final = await db.stripe_refund_attempts.find_one({"id": refund_attempt_id}, {"_id": 0})
    return {"ok": True, "refund_attempt": final}


async def _finalize_stripe_refund(refund_attempt_id: str) -> None:
    """Applies the canonical local reversal, safe whether called from the
    synchronous Refund.create response or the later refund.updated webhook
    (whichever observes status==succeeded first wins), and safe against
    duplicate/out-of-order webhook redelivery.

    IMPORTANT: Stripe's own refund status and LOCAL APPLICATION COMPLETENESS
    are two different things. The attempt's status flips to "succeeded"
    first (below), but the several local writes that follow (reversal
    Payment, original Payment.refunded_amount, retail_sales reversal,
    invoice refund state) are separate operations — a crash between any of
    them must NOT be mistaken for "nothing left to do" just because the
    attempt is already terminal. `applied_refund_payment_id` is the actual
    completeness marker, not `status`. So: re-entry is allowed whenever
    status=="succeeded" but applied_refund_payment_id is still unset, and
    EVERY step below is independently idempotent (its own stable key/marker),
    so re-running the whole tail on a resumed call is always safe — no
    step needs to remember whether an earlier step in THIS invocation ran."""
    attempt = await db.stripe_refund_attempts.find_one_and_update(
        {"id": refund_attempt_id, "status": {"$nin": list(STRIPE_REFUND_TERMINAL_STATUSES)}},
        {"$set": {"status": "succeeded", "updated_at": now_iso()}},
        return_document=ReturnDocument.AFTER,
    )
    if attempt is None:
        # Already terminal by status alone — but "terminal" no longer
        # means "nothing left to do." Only a genuinely-finished attempt
        # (applied_refund_payment_id set) is a true no-op; a "succeeded"
        # attempt with local application still incomplete must resume.
        existing = await db.stripe_refund_attempts.find_one({"id": refund_attempt_id}, {"_id": 0})
        if not existing or existing.get("status") != "succeeded" or existing.get("applied_refund_payment_id"):
            return  # never succeeded, or already fully applied — true no-op
        attempt = existing

    payment = await db.payments.find_one({"id": attempt["payment_id"]}, {"_id": 0})
    if not payment:
        return
    amount = round(attempt["amount_cents"] / 100.0, 2)
    ts = now_iso()
    invoice_id = attempt.get("invoice_id")

    # Step A — reversal Payment. Idempotent via idempotency_ref
    # (_insert_payment_row checks-before-inserting), so this always
    # resolves to the SAME row across any number of retries.
    reversal = await _insert_payment_row({
        "id": str(uuid.uuid4()), "invoice_id": invoice_id, "client_id": payment.get("client_id"),
        "amount": -amount, "method": "stripe_online", "is_credit": False,
        "date": business_today().isoformat(),
        "employee_id": None, "employee_name": "Stripe",
        "processor": "stripe", "processor_payment_id": attempt.get("stripe_refund_id"),
        "status": "completed", "notes": attempt.get("reason") or "Stripe refund", "refunded_amount": 0.0,
        "source": {"kind": "stripe_refund", "stripe_refund_attempt_id": attempt["id"], "stripe_refund_id": attempt.get("stripe_refund_id")},
        "booking_id": None, "ledger_id": None,
        "idempotency_ref": f"stripe_refund_attempt:{attempt['id']}",
        "created_at": ts, "updated_at": ts,
    })

    # Step B — original Payment.refunded_amount. Gated on a per-attempt
    # marker in the SAME atomic update as the $inc, so a retry can never
    # double-increment (same pattern as _apply_stripe_payment Step B2's
    # stripe_ar_adjustments_applied marker).
    await db.payments.update_one(
        {"id": payment["id"], "refund_attempts_applied": {"$ne": attempt["id"]}},
        {"$inc": {"refunded_amount": amount},
         "$addToSet": {"refund_attempts_applied": attempt["id"]},
         "$set": {"updated_at": ts}},
    )

    # Step C — invoice.refunded_total, when this refund belongs to an
    # invoice-backed payment. Same marker-gated-$inc idiom as Step B, so a
    # retry never double-increments; status is then recomputed fresh from
    # the just-updated document (always safe to rerun — a pure function of
    # current fields, no marker needed, matching Step B5's existing comment
    # style in _apply_stripe_payment).
    if invoice_id:
        updated_invoice = await db.invoices.find_one_and_update(
            {"id": invoice_id, "refund_attempts_applied": {"$ne": attempt["id"]}},
            {"$inc": {"refunded_total": amount},
             "$addToSet": {"refund_attempts_applied": attempt["id"]},
             "$set": {"updated_at": ts}},
            return_document=ReturnDocument.AFTER,
        )
        if updated_invoice:
            new_status = _derive_invoice_status(
                updated_invoice,
                amount_paid=float(updated_invoice.get("amount_paid") or 0),
                balance=float(updated_invoice.get("balance") or 0),
                credit_applied=float(updated_invoice.get("credit_applied") or 0),
            )
            await db.invoices.update_one({"id": invoice_id}, {"$set": {"status": new_status, "updated_at": ts}})
        # else: marker already present (already applied on a prior pass) or
        # invoice not found — either way, nothing further to do here.

    # Step D — offsetting retail_sales reversal row. The ORIGINAL row is
    # NEVER edited/deleted; this inserts a new negative row referencing it.
    # Idempotency reuses the reversal Payment's own already-stable id
    # (Step A) against retail_sales' EXISTING unique-partial index on
    # payment_id — no new index needed. Same "insert an offsetting negative
    # row, never touch the original" convention already used by
    # void_pos_sale and void_payment's invoice_payment_void reversal.
    # Fixes a real, pre-existing gap: Stripe refunds previously left the
    # original positive retail_sales row completely unreversed, so
    # Finance/Income/Register reporting overstated revenue after a refund.
    existing_retail_reversal = await db.retail_sales.find_one({"payment_id": reversal["id"]}, {"_id": 0})
    if not existing_retail_reversal:
        original_retail = await db.retail_sales.find_one({"payment_id": payment["id"]}, {"_id": 0})
        if original_retail:
            # Step 4B-9 — sales-tax reversal, full-refund-only. Refund
            # attempts carry no line-item identity, so PARTIAL refunds of a
            # taxable order never get a guessed tax split; but once the
            # CUMULATIVE refunded amount covers the full original charge,
            # the exact stored original tax is reversed — once. Prior
            # partial reversal rows carry an explicit 0.0 (the tax-explicit
            # marker, same convention as Step 4B-1's void rows), so the
            # completing refund's row carries the whole remaining tax and a
            # webhook replay can never write a second row (payment_id
            # unique index) or a second reversal.
            original_tax = round(float(original_retail.get("tax_amount") or 0), 2)
            tax_component = 0.0
            if attempt.get("shop_refund") and attempt.get("tax_amount_cents") is not None:
                # Shop refunds carry authoritative line identity and frozen
                # per-line allocated tax, so partial physical-item refunds
                # can reverse the exact tax slice instead of waiting for a
                # full-payment refund. Never estimate this from gross money.
                tax_component = -round(float(attempt.get("tax_amount_cents") or 0) / 100.0, 2)
            elif original_tax > 0:
                fresh_pay = await db.payments.find_one(
                    {"id": payment["id"]}, {"_id": 0, "refunded_amount": 1})
                cumulative_refunded = round(float((fresh_pay or {}).get("refunded_amount") or 0), 2)
                original_amount = round(float(original_retail.get("amount") or payment.get("amount") or 0), 2)
                prior_rows = await db.retail_sales.find(
                    {"source_kind": "stripe_refund", "reversed_payment_id": payment["id"],
                     "tax_amount": {"$exists": True}},
                    {"_id": 0, "tax_amount": 1},
                ).to_list(100)
                already_reversed = round(sum(-float(r.get("tax_amount") or 0) for r in prior_rows), 2)
                if original_amount > 0 and cumulative_refunded >= original_amount - 0.005:
                    tax_component = -round(max(0.0, original_tax - already_reversed), 2)
            try:
                await db.retail_sales.insert_one({
                    "id": str(uuid.uuid4()), "date": business_today().isoformat(), "amount": -amount,
                    "payment_method": "stripe_online", "client_id": payment.get("client_id"),
                    "client_name": original_retail.get("client_name"), "invoice_id": invoice_id,
                    "payment_id": reversal["id"], "reversed_payment_id": payment["id"],
                    "source_kind": "stripe_refund", "tax_amount": tax_component,
                    "description": f"Stripe refund · {payment['id']}",
                    "created_at": ts, "created_by": "stripe_refund", "logged_by": "Stripe",
                })
            except DuplicateKeyError:
                pass  # already applied by a concurrent/prior run

    # Step E — Shop-specific fulfillment reversal, if this payment belongs
    # to an Online Shop order. This preserves the ONE financial finalizer
    # while keeping inventory/credit/School side effects line-aware.
    await _apply_shop_refund_fulfillment(attempt)

    # Only after every applicable step above is independently confirmed
    # complete (each is safe to re-run, so simply having executed them
    # again here IS that confirmation) do we mark local application done.
    # This $set is itself idempotent — always writes the same reversal id.
    await db.stripe_refund_attempts.update_one(
        {"id": attempt["id"]}, {"$set": {"applied_refund_payment_id": reversal["id"], "updated_at": now_iso()}},
    )


async def _handle_refund_event(refund_obj: dict) -> None:
    refund_id = refund_obj.get("id")
    status = refund_obj.get("status")
    if refund_obj.get("balance_transaction"):
        await _record_stripe_balance_transaction(refund_obj, object_type="refund")
    attempt = await db.stripe_refund_attempts.find_one({"stripe_refund_id": refund_id}, {"_id": 0})
    if not attempt:
        # App-initiated refunds stamp their attempt id into the Stripe
        # metadata at Refund.create time — if the webhook races ahead of the
        # local stripe_refund_id write, recover the attempt through that
        # structured link instead of double-processing it as external.
        meta = refund_obj.get("metadata") or {}
        app_attempt_id = meta.get("sithappens_refund_attempt_id")
        if app_attempt_id:
            attempt = await db.stripe_refund_attempts.find_one({"id": app_attempt_id}, {"_id": 0})
            if attempt and not attempt.get("stripe_refund_id"):
                await db.stripe_refund_attempts.update_one(
                    {"id": app_attempt_id, "stripe_refund_id": None},
                    {"$set": {"stripe_refund_id": refund_id, "updated_at": now_iso()}},
                )
    if not attempt:
        # Step 4B-10 — externally initiated refund (e.g. Stripe Dashboard).
        # A refund must produce the same financial result regardless of
        # where it was initiated, so synthesize the attempt row the app flow
        # would have created and route it through the SAME
        # _finalize_stripe_refund (one revenue algorithm, one 4B-9 tax
        # algorithm, same idempotency). Only a PROVEN-successful refund
        # creates financial records — pending/failed external events are
        # ignored until a succeeded event arrives.
        if status != "succeeded":
            return
        intent_id = refund_obj.get("payment_intent")
        payment = None
        if intent_id:
            payment = await db.payments.find_one(
                {"processor": "stripe", "processor_payment_id": intent_id, "amount": {"$gt": 0}},
                {"_id": 0},
            )
        if not payment:
            # No reliable structured linkage — never fabricate a reversal.
            # Stripe receives 200 (the dispatcher returns ok), so this is a
            # deliberate skip, logged for reconciliation, not a retry loop.
            logger.warning(
                "External Stripe refund %s could not be linked to a local payment "
                "(payment_intent=%s) — no reversal created; reconcile manually.",
                refund_id, intent_id,
            )
            return
        amount_cents = int(refund_obj.get("amount") or 0)
        if amount_cents <= 0:
            logger.warning("External Stripe refund %s has no positive amount — skipped.", refund_id)
            return
        ts = now_iso()
        synthesized = {
            "id": str(uuid.uuid4()), "payment_id": payment["id"],
            "invoice_id": payment.get("invoice_id"), "shop_order_id": payment.get("shop_order_id"), "amount_cents": amount_cents,
            "reason": "Refund issued directly from Stripe",
            "status": "succeeded", "stripe_refund_id": refund_id,
            "stripe_payment_intent_id": intent_id,
            # The refund id IS the financial identity: concurrent deliveries
            # collide on this unique key and resume the same attempt.
            "idempotency_key": f"external-stripe-refund:{refund_id}",
            "request_fingerprint": f"external:{refund_id}",
            "source": "external_stripe",
            "applied_refund_payment_id": None, "created_at": ts, "updated_at": ts,
        }
        try:
            await db.stripe_refund_attempts.insert_one(dict(synthesized))
            attempt = synthesized
        except DuplicateKeyError:
            attempt = await db.stripe_refund_attempts.find_one({"stripe_refund_id": refund_id}, {"_id": 0})
            if not attempt:
                return
        await _finalize_stripe_refund(attempt["id"])
        return
    if attempt.get("status") in STRIPE_REFUND_TERMINAL_STATUSES:
        # Terminal status alone does not mean local application finished —
        # see _finalize_stripe_refund's own docstring. A redelivered webhook
        # for an attempt stuck at "succeeded" with local application still
        # incomplete must still be allowed to resume it; only a genuinely
        # complete attempt (or a real failed/canceled one) is a true no-op.
        if attempt.get("status") == "succeeded" and not attempt.get("applied_refund_payment_id"):
            await _finalize_stripe_refund(attempt["id"])
        return
    if status == "succeeded":
        await _finalize_stripe_refund(attempt["id"])
    else:
        # pending / requires_action / failed / canceled — record status,
        # never touch accounting unless/until succeeded is actually observed.
        await db.stripe_refund_attempts.find_one_and_update(
            {"id": attempt["id"], "status": {"$nin": list(STRIPE_REFUND_TERMINAL_STATUSES)}},
            {"$set": {"status": status, "updated_at": now_iso()}},
        )


async def _record_stripe_balance_transaction(obj: dict, *, object_type: str) -> None:
    bt_id = obj.get("balance_transaction")
    if not bt_id:
        return
    try:
        bt = stripe.BalanceTransaction.retrieve(bt_id).to_dict()
    except Exception as exc:
        logger.warning("Stripe balance transaction %s could not be retrieved: %s", bt_id, exc)
        return
    intent_id = obj.get("payment_intent")
    payment = None
    if intent_id:
        payment = await db.payments.find_one(
            {"$or": [{"processor_payment_id": intent_id}, {"source.stripe_payment_intent_id": intent_id}], "amount": {"$gt": 0}}, {"_id": 0},
        )
    created_ts = bt.get("created")
    if isinstance(created_ts, (int, float)):
        created_iso = datetime.fromtimestamp(created_ts, tz=timezone.utc).isoformat()
    else:
        created_iso = now_iso()
    fee_amount = round(float(bt.get("fee") or 0) / 100.0, 2)
    net_amount = round(float(bt.get("net") or 0) / 100.0, 2)
    gross_amount = round(float(bt.get("amount") or 0) / 100.0, 2)
    doc = {
        "id": bt_id, "object_type": object_type, "source_object_id": obj.get("id"),
        "payment_id": (payment or {}).get("id"), "client_id": (payment or {}).get("client_id"),
        "invoice_id": (payment or {}).get("invoice_id"), "shop_order_id": (payment or {}).get("shop_order_id"),
        "stripe_payment_intent_id": intent_id, "type": bt.get("type"), "status": bt.get("status"),
        "currency": bt.get("currency"), "amount": gross_amount, "fee": fee_amount, "net": net_amount,
        "available_on": bt.get("available_on"), "reporting_category": bt.get("reporting_category"),
        "created_at": created_iso, "updated_at": now_iso(),
    }
    await db.stripe_balance_transactions.update_one({"id": bt_id}, {"$set": doc}, upsert=True)

    # Processor fees flow into the same expense ledger the P&L already uses.
    # A negative fee (rare adjustment/fee reversal) is deliberately stored
    # as a negative expense, reducing processor-fee expense rather than
    # fabricating revenue.
    if abs(fee_amount) > 0.0005:
        existing = await db.expenses.find_one({"stripe_balance_transaction_id": bt_id}, {"_id": 0, "id": 1})
        if not existing:
            await db.expenses.insert_one({
                "id": str(uuid.uuid4()), "date": _business_date_from_timestamp(created_iso),
                "description": f"Stripe processing fee · {bt_id}", "amount": fee_amount,
                "quantity": 1, "unit_price": fee_amount, "category": "Merchant fees", "notes": "Automatically reconciled from Stripe",
                "payment_method": "card", "tax_deductible": True, "from_cash_drawer": False,
                "vendor": "Stripe", "recurring": False, "source_kind": "stripe_processor_fee",
                "stripe_balance_transaction_id": bt_id, "stripe_source_object_id": obj.get("id"),
                "created_at": now_iso(), "created_by": "stripe_webhook",
            })


async def _handle_stripe_reconciliation_event(event_type: str, obj: dict) -> None:
    if event_type == "charge.succeeded":
        await _record_stripe_balance_transaction(obj, object_type="charge")
        return
    if event_type.startswith("payout."):
        payout_id = obj.get("id")
        if not payout_id:
            return
        arrival = obj.get("arrival_date")
        arrival_iso = None
        if isinstance(arrival, (int, float)):
            arrival_iso = datetime.fromtimestamp(arrival, tz=timezone.utc).date().isoformat()
        await db.stripe_payouts.update_one(
            {"id": payout_id},
            {"$set": {
                "id": payout_id, "status": obj.get("status") or event_type.split(".", 1)[1],
                "amount": round(float(obj.get("amount") or 0) / 100.0, 2), "currency": obj.get("currency"),
                "arrival_date": arrival_iso, "method": obj.get("method"), "type": obj.get("type"),
                "description": obj.get("description"), "failure_code": obj.get("failure_code"),
                "failure_message": obj.get("failure_message"), "balance_transaction": obj.get("balance_transaction"),
                "updated_at": now_iso(),
            }, "$setOnInsert": {"created_at": now_iso()}},
            upsert=True,
        )


@api.get("/admin/stripe/reconciliation")
async def stripe_reconciliation_summary(_: dict = Depends(require_admin_and_permission("finance_reports"))):
    txns = await db.stripe_balance_transactions.find({}, {"_id": 0}).sort("created_at", -1).to_list(200)
    payouts = await db.stripe_payouts.find({}, {"_id": 0}).sort("updated_at", -1).to_list(100)
    fee_total = round(sum(float(t.get("fee") or 0) for t in txns), 2)
    net_total = round(sum(float(t.get("net") or 0) for t in txns), 2)
    return {"balance_transactions": txns, "payouts": payouts, "processor_fees": fee_total, "net_activity": net_total}


STRIPE_DISPUTE_OPEN_STATUSES = {
    "warning_needs_response", "warning_under_review", "needs_response", "under_review",
}


async def _stripe_dispute_payment(dispute_obj: dict) -> tuple[Optional[dict], Optional[str]]:
    intent_id = dispute_obj.get("payment_intent")
    if not intent_id and dispute_obj.get("charge"):
        try:
            charge = stripe.Charge.retrieve(dispute_obj["charge"]).to_dict()
            intent_id = charge.get("payment_intent")
        except Exception as exc:
            logger.warning("Could not resolve Stripe charge %s for dispute %s: %s", dispute_obj.get("charge"), dispute_obj.get("id"), exc)
    if not intent_id:
        return None, None
    payment = await db.payments.find_one(
        {"$or": [
            {"processor": "stripe", "processor_payment_id": intent_id, "amount": {"$gt": 0}},
            {"source.stripe_payment_intent_id": intent_id, "amount": {"$gt": 0}},
        ]}, {"_id": 0},
    )
    return payment, intent_id


async def _apply_dispute_financial_state(dispute: dict) -> None:
    """Reflect a final lost/won dispute in operating income without mutating
    the original payment, invoice, entitlements, or tax. Chargeback tax
    treatment can require jurisdiction-specific evidence, so tax_amount is
    deliberately 0 here and remains a review item rather than guessed."""
    payment_id = dispute.get("payment_id")
    if not payment_id:
        return
    payment = await db.payments.find_one({"id": payment_id}, {"_id": 0})
    if not payment:
        return
    amount = round(float(dispute.get("amount") or 0), 2)
    if amount <= 0:
        return
    status = dispute.get("status")
    did = dispute["id"]
    ts = now_iso()
    if status == "lost" and not dispute.get("loss_finance_row_id"):
        existing = await db.retail_sales.find_one({"stripe_dispute_key": f"{did}:lost"}, {"_id": 0})
        if existing:
            row_id = existing["id"]
        else:
            row_id = str(uuid.uuid4())
            try:
                await db.retail_sales.insert_one({
                    "id": row_id, "date": business_today().isoformat(), "amount": -amount,
                    "payment_method": "stripe_online", "client_id": payment.get("client_id"),
                    "invoice_id": payment.get("invoice_id"), "shop_order_id": payment.get("shop_order_id"),
                    "reversed_payment_id": payment_id, "source_kind": "stripe_dispute_loss",
                    "stripe_dispute_id": did, "stripe_dispute_key": f"{did}:lost", "tax_amount": 0.0,
                    "description": f"Stripe dispute lost · {did}", "created_at": ts,
                    "created_by": "stripe_webhook", "logged_by": "Stripe",
                })
            except DuplicateKeyError:
                existing = await db.retail_sales.find_one({"stripe_dispute_key": f"{did}:lost"}, {"_id": 0})
                row_id = (existing or {}).get("id")
        if row_id:
            await db.stripe_disputes.update_one({"id": did}, {"$set": {"loss_finance_row_id": row_id, "updated_at": ts}})
    elif status == "won" and dispute.get("loss_finance_row_id") and not dispute.get("win_finance_row_id"):
        existing = await db.retail_sales.find_one({"stripe_dispute_key": f"{did}:won"}, {"_id": 0})
        if existing:
            row_id = existing["id"]
        else:
            row_id = str(uuid.uuid4())
            try:
                await db.retail_sales.insert_one({
                    "id": row_id, "date": business_today().isoformat(), "amount": amount,
                    "payment_method": "stripe_online", "client_id": payment.get("client_id"),
                    "invoice_id": payment.get("invoice_id"), "shop_order_id": payment.get("shop_order_id"),
                    "source_kind": "stripe_dispute_won", "stripe_dispute_id": did,
                    "stripe_dispute_key": f"{did}:won", "tax_amount": 0.0,
                    "description": f"Stripe dispute won · {did}", "created_at": ts,
                    "created_by": "stripe_webhook", "logged_by": "Stripe",
                })
            except DuplicateKeyError:
                existing = await db.retail_sales.find_one({"stripe_dispute_key": f"{did}:won"}, {"_id": 0})
                row_id = (existing or {}).get("id")
        if row_id:
            await db.stripe_disputes.update_one({"id": did}, {"$set": {"win_finance_row_id": row_id, "updated_at": ts}})


async def _handle_stripe_dispute_event(dispute_obj: dict) -> None:
    dispute_id = dispute_obj.get("id")
    if not dispute_id:
        return
    payment, intent_id = await _stripe_dispute_payment(dispute_obj)
    amount = round(float(dispute_obj.get("amount") or 0) / 100.0, 2)
    status = dispute_obj.get("status") or "unknown"
    ts = now_iso()
    doc = {
        "id": dispute_id, "status": status, "reason": dispute_obj.get("reason"),
        "amount": amount, "currency": dispute_obj.get("currency"), "charge_id": dispute_obj.get("charge"),
        "stripe_payment_intent_id": intent_id, "payment_id": (payment or {}).get("id"),
        "client_id": (payment or {}).get("client_id"), "invoice_id": (payment or {}).get("invoice_id"),
        "shop_order_id": (payment or {}).get("shop_order_id"),
        "evidence_due_by": ((dispute_obj.get("evidence_details") or {}).get("due_by")),
        "is_charge_refundable": dispute_obj.get("is_charge_refundable"),
        "updated_at": ts,
    }
    # created_at/first_seen_at belong to $setOnInsert ALONE. Putting them in
    # $set as well makes Mongo reject the whole update with "would create a
    # conflict at 'created_at'" — which fired on the FIRST event for every
    # dispute, so no dispute was ever recorded. $setOnInsert already gives
    # the correct semantics: stamped once on insert, never rewritten by a
    # later replay of the same dispute.
    await db.stripe_disputes.update_one(
        {"id": dispute_id},
        {"$set": doc, "$setOnInsert": {"created_at": ts, "first_seen_at": ts}},
        upsert=True,
    )
    if payment:
        await db.payments.update_one(
            {"id": payment["id"]},
            {"$set": {"stripe_dispute_id": dispute_id, "stripe_dispute_status": status,
                      "stripe_disputed_amount": amount, "updated_at": ts}},
        )
    fresh = await db.stripe_disputes.find_one({"id": dispute_id}, {"_id": 0})
    if fresh:
        await _apply_dispute_financial_state(fresh)


