@api.get("/admin/stripe-online-payments")
async def list_stripe_online_payments(limit: int = 50, q: Optional[str] = None, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Staff-facing read model for the Front Desk 'Online Payments' panel —
    the ONLY place stripe_online booking Payment rows are listed for staff.
    Deliberately separate from Recent Sales (pos_sales, unrelated collection).
    Returns only fields the refund UI needs: no PaymentIntent id, no
    Stripe secret/webhook data, no internal stripe_refund_attempts document.
    Filters to source.kind=="stripe_online_payment" so refund reversal rows
    (source.kind=="stripe_refund", negative amount) are never listed as if
    they were a separate original payment — same exclusion convention as
    _booking_refund_locked's stripe_gross calculation."""
    limit = max(1, min(int(limit or 50), 200))
    fetch_cap = max(limit * 4, 200)  # headroom for the trivial client/invoice-id filter below
    # Client Shop Phase 2 — a shop-order payment has source.kind==
    # "shop_order_payment" instead of "stripe_online_payment" (never a
    # refund reversal row either way — same exclusion convention as
    # _booking_refund_locked's stripe_gross calculation). Included here so
    # staff see ALL online card payments — invoice AND shop order — in one
    # list. Shop-order rows expose their immutable line allocation so the
    # line-aware refund UI can reverse only what was actually purchased.
    payments = await db.payments.find(
        {"method": "stripe_online", "source.kind": {"$in": ["stripe_online_payment", "shop_order_payment"]}}, {"_id": 0},
    ).sort("created_at", -1).to_list(fetch_cap)

    invoice_ids = list({p["invoice_id"] for p in payments if p.get("invoice_id")})
    invoices = await db.invoices.find(
        {"id": {"$in": invoice_ids}}, {"_id": 0, "id": 1, "client_name": 1},
    ).to_list(len(invoice_ids) or 1) if invoice_ids else []
    client_name_by_invoice = {inv["id"]: inv.get("client_name") or "" for inv in invoices}

    shop_order_ids = list({p["shop_order_id"] for p in payments if p.get("shop_order_id")})
    shop_orders = await db.shop_orders.find(
        {"id": {"$in": shop_order_ids}}, {"_id": 0, "id": 1, "client_name": 1, "lines": 1, "refund_status": 1, "refund_reconciliation_required": 1},
    ).to_list(len(shop_order_ids) or 1) if shop_order_ids else []
    client_name_by_order = {o["id"]: o.get("client_name") or "" for o in shop_orders}
    shop_order_by_id = {o["id"]: o for o in shop_orders}

    payment_ids = [p["id"] for p in payments]
    active_attempts = await db.stripe_refund_attempts.find(
        {"payment_id": {"$in": payment_ids}, "status": {"$nin": list(STRIPE_REFUND_TERMINAL_STATUSES)}},
        {"_id": 0, "payment_id": 1, "status": 1},
    ).to_list(len(payment_ids) or 1) if payment_ids else []
    active_status_by_payment = {a["payment_id"]: a["status"] for a in active_attempts}

    q_norm = (q or "").strip().lower()
    rows = []
    for p in payments:
        invoice_id = p.get("invoice_id")
        shop_order_id = p.get("shop_order_id")
        client_name = client_name_by_invoice.get(invoice_id, "") if invoice_id else client_name_by_order.get(shop_order_id, "")
        ref_id = invoice_id or shop_order_id or ""
        if q_norm and q_norm not in client_name.lower() and q_norm not in ref_id.lower():
            continue
        amount = round(float(p.get("amount") or 0), 2)
        refunded_amount = round(float(p.get("refunded_amount") or 0), 2)
        remaining_refundable = round(max(0.0, amount - refunded_amount), 2)
        source = p.get("source") or {}
        refund_status = active_status_by_payment.get(p["id"])
        rows.append({
            "payment_id": p["id"],
            "invoice_id": invoice_id,
            "shop_order_id": shop_order_id,
            "client_name": client_name,
            "created_at": p.get("created_at"),
            "amount": amount,
            "refunded_amount": refunded_amount,
            "remaining_refundable": remaining_refundable,
            "status": p.get("status"),
            "card_brand": source.get("card_brand"),
            "card_last4": source.get("card_last4"),
            "refund_in_progress": refund_status is not None,
            "refund_status": refund_status,
            "dispute_id": p.get("stripe_dispute_id"),
            "dispute_status": p.get("stripe_dispute_status"),
            "disputed_amount": round(float(p.get("stripe_disputed_amount") or 0), 2),
            "shop_lines": [
                {
                    "item_id": l.get("item_id"), "kind": l.get("kind"), "name": l.get("name"),
                    "quantity": int(l.get("quantity") or 0), "quantity_refunded": int(l.get("quantity_refunded") or 0),
                    "amount_refunded": round(float(l.get("amount_refunded") or 0), 2),
                    "line_total": round(float(l.get("line_total") or 0), 2),
                    "fulfillment_kind": l.get("fulfillment_kind"),
                } for l in ((shop_order_by_id.get(shop_order_id) or {}).get("lines") or [])
            ] if shop_order_id else [],
            "shop_refund_status": (shop_order_by_id.get(shop_order_id) or {}).get("refund_status") if shop_order_id else None,
            "shop_refund_reconciliation_required": bool((shop_order_by_id.get(shop_order_id) or {}).get("refund_reconciliation_required")) if shop_order_id else False,
        })
        if len(rows) >= limit:
            break
    return {"payments": rows}


async def get_register_session(date: Optional[str] = None, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    date_value = _validated_register_date(date, allow_future=False)
    return await _register_session_view(date_value)


async def get_register_status(user: dict = Depends(require_employee_or_admin)):
    """Operational register state — least privilege.

    A cashier authorized to take money (take_payments / sell_credits) must
    be able to see whether today's register is genuinely OPEN, CLOSED, or
    NOT_OPEN — the full session view above stays finance_reports because it
    carries expected/actual cash and over/short figures. This returns the
    bare state only: no cash amounts, no totals, no closeout numbers.
    """
    perms = _perms_for(user)
    if not (perms.get("take_payments") or perms.get("sell_credits") or perms.get("finance_reports")):
        raise HTTPException(status_code=403, detail="You don't have permission to operate the register.")
    date_value = business_today().isoformat()
    session = await db.cash_drawer_sessions.find_one({"date": date_value}, {"_id": 0, "opened_at": 1, "opened_by_name": 1})
    active_closeout = await _active_register_closeout(date_value)
    status = "CLOSED" if active_closeout else ("OPEN" if session else "NOT_OPEN")
    return {
        "date": date_value,
        "status": status,
        "opened_at": (session or {}).get("opened_at"),
        "opened_by": (session or {}).get("opened_by_name"),
    }


