async def _reassign_items_off_subcategory(subcategory_id: str, new_subcategory_id: Optional[str], keep_category: bool) -> int:
    updated = 0
    patch: Dict[str, Any] = {"subcategory_id": new_subcategory_id, "updated_at": now_iso()}
    if not keep_category:
        patch["category_id"] = None
    for kind, coll_name in SHOP_ITEM_KIND_COLLECTIONS.items():
        coll = getattr(db, coll_name)
        res = await coll.update_many({"subcategory_id": subcategory_id}, {"$set": patch})
        updated += res.modified_count
    return updated


@api.delete("/shop/subcategories/{subcategory_id}")
async def remove_shop_subcategory(subcategory_id: str, body: ShopSubcategoryRemoveIn, user: dict = Depends(require_employee_or_admin)):
    _require_shop_org_perm(user, "delete_shop_categories")
    subcategory = await db.shop_subcategories.find_one({"id": subcategory_id}, {"_id": 0})
    if not subcategory:
        raise HTTPException(status_code=404, detail="Subcategory not found.")

    if body.action == "deactivate":
        await db.shop_subcategories.update_one({"id": subcategory_id}, {"$set": {
            "active": False, "updated_at": now_iso(), "updated_by": user.get("name", "Admin"),
        }})
        return {"ok": True, "action": "deactivated"}

    if body.action == "move_to_category":
        moved = await _reassign_items_off_subcategory(subcategory_id, None, keep_category=True)
        await db.shop_subcategories.delete_one({"id": subcategory_id})
        return {"ok": True, "action": "moved_to_category", "items_moved": moved}

    if body.action == "move_to_subcategory":
        if not body.target_subcategory_id or body.target_subcategory_id == subcategory_id:
            raise HTTPException(status_code=400, detail="Pick a different destination subcategory.")
        target = await db.shop_subcategories.find_one({"id": body.target_subcategory_id}, {"_id": 0})
        if not target:
            raise HTTPException(status_code=404, detail="Destination subcategory not found.")
        if target["category_id"] != subcategory["category_id"]:
            raise HTTPException(status_code=400, detail="Destination subcategory must belong to the same category.")
        moved = await _reassign_items_off_subcategory(subcategory_id, body.target_subcategory_id, keep_category=True)
        await db.shop_subcategories.delete_one({"id": subcategory_id})
        return {"ok": True, "action": "moved", "items_moved": moved}

    raise HTTPException(status_code=400, detail="Unknown removal action.")


@api.post("/shop/items/bulk-assign")
async def bulk_assign_shop_items(body: ShopBulkAssignIn, user: dict = Depends(require_employee_or_admin)):
    """A single bulk-assign call can mix item kinds (e.g. selecting a product
    and a credit pack together in the Shop Manager Items list), so the
    category/subcategory's section is checked once up front here, and any
    entry whose OWN kind doesn't belong to that section is skipped with an
    error rather than silently reassigned — never a partial, wrong-section
    write, and every other valid entry in the batch still goes through."""
    _require_shop_org_perm(user, "manage_shop_categories")
    await _validate_category_subcategory_pair(body.category_id, body.subcategory_id)
    target_section = None
    if body.category_id:
        target_cat = await db.shop_categories.find_one({"id": body.category_id}, {"_id": 0, "section": 1})
        target_section = (target_cat or {}).get("section")
    updated = 0
    errors: List[Dict[str, str]] = []
    for entry in body.items:
        if target_section and SHOP_SECTION_FOR_KIND.get(entry.kind) != target_section:
            errors.append({
                "kind": entry.kind, "id": entry.id,
                "detail": f"This item belongs to {SHOP_SECTION_LABELS.get(SHOP_SECTION_FOR_KIND.get(entry.kind), 'a different section')}, not {SHOP_SECTION_LABELS.get(target_section, target_section)}.",
            })
            continue
        coll_name = SHOP_ITEM_KIND_COLLECTIONS.get(entry.kind)
        coll = getattr(db, coll_name)
        res = await coll.update_one(
            {"id": entry.id},
            {"$set": {"category_id": body.category_id, "subcategory_id": body.subcategory_id, "updated_at": now_iso()}},
        )
        if res.matched_count:
            updated += 1
        else:
            errors.append({"kind": entry.kind, "id": entry.id, "detail": "Item not found"})
    return {"updated": updated, "errors": errors}


# ─────────────────────────────────────────────────────────────────────────────
# Shop Manager unification — one admin-facing aggregation across the three
# specialized item kinds. This is a READ projection only: it never creates a
# generic item model, never touches pos_products/credit_packs/programs'
# specialized fields, and every write (create/edit/archive/duplicate/etc.)
# still goes through each kind's own existing endpoint. Unifies the admin
# LISTING/FILTERING experience only, per the architecture rule.
# ─────────────────────────────────────────────────────────────────────────────

def _shop_manager_item_view(doc: dict, kind: str) -> dict:
    """Normalizes one pos_products/credit_packs/programs document into the
    common shape the Shop Manager Items table renders — never mutates or
    re-derives anything the specialized collections themselves own."""
    section = SHOP_SECTION_FOR_KIND[kind]
    base = {
        "id": doc["id"],
        "kind": kind,
        "section": section,
        "section_label": SHOP_SECTION_LABELS[section],
        "name": doc.get("name"),
        "image_id": doc.get("image_id"),
        "missing_image": not doc.get("image_id"),
        "category_id": doc.get("category_id"),
        "subcategory_id": doc.get("subcategory_id"),
        "active": bool(doc.get("active", True)),
        "featured": bool(doc.get("featured", False)),
        "show_at_register": doc.get("show_at_register", True) is not False,
        "created_at": doc.get("created_at"),
    }
    if kind == "physical_product":
        is_shopify = doc.get("sales_destination") == "shopify_external"
        base.update({
            "show_online": bool(doc.get("show_online")),
            "archived": bool(doc.get("archived")),
            "list_price": None if is_shopify else round(float(doc.get("price") or 0), 2),
            "pricing_variable": not is_shopify,  # Shopify-linked items are never overridden — Shopify owns that price.
            "sales_destination": doc.get("sales_destination") or "internal",
            "shopify_product_url": doc.get("shopify_product_url"),
            "shopify_display_price": doc.get("shopify_display_price"),
            "shopify_from_price": bool(doc.get("shopify_from_price")),
            "track_inventory": bool(doc.get("track_inventory")),
            "stock_on_hand": round(float(doc.get("stock_on_hand") or 0), 2) if doc.get("track_inventory") else None,
            "low_stock_threshold": doc.get("low_stock_threshold"),
            "missing_description": not (doc.get("online_description") or doc.get("description") or "").strip(),
            # Admin-only (this whole endpoint is gated on the pricing
            # permission) — never surfaced through _build_shop_catalog, so
            # Client Preview/the client Shop never see a product's cost.
            "cost": None if is_shopify else doc.get("cost"),
        })
    elif kind == "credit_pack":
        base.update({
            "show_online": bool(doc.get("available_online")),
            "archived": False,
            "list_price": round(float(doc.get("price") or 0), 2),
            "pricing_variable": True,
            "qty": doc.get("qty"),
            "service_type": doc.get("service_type"),
            "is_default": bool(doc.get("is_default")),
            "missing_description": not (doc.get("online_description") or "").strip(),
        })
    else:  # training_program
        fmt = doc.get("format") or {}
        base.update({
            "show_online": bool(doc.get("available_online")),
            "archived": False,
            "list_price": round(float(doc.get("price") or 0), 2),
            "pricing_variable": False,  # no client-specific/tier override resolver is wired up for programs today
            "program_type": doc.get("type"),
            "format_count": fmt.get("count"),
            "format_unit": fmt.get("unit"),
            "is_default": bool(doc.get("is_default")),
            "missing_description": not (doc.get("online_description") or doc.get("description") or "").strip(),
        })
    return base


@api.get("/shop-manager/items")
async def shop_manager_list_items(
    section: Optional[str] = None,
    category_id: Optional[str] = None,
    uncategorized_only: bool = False,
    hidden_only: bool = False,
    include_archived: bool = False,
    search: Optional[str] = None,
    user: dict = Depends(require_admin_and_permission("pricing")),
):
    """The single data source behind the Shop Manager's Items tab. Queries
    the three specialized collections directly (never a merged/generic
    collection) and tags each with its permanent section (derived purely
    from kind — see SHOP_SECTION_FOR_KIND).

    `hidden_only` means "not visible anywhere a client or the register would
    see it" — inactive, or active-but-hidden from both channels. `category_id`
    accepts the literal string "uncategorized" as a shorthand for
    `uncategorized_only=true` so the frontend can treat it as one more
    category option instead of a separate toggle."""
    if category_id == "uncategorized":
        uncategorized_only = True
        category_id = None

    products = await db.pos_products.find({}, {"_id": 0}).to_list(5000)
    packs = await db.credit_packs.find({}, {"_id": 0}).to_list(2000)
    programs = await db.programs.find({}, {"_id": 0}).to_list(2000)

    items = (
        [_shop_manager_item_view(p, "physical_product") for p in products if include_archived or not p.get("archived")]
        + [_shop_manager_item_view(p, "credit_pack") for p in packs]
        + [_shop_manager_item_view(p, "training_program") for p in programs]
    )

    if section:
        items = [it for it in items if it["section"] == section]
    if uncategorized_only:
        items = [it for it in items if not it.get("category_id")]
    elif category_id:
        items = [it for it in items if it.get("category_id") == category_id]
    if hidden_only:
        items = [it for it in items if not it["active"] or (not it["show_online"] and not it["show_at_register"])]
    if search:
        q = search.strip().lower()
        if q:
            items = [it for it in items if q in (it.get("name") or "").lower()]

    # Category/subcategory names — one pass, not per-item queries.
    cat_ids = {it["category_id"] for it in items if it.get("category_id")}
    sub_ids = {it["subcategory_id"] for it in items if it.get("subcategory_id")}
    cats = {c["id"]: c for c in await db.shop_categories.find({"id": {"$in": list(cat_ids)}}, {"_id": 0}).to_list(500)} if cat_ids else {}
    subs = {s["id"]: s for s in await db.shop_subcategories.find({"id": {"$in": list(sub_ids)}}, {"_id": 0}).to_list(2000)} if sub_ids else {}
    for it in items:
        cat = cats.get(it.get("category_id"))
        sub = subs.get(it.get("subcategory_id"))
        it["category_name"] = cat["name"] if cat else None
        it["subcategory_name"] = sub["name"] if sub else None
        # "Category Hidden" admin warning — an item can stay assigned to a
        # category an admin later deactivated; this is display-only and
        # never changes the assignment or the item's own visibility.
        it["category_hidden"] = bool(cat) and not cat.get("active", True)

    items.sort(key=lambda it: (it["section"], (it.get("category_name") or "￿"), it.get("name") or ""))
    return {"items": items}


def _public_purchase_state(kind: str, item_doc: dict, *, global_show_public_prices: bool = True) -> dict:
    """Public no-account storefront — migration-safe public-visibility/
    purchase-state resolution for one catalog item. Computed from BOTH the
    item's kind AND every account-dependent requirement flag — a product
    can't be guest-cart-eligible merely because guest_cart_allowed is stored
    True if it also requires_dog/requires_approval/requires_completed_onboarding,
    nor if its price isn't visible to guests. account_required is NEVER a
    stored/input field — only ever computed here, so it can never be
    misconfigured into a guest-checkout bypass."""
    is_product = kind == "product"
    publicly_visible = item_doc.get("publicly_visible")
    if publicly_visible is None:
        publicly_visible = True  # caller already filtered to show_online/available_online rows
    requires_dog = bool(item_doc.get("requires_dog", False))
    requires_approval = bool(item_doc.get("requires_approval", False))
    requires_completed_onboarding = bool(item_doc.get("requires_completed_onboarding", False))
    has_account_requirement = requires_dog or requires_approval or requires_completed_onboarding
    price_visible = global_show_public_prices and bool(item_doc.get("show_public_price", True))
    stored_guest_cart_allowed = is_product and bool(item_doc.get("guest_cart_allowed", False))
    # Effective eligibility: kind must be product, the stored flag must be
    # True, NONE of the account-dependent requirements may apply, AND price
    # must actually be visible — any one of these overrides the stored flag.
    guest_cart_allowed = stored_guest_cart_allowed and not has_account_requirement and price_visible
    account_required = (not is_product) or has_account_requirement or not stored_guest_cart_allowed
    # Free Online School claim eligibility is COMPUTED here for the same
    # reason account_required is: a storefront must never decide that
    # something is claimable just because a stored flag says so. This mirrors
    # the server's own claim gate exactly (_free_claim_program_blockers), so
    # the CTA a visitor sees and the rule the claim endpoint enforces can
    # never drift apart. A $0 program with no explicit opt-in returns False.
    free_claim_available = kind == "training_program" and _free_claim_program_blockers(item_doc) is None
    return {
        "publicly_visible": bool(publicly_visible),
        "account_required": account_required,
        "free_claim_available": free_claim_available,
        "guest_cart_allowed": guest_cart_allowed,
        "show_public_price": price_visible,
        "requires_dog": requires_dog,
        "requires_approval": requires_approval,
        "requires_completed_onboarding": requires_completed_onboarding,
    }


def _credit_pack_display_fields(pk: dict, qty: int, effective_price: float) -> dict:
    """Presentation-only credit-pack fields — never used for credit
    granting/redemption/FIFO lots/balances/voids/refunds, which always key
    off `qty` and `effective_price` directly. display_price_each and
    credits_per_display_unit are derived from the CALLER's effective_price
    (already grandfathered/tier-price-resolved), never the raw list price,
    so a client-specific override recalculates the displayed per-unit price
    too."""
    display_quantity = pk.get("display_quantity")
    out = {
        "display_quantity": display_quantity,
        "display_unit": pk.get("display_unit"),
        "display_dog_count": pk.get("display_dog_count"),
        "display_price_each": None,
        "credits_per_display_unit": None,
    }
    if display_quantity:
        dq = float(display_quantity)
        out["display_price_each"] = round(float(effective_price) / dq, 2)
        out["credits_per_display_unit"] = round(float(qty) / dq, 2)
    return out


async def _build_shop_catalog(client_id: Optional[str]) -> dict:
    """The one real catalog-building routine — read-only aggregation across
    the three specialized collections, tagging each result with a `kind`
    discriminator, applying the SAME resolve_client_price() every purchase
    path trusts, and the same Shop Organization visibility rules. Shared by
    the authenticated client Shop endpoint AND the admin Shop Manager Client
    Preview tab, so the preview is never a fake approximation — it is
    calling this exact function. `client_id=None` (used by the admin
    preview when previewing as "no specific client") resolves every item to
    its standard/public price, since resolve_client_price() already
    short-circuits to standard pricing when there's no client to look up.
    """
    # Shop Organization (Phase 1) — only ACTIVE categories/subcategories are
    # ever attached to a client-facing item. An item assigned to a category
    # or subcategory that's since gone inactive is hidden from the Shop
    # entirely (it stays fully editable/active in admin — see
    # _shop_org_visible below) rather than shown miscategorized or under a
    # hidden section. Uncategorized items (category_id is None) are always
    # shown — existing data never breaks because of this rollout.
    active_cats = {c["id"]: c for c in await db.shop_categories.find({"active": True}, {"_id": 0}).to_list(500)}
    active_subs = {s["id"]: s for s in await db.shop_subcategories.find({"active": True}, {"_id": 0}).to_list(2000)}

    def _shop_org_visible(cat_id, sub_id):
        if not cat_id:
            return True
        if cat_id not in active_cats:
            return False
        if sub_id and sub_id not in active_subs:
            return False
        return True

    def _shop_org_fields(cat_id, sub_id):
        cat = active_cats.get(cat_id) if cat_id else None
        sub = active_subs.get(sub_id) if sub_id else None
        return {
            "category_id": cat["id"] if cat else None,
            "category_name": cat["name"] if cat else None,
            "subcategory_id": sub["id"] if sub else None,
            "subcategory_name": sub["name"] if sub else None,
        }

    # Shop Appearance settings — a section with visible:false is hidden from
    # EVERY audience (authenticated client and guest alike) from this one
    # place, rather than three separate re-implementations. Additive: when
    # unset, every section defaults to visible (today's behavior).
    _shop_page_sections = ((await get_settings()).get("shop_page") or {}).get("sections") or {}
    _section_visible = {
        sec: bool((_shop_page_sections.get(sec) or {}).get("visible", True)) for sec in SHOP_SECTIONS
    }

    items = []

    products = await db.pos_products.find(
        {"show_online": True, "active": True, "archived": {"$ne": True}}, {"_id": 0},
    ).sort([("online_sort_order", 1), ("id", 1)]).to_list(length=None) if _section_visible["merch"] else []
    for p in products:
        if not _shop_org_visible(p.get("category_id"), p.get("subcategory_id")):
            continue
        if p.get("sales_destination") == "shopify_external":
            # Shopify-linked merchandise — a display-only catalog link.
            # Shopify remains authoritative for price/inventory/checkout, so
            # this is deliberately NEVER run through resolve_client_price()
            # (client-specific/grandfathered pricing doesn't apply to it —
            # see the pos_product guard in create_client_price_override /
            # set_pricing_tier_price) and carries no cart-relevant fields.
            items.append({
                "kind": "product",
                "id": p["id"],
                "name": p.get("name"),
                "description": p.get("online_description") or p.get("description") or "",
                "category": p.get("category") or "",
                "sales_destination": "shopify_external",
                "shopify_product_url": p.get("shopify_product_url"),
                "shopify_display_price": p.get("shopify_display_price"),
                "shopify_from_price": bool(p.get("shopify_from_price")),
                "featured": bool(p.get("featured")),
                "image_id": p.get("image_id"),
                "sort_order": p.get("online_sort_order"),
                # Public no-account storefront (Phase 1c fields) — carried
                # through from the stored doc so _public_purchase_state ever
                # sees the real values instead of silently falling back to
                # its defaults. Copied for every kind/branch below too.
                "publicly_visible": p.get("publicly_visible"),
                "guest_cart_allowed": bool(p.get("guest_cart_allowed", False)),
                "show_public_price": bool(p.get("show_public_price", True)),
                "requires_dog": bool(p.get("requires_dog", False)),
                "requires_approval": bool(p.get("requires_approval", False)),
                "requires_completed_onboarding": bool(p.get("requires_completed_onboarding", False)),
                **_shop_org_fields(p.get("category_id"), p.get("subcategory_id")),
            })
            continue
        track = bool(p.get("track_inventory"))
        stock = float(p.get("stock_on_hand") or 0)
        list_price = round(float(p.get("price") or 0), 2)
        # Reuse the exact same resolver every other grandfathered-pricing
        # path (Shop cart, front-desk sell, credit-pack catalog above)
        # already trusts — an authenticated client must see (and later be
        # charged) their locked individual or tier rate here too, never the
        # raw catalog price. Unauthenticated visitors never reach this route
        # at all (client account required, checked above), so they only
        # ever see the public price via other surfaces.
        pricing = await resolve_client_price(client_id, "pos_product", p["id"], list_price)
        effective_price = round(float(pricing["effective_price"]), 2)
        has_override = pricing["pricing_source"] != "standard"
        items.append({
            "kind": "product",
            "id": p["id"],
            "name": p.get("name"),
            "description": p.get("online_description") or p.get("description") or "",
            "category": p.get("category") or "",
            "sales_destination": "internal",
            "featured": bool(p.get("featured")),
            "list_price": list_price,
            "effective_price": effective_price,
            "pricing_source": pricing["pricing_source"],
            "price_override_id": pricing["override_id"],
            "has_price_override": has_override,
            "image_id": p.get("image_id"),
            "sort_order": p.get("online_sort_order"),
            "track_inventory": track,
            "in_stock": (not track) or (stock > 0.0005),
            "stock_on_hand": round(stock, 2) if track else None,
            "low_stock_threshold": p.get("low_stock_threshold") if track else None,
            # Backward-compatible aliases for existing consumers — new code
            # should read the clearer fields above instead.
            "price": effective_price,
            "legacy_price": list_price if has_override else None,
            "has_legacy_override": has_override,
            "publicly_visible": p.get("publicly_visible"),
            "guest_cart_allowed": bool(p.get("guest_cart_allowed", False)),
            "show_public_price": bool(p.get("show_public_price", True)),
            "requires_dog": bool(p.get("requires_dog", False)),
            "requires_approval": bool(p.get("requires_approval", False)),
            "requires_completed_onboarding": bool(p.get("requires_completed_onboarding", False)),
            **_shop_org_fields(p.get("category_id"), p.get("subcategory_id")),
        })

    packs = await db.credit_packs.find(
        {"available_online": True, "active": True}, {"_id": 0},
    ).sort([("name", 1), ("id", 1)]).to_list(length=None) if _section_visible["prepaid_visits"] else []
    for pk in packs:
        if not _shop_org_visible(pk.get("category_id"), pk.get("subcategory_id")):
            continue
        qty = int(pk.get("qty") or 0)
        list_price = round(float(pk.get("price") or 0), 2)
        # Reuse the exact same resolver every other credit-pack purchase path
        # (front-desk sell-pack, booking checkout) already trusts — a
        # grandfathered client must see and be charged their locked rate
        # here too, never the raw catalog price.
        pricing = await resolve_client_price(client_id, "credit_pack", pk["id"], list_price)
        effective_price = round(float(pricing["effective_price"]), 2)
        has_override = bool(pricing["override_id"])
        items.append({
            "kind": "credit_pack",
            "id": pk["id"],
            "name": pk.get("name"),
            "description": pk.get("online_description") or "",
            "service_type": pk.get("service_type"),
            "qty": qty,
            "list_price": list_price,
            "effective_price": effective_price,
            "pricing_source": "client_override" if has_override else "standard",
            "price_override_id": pricing["override_id"],
            "has_price_override": has_override,
            "value_each": round(effective_price / max(qty, 1), 2),
            "image_id": pk.get("image_id"),
            "featured": bool(pk.get("featured")),
            # Backward-compatible aliases for existing consumers — new code
            # should read the clearer fields above instead.
            "price": effective_price,
            "legacy_price": list_price if has_override else None,
            "has_legacy_override": has_override,
            "publicly_visible": pk.get("publicly_visible"),
            "show_public_price": bool(pk.get("show_public_price", True)),
            "requires_completed_onboarding": bool(pk.get("requires_completed_onboarding", False)),
            **_credit_pack_display_fields(pk, qty, effective_price),
            **_shop_org_fields(pk.get("category_id"), pk.get("subcategory_id")),
        })

    programs = await db.programs.find(
        {"available_online": True, "active": True}, {"_id": 0},
    ).sort([("name", 1), ("id", 1)]).to_list(length=None) if _section_visible["training"] else []
    for prog in programs:
        if not _shop_org_visible(prog.get("category_id"), prog.get("subcategory_id")):
            continue
        fmt = prog.get("format") or {}
        items.append({
            "kind": "training_program",
            "id": prog["id"],
            "name": prog.get("name"),
            "description": prog.get("online_description") or prog.get("description") or "",
            "focus": prog.get("focus") or "",
            "program_type": prog.get("type"),
            "format_count": fmt.get("count"),
            "format_unit": fmt.get("unit"),
            "min_age_months": prog.get("min_age_months") or 0,
            "price": round(float(prog.get("price") or 0), 2),
            "image_id": prog.get("image_id"),
            "featured": bool(prog.get("featured")),
            "publicly_visible": prog.get("publicly_visible"),
            "show_public_price": bool(prog.get("show_public_price", True)),
            "requires_dog": bool(prog.get("requires_dog", False)),
            "requires_approval": bool(prog.get("requires_approval", False)),
            "requires_completed_onboarding": bool(prog.get("requires_completed_onboarding", False)),
            # Phase 5 — client-facing so the Shop item detail page knows
            # whether to show a dog selector / real ownership CTA states.
            "purchase_fulfillment": prog.get("purchase_fulfillment") or "credits_only",
            # Free Online School claim — COMPUTED from the stored program by
            # the same helper the claim endpoint enforces, never a passthrough
            # of the raw flag. A $0 program with no explicit opt-in resolves
            # False here, so the Shop can never offer to claim one.
            "free_claim_available": _free_claim_program_blockers(prog) is None,
            "estimated_weeks": prog.get("estimated_weeks"),
            "school_support": prog.get("school_support") or {},
            "school_onboarding": prog.get("school_onboarding") or {},
            "recommended_next_program_slugs": prog.get("recommended_next_program_slugs") or [],
            # Online School storefront — card content. Bullet lists are admin-
            # authored marketing copy (ProgramIn.helps_with/welcome_outcomes);
            # counts are derived here so the storefront never needs the
            # curriculum itself (module/lesson NAMES stay non-public until
            # enrollment's welcome page).
            "helps_with": prog.get("helps_with") or [],
            "welcome_outcomes": prog.get("welcome_outcomes") or [],
            "module_count": len(prog.get("modules") or []),
            "lesson_count": sum(len(_effective_lessons(m)) for m in (prog.get("modules") or [])),
            **_shop_org_fields(prog.get("category_id"), prog.get("subcategory_id")),
        })

    return {"items": items}


async def _build_register_catalog(client_id: Optional[str]) -> dict:
    """Compatibility facade; register catalog ownership is domains.pos."""
    return await pos_domain_services.build_register_catalog(client_id)


async def get_register_catalog(client_id: Optional[str] = None, user: dict = Depends(require_employee_or_admin)):
    """Front Desk's real product/pack/program catalog — the register-visible
    counterpart to GET /shop/catalog. `client_id`, when given, resolves that
    client's grandfathered/tier pricing on every eligible line (products,
    credit packs); walk-in sales (no client_id) always see the standard
    price, exactly like an unauthenticated Shop visitor would."""
    _require_take_payments(user)
    return await _build_register_catalog(client_id)


@api.get("/shop/catalog")
async def get_shop_catalog(user: dict = Depends(get_current_user)):
    """Client Shop Phase 1 — thin auth wrapper around _build_shop_catalog().
    Returns only safe, client-facing fields — no cost, no
    inventory_movements history, no Stripe/idempotency internals, no admin
    notes. image_id only (never embedded image bytes) — the frontend
    fetches GET /shop/media/{id} separately per image."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    return await _build_shop_catalog(user.get("client_id"))


# Client Shop Item Detail page — kind here matches the catalog's own
# discriminator ("product"/"credit_pack"/"training_program"), the same
# strings used by the cart/checkout (ShopCartItemIn.kind), not the admin
# Shop Manager's "physical_product" spelling.
_SHOP_ITEM_DETAIL_SECTION = {"product": "merch", "credit_pack": "prepaid_visits", "training_program": "training"}


@api.get("/shop/item/{kind}/{item_id}")
async def get_shop_item_detail(kind: str, item_id: str, user: dict = Depends(get_current_user)):
    """Single-item detail view for the client Shop's item detail page.
    Reuses _build_shop_catalog so price, description, and visibility are
    byte-for-byte identical to the catalog grid, cart, and checkout — this
    is never a second pricing/visibility implementation. Returns 404 (never
    403/a distinguishable "hidden" response) for anything nonexistent,
    inactive, or not shown in the client Shop, so a guessed or stale URL
    can't be used to confirm an item's existence or peek at admin-only
    state."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    if kind not in _SHOP_ITEM_DETAIL_SECTION:
        raise HTTPException(status_code=404, detail="This item is unavailable.")
    catalog = await _build_shop_catalog(user.get("client_id"))
    item = next((dict(i) for i in catalog["items"] if i["kind"] == kind and i["id"] == item_id), None)
    if not item:
        raise HTTPException(status_code=404, detail="This item is unavailable.")
    section = _SHOP_ITEM_DETAIL_SECTION[kind]
    item["section"] = section
    item["section_label"] = SHOP_SECTION_LABELS[section]
    if kind == "training_program":
        prog = await db.programs.find_one({"id": item_id}, {"_id": 0})
        prereq_slugs = (prog or {}).get("prereq_slugs") or []
        if prereq_slugs:
            prereq_docs = await db.programs.find({"slug": {"$in": prereq_slugs}}, {"_id": 0, "name": 1, "slug": 1}).to_list(20)
            prereq_by_slug = {p.get("slug"): p.get("name") for p in prereq_docs}
            item["prerequisite_names"] = [prereq_by_slug.get(slug) or slug for slug in prereq_slugs]
        else:
            item["prerequisite_names"] = []

        # Online School prerequisites are per DOG, not merely per account.
        # Return an explicit server-derived eligibility row for each of this
        # client's dogs so the detail page can guide the customer before cart/
        # checkout while the checkout endpoint remains the final authority.
        item["school_prerequisite_eligibility"] = []
        if (prog or {}).get("purchase_fulfillment") == "online_school":
            client_dogs = await db.dogs.find(
                {"owner_id": user.get("client_id")}, {"_id": 0, "id": 1, "name": 1}
            ).to_list(200)
            for dog in client_dogs:
                missing = await _missing_program_prerequisites(dog["id"], prog or {})
                item["school_prerequisite_eligibility"].append({
                    "dog_id": dog["id"], "dog_name": dog.get("name"),
                    "eligible": len(missing) == 0, "missing": missing,
                })

        next_slugs = (prog or {}).get("recommended_next_program_slugs") or []
        if next_slugs:
            next_docs = await db.programs.find({"slug": {"$in": next_slugs}, "active": True}, {"_id": 0, "name": 1, "slug": 1}).to_list(20)
            by_slug = {x.get("slug"): x.get("name") for x in next_docs}
            item["recommended_next_programs"] = [{"slug": slug, "name": by_slug.get(slug) or slug} for slug in next_slugs]
        else:
            item["recommended_next_programs"] = []
    return item


@api.get("/shop-manager/catalog-preview")
async def shop_manager_catalog_preview(
    preview_client_id: Optional[str] = None,
    _: dict = Depends(require_admin_and_permission("pricing")),
):
    """Shop Manager Client Preview tab — calls the EXACT same catalog
    builder the real client Shop uses, so this is never a fake
    approximation. With no `preview_client_id`, every item resolves to its
    standard/public price (what an unauthenticated or override-free client
    would see). Passing a real client id previews their actual grandfathered/
    tier/individual-override price, using the same resolver the real
    checkout charges from."""
    if preview_client_id:
        client = await db.clients.find_one({"id": preview_client_id}, {"_id": 0, "id": 1})
        if not client:
            raise HTTPException(status_code=404, detail="Client not found")
    return await _build_shop_catalog(preview_client_id)


async def _shop_taxonomy_payload() -> dict:
    """Active-only category/subcategory navigation, in configured order —
    the one implementation shared by the client-facing endpoint and the
    admin Shop Manager preview (so preview is never a fake approximation)."""
    cats = await db.shop_categories.find({"active": True}, {"_id": 0}).sort("sort_order", 1).to_list(500)
    subs = await db.shop_subcategories.find({"active": True}, {"_id": 0}).sort("sort_order", 1).to_list(2000)
    subs_by_cat: Dict[str, List[dict]] = {}
    for s in subs:
        subs_by_cat.setdefault(s["category_id"], []).append(
            {"id": s["id"], "name": s["name"], "description": s.get("description"), "icon": s.get("icon"),
             "image_id": s.get("image_id"), "mobile_image_id": s.get("mobile_image_id")}
        )
    return {"categories": [
        {"id": c["id"], "name": c["name"], "description": c.get("description"), "icon": c.get("icon"),
         "image_id": c.get("image_id"), "mobile_image_id": c.get("mobile_image_id"),
         "is_featured": bool(c.get("is_featured")), "hide_when_empty": c.get("hide_when_empty"),
         "subcategories": subs_by_cat.get(c["id"], [])}
        for c in cats
    ]}


@api.get("/shop/catalog/taxonomy")
async def get_shop_catalog_taxonomy(user: dict = Depends(get_current_user)):
    """Public (client-facing) category/subcategory navigation — active only,
    in configured order. Separate from GET /shop/categories (the admin
    endpoint, which needs auth + inactive rows + counts for management)."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    return await _shop_taxonomy_payload()


@api.get("/shop-manager/catalog-preview-taxonomy")
async def shop_manager_catalog_preview_taxonomy(_: dict = Depends(require_admin_and_permission("pricing"))):
    """Shop Manager Client Preview tab — the exact same taxonomy payload a
    real client sees, so PortalShop's preview mode can render real category
    navigation without needing a role=='client' account. Same permission
    gate as GET /shop-manager/catalog-preview (the item/pricing sibling)."""
    return await _shop_taxonomy_payload()


# ─────────────────────────────────────────────────────────────────────────────
# Public no-account storefront (Phase 2a/2b) — read-only, allowlist-only
# surface for signed-out visitors. Every response below is built from an
# EXPLICIT per-kind field allowlist (never `dict(item)` with keys popped),
# reuses _build_shop_catalog(None) for pricing/visibility so standard
# pricing here is byte-for-byte the same computation the authenticated Shop
# and Client Preview already trust, and never accepts a client identity from
# an unauthenticated request. Guest/public visibility (show_public_merch/
# prepaid/training, show_public_prices, publicly_visible, item-level
# show_public_price) is a SEPARATE, additive layer on top of the existing
# section.visible/category/subcategory rules _build_shop_catalog already
# applies — those still gate authenticated AND guest audiences alike.
# ─────────────────────────────────────────────────────────────────────────────

_PUBLIC_FIELDS_COMMON = {
    "kind", "id", "name", "description", "image_id",
    "category_id", "category_name", "subcategory_id", "subcategory_name",
    "sort_order", "featured", "publicly_visible", "account_required",
    "guest_cart_allowed", "requires_dog", "requires_approval",
    "requires_completed_onboarding", "availability",
}
# ALL price-ish fields, including Shopify's own displayed price — stripped
# under the exact same show_public_prices/show_public_price gate as every
# other price field, never treated as a special case. value_each and
# display_price_each are both derived from effective_price, so they belong
# here too — a price-hidden pack must not leak its per-credit/per-unit rate
# through these side-channel fields.
_PUBLIC_FIELDS_PRICE = {"price", "list_price", "effective_price", "shopify_display_price", "shopify_from_price", "value_each", "display_price_each"}
# sales_destination/shopify_product_url are NEVER price-gated — View Options
# must keep working even when pricing is hidden.
_PUBLIC_FIELDS_PRODUCT = {"sales_destination", "shopify_product_url"}
# display_quantity/display_unit/display_dog_count/credits_per_display_unit
# describe QUANTITY, not price (same precedent as raw `qty` below, already
# unconditionally public) — safe to show even when pricing is hidden.
_PUBLIC_FIELDS_PACK = {"service_type", "qty", "display_quantity", "display_unit", "display_dog_count", "credits_per_display_unit"}
_PUBLIC_FIELDS_PROGRAM = {
    "focus", "program_type", "format_count", "format_unit", "min_age_months",
    "estimated_weeks", "school_support", "school_onboarding",
    # Online School storefront card content — admin-authored marketing bullets
    # and derived counts (never curriculum names/ids; see the catalog builder).
    "helps_with", "welcome_outcomes", "module_count", "lesson_count",
    # These two were always intended to be public — the guest storefront's
    # Online School tab filters on purchase_fulfillment and its free-course
    # discovery reads free_claim_available, but neither survived the public
    # allowlist, so the PUBLIC Online School tab was permanently empty (and
    # Start Free Course could never deep-link) no matter how programs were
    # flagged. Both are computed/config discriminators, not sensitive data,
    # and free_claim_available is already recomputed by _public_purchase_state
    # from the same rule the claim endpoint enforces.
    "purchase_fulfillment", "free_claim_available",
}

_PUBLIC_SECTION_FLAG_FOR_SECTION = {"merch": "show_public_merch", "prepaid_visits": "show_public_prepaid", "training": "show_public_training"}
_PUBLIC_SECTION_FOR_KIND = {"product": "merch", "credit_pack": "prepaid_visits", "training_program": "training"}


def _public_shop_item_availability(raw_item: dict) -> str:
    """Customer-safe stock state — never the raw count. Non-product kinds
    (and Shopify-external products, which carry no track_inventory/in_stock
    fields at all) have no local stock concept, so they're always
    'in_stock'; Shopify itself owns its own inventory display."""
    if raw_item.get("kind") != "product" or not raw_item.get("track_inventory"):
        return "in_stock"
    if not raw_item.get("in_stock"):
        return "out_of_stock"
    stock = raw_item.get("stock_on_hand")
    threshold = raw_item.get("low_stock_threshold")
    if stock is not None and threshold is not None and float(stock) <= float(threshold):
        return "low_stock"
    return "in_stock"


def _build_public_shop_item(raw_item: dict, *, global_show_public_prices: bool) -> Optional[dict]:
    """Builds ONE public item dict from an explicit allowlist — returns None
    when the item isn't publicly visible at all (excluded from the base set
    entirely, not just price-redacted)."""
    kind = raw_item["kind"]
    purchase_state = _public_purchase_state(kind, raw_item, global_show_public_prices=global_show_public_prices)
    if not purchase_state["publicly_visible"]:
        return None
    field_set = set(_PUBLIC_FIELDS_COMMON)
    if kind == "product":
        field_set |= _PUBLIC_FIELDS_PRODUCT
    elif kind == "credit_pack":
        field_set |= _PUBLIC_FIELDS_PACK
    elif kind == "training_program":
        field_set |= _PUBLIC_FIELDS_PROGRAM
    if purchase_state["show_public_price"]:
        field_set |= _PUBLIC_FIELDS_PRICE
    out = {k: raw_item[k] for k in field_set if k in raw_item}
    out["availability"] = _public_shop_item_availability(raw_item)
    out["publicly_visible"] = purchase_state["publicly_visible"]
    out["account_required"] = purchase_state["account_required"]
    out["guest_cart_allowed"] = purchase_state["guest_cart_allowed"]
    out["requires_dog"] = purchase_state["requires_dog"]
    out["requires_approval"] = purchase_state["requires_approval"]
    out["requires_completed_onboarding"] = purchase_state["requires_completed_onboarding"]
    return out


async def _public_shop_settings_or_404() -> dict:
    settings = await get_settings()
    sp = settings.get("shop_page") or {}
    if not sp.get("public_shop_enabled") or not sp.get("public_browsing_enabled"):
        raise HTTPException(status_code=404, detail="Shop is not available.")
    return sp


async def _public_visible_shop_items() -> list[dict]:
    """The BASE set: permanently public right now — publicly_visible,
    section on (section.visible AND show_public_<section>), category/
    subcategory active (already enforced by _build_shop_catalog). Used by
    item-detail. Does NOT filter by stock — an out-of-stock item is still
    'visible', just not purchase-ready."""
    sp = await _public_shop_settings_or_404()
    catalog = await _build_shop_catalog(None)  # standard pricing only — a public request never carries a client identity
    show_public_prices_global = bool(sp.get("show_public_prices", True))
    out = []
    for raw in catalog["items"]:
        section = _PUBLIC_SECTION_FOR_KIND[raw["kind"]]
        if not bool(sp.get(_PUBLIC_SECTION_FLAG_FOR_SECTION[section], True)):
            continue
        built = _build_public_shop_item(raw, global_show_public_prices=show_public_prices_global)
        if built is None:
            continue
        out.append(built)
    return out


async def _public_catalog_items() -> list[dict]:
    """Browse list = _public_visible_shop_items() further filtered by
    show_out_of_stock. Used by /public/shop/catalog and
    /public/shop/taxonomy's item-count/emptiness math."""
    base = await _public_visible_shop_items()
    settings = await get_settings()
    sp = settings.get("shop_page") or {}
    if bool(sp.get("show_out_of_stock", True)):
        return base
    return [i for i in base if i.get("availability") != "out_of_stock"]


@api.get("/public/shop/catalog")
async def get_public_shop_catalog(request: Request):
    await _enforce_rate_limit(request, "public_shop_catalog", _client_ip(request), limit=60, window_seconds=60)
    return {"items": await _public_catalog_items()}


@api.get("/public/shop/item/{kind}/{item_id}")
async def get_public_shop_item_detail(kind: str, item_id: str, request: Request):
    """Direct item-detail link — looks up the BASE (not stock-filtered) set,
    so an out-of-stock item's direct link still 200s with its out-of-stock
    state shown even when show_out_of_stock hides it from browsing. Same
    404-never-403 behavior as the authenticated item-detail route."""
    await _enforce_rate_limit(request, "public_shop_catalog", _client_ip(request), limit=60, window_seconds=60)
    if kind not in _SHOP_ITEM_DETAIL_SECTION:
        raise HTTPException(status_code=404, detail="This item is unavailable.")
    items = await _public_visible_shop_items()
    item = next((dict(i) for i in items if i["kind"] == kind and i["id"] == item_id), None)
    if not item:
        raise HTTPException(status_code=404, detail="This item is unavailable.")
    section = _SHOP_ITEM_DETAIL_SECTION[kind]
    item["section"] = section
    item["section_label"] = SHOP_SECTION_LABELS[section]
    return item


@api.get("/public/shop/taxonomy")
async def get_public_shop_taxonomy(request: Request):
    """Mirrors /shop/catalog/taxonomy but counts/emptiness are derived from
    _public_catalog_items() (browse-consistent — respects show_out_of_stock
    and the public section/price gates), so a category the public catalog
    would treat as empty is dropped here too under the same hide-when-empty
    rule, never left inconsistently visible."""
    await _enforce_rate_limit(request, "public_shop_catalog", _client_ip(request), limit=60, window_seconds=60)
    sp = await _public_shop_settings_or_404()
    catalog_items = await _public_catalog_items()
    non_empty_cat_ids = {i["category_id"] for i in catalog_items if i.get("category_id")}
    hide_empty_default = bool(sp.get("hide_empty_categories", True))
    full = await _shop_taxonomy_payload()
    out_categories = []
    for c in full["categories"]:
        effective_hide = c.get("hide_when_empty")
        if effective_hide is None:
            effective_hide = hide_empty_default
        if effective_hide and c["id"] not in non_empty_cat_ids:
            continue
        out_categories.append(c)
    return {"categories": out_categories}


_SECTION_FOR_SHOP_COLLECTION = {"pos_products": "merch", "credit_packs": "prepaid_visits", "programs": "training"}


async def _is_public_shop_media(media_id: str) -> bool:
    """Layered, targeted-query authorization check for one media_id — never
    a catalog rebuild. Applies the exact same rules the public taxonomy/
    catalog browse view applies (section public+visible, category/
    subcategory active, effective hide-when-empty non-emptiness, item
    published+publicly_visible), just via direct point lookups so this can
    run on every single media request cheaply."""
    settings = await get_settings()
    sp = settings.get("shop_page") or {}
    if not sp.get("public_shop_enabled") or not sp.get("public_browsing_enabled"):
        return False

    def _section_is_public(section: str) -> bool:
        sec = (sp.get("sections") or {}).get(section) or {}
        if not bool(sec.get("visible", True)):
            return False
        return bool(sp.get(_PUBLIC_SECTION_FLAG_FOR_SECTION.get(section, ""), True))

    if sp.get("banner_image_id") == media_id:
        return True  # banner is site-wide chrome, not section-scoped

    for key, sec in (sp.get("sections") or {}).items():
        if sec.get("image_id") == media_id and _section_is_public(key):
            return True

    show_oos = bool(sp.get("show_out_of_stock", True))

    async def _category_has_public_item(category_id: str) -> bool:
        for coll, online_field in ((db.pos_products, "show_online"), (db.credit_packs, "available_online"), (db.programs, "available_online")):
            async for doc in coll.find(
                {"category_id": category_id, "active": True, online_field: True, "publicly_visible": {"$ne": False}},
                {"_id": 0, "id": 1, "subcategory_id": 1, "track_inventory": 1, "stock_on_hand": 1},
            ):
                if doc.get("subcategory_id"):
                    sub_active = await db.shop_subcategories.find_one({"id": doc["subcategory_id"], "active": True}, {"_id": 0, "id": 1})
                    if not sub_active:
                        continue
                if not show_oos and doc.get("track_inventory") and float(doc.get("stock_on_hand") or 0) <= 0.0005:
                    continue
                return True
        return False

    async def _category_media_authorized(cat: dict) -> bool:
        if not cat.get("active") or not _section_is_public(cat["section"]):
            return False
        effective_hide_when_empty = cat.get("hide_when_empty")
        if effective_hide_when_empty is None:
            effective_hide_when_empty = bool(sp.get("hide_empty_categories", True))
        if effective_hide_when_empty and not await _category_has_public_item(cat["id"]):
            return False
        return True

    cat = await db.shop_categories.find_one(
        {"$or": [{"image_id": media_id}, {"mobile_image_id": media_id}]},
        {"_id": 0, "id": 1, "section": 1, "active": 1, "hide_when_empty": 1},
    )
    if cat and await _category_media_authorized(cat):
        return True

    sub = await db.shop_subcategories.find_one(
        {"active": True, "$or": [{"image_id": media_id}, {"mobile_image_id": media_id}]}, {"_id": 0, "id": 1, "category_id": 1},
    )
    if sub:
        parent = await db.shop_categories.find_one(
            {"id": sub["category_id"]}, {"_id": 0, "id": 1, "section": 1, "active": 1, "hide_when_empty": 1},
        )
        if parent and await _category_media_authorized(parent):
            return True

    for coll, online_field in ((db.pos_products, "show_online"), (db.credit_packs, "available_online"), (db.programs, "available_online")):
        doc = await coll.find_one(
            {"image_id": media_id, "active": True, online_field: True, "publicly_visible": {"$ne": False}},
            {"_id": 0, "id": 1, "category_id": 1, "subcategory_id": 1},
        )
        if not doc:
            continue
        item_section = _SECTION_FOR_SHOP_COLLECTION[coll.name]
        if not _section_is_public(item_section):
            continue
        if doc.get("category_id"):
            active_cat = await db.shop_categories.find_one({"id": doc["category_id"], "active": True}, {"_id": 0, "id": 1})
            if not active_cat:
                continue
        if doc.get("subcategory_id"):
            active_sub = await db.shop_subcategories.find_one({"id": doc["subcategory_id"], "active": True}, {"_id": 0, "id": 1})
            if not active_sub:
                continue
        return True
    return False


@api.get("/public/shop/media/{media_id}")
async def get_public_shop_media(media_id: str, request: Request, response: Response):
    """Public-safe media serving — its own, more permissive rate-limit scope
    (separate from the catalog/item-detail family) since a shop page can
    reference dozens of images per load. Runs _is_public_shop_media on EVERY
    request, including conditional (If-None-Match) ones — authorization, not
    just content, is what's being revalidated, so a since-hidden image must
    404 even on a request that would otherwise be a cheap 304."""
    await _enforce_rate_limit(request, "public_shop_media", _client_ip(request), limit=300, window_seconds=60)
    authorized = await _is_public_shop_media(media_id)
    if not authorized:
        raise HTTPException(status_code=404, detail="Not found.")
    etag = f'"{media_id}"'
    if request.headers.get("if-none-match") == etag:
        return Response(status_code=304, headers={"Cache-Control": "public, max-age=0, must-revalidate", "ETag": etag})
    m = await db.shop_media.find_one({"id": media_id}, {"_id": 0})
    if not m:
        raise HTTPException(status_code=404, detail="Not found.")
    response.headers["Cache-Control"] = "public, max-age=0, must-revalidate"
    response.headers["ETag"] = etag
    return {"data": m["data"], "mime": m["mime"]}


class ShopMerchClickIn(BaseModel):
    product_id: str = Field(min_length=1)


@api.post("/shop/merch-click")
async def record_shop_merch_click(body: ShopMerchClickIn, user: dict = Depends(get_current_user)):
    """Lightweight, nonfinancial telemetry for Shopify-linked merchandise:
    records only which listing was opened, by whom (if authenticated), when,
    and which domain it sent the client to — never an order, never revenue,
    never anything about the actual Shopify checkout/payment. destination
    domain is derived from the product's OWN stored URL server-side, never
    trusted from the request body, so this can't be used to log arbitrary
    click data for an unrelated destination."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    product = await db.pos_products.find_one({"id": body.product_id}, {"_id": 0, "sales_destination": 1, "shopify_product_url": 1})
    if not product or product.get("sales_destination") != "shopify_external":
        raise HTTPException(status_code=404, detail="Shopify listing not found")
    destination_domain = urlsplit(product.get("shopify_product_url") or "").netloc or None
    await db.shop_merch_clicks.insert_one({
        "id": str(uuid.uuid4()),
        "product_id": body.product_id,
        "client_id": user.get("client_id"),
        "timestamp": now_iso(),
        "destination_domain": destination_domain,
    })
    return {"ok": True}


# ─────────────────────────────────────────────────────────────────────────────
# Client Shop Phase 2 — cart, checkout, Stripe payment, fulfillment
# ─────────────────────────────────────────────────────────────────────────────
# Builds on Phase 1's read-only catalog above. A shop_orders document is the
# checkout-time snapshot of a client's cart (mirrors invoices' "snapshot,
# never rewrite" philosophy) — physical product lines, credit-pack lines,
# and training-program lines can all coexist in one order. Money only ever
# moves through the EXISTING /webhooks/stripe endpoint and the existing
# canonical payments/retail_sales/credit_lots machinery (_insert_payment_row,
# the retail_sales.payment_id partial unique index, credit_lots' own shape)
# — this section adds a shop-specific checkout/reservation/fulfillment layer
# on top of that, it does not duplicate the invoice-Stripe payment
# architecture or the credit/program grant math.

SHOP_PAYMENT_ATTEMPT_TERMINAL_STATUSES = ("applied", "failed", "expired", "canceled")

# Once a shop_order's pickup_status reaches any of these, it is initialized —
# a payment/webhook replay must never overwrite it back to "preparing"/None.
# Missing field or None (never-initialized/legacy order) is deliberately NOT
# in this set, so a $nin query against it naturally covers both.
SHOP_PICKUP_INITIALIZED_STATES = ("preparing", "ready_for_pickup", "picked_up", "not_applicable")


class ShopCartItemIn(BaseModel):
    kind: Literal["product", "credit_pack", "training_program"]
    ref_id: str = Field(min_length=1)
    quantity: int = Field(ge=1, le=50)
    # Phase 5 — Online School commerce. Only meaningful for a
    # training_program line whose program is configured
    # purchase_fulfillment="online_school" (see _validate_shop_item_eligibility);
    # every other line kind/fulfillment ignores this field entirely, same
    # as before it existed. Never trusted as proof of ownership by itself —
    # ownership is re-validated server-side at eligibility-check time.
    dog_id: Optional[str] = None


class ShopCheckoutIn(BaseModel):
    items: List[ShopCartItemIn] = Field(min_length=1, max_length=40)
    idempotency_key: str = Field(min_length=8, max_length=128)


def _normalize_cart_lines(items: List[ShopCartItemIn]) -> List[ShopCartItemIn]:
    """Aggregates duplicate (kind, ref_id) cart lines into ONE summed-
    quantity line each, in first-seen order — called before pricing, stock
    checks, idempotency fingerprinting, reservation, entitlement creation,
    or Stripe session creation, so a cart split into several small
    duplicate lines can never bypass a stock ceiling or eligibility check
    that only looked at each line individually.

    Explicitly validates kind/ref_id/quantity itself rather than trusting
    the caller's Pydantic model instance — the combined line below is built
    via `model_construct` (bypassing Pydantic's own per-line `le=50` cap,
    which was only ever a per-request-line sanity bound, not a true
    aggregate ceiling — the real ceiling is the stock check downstream),
    so this function is the one place a malformed line is guaranteed to be
    rejected with a clean 422, never an unhandled construction error.

    Phase 5 — the aggregation key includes `dog_id` so two different dogs
    buying the same online_school-fulfillment program stay as separate
    lines (each needs its own enrollment) rather than being summed into a
    single quantity>1 line, which _validate_shop_item_eligibility rejects
    for that fulfillment kind. Every non-dog-targeted line (dog_id=None,
    i.e. every line kind/program that existed before Phase 5) aggregates
    exactly as it always has.

    Commerce-integrity hardening — a dog_id-carrying line represents ONE
    Online School entitlement for that one dog (dog_id is only ever set by
    the client for that purpose; see ShopCartItemIn.dog_id). Quantity must
    equal exactly 1 for such a line, enforced HERE, before pricing/stock/
    eligibility/Stripe ever run — not merely by _validate_shop_item_eligibility
    (defense-in-depth, kept below) and never only by hiding the UI quantity
    stepper. Rejects a single request line requesting >1, and rejects two
    requests for the SAME (kind, ref_id, dog_id) combining to >1 — neither
    a single oversized line nor a client re-submitting the same dog+course
    twice can turn into a quantity>1 charge for one entitlement."""
    combined: Dict[Tuple[str, str, Optional[str]], int] = {}
    order_seen: List[Tuple[str, str, Optional[str]]] = []
    for it in items:
        kind = it.kind
        ref_id = (it.ref_id or "").strip()
        qty = it.quantity
        dog_id = (it.dog_id or "").strip() or None
        if kind not in ("product", "credit_pack", "training_program"):
            raise HTTPException(status_code=422, detail="Invalid item kind in cart.")
        if not ref_id:
            raise HTTPException(status_code=422, detail="Invalid item in cart.")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise HTTPException(status_code=422, detail="Invalid quantity in cart.")
        if dog_id and qty != 1:
            raise HTTPException(status_code=422, detail="An Online School course can only be purchased one at a time per dog.")
        key = (kind, ref_id, dog_id)
        if key not in combined:
            order_seen.append(key)
            combined[key] = 0
        combined[key] += qty
        if dog_id and combined[key] > 1:
            raise HTTPException(status_code=422, detail="An Online School course can only be purchased one at a time per dog.")
    return [
        ShopCartItemIn.model_construct(kind=k, ref_id=rid, quantity=combined[(k, rid, did)], dog_id=did)
        for (k, rid, did) in order_seen
    ]


_SHOP_ITEM_ONLINE_FIELD = {"product": "show_online", "credit_pack": "available_online", "training_program": "available_online"}
_SHOP_ITEM_COLLECTION_NAME = {"product": "pos_products", "credit_pack": "credit_packs", "training_program": "programs"}


async def _shop_item_org_visible(category_id: Optional[str], subcategory_id: Optional[str]) -> bool:
    """Same two-level active-category/active-subcategory rule as the
    private `_shop_org_visible` closures inside `_build_shop_catalog`/
    `_build_register_catalog` — a standalone, targeted-query version so
    checkout eligibility (which validates one already-known item at a time,
    not a whole catalog) can reuse the identical rule without a batch
    rebuild."""
    if not category_id:
        return True
    cat = await db.shop_categories.find_one({"id": category_id, "active": True}, {"_id": 0, "id": 1})
    if not cat:
        return False
    if subcategory_id:
        sub = await db.shop_subcategories.find_one({"id": subcategory_id, "active": True}, {"_id": 0, "id": 1})
        if not sub:
            return False
    return True


async def _validate_shop_item_eligibility(client: dict, kind: str, item_doc: Optional[dict], quantity: int, dog_id: Optional[str] = None) -> None:
    """ADDITIVE ONLY — never touches price, inventory math, or reservation
    logic itself. Called once per already-normalized cart line in
    create_shop_checkout, immediately before the order (and therefore any
    reservation/entitlement/Stripe session) is created — never on a
    retry that resumes an already-created order, so a fully eligible cart's
    idempotent-retry behavior is completely unaffected by this check.

    Deliberately never reads `publicly_visible` — that's a guest/public-
    facing concept; an authenticated client's eligibility to buy something
    they can already see in their own Shop never depends on it."""
    name = (item_doc or {}).get("name") or "This item"
    if item_doc is None:
        raise HTTPException(status_code=404, detail="One of the items in your cart no longer exists.")
    if not item_doc.get("active", True):
        raise HTTPException(status_code=409, detail=f"{name} is no longer available.")
    online_field = _SHOP_ITEM_ONLINE_FIELD[kind]
    if not item_doc.get(online_field, False):
        raise HTTPException(status_code=409, detail=f"{name} is no longer available online.")
    settings = await get_settings()
    sp = settings.get("shop_page") or {}
    section = _PUBLIC_SECTION_FOR_KIND[kind]
    section_visible = bool(((sp.get("sections") or {}).get(section) or {}).get("visible", True))
    if not section_visible:
        raise HTTPException(status_code=409, detail=f"{name} is no longer available.")
    if not await _shop_item_org_visible(item_doc.get("category_id"), item_doc.get("subcategory_id")):
        raise HTTPException(status_code=409, detail=f"{name} is no longer available.")
    if not isinstance(quantity, int) or quantity <= 0:
        raise HTTPException(status_code=422, detail="Invalid quantity.")
    if kind == "product" and item_doc.get("track_inventory"):
        stock = float(item_doc.get("stock_on_hand") or 0)
        if quantity > stock + 0.0005:
            if stock <= 0.0005:
                raise HTTPException(status_code=409, detail=f"{name} is out of stock.")
            raise HTTPException(status_code=409, detail=f"Only {stock:g} of {name} are available.")
    if item_doc.get("requires_approval"):
        raise HTTPException(status_code=422, detail=f"{name} requires approval before purchase — please contact us to complete this purchase.")
    if kind == "training_program" and item_doc.get("purchase_fulfillment") == "online_school":
        # Phase 5 — this is the one case with a real dog-selection
        # mechanism (the frozen per-line dog_id — see _price_shop_cart):
        # require it, validate it against THIS client's own dogs (never
        # trust the client-posted id as proof of ownership), and require
        # exactly one enrollment per line so "buy for 2 dogs" can't
        # silently collapse into a single enrollment. Every other
        # requires_dog program (fulfillment left at the "credits_only"
        # default) falls through to the unconditional reject below,
        # completely unchanged.
        if quantity != 1:
            raise HTTPException(status_code=422, detail=f"{name} can only be purchased one dog at a time — add it again for a second dog.")
        if not dog_id:
            raise HTTPException(status_code=422, detail=f"{name} requires selecting a dog before checkout.")
        dog = await db.dogs.find_one({"id": dog_id}, {"_id": 0, "id": 1, "owner_id": 1})
        if not dog or dog.get("owner_id") != client.get("id"):
            raise HTTPException(status_code=422, detail="Selected dog was not found on this account.")
        # Commerce-integrity hardening — reject BEFORE any order/Stripe
        # session is created, not just at fulfillment time. Fulfillment's
        # OnlineSchoolAlreadyEnrolledError convergence stays in place as the
        # final safety net for a genuine race (two concurrent checkouts),
        # but a client should never be able to pay again for a course they
        # already own or already completed — this is the no-retake policy
        # from the Phase 5 spec (§10), enforced at the money boundary, not
        # only implied by the CTA the client happens to be looking at.
        existing_enrollment = await db.dog_programs.find_one(
            {"dog_id": dog_id, "program_id": item_doc["id"], "delivery_channel": "online_school",
             # Phase 6 retake policy — withdrawn is blocked here too, not
             # just active/completed: a withdrawn enrollment must not be
             # silently superseded by a repurchase either (see the Phase 6
             # spec's retake policy — a real retake needs a future,
             # explicit staff workflow, never an automatic second charge).
             "status": {"$in": ["active", "completed", "withdrawn"]}},
            {"_id": 0, "status": 1},
        )
        if existing_enrollment:
            if existing_enrollment["status"] == "completed":
                raise HTTPException(status_code=409, detail=f"{name} has already been completed for this dog — repurchase isn't available yet.")
            if existing_enrollment["status"] == "withdrawn":
                raise HTTPException(status_code=409, detail=f"This dog's enrollment in {name} was withdrawn — contact us before repurchasing.")
            raise HTTPException(status_code=409, detail=f"This dog is already enrolled in {name} — go to Online School to continue instead of buying it again.")
        # This function receives the client DOCUMENT (`client`), not a
        # client_id — referencing client_id raised NameError on EVERY Online
        # School program checkout, so no program could be bought at all.
        _agreement_client_id = (client or {}).get("id")
        if _agreement_client_id:
            await _require_agreements_signed(_agreement_client_id, program_id=item_doc["id"])
        # Age + prerequisites are checked before an order/Stripe session exists
        # so a client can never pay for a course this dog is not eligible to enter.
        _require_program_min_age(dog, item_doc)
        await _require_program_prerequisites(dog_id, item_doc)
    elif item_doc.get("requires_dog"):
        # No dog-selection-at-cart-line mechanism exists yet for any other
        # requires_dog item kind — conservatively reject rather than
        # silently proceed without one.
        raise HTTPException(status_code=422, detail=f"{name} requires selecting a dog — please contact us to complete this purchase.")
    if item_doc.get("requires_completed_onboarding"):
        status = await _compute_setup_status_for_client(client)
        if status.get("booking_locked"):
            raise HTTPException(status_code=422, detail="Please finish your account setup before completing this purchase.")


async def _price_shop_cart(items: List[ShopCartItemIn], client_id: Optional[str] = None) -> dict:
    """Prices a Shop cart entirely server-side — never trusts a client-
    supplied price. Only `product` lines are physical/taxable; credit_pack
    and training_program lines are never taxed (confirmed: no tax
    computation exists anywhere for either today, so allocated_tax=0 for
    both, always). Order-level tax is computed over the taxable (physical-
    only) subtotal using the SAME retail sales-tax config _price_pos_cart
    already uses, then allocated across physical lines proportional to each
    line's own subtotal, with the LAST taxable line absorbing the rounding
    remainder — guarantees the per-line sum always exactly equals the
    order-level tax total, by construction.

    This is a pre-commit PRICING check only — real stock enforcement happens
    atomically at reservation time (_reserve_shop_inventory_line), exactly
    like _price_pos_cart's own stock check is a convenience, not the final
    word."""
    lines = []
    product_cache: Dict[str, dict] = {}
    for cart_item in items:
        qty = int(cart_item.quantity)
        if cart_item.kind == "product":
            product = product_cache.get(cart_item.ref_id)
            if product is None:
                product = await db.pos_products.find_one(
                    {"id": cart_item.ref_id, "show_online": True, "active": True, "archived": {"$ne": True}}, {"_id": 0},
                )
                if not product:
                    raise HTTPException(status_code=400, detail="One of the products in this cart is no longer available.")
                product_cache[cart_item.ref_id] = product
            if product.get("sales_destination") == "shopify_external":
                # Shopify-linked merchandise is a display-only catalog link —
                # Shopify is authoritative for its price and checkout, so it
                # must never reach the Sit Happens cart/order/payment path.
                raise HTTPException(
                    status_code=400,
                    detail="This item is Shopify merchandise and can't be added to the Sit Happens cart — use its Shopify link instead.",
                )
            # Never trust a client-supplied price — resolve_client_price() is
            # the SAME source of truth credit_pack lines (below) and
            # GET /shop/catalog already use, so a grandfathered/tier-priced
            # client is CHARGED their locked rate here, not just shown it.
            list_unit_price = round(float(product.get("price") or 0), 2)
            product_pricing = await resolve_client_price(client_id, "pos_product", product["id"], list_unit_price)
            unit_price = round(float(product_pricing["effective_price"]), 2)
            name = product.get("name") or "Product"
            org_source = product
        elif cart_item.kind == "credit_pack":
            pack = await db.credit_packs.find_one(
                {"id": cart_item.ref_id, "available_online": True, "active": True}, {"_id": 0},
            )
            if not pack:
                raise HTTPException(status_code=400, detail="One of the credit packs in this cart is no longer available.")
            # Never derive this from a service rate or a client-submitted
            # amount — resolve_client_price() is the ONE source of truth a
            # credit-pack override already uses everywhere else (front-desk
            # sell-pack, GET /shop/catalog). A grandfathered client must be
            # CHARGED their locked rate here, not just shown it.
            list_unit_price = round(float(pack.get("price") or 0), 2)
            pricing = await resolve_client_price(client_id, "credit_pack", pack["id"], list_unit_price)
            unit_price = round(float(pricing["effective_price"]), 2)
            name = pack.get("name") or "Credit Pack"
            org_source = pack
        else:
            program = await db.programs.find_one(
                {"id": cart_item.ref_id, "available_online": True, "active": True}, {"_id": 0},
            )
            if not program:
                raise HTTPException(status_code=400, detail="One of the training programs in this cart is no longer available.")
            fmt = program.get("format") or {}
            if int(fmt.get("count") or 0) <= 0:
                raise HTTPException(status_code=400, detail="This training program isn't set up for online purchase yet.")
            unit_price = round(float(program.get("price") or 0), 2)
            name = program.get("name") or "Training Program"
            org_source = program

        line_subtotal = round(unit_price * qty, 2)
        org_snapshot = await _shop_org_snapshot(org_source.get("category_id"), org_source.get("subcategory_id"))
        line = {
            "item_id": str(uuid.uuid4()), "kind": cart_item.kind, "ref_id": cart_item.ref_id,
            "name": name, "unit_price": unit_price, "quantity": qty,
            "line_subtotal": line_subtotal, "allocated_tax": 0.0,
            "line_total": line_subtotal, "fulfillment_status": "pending",
            # Step 4C-1 — taxability from structured metadata, same rule as
            # the POS path: only PHYSICAL products can be taxable (honoring a
            # per-product taxable=false override); credit packs and training
            # programs are services and never taxable online either.
            "taxable": bool(org_source.get("taxable", True)) if cart_item.kind == "product" else False,
            **org_snapshot,
        }
        if cart_item.kind == "training_program":
            # Phase 5 — frozen at pricing time so _apply_shop_payment never
            # re-reads the (possibly since-edited) program doc to decide
            # fulfillment branching, and so a dog picked at cart time can't
            # be silently retargeted by a later program edit or payment
            # retry. Every existing program (purchase_fulfillment absent/
            # "credits_only") gets fulfillment_kind="credits_only" and
            # dog_id=None exactly as today.
            line["dog_id"] = cart_item.dog_id
            line["fulfillment_kind"] = org_source.get("purchase_fulfillment") or "credits_only"
            if cart_item.dog_id:
                # Phase 6 (6.8) — staff operational visibility. Without this,
                # the admin Online Orders view has no way to show WHICH dog
                # an online_school purchase is for short of decoding a raw
                # dog_id — frozen at order time like every other line
                # snapshot, so a later dog rename never rewrites history.
                dog_doc = await db.dogs.find_one({"id": cart_item.dog_id}, {"_id": 0, "name": 1})
                line["dog_name"] = (dog_doc or {}).get("name")
        if cart_item.kind == "credit_pack":
            # Immutable pricing snapshot — frozen at order-creation time so a
            # later public-price change or override/tier edit or revocation
            # can never alter what this order (or its eventual credit lot)
            # charged. Editing a tier/override AFTER this point must never
            # reach back and change a completed order.
            has_override = bool(pricing["override_id"] or pricing["pricing_source"] != "standard")
            line.update({
                "list_unit_price": list_unit_price,
                "pricing_source": pricing["pricing_source"],
                "price_override_id": pricing["override_id"],
                "has_price_override": has_override,
                "pricing_tier_id": pricing.get("tier_id"),
                "pricing_tier_name": pricing.get("tier_name"),
            })
        elif cart_item.kind == "product":
            # Same immutable-snapshot contract as credit_pack lines above —
            # the actual charged unit price, and which pricing rule produced
            # it, are frozen onto the line at order-creation time.
            has_override = product_pricing["pricing_source"] != "standard"
            line.update({
                "list_unit_price": list_unit_price,
                "pricing_source": product_pricing["pricing_source"],
                "price_override_id": product_pricing["override_id"],
                "has_price_override": has_override,
                "pricing_tier_id": product_pricing.get("tier_id"),
                "pricing_tier_name": product_pricing.get("tier_name"),
            })
        lines.append(line)

    if not lines:
        raise HTTPException(status_code=400, detail="Cart is empty.")

    # Same summed-qty-per-product stock check _price_pos_cart uses, so two
    # cart lines referencing the same product can't each individually pass a
    # check that their combined quantity would fail.
    qty_by_product: Dict[str, float] = {}
    for line in lines:
        if line["kind"] == "product":
            qty_by_product[line["ref_id"]] = qty_by_product.get(line["ref_id"], 0) + line["quantity"]
    for product_id, total_qty in qty_by_product.items():
        product = product_cache[product_id]
        if not product.get("track_inventory"):
            continue
        stock = float(product.get("stock_on_hand") or 0)
        if total_qty > stock + 0.0005:
            if stock <= 0.0005:
                raise HTTPException(status_code=400, detail=f"{product.get('name')} is out of stock.")
            raise HTTPException(status_code=400, detail=f"Only {stock:g} in stock for {product.get('name')}.")

    subtotal = round(sum(l["line_subtotal"] for l in lines), 2)
    # Step 4C-1 — was `kind == "product"` alone, which ignored a product's
    # own taxable=false override online (the POS path honored it).
    taxable_lines = [l for l in lines if l.get("taxable")]
    taxable_subtotal = round(sum(l["line_subtotal"] for l in taxable_lines), 2)

    tax_amount = 0.0
    tax_rate_pct = 0.0
    if taxable_subtotal > 0:
        try:
            settings_tx = await get_settings()
            tx_cfg = (settings_tx or {}).get("sales_tax") or {}
            if tx_cfg.get("enabled") and float(tx_cfg.get("rate_pct") or 0) > 0:
                applies = (tx_cfg.get("applies_to") or {})
                if applies.get("retail", True):
                    tax_rate_pct = float(tx_cfg["rate_pct"])
                    tax_amount = round(taxable_subtotal * (tax_rate_pct / 100.0), 2)
        except Exception as exc:
            logger.warning("Shop cart tax calc failed: %s", exc)

    if tax_amount > 0 and taxable_lines:
        allocated_so_far = 0.0
        for i, line in enumerate(taxable_lines):
            if i == len(taxable_lines) - 1:
                line_tax = round(tax_amount - allocated_so_far, 2)
            else:
                line_tax = round(tax_amount * (line["line_subtotal"] / taxable_subtotal), 2)
                allocated_so_far = round(allocated_so_far + line_tax, 2)
            line["allocated_tax"] = line_tax
            line["line_total"] = round(line["line_subtotal"] + line_tax, 2)

    total = round(subtotal + tax_amount, 2)
    return {
        "lines": lines, "subtotal": subtotal, "tax_amount": tax_amount,
        "tax_rate_pct": tax_rate_pct, "total": total,
    }


# ── Inventory reservation state machine (RESERVE/COMMIT/RELEASE) ───────────
# Layered on top of pos_products/_mutate_product_stock, never altering that
# function's own behavior for POS register sales. A physical Shop cart line
# reserves a claim on stock (via `stock_reserved` + a `shop_reservations`
# array entry on the product doc) at checkout time, BEFORE Stripe is ever
# involved, so two concurrent Shop checkouts can never oversell the same
# unit even though money hasn't moved yet. `stock_on_hand` itself is only
# ever decremented at COMMIT (i.e. once payment is confirmed) — mirrors
# real stock only leaving the shelf once the sale is real.

def _shop_inventory_ref(order_id: str, item_id: str) -> str:
    return f"shop_order:{order_id}:item:{item_id}"


def _shop_order_line_terminal_release(order: dict, item_id: str) -> bool:
    """Durable, order-owned proof that this line's reservation was already
    released before any payment occurred — never inferred from clock time.
    True once the whole order is payment_failed/canceled, or once this
    line's own fulfillment_status has already been marked 'released'."""
    if order.get("status") in ("payment_failed", "canceled"):
        return True
    line = next((l for l in (order.get("lines") or []) if l.get("item_id") == item_id), None)
    return bool(line and line.get("fulfillment_status") == "released")


async def _reserve_shop_inventory_line(order: dict, line: dict) -> str:
    """Reserves stock for one physical-product cart line, following the
    exact retry precedence: (1) an inventory_movements row already exists
    for this ref — durable proof of COMMITTED, never re-reserve; (2) the
    owning order/line already proves a terminal pre-payment release —
    RELEASED, never re-reserve; (3) an active reservation already exists on
    the product doc — return its current state as-is, never double-count;
    (4) otherwise, a fresh atomic reservation attempt (optimistic retry, up
    to 5x, mirroring _mutate_product_stock's own idiom). Returns
    'reserved'|'committed'|'released'|'skipped' ('skipped' covers both
    non-product lines and untracked products, neither of which needs a
    reservation at all)."""
    if line["kind"] != "product":
        return "skipped"
    order_id = order["id"]
    item_id = line["item_id"]
    ref = _shop_inventory_ref(order_id, item_id)
    product_id = line["ref_id"]
    qty = float(line["quantity"])

    if await db.inventory_movements.find_one({"source_ref": ref}, {"_id": 0, "id": 1}):
        return "committed"
    if _shop_order_line_terminal_release(order, item_id):
        return "released"

    for _ in range(5):
        product = await db.pos_products.find_one({"id": product_id}, {"_id": 0})
        if not product:
            raise HTTPException(status_code=400, detail=f"{line.get('name') or 'A product'} is no longer available.")
        if not product.get("track_inventory"):
            return "skipped"
        for entry in (product.get("shop_reservations") or []):
            if entry.get("ref") == ref:
                return entry.get("state", "reserved")
        reserved = float(product.get("stock_reserved") or 0)
        stock = float(product.get("stock_on_hand") or 0)
        available = stock - reserved
        if qty > available + 0.0005:
            raise HTTPException(status_code=400, detail=f"Only {max(available, 0):g} in stock for {product.get('name')}.")
        ts = now_iso()
        # Legacy products created before stock_reserved/shop_reservations
        # existed have neither field at all. Mongo's plain equality match
        # never matches a missing field against 0, so a reserved-value of 0
        # read locally (whether genuinely 0 or defaulted from "missing") must
        # accept EITHER condition on the atomic filter. Once any reservation
        # has ever succeeded, stock_reserved is a real number > 0 and this
        # OR clause stops applying — the exact-match CAS behavior below is
        # unchanged for every non-zero case, so two concurrent reservations
        # for the same last unit still can only ever let one writer win.
        stock_reserved_match = (
            {"$or": [{"stock_reserved": 0}, {"stock_reserved": {"$exists": False}}]}
            if reserved == 0 else {"stock_reserved": reserved}
        )
        result = await db.pos_products.find_one_and_update(
            {"id": product_id, "shop_reservations.ref": {"$ne": ref}, **stock_reserved_match},
            {
                "$inc": {"stock_reserved": qty},
                "$push": {"shop_reservations": {
                    "ref": ref, "order_id": order_id, "item_id": item_id, "quantity": qty,
                    "state": "reserved", "created_at": ts, "updated_at": ts,
                }},
                "$set": {"updated_at": ts},
            },
        )
        if result is not None:
            return "reserved"
        # Lost the optimistic race (or a concurrent retry already inserted a
        # reservation for this exact ref) — loop back and re-resolve via the
        # same precedence rather than assuming failure.
    raise HTTPException(status_code=409, detail="Stock changed too many times concurrently — try again.")


async def _commit_shop_inventory_line(order_id: str, line: dict) -> None:
    """Idempotent RESERVED -> COMMITTED transition, called only after
    payment is confirmed. Decrements real stock_on_hand exactly once —
    proven by an inventory_movements row keyed on this line's own ref
    (never inferred from whether the reservation array entry was freshly
    matched) — and writes exactly one inventory_movements row. Safe to call
    any number of times for the same line."""
    if line["kind"] != "product":
        return
    item_id = line["item_id"]
    ref = _shop_inventory_ref(order_id, item_id)
    product_id = line["ref_id"]
    qty = float(line["quantity"])

    if await db.inventory_movements.find_one({"source_ref": ref}, {"_id": 0, "id": 1}):
        return  # already committed by an earlier (crashed) run

    product = await db.pos_products.find_one({"id": product_id}, {"_id": 0})
    if not product or not product.get("track_inventory"):
        return  # untracked (or since-deleted) product never had a reservation to commit

    ts = now_iso()
    stock_before = float(product.get("stock_on_hand") or 0)
    movement = {
        "id": str(uuid.uuid4()), "product_id": product_id, "type": "shop_sale",
        "quantity_delta": round(-qty, 3),
        "stock_before": stock_before, "stock_after": round(stock_before - qty, 3),
        "reason": f"Online Shop order {order_id}", "pos_sale_id": None, "source_ref": ref,
        "user_id": None, "user_name": "Online Shop", "created_at": ts,
    }
    try:
        await db.inventory_movements.insert_one(movement.copy())
    except DuplicateKeyError:
        return  # a concurrent/prior run committed this exact line first
    await db.pos_products.update_one(
        {"id": product_id, "shop_reservations.ref": ref},
        {
            "$inc": {"stock_on_hand": -qty, "stock_reserved": -qty},
            "$set": {"shop_reservations.$.state": "committed", "shop_reservations.$.updated_at": ts, "updated_at": ts},
        },
    )


async def _release_shop_inventory_line(order_id: str, line: dict) -> None:
    """Idempotent RESERVED -> RELEASED transition for a cart line whose
    checkout never completed payment (failed/expired/canceled). Never
    releases a line that's already been committed — checked first, so a
    stale release event racing behind a just-applied payment can never
    resurrect stock that's already been sold."""
    if line["kind"] != "product":
        return
    item_id = line["item_id"]
    ref = _shop_inventory_ref(order_id, item_id)
    product_id = line["ref_id"]
    qty = float(line["quantity"])
    if await db.inventory_movements.find_one({"source_ref": ref}, {"_id": 0, "id": 1}):
        return  # already committed — never release money-committed stock
    ts = now_iso()
    await db.pos_products.update_one(
        {"id": product_id, "shop_reservations": {"$elemMatch": {"ref": ref, "state": "reserved"}}},
        {
            "$inc": {"stock_reserved": -qty},
            "$set": {"shop_reservations.$.state": "released", "shop_reservations.$.updated_at": ts, "updated_at": ts},
        },
    )


async def _release_shop_order_inventory(order_id: str) -> None:
    """Releases every still-reserved physical line on an order whose
    payment did not succeed. Marks each line 'released' on the shop_orders
    document FIRST, then releases the product-level reservation — that
    ordering is load-bearing: _shop_order_line_terminal_release reads the
    order doc's own line status as its precedence-#2 proof."""
    order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
    if not order:
        return
    for line in order.get("lines") or []:
        if line["kind"] != "product" or line.get("fulfillment_status") == "fulfilled":
            continue
        await db.shop_orders.update_one(
            {"id": order_id, "lines.item_id": line["item_id"], "lines.fulfillment_status": {"$ne": "fulfilled"}},
            {"$set": {"lines.$.fulfillment_status": "released"}},
        )
        await _release_shop_inventory_line(order_id, line)


# ── Credit-pack / training-program fulfillment — reuses the EXISTING grant
# math (sell_credit_packs_bulk / sell_training_program), looped per unit so
# each individual unit purchased gets its own durable fulfillment_ref. Never
# duplicates the pricing/grant computation itself. ──────────────────────────

async def _fulfill_shop_credit_pack_line(order: dict, line: dict) -> None:
    """Grants N independent credit_lots (N = line quantity), each keyed by
    its own fulfillment_ref (`shop_order:{order}:item:{item}:unit:{n}`) so a
    crash-and-retry can never double-grant a single unit — reuses
    sell_credit_packs_bulk's exact lot shape. The client's aggregate balance
    $inc is gated by ITS OWN independent atomic marker on the client
    document (shop_credit_grants_applied), never inferred from whether the
    credit_lots insert above was fresh — mirrors _apply_stripe_payment's
    stripe_ar_adjustments_applied pattern."""
    client_id = order["client_id"]
    pack = await db.credit_packs.find_one({"id": line["ref_id"]}, {"_id": 0})
    if not pack:
        raise HTTPException(status_code=500, detail="Credit pack missing during shop fulfillment")
    qty_per_unit = int(pack["qty"])
    unit_price = round(float(line["unit_price"]), 2)
    value_each = round(unit_price / max(qty_per_unit, 1), 2)
    svc_type = pack.get("service_type") or "daycare"
    pool_field = {"daycare": "credits", "training": "training_credits", "boarding": "boarding_credits"}.get(svc_type, "credits")
    # Read the FROZEN snapshot the order line already carries — never the
    # pack's current live price, which may have changed (or the client's
    # override may have since been edited/revoked) since this order was
    # placed. Orders created before these fields existed fall back to the
    # pack's current price/no-override, matching this function's own
    # pre-existing behavior for that legacy case.
    list_price = float(line["list_unit_price"]) if line.get("list_unit_price") is not None else float(pack["price"])
    price_override_id = line.get("price_override_id")

    for n in range(int(line["quantity"])):
        fulfillment_ref = f"{_shop_inventory_ref(order['id'], line['item_id'])}:unit:{n}"
        existing_lot = await db.credit_lots.find_one({"fulfillment_ref": fulfillment_ref}, {"_id": 0, "id": 1})
        if not existing_lot:
            lot = {
                "id": str(uuid.uuid4()), "client_id": client_id,
                "pack_id": pack["id"], "pack_name": pack["name"], "service_type": svc_type,
                "qty_total": qty_per_unit, "qty_remaining": qty_per_unit,
                "price_paid": unit_price, "list_price": round(list_price, 2),
                "price_override_id": price_override_id,
                "value_each": value_each, "payment_method": "stripe_online",
                "note": f"Online Shop order {order['id'][:8].upper()}",
                "sold_by": "Online Shop", "purchased_at": now_iso(),
                "recognize_at_sale": True, "fulfillment_ref": fulfillment_ref,
                "shop_order_id": order["id"],
            }
            try:
                await db.credit_lots.insert_one(lot.copy())
            except DuplicateKeyError:
                pass  # a concurrent/prior run already granted this exact unit

        await db.clients.find_one_and_update(
            {"id": client_id, "shop_credit_grants_applied": {"$ne": fulfillment_ref}},
            {"$inc": {pool_field: qty_per_unit}, "$addToSet": {"shop_credit_grants_applied": fulfillment_ref}},
        )


async def _fulfill_shop_training_program_line(order: dict, line: dict) -> None:
    """Grants N independent training-credit lots (N = line quantity, almost
    always 1) reusing sell_training_program's exact credit_lot grant shape —
    deliberately WITHOUT its dog-enrollment/session-scheduling features,
    which have no equivalent input in a Shop cart and are an admin-only
    concern. A client who buys a program online still receives their
    training_credits and can be enrolled by staff exactly as any other
    training-credit purchase would be. Same two-independent-idempotency-
    guarantee shape as the credit-pack path above."""
    client_id = order["client_id"]
    program = await db.programs.find_one({"id": line["ref_id"]}, {"_id": 0})
    if not program:
        raise HTTPException(status_code=500, detail="Training program missing during shop fulfillment")
    fmt = program.get("format") or {}
    qty_per_unit = int(fmt.get("count") or 0)
    unit = fmt.get("unit") or "sessions"
    unit_price = round(float(line["unit_price"]), 2)
    value_each = round(unit_price / max(qty_per_unit, 1), 2)

    for n in range(int(line["quantity"])):
        fulfillment_ref = f"{_shop_inventory_ref(order['id'], line['item_id'])}:unit:{n}"
        existing_lot = await db.credit_lots.find_one({"fulfillment_ref": fulfillment_ref}, {"_id": 0, "id": 1})
        if not existing_lot:
            lot = {
                "id": str(uuid.uuid4()), "client_id": client_id,
                "pack_kind": "training_program", "pack_id": program["id"], "pack_name": program["name"],
                "program_id": program["id"], "program_name": program["name"], "service_type": "training",
                "qty_total": qty_per_unit, "qty_remaining": qty_per_unit, "unit": unit,
                "price_paid": unit_price, "list_price": round(float(program.get("price") or 0), 2),
                "value_each": value_each, "payment_method": "stripe_online",
                "note": f"Online Shop order {order['id'][:8].upper()}",
                "sold_by": "Online Shop", "purchased_at": now_iso(),
                "fulfillment_ref": fulfillment_ref, "shop_order_id": order["id"],
            }
            try:
                await db.credit_lots.insert_one(lot.copy())
            except DuplicateKeyError:
                pass

        await db.clients.find_one_and_update(
            {"id": client_id, "shop_credit_grants_applied": {"$ne": fulfillment_ref}},
            {"$inc": {"training_credits": qty_per_unit}, "$addToSet": {"shop_credit_grants_applied": fulfillment_ref}},
        )


async def _fulfill_shop_online_school_program_line(order: dict, line: dict) -> None:
    """Phase 5 — grants Online School access for a purchase_fulfillment=
    "online_school" program line by calling the SAME canonical helper
    school_enroll uses: never a parallel commerce enrollment. Money grants
    access; it does not create a second training-progress model.

    Idempotent the same way every other _apply_shop_payment fulfillment
    step is: this is called from Step B3, which already skips any line
    already marked fulfillment_status=="fulfilled" and retries
    "pending"/"failed" ones — so a crash or webhook replay before this
    line's $set lands simply re-enters here, and
    OnlineSchoolAlreadyEnrolledError (raised when the enrollment this
    exact retry would create already exists) converges onto that existing
    enrollment instead of erroring. dog_id/fulfillment_kind are read from
    the line's own frozen pricing-time snapshot (see _price_shop_cart),
    never re-derived from the live program doc, so a program edited after
    purchase can't retarget an in-flight fulfillment."""
    dog_id = line.get("dog_id")
    if not dog_id:
        raise HTTPException(status_code=500, detail="Online School shop line is missing its frozen dog_id during fulfillment")
    dog = await db.dogs.find_one({"id": dog_id}, {"_id": 0})
    if not dog or dog.get("owner_id") != order["client_id"]:
        raise HTTPException(status_code=500, detail="Online School shop line's dog no longer belongs to the purchasing client")
    program = await db.programs.find_one({"id": line["ref_id"]}, {"_id": 0})
    if not program:
        raise HTTPException(status_code=500, detail="Training program missing during shop fulfillment")
    source_ref = f"shop_order:{order['id']}:line:{line['item_id']}"
    try:
        result = await _grant_online_school_enrollment(
            dog, program, enrolled_by=None, enrollment_source="purchase", source_ref=source_ref,
        )
        enrollment_id = result["enrollment"]["id"]
    except OnlineSchoolAlreadyEnrolledError as exc:
        enrollment_id = exc.dog_program_id

    await db.shop_orders.update_one(
        {"id": order["id"], "lines.item_id": line["item_id"]},
        {"$set": {"lines.$.online_school_enrollment_id": enrollment_id, "updated_at": now_iso()}},
    )


# ── Atomic shop_order-pointer reservation — the Invoice-pointer pattern,
# reimplemented against shop_orders (can't reuse the invoice helpers
# verbatim, they're hardcoded to db.invoices). ──────────────────────────────

async def _acquire_shop_order_reservation(order_id: str, attempt_id: str, amount_cents: int) -> Optional[dict]:
    return await db.shop_orders.find_one_and_update(
        {"id": order_id, "status": "pending_payment", "stripe_active_attempt_id": None},
        {"$set": {
            "stripe_active_attempt_id": attempt_id, "stripe_reserved_amount_cents": amount_cents,
            "updated_at": now_iso(),
        }},
        return_document=ReturnDocument.AFTER,
    )


async def _release_shop_order_reservation_if_owned(order_id: str, attempt_id: str) -> None:
    await db.shop_orders.update_one(
        {"id": order_id, "stripe_active_attempt_id": attempt_id},
        {"$unset": {"stripe_active_attempt_id": "", "stripe_reserved_amount_cents": ""},
         "$set": {"updated_at": now_iso()}},
    )


# ── Resumable, crash-safe local application — mirrors _apply_stripe_payment's
# exact Step A/B1-B5 idiom. ──────────────────────────────────────────────────

def _verify_shop_stripe_session_authoritative(session_obj: dict, attempt: dict, order: dict) -> None:
    """Independently proves the Stripe payment actually belongs to and
    exactly matches this shop order, BEFORE any fulfillment, inventory
    commit, credit/program grant, or local-paid state occurs. Every value
    checked here comes from Stripe itself — either the signature-verified
    webhook payload (construct_event already proved it's genuinely from
    Stripe before this ever runs) or a direct stripe.checkout.Session.
    retrieve() call — never from metadata alone, never from a browser-
    return query parameter, never from a client-submitted total.

    Raises HTTPException(409) on ANY mismatch. The caller is responsible
    for landing the attempt in reconciliation_required and performing NO
    financial or fulfillment mutation — never auto-refund or auto-recharge
    just because reconciliation is required."""
    if session_obj.get("id") != attempt.get("stripe_checkout_session_id"):
        raise HTTPException(status_code=409, detail="Stripe session id does not match the stored payment attempt — reconciliation required.")
    metadata = session_obj.get("metadata") or {}
    if metadata.get("sithappens_shop_order_id") != order.get("id"):
        raise HTTPException(status_code=409, detail="Stripe session metadata does not match the expected shop order — reconciliation required.")
    if metadata.get("sithappens_attempt_id") != attempt.get("id"):
        raise HTTPException(status_code=409, detail="Stripe session metadata does not match the expected payment attempt — reconciliation required.")
    if (session_obj.get("currency") or "").lower() != "usd":
        raise HTTPException(status_code=409, detail="Stripe session currency does not match the expected currency — reconciliation required.")
    if session_obj.get("payment_status") != "paid":
        raise HTTPException(status_code=409, detail="Stripe session does not represent a completed payment — reconciliation required.")
    # Never trust attempt.amount_cents alone — recompute the expected charge
    # from the order's own frozen total (the one number nothing here ever
    # lets a client influence) and require BOTH Stripe's own amount_total
    # AND our stored attempt amount to agree with it exactly, in cents.
    expected_cents = _stripe_amount_cents(order.get("total") or 0)
    stripe_amount = session_obj.get("amount_total")
    if stripe_amount is None or int(stripe_amount) != expected_cents:
        raise HTTPException(status_code=409, detail="Stripe paid amount does not match the order total — reconciliation required.")
    if int(attempt.get("amount_cents") or -1) != expected_cents:
        raise HTTPException(status_code=409, detail="Stored payment attempt amount does not match the order total — reconciliation required.")


async def _queue_new_shop_order_notification(order: dict) -> None:
    """Admin notification that a Shop order was paid — durably QUEUED into
    email_outbox (see email_service.queue_admin_new_shop_order), never sent
    synchronously here. A crash immediately after this call returns still
    results in eventual delivery: the row already exists in email_outbox,
    independent of this process's lifetime, and process_email_outbox picks
    it up later.

    notification_log is read here ONLY as a "we already know this was fully
    delivered" short-circuit (skip re-queuing once it's confirmed sent) —
    never as a pre-send gate. Without this check, a webhook replay arriving
    AFTER email_outbox has already delivered-and-deleted the row would
    re-queue a fresh send; with it, once notification_log has the
    post-delivery stamp, we correctly stop. Before that stamp exists,
    _queue_email's own upsert-on-key is what prevents a second row from
    ever being created (see its docstring) — so there is no window where a
    crash between claim and send can permanently suppress the email, unlike
    the notification_log-claim-first design this replaces."""
    order_id = order["id"]
    already_delivered = await db.notification_log.find_one({"key": f"shop_order_new:{order_id}"}, {"_id": 0, "key": 1})
    if already_delivered is not None:
        return
    client = await db.clients.find_one({"id": order.get("client_id")}, {"_id": 0})
    await queue_admin_new_shop_order(order, client)


async def _apply_shop_payment(attempt: dict, session_obj: Optional[dict] = None) -> dict:
    """The ONE local-application sequence for a Stripe-confirmed Shop order
    payment. Safe to call any number of times for the SAME attempt — every
    step is independently idempotent via its own durable marker, so a crash
    between any two steps is recoverable by simply calling this again.
    Reuses the EXISTING canonical Payment/retail_sales/credit_lots/inventory
    machinery — this is not a second accounting engine. Per-line
    fulfillment is independent: one line failing never blocks, rolls back,
    or re-processes a sibling line that already succeeded.

    `session_obj` is the authoritative Stripe Checkout Session payload
    (from the signature-verified webhook, or a direct Session.retrieve()
    call) — REQUIRED the first time this attempt ever transitions the
    order to paid (see _verify_shop_stripe_session_authoritative), so that
    verification can never be skipped by construction. Not required on a
    resumed/retry call once the order is already past that transition —
    e.g. the Front Desk "Retry Fulfillment" action, which only re-drives
    Step B for an order already verified paid, and never re-charges."""
    attempt_id = attempt["id"]
    order_id = attempt["shop_order_id"]
    amount = round(attempt["amount_cents"] / 100.0, 2)
    ts = now_iso()
    business_date = business_today().isoformat()

    order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
    if not order:
        raise HTTPException(status_code=500, detail="Shop order missing during Stripe apply")

    # ── Step A — order status transition, idempotent via
    # shop_last_applied_attempt_id (never cleared for this attempt once set) ──
    if order.get("shop_last_applied_attempt_id") != attempt_id:
        # ── Step 0 — authoritative Stripe verification, gated INSIDE this
        # same "first transition" branch so it can never be bypassed by a
        # caller that forgets to pass session_obj: without it, we refuse
        # outright rather than silently trusting our own stored attempt. ──
        if session_obj is None:
            raise HTTPException(status_code=409, detail="Missing authoritative Stripe session data — reconciliation required.")
        _verify_shop_stripe_session_authoritative(session_obj, attempt, order)
        result = await db.shop_orders.find_one_and_update(
            {
                "id": order_id, "status": {"$ne": "canceled"},
                "shop_last_applied_attempt_id": {"$ne": attempt_id},
            },
            {"$set": {"status": "paid", "shop_last_applied_attempt_id": attempt_id, "updated_at": ts}},
            return_document=ReturnDocument.AFTER,
        )
        if result is None:
            fresh = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
            if not fresh or fresh.get("shop_last_applied_attempt_id") != attempt_id:
                raise HTTPException(status_code=409, detail="Shop order reservation was lost before payment could be applied — reconciliation required.")
            order = fresh
        else:
            order = result
            # Fires exactly once per order — only the caller that actually won
            # this status-transition race reaches here; a concurrent/retried
            # call that finds the order already flipped takes the `fresh`
            # branch above instead, so this can never double-send.
            try:
                asyncio.create_task(_maybe_auto_email_receipt("shop_order", order_id, order.get("client_id")))
            except Exception as exc:
                logger.warning("auto-email receipt spawn failed for shop order %s: %s", order_id, exc)

    # ── Step B1 — canonical Payment row, reusing the EXISTING check-before-
    # insert idempotency helper. invoice_id=None, shop_order_id set. ──
    payment_row = await _insert_payment_row({
        "id": str(uuid.uuid4()), "invoice_id": None, "shop_order_id": order_id,
        "client_id": order.get("client_id"),
        "amount": amount, "method": "stripe_online", "is_credit": False, "date": business_date,
        "employee_id": None, "employee_name": None,
        "processor": "stripe", "processor_payment_id": attempt.get("stripe_payment_intent_id"),
        "status": "completed", "notes": "", "refunded_amount": 0.0,
        "source": {
            "kind": "shop_order_payment", "stripe_attempt_id": attempt_id,
            "stripe_checkout_session_id": attempt.get("stripe_checkout_session_id"),
            "stripe_payment_intent_id": attempt.get("stripe_payment_intent_id"),
            "stripe_customer_id": attempt.get("stripe_customer_id"),
            "card_brand": attempt.get("card_brand"), "card_last4": attempt.get("card_last4"),
        },
        "booking_id": None, "ledger_id": None,
        "idempotency_ref": f"shop_attempt:{attempt_id}",
        "created_at": ts, "updated_at": ts,
        "tendered_amount": None, "change_given": None, "business_date": business_date,
    })
    payment_id = payment_row["id"]

    # ── Step B2 — ONE retail_sales revenue row for the whole order,
    # independently resumable by the canonical Payment id — reuses the SAME
    # existing unique partial index on retail_sales.payment_id, no new
    # index needed. ──
    existing_retail = await db.retail_sales.find_one({"payment_id": payment_id}, {"_id": 0})
    if not existing_retail:
        retail_row = {
            "id": str(uuid.uuid4()), "date": business_date, "amount": amount,
            "payment_method": "stripe_online",
            "client_id": order.get("client_id"), "client_name": order.get("client_name"),
            "payment_id": payment_id, "shop_order_id": order_id,
            "source_kind": "shop_order", "description": f"Online Shop order #{order_id[:8].upper()}",
            "tax_amount": round(float(order.get("tax_amount") or 0), 2),
            "tax_rate_pct": float(order.get("tax_rate_pct") or 0),
            "pre_tax_amount": round(float(order.get("subtotal") or 0), 2),
            "created_at": ts, "created_by": "stripe_webhook", "logged_by": "Stripe",
        }
        try:
            await db.retail_sales.insert_one(retail_row.copy())
        except DuplicateKeyError:
            pass  # already inserted by a concurrent/prior run

    # ── Order is now confirmed PAID with its canonical Payment/retail_sales
    # rows in place — durably queue the admin new-order notification,
    # before per-line fulfillment continues below. Never coupled to
    # fulfillment outcome: this fires whether or not individual lines below
    # go on to succeed. Queuing is a fast Mongo upsert only — no synchronous
    # Resend call happens on this path. ──
    try:
        await _queue_new_shop_order_notification(order)
    except Exception:
        logger.exception("failed to queue admin new-shop-order notification for order %s", order_id)

    # ── Step B3 — per-line independent fulfillment. ──
    for line in order.get("lines") or []:
        if line.get("fulfillment_status") == "fulfilled":
            continue
        try:
            if line["kind"] == "product":
                await _commit_shop_inventory_line(order_id, line)
            elif line["kind"] == "credit_pack":
                await _fulfill_shop_credit_pack_line(order, line)
            elif line["kind"] == "training_program" and line.get("fulfillment_kind") == "online_school":
                await _fulfill_shop_online_school_program_line(order, line)
            else:
                await _fulfill_shop_training_program_line(order, line)
            await db.shop_orders.update_one(
                {"id": order_id, "lines.item_id": line["item_id"]},
                # Phase 6 (6.8) — clear any stale fulfillment_error from an
                # earlier failed attempt now that a retry has succeeded, so
                # staff never see a resolved error sitting on a fulfilled line.
                {"$set": {"lines.$.fulfillment_status": "fulfilled", "lines.$.fulfillment_error": None, "updated_at": now_iso()}},
            )
        except Exception as exc:
            logger.warning("Shop order %s line %s fulfillment failed: %s", order_id, line["item_id"], exc)
            await db.shop_orders.update_one(
                {"id": order_id, "lines.item_id": line["item_id"]},
                # Phase 6 (6.8) — the actual failure reason, truncated, so
                # the admin Online Orders "Needs Attention" view can show
                # WHY a line is stuck rather than only that it is.
                {"$set": {"lines.$.fulfillment_status": "failed", "lines.$.fulfillment_error": str(exc)[:500], "updated_at": now_iso()}},
            )

    # ── Step B4 — order-level fulfillment status, always safe to rerun (a
    # pure function of the order's current line states). ──
    fresh_order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
    fresh_lines = fresh_order.get("lines") or []
    order_fulfillment = "fulfilled" if all(l.get("fulfillment_status") == "fulfilled" for l in fresh_lines) else "needs_attention"
    await db.shop_orders.update_one({"id": order_id}, {"$set": {"fulfillment_status": order_fulfillment, "updated_at": now_iso()}})

    # ── Step B5 — initialize pickup_status exactly once. Physical orders
    # start "preparing" (staff then walks it through ready_for_pickup ->
    # picked_up); an order with no kind=="product" line needs no pickup at
    # all. The filter's $nin excludes every already-initialized state AND
    # (by Mongo's null-equivalence for a missing/None field) the
    # never-initialized case — so a webhook/payment replay can never
    # regress an order that staff has already progressed to
    # ready_for_pickup/picked_up back to "preparing". ──
    has_physical_product = any(l.get("kind") == "product" for l in fresh_lines)
    initial_pickup_status = "preparing" if has_physical_product else "not_applicable"
    await db.shop_orders.update_one(
        {"id": order_id, "pickup_status": {"$nin": list(SHOP_PICKUP_INITIALIZED_STATES)}},
        {"$set": {"pickup_status": initial_pickup_status, "updated_at": now_iso()}},
    )

    # ── Every Step B write independently confirmed complete — mark applied,
    # THEN (only then) release the reservation. Never the reverse order. ──
    await db.shop_payment_attempts.update_one(
        {"id": attempt_id}, {"$set": {"status": "applied", "applied_payment_id": payment_id, "updated_at": now_iso()}},
    )
    await _release_shop_order_reservation_if_owned(order_id, attempt_id)

    return await db.shop_orders.find_one({"id": order_id}, {"_id": 0})


async def _verify_and_reconcile_shop_session(attempt: dict) -> dict:
    """No-TTL replacement for time-based release — mirrors
    _verify_and_reconcile_stripe_session exactly. Never releases a 'pending'
    shop payment attempt just because expires_at has passed; always asks
    Stripe for the real Checkout Session state first."""
    if attempt.get("status") != "pending":
        return attempt
    session = stripe.checkout.Session.retrieve(attempt["stripe_checkout_session_id"]).to_dict()
    if session.get("payment_status") == "paid":
        try:
            await _apply_shop_payment(attempt, session)
        except HTTPException:
            await db.shop_payment_attempts.find_one_and_update(
                {"id": attempt["id"], "status": {"$nin": list(SHOP_PAYMENT_ATTEMPT_TERMINAL_STATUSES)}},
                {"$set": {"status": "reconciliation_required", "updated_at": now_iso()}},
            )
    elif not await _shop_order_already_paid(attempt["shop_order_id"]):
        result = await db.shop_payment_attempts.find_one_and_update(
            {"id": attempt["id"], "status": "pending"},
            {"$set": {"status": "expired", "updated_at": now_iso()}},
        )
        if result is not None:
            await _release_shop_order_reservation_if_owned(attempt["shop_order_id"], attempt["id"])
            await _release_shop_order_inventory(attempt["shop_order_id"])
            await db.shop_orders.update_one(
                {"id": attempt["shop_order_id"], "status": {"$ne": "paid"}},
                {"$set": {"status": "canceled", "updated_at": now_iso()}},
            )
    return await db.shop_payment_attempts.find_one({"id": attempt["id"]}, {"_id": 0})


# ── Free Online School claim ────────────────────────────────────────────────
#
# A genuinely free course grants Online School access WITHOUT money moving.
# It therefore does not — and must not — travel the checkout path: no Stripe
# session, no PaymentIntent, no shop_order, no payment, no revenue, no tax, no
# merchant fee, no drawer movement. The $0 cart guard in create_shop_checkout
# stays exactly as it is; this is a different door, not a hole in that one.
#
# What it DOES share with a paid purchase is everything that matters for
# correctness:
#   • _validate_shop_item_eligibility — the same canonical purchase gate
#     (active, online, section/category visibility, approval, dog ownership,
#     one-enrollment-per-dog, prerequisites, completed-onboarding). Routing
#     through it rather than reimplementing means any gate added there later
#     — a program agreement requirement, for one — applies here automatically.
#   • _grant_online_school_enrollment — THE canonical enrollment creator. A
#     free enrollment is byte-identical in shape to a paid or staff-created
#     one, differing only in enrollment_source provenance.
#
# Free changes how entitlement is OBTAINED. It changes nothing about how
# School works afterwards.


class FreeCourseClaimIn(BaseModel):
    program_id: str
    dog_id: Optional[str] = None


def _free_claim_program_blockers(program: Optional[dict]) -> Optional[str]:
    """Why this program may NOT be claimed for free, or None when it may.

    Every condition is read from the STORED program document, never from
    anything the client sent. Deliberately independent of price alone: an
    imported draft sitting at $0 is not a free course, it is an unpriced one,
    and the difference is the explicit opt-in flag."""
    if not program:
        return "This course is no longer available."
    if not program.get("free_enrollment_enabled"):
        # Covers the dangerous case: price == 0 with no deliberate opt-in.
        return "This course isn't available as a free course."
    if not program.get("active", True):
        return "This course is no longer available."
    if float(program.get("price") or 0) > 0.005:
        # Belt and braces: a priced program must never be claimable even if
        # the flag was left on by mistake after a price was added.
        return "This course isn't free — please purchase it from the shop."
    if program.get("purchase_fulfillment") != "online_school":
        return "This course isn't set up for Online School access."
    if program.get("delivery_mode", "trainer_led") not in ("self_guided", "both"):
        return "This course isn't set up for self-guided delivery."
    return None


@api.post("/shop/free-course/claim")
async def claim_free_program(body: FreeCourseClaimIn, user: dict = Depends(get_current_user)):
    """Start Free Course — grant a client Online School access to a program
    explicitly configured for free enrollment, for one of their own dogs.

    Idempotent by construction. The canonical creator raises
    OnlineSchoolAlreadyEnrolledError for an existing active enrollment (and
    self-heals an orphaned dog_programs row while doing so), which is
    converged onto here rather than surfaced as an error — a double-click or
    a retry lands the client on the course they already have. Genuine
    concurrency is caught by the dp_online_active_unique partial index inside
    the creator, so two simultaneous claims still produce exactly one
    enrollment."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    client_id = user.get("client_id")
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")

    program = await db.programs.find_one({"id": body.program_id}, {"_id": 0})
    blocker = _free_claim_program_blockers(program)
    if blocker:
        # 404 for "doesn't exist", 409 for "exists but isn't claimable" — a
        # probing client learns nothing about programs they can't see.
        raise HTTPException(status_code=404 if not program else 409, detail=blocker)

    # School progress belongs to a dog; never invent one.
    if not body.dog_id:
        raise HTTPException(status_code=422, detail={
            "code": "free_course_dog_required",
            "message": f"Choose which dog is taking {program.get('name') or 'this course'}.",
        })
    dog = await db.dogs.find_one({"id": body.dog_id}, {"_id": 0})
    if not dog or dog.get("owner_id") != client_id:
        # Same message for missing and not-yours: a client must not be able to
        # probe for other people's dog ids.
        raise HTTPException(status_code=404, detail="Selected dog was not found on this account.")

    # Already actively enrolled? Converge and hand back the existing course.
    # This runs BEFORE the purchase gate on purpose: that gate correctly 409s
    # a repeat PURCHASE ("you already own this, don't pay twice"), but a
    # repeat free CLAIM is a double-click, and the right answer to a
    # double-click is the course they already have, not an error.
    existing = await db.dog_programs.find_one(
        {"dog_id": body.dog_id, "program_id": program["id"],
         "delivery_channel": "online_school", "status": "active"},
        {"_id": 0, "id": 1},
    )
    if existing:
        companion = await _self_heal_missing_school_enrollment(
            existing["id"], body.dog_id, program["id"], client_id, None,
        )
        return {
            "school_enrollment_id": companion["id"],
            "program_id": program["id"],
            "program_name": program.get("name") or "",
            "dog_id": body.dog_id,
            "dog_name": dog.get("name") or "",
            "created": False,
        }

    # THE canonical purchase gate, reused verbatim. Completed/withdrawn
    # enrollments still get its clear no-retake messages, and every other
    # requirement it enforces applies here unchanged.
    await _validate_shop_item_eligibility(client, "training_program", program, 1, dog_id=body.dog_id)

    try:
        result = await _grant_online_school_enrollment(
            dog, program, enrolled_by=None,
            enrollment_source="free_claim", source_ref=f"free_claim:client:{client_id}",
        )
        school_enrollment_id = result["school_enrollment"]["id"]
        created = True
    except OnlineSchoolAlreadyEnrolledError as exc:
        # Converge, never error: this is a retry, a double-click, or a lost
        # concurrency race, and in all three the client should simply arrive
        # at the enrollment that exists.
        if exc.status in ("completed", "withdrawn"):
            raise HTTPException(status_code=409, detail=(
                f"This dog has already taken {program.get('name') or 'this course'}."
            ))
        school_enrollment_id = exc.school_enrollment_id
        created = False

    return {
        "school_enrollment_id": school_enrollment_id,
        "program_id": program["id"],
        "program_name": program.get("name") or "",
        "dog_id": body.dog_id,
        "dog_name": dog.get("name") or "",
        "created": created,
    }


@api.post("/shop/checkout")
async def create_shop_checkout(body: ShopCheckoutIn, user: dict = Depends(get_current_user)):
    """Client Shop Phase 2 — the ONE checkout entry point. Claim-first
    idempotency preassigns a shop_order_id so a retried request always
    resumes the SAME order/reservation/Stripe session rather than pricing,
    reserving, or charging a second time."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    _require_stripe_online_enabled()
    client_id = user.get("client_id")
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")

    # Combine duplicate (kind, ref_id) lines into one BEFORE anything else —
    # fingerprinting, pricing, stock checks, eligibility, reservation,
    # entitlement creation, and Stripe session creation all operate on this
    # normalized list, never the raw, possibly-duplicated request body.
    normalized_items = _normalize_cart_lines(body.items)

    cart_fingerprint_items = [{"kind": it.kind, "ref_id": it.ref_id, "quantity": it.quantity, "dog_id": it.dog_id} for it in normalized_items]
    fingerprint = _request_fingerprint(client_id, cart_fingerprint_items)
    order_id = str(uuid.uuid4())
    ts = now_iso()

    try:
        await db.shop_checkout_claims.insert_one({
            "id": str(uuid.uuid4()), "idempotency_key": body.idempotency_key, "request_fingerprint": fingerprint,
            "client_id": client_id, "shop_order_id": order_id, "created_at": ts, "updated_at": ts,
        })
    except DuplicateKeyError:
        existing_claim = await db.shop_checkout_claims.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if not existing_claim or existing_claim.get("client_id") != client_id or existing_claim.get("request_fingerprint") != fingerprint:
            raise HTTPException(status_code=409, detail="This idempotency key was already used for a different request.")
        order_id = existing_claim["shop_order_id"]  # resume the SAME order this key already claimed

    order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
    if not order:
        priced = await _price_shop_cart(normalized_items, client_id=client_id)
        if priced["total"] <= 0.005:
            raise HTTPException(status_code=400, detail="Cart total must be greater than zero.")

        # Additive eligibility/state revalidation — immediately before the
        # order (and therefore any reservation, entitlement, inventory
        # movement, or Stripe session) is created. A rejection here means
        # no order row is ever inserted — the idempotency claim row above
        # is the only trace of the attempt, and the same idempotency key
        # can be retried later once the underlying issue is fixed. Runs
        # only on first creation, never when resuming an already-created
        # order, so a fully eligible cart's idempotent-retry behavior is
        # completely unaffected.
        for line in priced["lines"]:
            item_doc = await db[_SHOP_ITEM_COLLECTION_NAME[line["kind"]]].find_one({"id": line["ref_id"]}, {"_id": 0})
            await _validate_shop_item_eligibility(client, line["kind"], item_doc, int(line["quantity"]), dog_id=line.get("dog_id"))

        order_doc = {
            "id": order_id, "client_id": client_id, "client_name": client.get("name") or "",
            "status": "pending_payment", "fulfillment_status": "pending", "pickup_status": None,
            "lines": priced["lines"], "subtotal": priced["subtotal"], "tax_amount": priced["tax_amount"],
            "tax_rate_pct": priced["tax_rate_pct"], "total": priced["total"], "currency": "USD",
            "stripe_active_attempt_id": None, "stripe_reserved_amount_cents": None,
            "shop_last_applied_attempt_id": None,
            # Front Desk "new order" badge marker. Initialized ONCE here at
            # creation (never inside _apply_shop_payment, which is
            # replayable) so a webhook replay/Retry Fulfillment can never
            # reset it back to true once staff has seen it. Historical
            # orders predating this field simply lack it — the unseen-count
            # query requires admin_unseen == True by exact match, so a
            # missing field never counts (never treated as unseen).
            "admin_unseen": True,
            "created_at": ts, "updated_at": ts,
        }
        try:
            await db.shop_orders.insert_one(order_doc)
            order = order_doc
        except DuplicateKeyError:
            order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})

    if order.get("status") in ("payment_failed", "canceled"):
        raise HTTPException(status_code=409, detail="This order can no longer be paid — please start a new checkout.")

    # Reserve inventory for every physical line — per-line independent, using
    # the exact retry precedence documented on _reserve_shop_inventory_line.
    for line in order["lines"]:
        await _reserve_shop_inventory_line(order, line)

    amount_cents = _stripe_amount_cents(order["total"])
    attempt_id = str(uuid.uuid4())
    try:
        await db.shop_payment_attempts.insert_one({
            "id": attempt_id, "idempotency_key": body.idempotency_key, "request_fingerprint": fingerprint,
            "shop_order_id": order_id, "client_id": client_id, "amount_cents": amount_cents,
            "status": "pending",
            "stripe_checkout_session_id": None, "stripe_checkout_session_url": None,
            "stripe_payment_intent_id": None, "stripe_customer_id": None,
            "card_brand": None, "card_last4": None, "applied_payment_id": None,
            "created_at": ts, "updated_at": ts, "expires_at": None,
        })
    except DuplicateKeyError:
        existing = await db.shop_payment_attempts.find_one({"idempotency_key": body.idempotency_key}, {"_id": 0})
        if not existing or existing.get("shop_order_id") != order_id:
            raise HTTPException(status_code=409, detail="This idempotency key was already used for a different request.")
        if existing.get("stripe_checkout_session_url"):
            return {"url": existing["stripe_checkout_session_url"], "order_id": order_id}
        if existing.get("status") in SHOP_PAYMENT_ATTEMPT_TERMINAL_STATUSES:
            raise HTTPException(status_code=409, detail="This payment attempt has already been resolved.")
        attempt_id = existing["id"]

    reserved_order = await _acquire_shop_order_reservation(order_id, attempt_id, amount_cents)
    if reserved_order is None:
        current_order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0, "stripe_active_attempt_id": 1})
        if not (current_order and current_order.get("stripe_active_attempt_id") == attempt_id):
            await db.shop_payment_attempts.delete_one({"id": attempt_id, "stripe_checkout_session_id": None})
            raise HTTPException(status_code=409, detail="This order already has an active online payment in progress.")

    expires_at = datetime.now(timezone.utc) + timedelta(seconds=STRIPE_CHECKOUT_EXPIRES_SECONDS)
    stripe_customer_id = client.get("stripe_customer_id")
    try:
        if not stripe_customer_id:
            customer = stripe.Customer.create(
                name=client.get("name") or None, email=client.get("email") or None,
                metadata={"sithappens_client_id": client_id},
            )
            stripe_customer_id = customer["id"]
            await db.clients.update_one({"id": client_id}, {"$set": {"stripe_customer_id": stripe_customer_id}})

        line_items = [{
            "price_data": {
                "currency": "usd", "product_data": {"name": l["name"]},
                "unit_amount": _stripe_amount_cents(l["unit_price"]),
            },
            "quantity": l["quantity"],
        } for l in order["lines"]]
        if order.get("tax_amount"):
            line_items.append({
                "price_data": {
                    "currency": "usd", "product_data": {"name": "Sales tax"},
                    "unit_amount": _stripe_amount_cents(order["tax_amount"]),
                },
                "quantity": 1,
            })

        session = stripe.checkout.Session.create(
            mode="payment",
            customer=stripe_customer_id,
            line_items=line_items,
            success_url=f"{_app_public_url()}/portal?shop_order={order_id}&stripe=success",
            cancel_url=f"{_app_public_url()}/portal?shop_order={order_id}&stripe=cancel",
            expires_at=int(expires_at.timestamp()),
            metadata={
                "sithappens_attempt_id": attempt_id, "sithappens_shop_order_id": order_id,
                "sithappens_client_id": client_id,
            },
            idempotency_key=f"shop_attempt_create:{attempt_id}",
        )
    except Exception as exc:
        await db.shop_payment_attempts.update_one({"id": attempt_id}, {"$set": {"status": "failed", "updated_at": now_iso()}})
        await _release_shop_order_reservation_if_owned(order_id, attempt_id)
        # Unlike an invoice (no separate inventory concept), a shop order may
        # already hold real stock reservations at this point — those must
        # never be left dangling just because Stripe itself was unreachable.
        # Mark the order failed and release every physical line's claim.
        await db.shop_orders.update_one(
            {"id": order_id, "status": {"$ne": "paid"}},
            {"$set": {"status": "payment_failed", "updated_at": now_iso()}},
        )
        await _release_shop_order_inventory(order_id)
        logger.warning("Stripe Checkout Session creation failed for shop attempt %s: %s", attempt_id, exc)
        raise HTTPException(status_code=502, detail="Could not start the online payment — please try again.")

    await db.shop_payment_attempts.update_one(
        {"id": attempt_id},
        {"$set": {
            "stripe_checkout_session_id": session["id"], "stripe_checkout_session_url": session["url"],
            "stripe_customer_id": stripe_customer_id, "expires_at": expires_at.isoformat(), "updated_at": now_iso(),
        }},
    )
    return {"url": session["url"], "order_id": order_id}


@api.get("/portal/shop-orders")
async def portal_shop_orders(user: dict = Depends(get_current_user)):
    """Client's own Shop order history — hand-picked safe fields only, same
    convention as portal_invoices. Ownership is enforced by construction:
    the query is scoped to user['client_id'] from the authenticated
    session, never a client-submitted id."""
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    cid = user.get("client_id")
    orders = []
    if cid:
        rows = await db.shop_orders.find({"client_id": cid}, {"_id": 0}).sort("created_at", -1).to_list(200)
        for o in rows:
            orders.append({
                "order_id": o["id"], "created_at": o.get("created_at"),
                "status": o.get("status"), "fulfillment_status": o.get("fulfillment_status"),
                "pickup_status": o.get("pickup_status"), "total": o.get("total"),
                "lines": [
                    {"kind": l["kind"], "name": l["name"], "quantity": l["quantity"], "fulfillment_status": l.get("fulfillment_status")}
                    for l in (o.get("lines") or [])
                ],
            })
    return {"orders": orders}


@api.get("/portal/shop-orders/{order_id}")
async def portal_shop_order_status(order_id: str, user: dict = Depends(get_current_user)):
    if user.get("role") != "client":
        raise HTTPException(status_code=403, detail="Client account required")
    order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
    if not order or order.get("client_id") != user.get("client_id"):
        raise HTTPException(status_code=404, detail="Order not found")

    attempt = await db.shop_payment_attempts.find_one({"shop_order_id": order_id}, {"_id": 0})
    if attempt and attempt.get("status") == "pending" and attempt.get("expires_at"):
        try:
            if datetime.now(timezone.utc) > datetime.fromisoformat(attempt["expires_at"]):
                await _verify_and_reconcile_shop_session(attempt)
                order = await db.shop_orders.find_one({"id": order_id}, {"_id": 0})
        except HTTPException:
            pass  # verification itself failed — client just sees the current state and can poll again

    return {
        "order_id": order_id, "status": order.get("status"), "fulfillment_status": order.get("fulfillment_status"),
        "pickup_status": order.get("pickup_status"), "total": order.get("total"),
        "lines": [
            {"kind": l["kind"], "name": l["name"], "quantity": l["quantity"], "fulfillment_status": l.get("fulfillment_status")}
            for l in (order.get("lines") or [])
        ],
    }


