class PunchCorrectionDecisionIn(BaseModel):
    decision: Literal["approved", "denied"]
    admin_note: Optional[str] = Field(default="", max_length=500)


@api.post("/employee/punch-corrections/{cid}/decision")
async def employee_decide_punch_correction(
    cid: str, body: PunchCorrectionDecisionIn, user: dict = Depends(require_admin_and_permission("manage_staff_scheduling")),
):
    """Admin approves/denies a correction. On approve, the requested
    clock_in/clock_out get applied to the time_clock_entries row (or a new
    row is created if target_entry_id is empty)."""
    req = await db.punch_corrections.find_one({"id": cid}, {"_id": 0})
    if not req:
        raise HTTPException(status_code=404, detail="Request not found")
    if req["status"] != "pending":
        raise HTTPException(status_code=409, detail="Already decided")
    update = {
        "status": body.decision,
        "decided_by_id": user.get("id"),
        "decided_by_name": user.get("name") or user.get("email"),
        "decided_at": now_iso(),
        "admin_note": (body.admin_note or "").strip(),
    }
    await db.punch_corrections.update_one({"id": cid}, {"$set": update})

    if body.decision == "approved":
        # Apply to a time_clock_entries row.
        target_id = req.get("target_entry_id")
        patch = {}
        if req.get("requested_clock_in"):
            patch["clock_in_at"] = req["requested_clock_in"]
        if req.get("requested_clock_out"):
            patch["clock_out_at"] = req["requested_clock_out"]
        if target_id:
            await db.time_clock_entries.update_one({"id": target_id}, {"$set": patch})
        elif patch:
            # Create a fresh entry — staff forgot to clock in/out entirely.
            row = {
                "id": str(uuid.uuid4()),
                "user_id": req["user_id"],
                "user_name": req["user_name"],
                "clock_in_at": patch.get("clock_in_at", ""),
                "clock_out_at": patch.get("clock_out_at", ""),
                "created_at": now_iso(),
                "corrected_via_request_id": cid,
            }
            await db.time_clock_entries.insert_one(row)

    req.update(update)
    return req


# ──────────── Staff trivia (no scoring, just learning) ────────────
@api.get("/employee/trivia/quiz")
async def employee_trivia_quiz(count: int = 5, _: dict = Depends(require_employee_or_admin)):
    """Adaptive practice quiz for staff. Same question pool as the client
    portal, but answering doesn't touch streaks/leaderboards — it's pure
    learning. Helps staff get smarter about breeds, behavior, training."""
    count = max(1, min(int(count), 10))
    ladder: List[str] = []
    for i in range(count):
        pct = i / max(1, count - 1)
        ladder.append("easy" if pct < 0.4 else "medium" if pct < 0.75 else "hard")
    out: List[dict] = []
    used: set = set()
    for diff in ladder:
        for filt in (
            {"active": True, "difficulty": diff, "id": {"$nin": list(used)}},
            {"active": True, "id": {"$nin": list(used)}},
        ):
            pool = await db.trivia_questions.find(filt, {"_id": 0}).limit(50).to_list(50)
            if pool:
                import random as _r
                q = _r.choice(pool)
                out.append(_strip_correct(q))
                used.add(q["id"])
                break
    return {"questions": out}


@api.post("/employee/trivia/answer")
async def employee_trivia_answer(body: TriviaAnswerIn, _: dict = Depends(require_employee_or_admin)):
    """Reveal the correct answer + the educational explanation, no scoring."""
    q = await db.trivia_questions.find_one({"id": body.question_id, "active": True}, {"_id": 0})
    if not q:
        raise HTTPException(status_code=404, detail="Question not found")
    return {
        "correct": body.chosen_index == q["correct_index"],
        "correct_index": q["correct_index"],
        "explanation": q.get("explanation") or "",
    }





# ────────────────────────── Expenses ──────────────────────────

EXPENSE_CATEGORY_DEFAULTS = [
    "Dog food / treats", "Cleaning supplies", "Training equipment", "Boarding supplies",
    "Daycare supplies", "Office supplies", "Advertising / marketing", "Software / apps",
    "Rent / facility", "Utilities", "Insurance", "Vehicle / mileage", "Repairs / maintenance",
    "Payroll / contract labor", "Merchant fees", "Bank fees", "Licenses / taxes", "Professional services", "Other",
]

MAX_EXPENSE_RECEIPT_BYTES = 2_600_000  # base64 data URL guard; keeps Mongo documents sane

def _clean_receipt_payload(data_url: Optional[str], filename: Optional[str]) -> Tuple[Optional[str], Optional[str]]:
    """Validate inline receipt payloads before saving.

    Frontend compresses images and limits PDFs, but backend keeps the final guard
    so a giant receipt cannot bloat MongoDB or break document updates.
    """
    data = (data_url or "").strip()
    name = (filename or "").strip()[:180]
    if not data:
        return None, None
    if not (data.startswith("data:image/") or data.startswith("data:application/pdf")):
        raise HTTPException(status_code=400, detail="Receipt must be an image or PDF data URL")
    if len(data.encode("utf-8")) > MAX_EXPENSE_RECEIPT_BYTES:
        raise HTTPException(status_code=400, detail="Receipt is too large. Please compress it below about 2.5 MB.")
    return data, (name or "receipt")

class ExpenseIn(BaseModel):
    date: str = Field(min_length=10, max_length=10)  # YYYY-MM-DD
    description: str = Field(min_length=1, max_length=200)
    amount: float = Field(ge=0)
    quantity: Optional[float] = Field(default=1, ge=0)
    unit_price: Optional[float] = Field(default=None, ge=0)
    category: Optional[str] = ""
    notes: Optional[str] = ""
    payment_method: Optional[Literal["cash", "card", "transfer", "venmo", "paypal", "check", "other"]] = "card"
    tax_deductible: Optional[bool] = True
    from_cash_drawer: Optional[bool] = False
    vendor: Optional[str] = ""
    recurring: Optional[bool] = False
    recurring_interval: Optional[Literal["weekly", "monthly", "quarterly", "yearly"]] = "monthly"
    # Sprint 110ap — optional photo/PDF/scan of the receipt for IRS audit
    # peace-of-mind. Stored inline as a base64 data URL (`data:image/jpeg;…`
    # or `data:application/pdf;…`). Front-end compresses images to <800kB
    # before upload; PDFs are passed through as-is up to ~2MB. Empty string
    # means no receipt on file.
    receipt_image: Optional[str] = ""
    receipt_filename: Optional[str] = ""


@api.get("/expenses")
async def list_expenses(
    _: dict = Depends(require_admin_and_permission("finance_reports")),
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
):
    """List expenses, optionally filtered to a date window. Newest first."""
    q: Dict[str, Any] = {}
    if start_date or end_date:
        q["date"] = {}
        if start_date:
            q["date"]["$gte"] = start_date
        if end_date:
            q["date"]["$lte"] = end_date
    cursor = db.expenses.find(q, {"_id": 0}).sort([("date", -1), ("created_at", -1)])
    return await cursor.to_list(2000)


@api.post("/expenses")
async def create_expense(body: ExpenseIn, user: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Log an out-of-pocket business expense (food, supplies, utilities, etc.).
    These flow into the Income screen's monthly/range view so you can see NET
    instead of just gross income."""
    await _require_register_day_open(body.date)
    receipt_image, receipt_filename = _clean_receipt_payload(body.receipt_image, body.receipt_filename)
    doc = {
        "id": str(uuid.uuid4()),
        "date": body.date,
        "description": body.description.strip(),
        "amount": round(float(body.amount), 2),
        "quantity": round(float(body.quantity or 1), 3),
        "unit_price": round(float(body.unit_price), 2) if body.unit_price is not None else None,
        "category": (body.category or "").strip(),
        "notes": (body.notes or "").strip(),
        "payment_method": _normalize_payment_method(body.payment_method, store=True),
        "tax_deductible": bool(body.tax_deductible),
        "from_cash_drawer": bool(body.from_cash_drawer),
        "vendor": (body.vendor or "").strip(),
        "recurring": bool(body.recurring),
        "recurring_interval": body.recurring_interval if body.recurring else None,
        "receipt_image": receipt_image,
        "receipt_filename": receipt_filename,
        "created_at": now_iso(),
        "created_by": user.get("id"),
    }
    # Strip None so we don't store empty receipt keys for legacy rows
    doc = {k: v for k, v in doc.items() if v is not None}
    await db.expenses.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.put("/expenses/{expense_id}")
async def update_expense(expense_id: str, body: ExpenseIn, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    existing = await db.expenses.find_one({"id": expense_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Expense not found")
    await _require_register_day_open(existing.get("date") or body.date)
    if body.date != existing.get("date"):
        await _require_register_day_open(body.date)
    patch = {
        "date": body.date,
        "description": body.description.strip(),
        "amount": round(float(body.amount), 2),
        "quantity": round(float(body.quantity or 1), 3),
        "unit_price": round(float(body.unit_price), 2) if body.unit_price is not None else None,
        "category": (body.category or "").strip(),
        "notes": (body.notes or "").strip(),
        "payment_method": _normalize_payment_method(body.payment_method, store=True),
        "tax_deductible": bool(body.tax_deductible),
        "from_cash_drawer": bool(body.from_cash_drawer),
        "vendor": (body.vendor or "").strip(),
        "recurring": bool(body.recurring),
        "recurring_interval": body.recurring_interval if body.recurring else None,
        "updated_at": now_iso(),
    }
    # Receipt is editable — empty string means "remove the receipt", non-empty
    # replaces it. We intentionally don't clobber an existing receipt when
    # `receipt_image` is omitted entirely (Pydantic default).
    if body.receipt_image is not None:
        receipt_image, receipt_filename = _clean_receipt_payload(body.receipt_image, body.receipt_filename)
        patch["receipt_image"] = receipt_image
        patch["receipt_filename"] = receipt_filename
        # Drop None values so Mongo's $set doesn't store explicit nulls
        if patch["receipt_image"] is None:
            patch.pop("receipt_image")
            patch.pop("receipt_filename", None)
            await db.expenses.update_one(
                {"id": expense_id},
                {"$unset": {"receipt_image": "", "receipt_filename": ""}},
            )
    await db.expenses.update_one({"id": expense_id}, {"$set": patch})
    return {**existing, **patch}


@api.delete("/expenses/{expense_id}")
async def delete_expense(expense_id: str, _: dict = Depends(require_admin_and_permission("delete_records"))):
    existing = await db.expenses.find_one({"id": expense_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Expense not found")
    await _require_register_day_open(existing.get("date") or business_today().isoformat())
    res = await db.expenses.delete_one({"id": expense_id})
    if res.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Expense not found")
    return {"ok": True}


@api.get("/expenses/categories")
async def expense_categories(_: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Default + previously used expense categories for consistent tax cleanup."""
    cats = await db.expenses.distinct("category")
    merged = sorted(set(EXPENSE_CATEGORY_DEFAULTS + [c for c in cats if c]))
    return {"categories": merged, "defaults": EXPENSE_CATEGORY_DEFAULTS}


# ────────────────────────── Retail Sales ──────────────────────────
# User has an external POS for actual checkout. This is just a lightweight
# revenue ledger so retail $$ flows into the same Income / P&L tally as
# services. No inventory, no checkout, no tax math — just a row per sale.
class RetailSaleIn(BaseModel):
    date: str = Field(min_length=10, max_length=10)  # YYYY-MM-DD
    description: str = Field(min_length=1, max_length=200)
    amount: float = Field(ge=0)
    # Sprint 110dq — Register/POS quantity support. Amount stays the money
    # source of truth, but quantity + unit_price are saved for receipts/audit
    # so a sale can say "2 × leash @ $12.99" instead of just one lump sum.
    quantity: Optional[float] = Field(default=1, ge=0)
    unit_price: Optional[float] = Field(default=None, ge=0)
    category: Optional[str] = ""
    notes: Optional[str] = ""
    payment_method: Optional[Literal["cash", "card", "transfer", "venmo", "paypal", "check", "credits", "other"]] = "card"
    client_id: Optional[str] = None  # optional — link a sale to a specific client
    # Sprint 110aw — Sales tax. If true, `amount` is the TOTAL the customer
    # paid (incl. tax) and the backend back-calculates the tax slice. If false
    # or absent, the line is tax-exempt (e.g. a wholesale item).
    apply_tax: Optional[bool] = None
    # Sprint 110di-61 — Partial-pay support for retail. When provided AND
    # less than `amount`, the difference goes onto the client's running tab
    # (account_balance) and today's revenue records ONLY the amount paid
    # (cash-basis recognition — option 1c). Requires `client_id` to be set
    # (no tab without a client to attach it to).
    amount_paid: Optional[float] = Field(default=None, ge=0)


@api.get("/retail-sales")
async def list_retail_sales(
    _: dict = Depends(require_admin_and_permission("finance_reports")),
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
):
    """List retail sales, optionally filtered to a date window. Newest first."""
    q: Dict[str, Any] = {}
    if start_date or end_date:
        q["date"] = {}
        if start_date:
            q["date"]["$gte"] = start_date
        if end_date:
            q["date"]["$lte"] = end_date
    cursor = db.retail_sales.find(q, {"_id": 0}).sort([("date", -1), ("created_at", -1)])
    return await cursor.to_list(2000)


async def _build_retail_sale_doc(
    *, date: str, description: str, amount: float, quantity: float = 1,
    unit_price: Optional[float] = None, category: str = "", notes: str = "",
    payment_method: str, client_id: Optional[str] = None, client_name: str = "",
    created_by: Optional[str] = None, apply_tax: Optional[bool] = None,
    precomputed_tax: Optional[dict] = None,
) -> dict:
    """Builds one retail_sales document — the single accounting entry point
    for retail-style revenue, used by both the manual retail-sale form and
    the Front Desk POS register (§ front-desk POS). Does NOT insert it.

    `precomputed_tax`, when given (e.g. from _price_pos_cart, which computes
    tax as an addition on top of pre-tax line prices — the normal register
    convention), is trusted as-is. When omitted, falls back to the original
    behavior: treat `amount` as tax-INCLUSIVE and back out the tax slice —
    preserved byte-for-byte for the existing manual retail-sale form so nothing
    about its accounting changes."""
    doc = {
        "id": str(uuid.uuid4()),
        "date": date,
        "description": description.strip(),
        "amount": round(float(amount), 2),
        "quantity": round(float(quantity or 1), 3),
        "unit_price": round(float(unit_price), 2) if unit_price is not None else None,
        "category": (category or "").strip(),
        "notes": (notes or "").strip(),
        "payment_method": payment_method,
        "client_id": client_id or None,
        "client_name": client_name,
        "created_at": now_iso(),
        "created_by": created_by,
    }
    if precomputed_tax is not None:
        if float(precomputed_tax.get("tax_amount") or 0) > 0.005:
            doc["tax_amount"] = round(float(precomputed_tax["tax_amount"]), 2)
            doc["tax_rate_pct"] = float(precomputed_tax.get("tax_rate_pct") or 0)
            doc["pre_tax_amount"] = round(
                float(precomputed_tax.get("pre_tax_amount") if precomputed_tax.get("pre_tax_amount") is not None
                      else doc["amount"] - doc["tax_amount"]), 2,
            )
    else:
        # Sprint 110aw — Tax breakout. When sales_tax is enabled, retail is
        # tax-applicable by default (unless the row explicitly says otherwise).
        try:
            settings_tx = await get_settings()
            tx_cfg = (settings_tx or {}).get("sales_tax") or {}
            if tx_cfg.get("enabled") and float(tx_cfg.get("rate_pct") or 0) > 0:
                applies = (tx_cfg.get("applies_to") or {})
                should_tax = apply_tax if apply_tax is not None else applies.get("retail", True)
                if should_tax:
                    rate_pct = float(tx_cfg["rate_pct"])
                    # Treat `amount` as TOTAL incl. tax (matches a typical POS receipt).
                    total = doc["amount"]
                    pre_tax = round(total / (1 + rate_pct / 100.0), 2)
                    doc["tax_amount"] = round(total - pre_tax, 2)
                    doc["tax_rate_pct"] = rate_pct
                    doc["pre_tax_amount"] = pre_tax
        except Exception as exc:
            logger.warning("retail tax calc failed: %s", exc)
    return doc


@api.post("/retail-sales")
async def create_retail_sale(body: RetailSaleIn, user: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Log a retail sale (treats, leash, food bag, etc.) from your external POS.
    Flows into the Income screen + P&L PDF alongside service revenue."""
    await _require_register_day_open(body.date)
    client_name = ""
    if body.client_id:
        c = await db.clients.find_one({"id": body.client_id}, {"_id": 0, "name": 1})
        if c:
            client_name = c.get("name") or ""
    doc = await _build_retail_sale_doc(
        date=body.date, description=body.description, amount=body.amount, quantity=body.quantity,
        unit_price=body.unit_price, category=body.category, notes=body.notes,
        payment_method=_normalize_payment_method(body.payment_method, store=True),
        client_id=body.client_id, client_name=client_name, created_by=user.get("id"),
        apply_tax=body.apply_tax,
    )
    # Sprint 110di-61 — Partial-pay branch for retail (cash-basis option 1c).
    # When `amount_paid` is provided AND < the ticket amount AND we have a
    # client to attach the tab to, the unpaid remainder lands on the client's
    # balance and the recorded retail-sale `amount` is reduced to what was
    # actually paid (so today's income reflects cash received).
    full_amount = doc["amount"]
    is_partial = (
        body.amount_paid is not None
        and full_amount > 0
        and body.client_id
        and abs(float(body.amount_paid) - full_amount) > 0.005
    )
    if is_partial:
        revenue_today = max(0.0, min(float(body.amount_paid), full_amount))
        await _apply_sale_partial_payment(
            client_id=body.client_id,
            total=full_amount,
            paid=float(body.amount_paid),
            sale_kind="retail",
            sale_id=doc["id"],
            label=f"Retail · {doc['description']}",
            method=_normalize_payment_method(body.payment_method, store=True),
        )
        # Rewrite the cash-side fields to only count today's actual payment.
        doc["amount"] = round(revenue_today, 2)
        doc["full_ticket_amount"] = round(full_amount, 2)  # audit trail
        doc["partial_pay"] = True
        # Recompute tax slice against the actual cash received (pre-tax + tax
        # ratios stay proportional).
        if "tax_amount" in doc and full_amount > 0:
            ratio = revenue_today / full_amount
            doc["tax_amount"] = round(doc["tax_amount"] * ratio, 2)
            doc["pre_tax_amount"] = round(doc["pre_tax_amount"] * ratio, 2)
    await db.retail_sales.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.put("/retail-sales/{sale_id}")
async def update_retail_sale(sale_id: str, body: RetailSaleIn, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    existing = await db.retail_sales.find_one({"id": sale_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Retail sale not found")
    await _require_register_day_open(existing.get("date") or body.date)
    if body.date != existing.get("date"):
        await _require_register_day_open(body.date)
    client_name = existing.get("client_name") or ""
    if body.client_id and body.client_id != existing.get("client_id"):
        c = await db.clients.find_one({"id": body.client_id}, {"_id": 0, "name": 1})
        client_name = (c or {}).get("name") or ""
    elif not body.client_id:
        client_name = ""
    patch = {
        "date": body.date,
        "description": body.description.strip(),
        "amount": round(float(body.amount), 2),
        "quantity": round(float(body.quantity or 1), 3),
        "unit_price": round(float(body.unit_price), 2) if body.unit_price is not None else None,
        "category": (body.category or "").strip(),
        "notes": (body.notes or "").strip(),
        "payment_method": _normalize_payment_method(body.payment_method, store=True),
        "client_id": body.client_id or None,
        "client_name": client_name,
        "updated_at": now_iso(),
    }
    await db.retail_sales.update_one({"id": sale_id}, {"$set": patch})
    return {**existing, **patch}


@api.delete("/retail-sales/{sale_id}")
async def delete_retail_sale(sale_id: str, _: dict = Depends(require_admin_and_permission("delete_records"))):
    existing = await db.retail_sales.find_one({"id": sale_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Retail sale not found")
    await _require_register_day_open(existing.get("date") or business_today().isoformat())
    res = await db.retail_sales.delete_one({"id": sale_id})
    if res.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Retail sale not found")
    return {"ok": True}


@api.get("/retail-sales/categories")
async def retail_sale_categories(_: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Unique category strings seen so far — used to power autocomplete."""
    cats = await db.retail_sales.distinct("category")
    cats = sorted([c for c in cats if c])
    return {"categories": cats}


# ──────────────────────── Legacy Pricing (per-client price overrides) ──────────
# Sprint 110am — Some clients are grandfathered into the OLD prices when an
# admin raises the public rate. We never modify the catalog row itself —
# instead each grandfathered client gets one row per (target_kind, target_code)
# with the locked rate and an optional expiry date. Booking creation +
# credit-pack purchase + check-out price-resolution all consult this table
# server-side, so the client portal / public booking flow can never bypass it
# even if the catalog later shows a different number.


class PriceOverrideIn(BaseModel):
    target_kind: Literal["service", "credit_pack", "pos_product"]
    # The catalog row's `id` (uuid). Stable across rename and price edits, so
    # an override survives even if the admin renames "Daycare" later.
    target_code: str = Field(min_length=1)
    override_price: float = Field(ge=0)
    # ISO date `YYYY-MM-DD`. Empty / null = applies immediately.
    starts_on: Optional[str] = None
    # ISO date `YYYY-MM-DD`. Empty / null = grandfathered forever.
    expires_on: Optional[str] = None
    note: Optional[str] = ""


class PriceOverridePatch(BaseModel):
    override_price: Optional[float] = Field(default=None, ge=0)
    starts_on: Optional[str] = None
    expires_on: Optional[str] = None
    note: Optional[str] = None


class PriceOverrideRevokeIn(BaseModel):
    reason: Optional[str] = ""


def _override_is_active(row: dict, today: Optional[date] = None) -> bool:
    """Compatibility facade for canonical pricing lifecycle rules."""
    return pricing_domain_services.override_is_active(row, today)


async def _count_active_overrides_for_target(target_kind: str, target_code: str) -> int:
    """How many clients currently have an ACTIVE (not expired, not revoked)
    price override attached to this exact catalog item — used to warn an
    admin before deleting/deactivating it, never to block silently."""
    rows = await db.price_overrides.find(
        {"target_kind": target_kind, "target_code": target_code}, {"_id": 0},
    ).to_list(1000)
    return sum(1 for r in rows if _override_is_active(r))


def _override_status_label(row: dict) -> str:
    """Plain-language status for the admin UI — never just a raw boolean."""
    row = row or {}
    if row.get("status") == "revoked":
        return "Revoked"
    today = business_today()
    starts = row.get("starts_on")
    if starts:
        try:
            if date.fromisoformat(starts) > today:
                return f"Starts {starts}"
        except Exception:
            pass
    exp = row.get("expires_on")
    if exp:
        if _override_is_active(row):
            return f"Expires on {exp}"
        return "Expired"
    return "Active"


def _price_override_precedence_key(row: dict) -> tuple:
    """Compatibility facade for canonical pricing precedence."""
    return pricing_domain_services.price_override_precedence_key(row)


def _pick_applicable_price_override(
    rows: List[Dict[str, Any]], today: Optional[date] = None,
) -> Optional[Dict[str, Any]]:
    """Compatibility facade for canonical pricing-history selection."""
    return pricing_domain_services.pick_applicable_price_override(rows, today)


async def _apply_client_overrides(
    items: List[Dict[str, Any]],
    client_id: Optional[str],
    target_kind: str,  # "service" or "credit_pack"
    price_field: str,  # "base_price" for services, "price" for credit_packs
) -> List[Dict[str, Any]]:
    """Sprint 110bv — bulk-rewrite catalog prices to a client's locked-in
    legacy rates. Used by `/services` and `/credit-packs` so a grandfathered
    client never sees the new catalog price in the portal.

    Mutates each item in place:
      - adds `legacy_price` = original list price (so the UI can show "was $X")
      - adds `has_legacy_override = True` when this client has an active row
      - overwrites `price_field` with the override price
    Items without an active override are returned unchanged.
    """
    if not client_id or not items:
        return items
    codes = [str(it.get("id") or it.get("code") or "")
             for it in items if it.get("id") or it.get("code")]
    if not codes:
        return items
    rows = await db.price_overrides.find(
        {"client_id": client_id, "target_kind": target_kind, "target_code": {"$in": codes}},
        {"_id": 0, "target_code": 1, "override_price": 1, "expires_on": 1, "id": 1},
    ).to_list(500)
    overrides_by_code: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        if _override_is_active(row):
            overrides_by_code[row["target_code"]] = row
    for it in items:
        code = str(it.get("id") or it.get("code") or "")
        ovr = overrides_by_code.get(code)
        if not ovr:
            continue
        list_price = float(it.get(price_field) or 0)
        it["legacy_price"] = list_price
        it["has_legacy_override"] = True
        it[price_field] = float(ovr.get("override_price") or 0)
    return items



async def resolve_client_price(
    client_id: Optional[str], target_kind: str, target_code: str, list_price: float,
) -> dict:
    """Compatibility facade for the canonical Phase-5 pricing resolver."""
    return await pricing_domain_services.resolve_client_price(
        client_id, target_kind, target_code, list_price
    )


async def resolve_addon_snapshots(
    client_id: Optional[str], addon_service_ids: List[str], base_service_type: str,
) -> List[Dict[str, Any]]:
    """Compatibility facade for canonical add-on pricing snapshots."""
    return await pricing_domain_services.resolve_addon_snapshots(
        client_id, addon_service_ids, base_service_type
    )


async def list_client_price_overrides(client_id: str, _: dict = Depends(require_admin_and_permission("pricing")), include_expired: bool = False):
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    rows = await db.price_overrides.find({"client_id": client_id}, {"_id": 0}).to_list(500)
    if not include_expired:
        rows = [r for r in rows if _override_is_active(r)]
    # Enrich with the catalog row so the UI can show "Daycare · was $35 → now $30"
    svc_codes = [r["target_code"] for r in rows if r["target_kind"] == "service"]
    pack_ids = [r["target_code"] for r in rows if r["target_kind"] == "credit_pack"]
    product_ids = [r["target_code"] for r in rows if r["target_kind"] == "pos_product"]
    svcs = {s["id"]: s for s in await db.services.find({"id": {"$in": svc_codes}}, {"_id": 0}).to_list(500)} if svc_codes else {}
    packs = {p["id"]: p for p in await db.credit_packs.find({"id": {"$in": pack_ids}}, {"_id": 0}).to_list(500)} if pack_ids else {}
    products = {p["id"]: p for p in await db.pos_products.find({"id": {"$in": product_ids}}, {"_id": 0}).to_list(500)} if product_ids else {}
    for r in rows:
        if r["target_kind"] == "service":
            s = svcs.get(r["target_code"])
            r["target_name"] = (s or {}).get("name") or r["target_code"]
            r["list_price"] = float((s or {}).get("base_price") or 0)
        elif r["target_kind"] == "credit_pack":
            p = packs.get(r["target_code"])
            r["target_name"] = (p or {}).get("name") or r["target_code"]
            r["list_price"] = float((p or {}).get("price") or 0)
        else:
            pr = products.get(r["target_code"])
            r["target_name"] = (pr or {}).get("name") or r["target_code"]
            r["list_price"] = float((pr or {}).get("price") or 0)
        r["active"] = _override_is_active(r)
        r["savings"] = round(r["list_price"] - float(r["override_price"]), 2)
        r["status_label"] = _override_status_label(r)
        r.setdefault("status", "active")
        r.setdefault("revoked_at", None)
        r.setdefault("revoked_by", None)
        r.setdefault("revocation_reason", None)
    rows.sort(key=lambda r: (not r["active"], r["target_kind"], r["target_name"]))
    return {"overrides": rows}


async def client_credit_pack_prices(client_id: str, _: dict = Depends(require_admin_and_permission("sell_credits"))):
    """Effective credit-pack prices for ONE client, straight from
    resolve_client_price — the same resolver the sell endpoints charge with.
    Exists so the sell-packs UI can show the number the client will actually
    pay (individual override or tier price) instead of the public list price.
    Gated by sell_credits (not `pricing`) so anyone allowed to sell packs can
    see the price they are about to charge."""
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    packs = await db.credit_packs.find({"active": True}, {"_id": 0, "id": 1, "price": 1}).to_list(200)
    out = {}
    for pack in packs:
        pricing = await resolve_client_price(client_id, "credit_pack", pack["id"], float(pack.get("price") or 0))
        out[pack["id"]] = {
            "list_price": pricing["list_price"],
            "effective_price": pricing["effective_price"],
            "pricing_source": pricing["pricing_source"],
            "tier_name": pricing["tier_name"],
        }
    return {"prices": out}


@api.get("/clients/{client_id}/service-prices")
async def client_service_prices(client_id: str, _: dict = Depends(require_employee_or_admin)):
    """Effective per-SERVICE prices for ONE client, straight from
    resolve_client_price — the exact sibling of client_credit_pack_prices
    above, for the booking/check-in screens instead of the sell-packs one.

    Quick Check-In needs this because an individual client price is keyed to
    ONE exact `services.id`, while Quick Check-In picks the service for the
    operator. If it picks the catalogue default when the client's rate lives
    on a different service of the same type, the resolver correctly finds no
    override and the walk-in rings at full price. Knowing WHICH service
    carries the client's price is what lets the picker choose the right one.

    Read-only, and deliberately not a second pricing formula: every number
    here is resolve_client_price's own answer. The frontend uses it to choose
    a service IDENTITY; what the client actually pays is still decided
    server-side at quote, booking and checkout.

    Gated by employee-or-admin rather than the `pricing` permission: anyone
    allowed to check a dog in needs to see the price they are about to
    charge, exactly as sell_credits gates the credit-pack twin.
    """
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    services = await db.services.find(
        {"active": True, "is_addon": {"$ne": True}},
        {"_id": 0, "id": 1, "name": 1, "service_type": 1, "base_price": 1, "is_default": 1},
    ).to_list(500)
    out = {}
    for svc in services:
        pricing = await resolve_client_price(
            client_id, "service", svc["id"], float(svc.get("base_price") or 0))
        out[svc["id"]] = {
            "service_id": svc["id"],
            "service_name": svc.get("name"),
            "service_type": svc.get("service_type"),
            "is_default": bool(svc.get("is_default")),
            "list_price": pricing["list_price"],
            "effective_price": pricing["effective_price"],
            "pricing_source": pricing["pricing_source"],
            "override_id": pricing["override_id"],
            "tier_name": pricing["tier_name"],
        }
    return {"prices": out}


async def create_client_price_override(client_id: str, body: PriceOverrideIn, user: dict = Depends(require_admin_and_permission("pricing"))):
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1, "name": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    # Validate the catalog item exists so we don't accumulate orphan overrides
    if body.target_kind == "service":
        target = await db.services.find_one({"id": body.target_code}, {"_id": 0, "name": 1, "base_price": 1})
    elif body.target_kind == "credit_pack":
        target = await db.credit_packs.find_one({"id": body.target_code}, {"_id": 0, "name": 1, "price": 1})
    else:
        target = await db.pos_products.find_one({"id": body.target_code}, {"_id": 0, "name": 1, "price": 1, "sales_destination": 1})
    if not target:
        raise HTTPException(status_code=404, detail=f"Unknown {body.target_kind} `{body.target_code}`")
    if body.target_kind == "pos_product" and target.get("sales_destination") == "shopify_external":
        raise HTTPException(
            status_code=400,
            detail="Client-specific pricing can't be applied to Shopify-linked merchandise — Shopify controls that price.",
        )
    # Light date validation
    if body.starts_on:
        try:
            date.fromisoformat(body.starts_on)
        except Exception:
            raise HTTPException(status_code=422, detail="starts_on must be YYYY-MM-DD or empty")
    if body.expires_on:
        try:
            date.fromisoformat(body.expires_on)
        except Exception:
            raise HTTPException(status_code=422, detail="expires_on must be YYYY-MM-DD or empty")
    if body.starts_on and body.expires_on and body.starts_on > body.expires_on:
        raise HTTPException(status_code=422, detail="starts_on must be on or before expires_on")
    # One ACTIVE override per (client, kind, code) — enforced both here and
    # by _ensure_price_overrides_active_unique_index()'s partial unique
    # index. If the only existing row for this key was explicitly revoked,
    # that row's audit trail (revoked_at/revoked_by/revocation_reason) is
    # preserved as history and a FRESH row is inserted for the new price —
    # never resurrected in place, which would erase why the old one ended.
    # If the existing row is still active (or predates the revoke feature
    # and has no status at all), this remains the original upsert-in-place
    # behavior: editing an active override's price is just an edit, not a
    # new lifecycle.
    # Do not use an unrestricted find_one here either. Once a client has
    # returned an item to standard price, retained revoked history may be the
    # oldest/natural-order row even while a newer active row also exists.
    # Editing the price must update that live row, not try to insert a second
    # active row and trip the uniqueness index.
    existing_rows = await db.price_overrides.find(
        {"client_id": client_id, "target_kind": body.target_kind, "target_code": body.target_code},
        {"_id": 0},
    ).to_list(500)
    non_revoked_rows = [r for r in existing_rows if r.get("status") != "revoked"]
    existing = max(non_revoked_rows, key=_price_override_precedence_key) if non_revoked_rows else None
    ts = now_iso()
    reuse_existing_row = bool(existing)
    doc = {
        "id": existing["id"] if reuse_existing_row else str(uuid.uuid4()),
        "client_id": client_id,
        "target_kind": body.target_kind,
        "target_code": body.target_code,
        "override_price": float(body.override_price),
        "starts_on": body.starts_on or None,
        "expires_on": body.expires_on or None,
        "note": (body.note or "").strip(),
        "status": "active",
        "revoked_at": None,
        "revoked_by": None,
        "revocation_reason": None,
        "created_by": user.get("name", "Admin"),
        "created_at": existing.get("created_at") if reuse_existing_row and existing.get("created_at") else ts,
        "updated_at": ts,
    }
    if reuse_existing_row:
        await db.price_overrides.update_one(
            {"client_id": client_id, "target_kind": body.target_kind, "target_code": body.target_code,
             "id": existing["id"]},
            {"$set": doc},
        )
    else:
        try:
            await db.price_overrides.insert_one(doc.copy())
        except DuplicateKeyError:
            raise HTTPException(
                status_code=409,
                detail="This client already has an active price for this item — edit the existing override or return it to standard price first.",
            )
    doc.pop("_id", None)
    return doc


class BulkPriceOverrideEntry(BaseModel):
    target_kind: Literal["service", "credit_pack", "pos_product"]
    target_code: str = Field(min_length=1)
    override_price: float = Field(ge=0)
    expires_on: Optional[str] = None


class BulkPriceOverrideIn(BaseModel):
    entries: List[BulkPriceOverrideEntry] = Field(min_length=1, max_length=100)
    note: Optional[str] = ""


async def bulk_apply_client_price_overrides(client_id: str, body: BulkPriceOverrideIn, user: dict = Depends(require_admin_and_permission("pricing"))):
    """"Apply pricing set" — an admin convenience for setting several exact
    final prices for one client in one action. Deliberately reuses
    create_client_price_override() per entry rather than a new bulk-write
    path, so every safety check it already performs (item exists, date
    validation, active-override upsert-vs-insert-new-row semantics, the
    active-unique-index guard) applies identically here — no second pricing
    formula, no shortcut. Never partially-transactional (this codebase uses
    no Mongo transactions anywhere): each entry either succeeds or is
    reported as an individual error, so one bad row in a large set never
    silently discards the rest."""
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    applied: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []
    for entry in body.entries:
        try:
            single = PriceOverrideIn(
                target_kind=entry.target_kind, target_code=entry.target_code,
                override_price=entry.override_price, expires_on=entry.expires_on, note=body.note or "",
            )
            result = await create_client_price_override(client_id, single, user)
            applied.append(result)
        except HTTPException as exc:
            errors.append({"target_kind": entry.target_kind, "target_code": entry.target_code, "detail": exc.detail})
    return {"applied": len(applied), "overrides": applied, "errors": errors}


async def update_price_override(override_id: str, body: PriceOverridePatch, _: dict = Depends(require_admin_and_permission("pricing"))):
    row = await db.price_overrides.find_one({"id": override_id}, {"_id": 0})
    if not row:
        raise HTTPException(status_code=404, detail="Override not found")
    if row.get("status") == "revoked":
        raise HTTPException(status_code=409, detail="This override has been revoked — create a new one instead of editing it.")
    patch: Dict[str, Any] = {"updated_at": now_iso()}
    if body.override_price is not None:
        patch["override_price"] = float(body.override_price)
    if body.starts_on is not None:
        if body.starts_on == "":
            patch["starts_on"] = None
        else:
            try:
                date.fromisoformat(body.starts_on)
            except Exception:
                raise HTTPException(status_code=422, detail="starts_on must be YYYY-MM-DD or empty")
            patch["starts_on"] = body.starts_on
    if body.expires_on is not None:
        if body.expires_on == "":
            patch["expires_on"] = None
        else:
            try:
                date.fromisoformat(body.expires_on)
            except Exception:
                raise HTTPException(status_code=422, detail="expires_on must be YYYY-MM-DD or empty")
            patch["expires_on"] = body.expires_on
    if body.note is not None:
        patch["note"] = body.note.strip()
    await db.price_overrides.update_one({"id": override_id}, {"$set": patch})
    return {**row, **patch}


async def delete_price_override(override_id: str, body: Optional[PriceOverrideRevokeIn] = None, user: dict = Depends(require_admin_and_permission("pricing"))):
    """"Return to standard price" — NEVER a hard delete. The override row
    (and its history) is preserved; only its status flips to revoked, so
    every booking/order/payment/receipt/credit lot that already used this
    price is completely unaffected, and future purchases immediately fall
    back to the current public price."""
    row = await db.price_overrides.find_one({"id": override_id}, {"_id": 0})
    if not row:
        raise HTTPException(status_code=404, detail="Override not found")
    if row.get("status") == "revoked":
        return {"ok": True, "deleted": 0, "already_revoked": True}
    await db.price_overrides.update_one({"id": override_id}, {"$set": {
        "status": "revoked",
        "revoked_at": now_iso(),
        "revoked_by": user.get("name", "Admin"),
        "revocation_reason": ((body.reason if body else "") or "").strip(),
        "updated_at": now_iso(),
    }})
    return {"ok": True, "deleted": 1, "revoked": True}


# ──────────────────────────── Pricing Tiers ────────────────────────────────
# Grandfathered pricing groups (e.g. "Founding Clients") — a lightweight
# reusable alternative to entering the SAME override on every client
# individually. Reuses the exact same resolve_client_price() precedence
# every other special-pricing path already goes through (see that
# function's docstring): individual override > tier price > standard.
# Deliberately no hard-delete for a tier — only deactivate — so a past
# order's `pricing_tier_name` snapshot always has something real behind it.


class PricingTierIn(BaseModel):
    name: str = Field(min_length=1, max_length=80)


class PricingTierPatch(BaseModel):
    name: Optional[str] = Field(default=None, min_length=1, max_length=80)
    active: Optional[bool] = None


class PricingTierPriceIn(BaseModel):
    target_kind: Literal["service", "credit_pack", "pos_product"]
    target_code: str = Field(min_length=1)
    override_price: float = Field(ge=0)


async def _pricing_tier_target_name(target_kind: str, target_code: str) -> Optional[str]:
    if target_kind == "service":
        t = await db.services.find_one({"id": target_code}, {"_id": 0, "name": 1})
    elif target_kind == "credit_pack":
        t = await db.credit_packs.find_one({"id": target_code}, {"_id": 0, "name": 1})
    else:
        t = await db.pos_products.find_one({"id": target_code}, {"_id": 0, "name": 1})
    return (t or {}).get("name")


async def list_pricing_tiers(_: dict = Depends(require_admin_and_permission("pricing")), include_inactive: bool = True):
    q: Dict[str, Any] = {} if include_inactive else {"active": True}
    tiers = await db.pricing_tiers.find(q, {"_id": 0}).sort("name", 1).to_list(200)
    tier_ids = [t["id"] for t in tiers]
    client_counts: Dict[str, int] = {}
    if tier_ids:
        async for row in db.clients.aggregate([
            {"$match": {"pricing_tier_id": {"$in": tier_ids}}},
            {"$group": {"_id": "$pricing_tier_id", "n": {"$sum": 1}}},
        ]):
            client_counts[row["_id"]] = row["n"]
    price_counts: Dict[str, int] = {}
    if tier_ids:
        async for row in db.pricing_tier_prices.aggregate([
            {"$match": {"tier_id": {"$in": tier_ids}}},
            {"$group": {"_id": "$tier_id", "n": {"$sum": 1}}},
        ]):
            price_counts[row["_id"]] = row["n"]
    for t in tiers:
        t["client_count"] = client_counts.get(t["id"], 0)
        t["priced_item_count"] = price_counts.get(t["id"], 0)
    return {"tiers": tiers}


async def create_pricing_tier(body: PricingTierIn, user: dict = Depends(require_admin_and_permission("pricing"))):
    doc = {
        "id": str(uuid.uuid4()),
        "name": body.name.strip(),
        "active": True,
        "created_at": now_iso(),
        "created_by": user.get("name") or user.get("email") or "Admin",
        "updated_at": now_iso(),
    }
    await db.pricing_tiers.insert_one(doc.copy())
    doc.pop("_id", None)
    return doc


async def get_pricing_tier(tier_id: str, _: dict = Depends(require_admin_and_permission("pricing"))):
    tier = await db.pricing_tiers.find_one({"id": tier_id}, {"_id": 0})
    if not tier:
        raise HTTPException(status_code=404, detail="Pricing tier not found")
    clients = await db.clients.find(
        {"pricing_tier_id": tier_id}, {"_id": 0, "id": 1, "name": 1, "email": 1},
    ).sort("name", 1).to_list(2000)
    prices = await db.pricing_tier_prices.find({"tier_id": tier_id}, {"_id": 0}).to_list(1000)
    for p in prices:
        p["target_name"] = await _pricing_tier_target_name(p["target_kind"], p["target_code"])
    tier["clients"] = clients
    tier["client_count"] = len(clients)
    tier["prices"] = prices
    return tier


async def update_pricing_tier(tier_id: str, body: PricingTierPatch, user: dict = Depends(require_admin_and_permission("pricing"))):
    """Rename and/or activate/deactivate. Deactivating a tier stops it from
    applying to ANY client assigned to it (resolve_client_price checks
    `pricing_tiers.active`) without unassigning anyone or deleting its
    priced items — flip it back on and everything resumes exactly as it
    was, with zero re-entry."""
    tier = await db.pricing_tiers.find_one({"id": tier_id}, {"_id": 0})
    if not tier:
        raise HTTPException(status_code=404, detail="Pricing tier not found")
    patch: Dict[str, Any] = {"updated_at": now_iso()}
    if body.name is not None:
        patch["name"] = body.name.strip()
    if body.active is not None:
        patch["active"] = body.active
    await db.pricing_tiers.update_one({"id": tier_id}, {"$set": patch})
    return {**tier, **patch}


async def assign_client_to_pricing_tier(tier_id: str, client_id: str, user: dict = Depends(require_admin_and_permission("pricing"))):
    """Intentional, one-at-a-time assignment only — clients are never
    auto-enrolled into a tier. Overwrites any PREVIOUS tier assignment
    (a client has at most one normal pricing tier at a time), which is a
    deliberate admin action here, never an accidental side effect of
    anything else."""
    tier = await db.pricing_tiers.find_one({"id": tier_id}, {"_id": 0, "id": 1})
    if not tier:
        raise HTTPException(status_code=404, detail="Pricing tier not found")
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1, "pricing_tier_id": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    previous_tier_id = client.get("pricing_tier_id")
    await db.clients.update_one({"id": client_id}, {"$set": {"pricing_tier_id": tier_id, "updated_at": now_iso()}})
    return {"ok": True, "client_id": client_id, "tier_id": tier_id, "previous_tier_id": previous_tier_id}


async def unassign_client_from_pricing_tier(tier_id: str, client_id: str, user: dict = Depends(require_admin_and_permission("pricing"))):
    """Only clears the assignment if the client is CURRENTLY on this exact
    tier — refuses to silently clear a different tier a stale UI might be
    pointed at."""
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "id": 1, "pricing_tier_id": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    if client.get("pricing_tier_id") != tier_id:
        raise HTTPException(status_code=409, detail="This client is not currently assigned to this pricing tier.")
    await db.clients.update_one({"id": client_id}, {"$set": {"pricing_tier_id": None, "updated_at": now_iso()}})
    return {"ok": True}


async def set_pricing_tier_price(tier_id: str, body: PricingTierPriceIn, user: dict = Depends(require_admin_and_permission("pricing"))):
    tier = await db.pricing_tiers.find_one({"id": tier_id}, {"_id": 0, "id": 1})
    if not tier:
        raise HTTPException(status_code=404, detail="Pricing tier not found")
    target_name = await _pricing_tier_target_name(body.target_kind, body.target_code)
    if not target_name:
        raise HTTPException(status_code=404, detail=f"Unknown {body.target_kind} `{body.target_code}`")
    if body.target_kind == "pos_product":
        product = await db.pos_products.find_one({"id": body.target_code}, {"_id": 0, "sales_destination": 1})
        if product and product.get("sales_destination") == "shopify_external":
            raise HTTPException(
                status_code=400,
                detail="Pricing tiers can't be applied to Shopify-linked merchandise — Shopify controls that price.",
            )
    existing = await db.pricing_tier_prices.find_one(
        {"tier_id": tier_id, "target_kind": body.target_kind, "target_code": body.target_code}, {"_id": 0},
    )
    ts = now_iso()
    doc = {
        "id": existing["id"] if existing else str(uuid.uuid4()),
        "tier_id": tier_id,
        "target_kind": body.target_kind,
        "target_code": body.target_code,
        "override_price": float(body.override_price),
        "created_by": user.get("name") or user.get("email") or "Admin",
        "created_at": existing.get("created_at") if existing else ts,
        "updated_at": ts,
    }
    await db.pricing_tier_prices.update_one(
        {"tier_id": tier_id, "target_kind": body.target_kind, "target_code": body.target_code},
        {"$set": doc}, upsert=True,
    )
    doc["target_name"] = target_name
    return doc


async def remove_pricing_tier_price(tier_id: str, price_id: str, user: dict = Depends(require_admin_and_permission("pricing"))):
    res = await db.pricing_tier_prices.delete_one({"id": price_id, "tier_id": tier_id})
    if res.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Tier price not found")
    return {"ok": True}


# ────────────────────────── Credit Packs + FIFO Lots ──────────────────────────
from credit_packs_data import SEED_CREDIT_PACKS


class CreditPackIn(BaseModel):
    slug: Optional[str] = ""
    name: str = Field(min_length=1)
    qty: int = Field(ge=1)
    price: float = Field(ge=0)
    service_type: Optional[str] = "daycare"
    icon: Optional[str] = ""
    color: Optional[str] = ""
    active: bool = True
    active: bool = True
    # Sprint 110di-62 — Auto-fire email template slug on pack sale.
    welcome_email_template_slug: Optional[str] = None
    # Client Shop Phase 1 — additive online-visibility fields. qty/price/
    # service_type remain the one authoritative pack definition either way.
    available_online: bool = False
    online_description: Optional[str] = None
    image_id: Optional[str] = None
    # Shop Organization (Phase 1) — purely organizational, never affects
    # pricing, credit quantity, or the pack's own resolver-driven price.
    category_id: Optional[str] = None
    subcategory_id: Optional[str] = None
    # Shop Manager unification — independent from `active`; see the
    # identical field on PosProductIn for the full rationale. Defaults True
    # so every existing pack keeps appearing in the sell-pack picker.
    show_at_register: bool = True
    featured: bool = False
    # Front Desk checkout integrity audit — per-item taxable configuration.
    # Defaults False (prepaid visit credits are a service, not a taxed
    # retail good in most jurisdictions) but is now a real per-pack
    # override rather than a hardcoded "credit packs are never taxable" rule.
    taxable: bool = False
    tax_exempt_reason: Optional[str] = Field(default=None, max_length=300)
    # Public no-account storefront — credit packs are ALWAYS account-required
    # (see _public_purchase_state's kind-based hard rule); these fields only
    # affect whether/how a guest can BROWSE this pack, never whether they
    # can complete a purchase.
    publicly_visible: Optional[bool] = None
    show_public_price: bool = True
    requires_completed_onboarding: bool = False
    # Customer-facing quantity fix — presentation-only marketing metadata.
    # `qty` (above) stays the sole authoritative credit count granted to the
    # client's account/credit lot; these three fields never influence
    # granting, redemption, FIFO lots, balances, voids, or refunds. They
    # exist purely so "Daycare 2 dogs 10 days" (qty=15 internal credits,
    # because a two-dog day costs 1.5 credits) can be described to
    # customers as "10 days for 2 dogs" instead of the misleading "15
    # visits". See _credit_pack_display_fields().
    display_quantity: Optional[float] = Field(default=None, gt=0)
    display_unit: Optional[Literal["day", "visit", "night", "session"]] = None
    display_dog_count: Optional[int] = Field(default=None, ge=1)

    @model_validator(mode="after")
    def _display_quantity_and_unit_travel_together(self):
        # A quantity with no unit ("10" — 10 what?) or a unit with no
        # quantity is meaningless customer-facing copy — both or neither.
        # display_dog_count has no such pairing requirement: a pack can
        # legitimately advertise "10 days" with no dog count at all.
        if (self.display_quantity is None) != (self.display_unit is None):
            raise ValueError("display_quantity and display_unit must be set together, or both left unset.")
        return self


class SellCreditPackIn(BaseModel):
    pack_id: str
    payment_method: Optional[Literal["cash", "card", "transfer", "venmo", "paypal", "check", "other"]] = "cash"
    note: Optional[str] = ""
    # Sprint 110di-61 — Partial pay. When < pack price, the delta lands on
    # client.account_balance and today's recognized revenue = amount_paid.
    amount_paid: Optional[float] = Field(default=None, ge=0)


class SellCreditPackItem(BaseModel):
    pack_id: str
    quantity: int = Field(ge=1, le=50)


class SellCreditPacksBulkIn(BaseModel):
    items: List[SellCreditPackItem] = Field(min_length=1, max_length=20)
    payment_method: Optional[Literal["cash", "card", "transfer", "venmo", "paypal", "check", "other"]] = "cash"
    note: Optional[str] = ""
    # Sprint 110di-61 — Partial pay across the whole bulk-sale cart.
    amount_paid: Optional[float] = Field(default=None, ge=0)


@api.get("/credit-packs")
async def list_credit_packs(user: dict = Depends(get_current_user), include_inactive: bool = False, register_only: bool = False):
    q: Dict = {} if include_inactive else {"active": True}
    if register_only:
        q["show_at_register"] = {"$ne": False}
    packs = await db.credit_packs.find(q, {"_id": 0}).sort("qty", 1).to_list(200)
    # Sprint 110bv — rewrite to client's legacy price when applicable
    if user.get("role") == "client" and user.get("client_id"):
        await _apply_client_overrides(packs, user["client_id"], "credit_pack", "price")
    # Compute value_each AFTER override so it reflects what the client actually pays
    for p in packs:
        qty = int(p.get("qty") or 1)
        price = float(p.get("price") or 0)
        p["value_each"] = round(price / max(qty, 1), 2)
        p.update(_credit_pack_display_fields(p, qty, price))
    return packs


@api.post("/credit-packs")
async def create_credit_pack(body: CreditPackIn, _: dict = Depends(require_admin_and_permission("pricing"))):
    await _validate_category_subcategory_pair(body.category_id, body.subcategory_id, expected_section="prepaid_visits")
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["slug"] = doc.get("slug") or doc["name"].lower().replace(" ", "_")[:40]
    doc["is_default"] = False
    doc["created_at"] = now_iso()
    await db.credit_packs.insert_one(doc)
    doc.pop("_id", None)
    doc["value_each"] = round(doc["price"] / max(doc["qty"], 1), 2)
    return doc


@api.put("/credit-packs/{pack_id}")
async def update_credit_pack(pack_id: str, body: CreditPackIn, _: dict = Depends(require_admin_and_permission("pricing"))):
    existing = await db.credit_packs.find_one({"id": pack_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Pack not found")
    await _validate_category_subcategory_pair(
        body.category_id, body.subcategory_id,
        existing_category_id=existing.get("category_id"), existing_subcategory_id=existing.get("subcategory_id"),
        expected_section="prepaid_visits",
    )
    update = body.model_dump()
    update.pop("slug", None)
    update.pop("is_default", None)
    await db.credit_packs.update_one({"id": pack_id}, {"$set": update})
    merged = {**existing, **update}
    merged["value_each"] = round(float(merged.get("price") or 0) / max(int(merged.get("qty") or 1), 1), 2)
    return merged


@api.post("/credit-packs/{pack_id}/duplicate")
async def duplicate_credit_pack(pack_id: str, user: dict = Depends(require_admin_and_permission("pricing"))):
    """Copies a pack definition into a brand-new row with its own id and no
    sale history — mirrors duplicate_pos_product's pattern. Never touches
    already-issued credit lots; a duplicate starts hidden from the client
    Shop so an admin can review it before publishing."""
    existing = await db.credit_packs.find_one({"id": pack_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Pack not found")
    doc = {
        **existing,
        "id": str(uuid.uuid4()),
        "name": f"{existing.get('name') or 'Pack'} (Copy)",
        "slug": None,
        "is_default": False,
        "available_online": False,
        "active": True,
        "created_at": now_iso(),
    }
    doc["slug"] = _shop_org_slugify(doc["name"])[:40]
    await db.credit_packs.insert_one(doc)
    doc.pop("_id", None)
    doc["value_each"] = round(float(doc.get("price") or 0) / max(int(doc.get("qty") or 1), 1), 2)
    return doc


@api.delete("/credit-packs/{pack_id}")
async def delete_credit_pack(pack_id: str, force: bool = False, _: dict = Depends(require_admin_and_permission("pricing"))):
    existing = await db.credit_packs.find_one({"id": pack_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Pack not found")
    if not force:
        affected = await _count_active_overrides_for_target("credit_pack", pack_id)
        if affected > 0:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"{affected} client{'s' if affected != 1 else ''} have an active client-specific price on "
                    f"\"{existing.get('name')}\". Their override will NOT be changed or deleted, but it will no "
                    "longer correspond to an item in your standard catalog. Pass force=true to proceed anyway."
                ),
            )
    if existing.get("is_default"):
        await db.credit_packs.update_one({"id": pack_id}, {"$set": {"active": False}})
    else:
        await db.credit_packs.delete_one({"id": pack_id})
    return {"ok": True}


class CreditAdjustIn(BaseModel):
    daycare: float = 0       # positive = add, negative = subtract; supports .5 balances
    training: float = 0
    boarding: float = 0
    note: Optional[str] = ""


@api.post("/clients/{client_id}/adjust-credits")
async def adjust_client_credits(client_id: str, body: CreditAdjustIn, user: dict = Depends(require_admin_and_permission("finance_reports"))):
    """Manual +/- credit adjustment for fixing mistakes or comping a client.
    Routes through the shared credit-mutation service (_mutate_client_credits)
    so every adjustment mints/reduces a real backing credit_lots row —
    never just the displayed balance — keeping it genuinely redeemable at
    checkout exactly like a purchased pack. Writes one `credit_adjustments`
    audit row per affected pool (previously one combined row per call —
    see _mutate_client_credits's docstring). Refuses to take a balance
    below zero."""
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")

    pool_map = {
        "daycare": round(float(body.daycare or 0), 2),
        "training": round(float(body.training or 0), 2),
        "boarding": round(float(body.boarding or 0), 2),
    }
    if not any(pool_map.values()):
        raise HTTPException(status_code=400, detail="No adjustment specified.")

    changes: Dict[str, Dict[str, float]] = {}
    for service_type, delta in pool_map.items():
        if abs(delta) < 0.0001:
            continue
        mutation = await _mutate_client_credits(
            client_id, service_type, delta,
            source="manual_adjustment", reason=body.note or "",
            actor_id=user.get("id", "admin"), actor_name=user.get("name", "Admin"),
        )
        changes[service_type] = {"before": mutation["before"], "delta": mutation["delta"], "after": mutation["after"]}

    # Sprint 110g — if a manual adjustment lifts any low-credit pool back above
    # the threshold, clear its email-sent stamp so the NEXT dip re-fires the
    # heads-up email instead of silently being skipped by the idempotency guard.
    for pool, change in changes.items():
        if change["after"] > 2:
            await db.clients.update_one(
                {"id": client_id, f"low_credit_emailed_at.{pool}": {"$exists": True}},
                {"$unset": {f"low_credit_emailed_at.{pool}": ""}},
            )

    # Kept as one combined object for API-response-shape compatibility — the
    # actual audit trail is now the per-pool credit_adjustments rows
    # _mutate_client_credits already wrote, not a separate row for this.
    return {
        "id": str(uuid.uuid4()),
        "client_id": client_id,
        "client_name": client.get("name", ""),
        "changes": changes,
        "note": body.note or "",
        "adjusted_by": user.get("name", "Admin"),
        "adjusted_at": now_iso(),
    }


@api.get("/clients/{client_id}/credit-adjustments")
async def list_credit_adjustments(client_id: str, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    items = await db.credit_adjustments.find(
        {"client_id": client_id}, {"_id": 0}
    ).sort("adjusted_at", -1).to_list(100)
    return items


# -------- Read-only credit reconciliation --------
# This report intentionally performs no writes.  It compares the balances shown
# on each client record with the remaining purchased-credit lots plus the net
# manual adjustments recorded in `credit_adjustments`.  A variance is a review
# flag, not an automatic correction: older imports can legitimately pre-date
# lot-level tracking.
_CREDIT_RECON_POOLS = {
    "daycare": "credits",
    "training": "training_credits",
    "boarding": "boarding_credits",
}


def _credit_recon_num(value: Any) -> float:
    try:
        return round(float(value or 0), 2)
    except (TypeError, ValueError):
        return 0.0


def _credit_recon_client_row(
    client: Dict[str, Any],
    lot_totals: Dict[str, Dict[str, Any]],
    adjustment_totals: Dict[str, Any],
) -> Dict[str, Any]:
    pools: Dict[str, Any] = {}
    issues: List[str] = []
    has_variance = False
    has_structural_issue = False

    for pool, field in _CREDIT_RECON_POOLS.items():
        lot = lot_totals.get(pool) or {}
        displayed = _credit_recon_num(client.get(field))
        lot_remaining = _credit_recon_num(lot.get("remaining"))
        # Real bug fix — manual/reward credit grants now ALWAYS mint a real
        # backing credit_lots row (see _mutate_client_credits), so
        # lot_remaining alone already reflects every adjustment that's ever
        # been applied through the current code. Adding manual_net on top
        # here used to double-count: an adjustment that had already been
        # migrated into a real lot (by the manual-credits backfill, or by
        # this fix going forward) would count once as a lot AND again as an
        # adjustment-history total, making an already-correct client look
        # like it had a variance. credit_adjustments/rewards_ledger stay
        # informational history only — manual_net is still surfaced below
        # for visibility, it just never feeds into the tracked/variance math.
        manual_net = _credit_recon_num(adjustment_totals.get(pool))
        tracked_total = lot_remaining
        variance = round(displayed - tracked_total, 2)
        negative_lots = int(lot.get("negative_count") or 0)
        overfilled_lots = int(lot.get("overfilled_count") or 0)
        lot_count = int(lot.get("lot_count") or 0)
        adjustment_count = int(adjustment_totals.get("count") or 0)
        pool_issues: List[str] = []

        if abs(variance) > 0.009:
            has_variance = True
            pool_issues.append(
                f"Displayed balance differs from backing credit lots by {variance:+g}."
            )
        if displayed < -0.009:
            has_structural_issue = True
            pool_issues.append("Displayed balance is negative.")
        if negative_lots:
            has_structural_issue = True
            pool_issues.append(f"{negative_lots} credit lot(s) have a negative remaining quantity.")
        if overfilled_lots:
            has_structural_issue = True
            pool_issues.append(f"{overfilled_lots} credit lot(s) exceed their original quantity.")

        if pool_issues:
            issues.extend([f"{pool.title()}: {msg}" for msg in pool_issues])

        pools[pool] = {
            "displayed": displayed,
            "lot_remaining": lot_remaining,
            "manual_adjustment_net": manual_net,
            "tracked_total": tracked_total,
            "variance": variance,
            "lot_count": lot_count,
            "adjustment_count": adjustment_count,
            "negative_lot_count": negative_lots,
            "overfilled_lot_count": overfilled_lots,
            "status": "issue" if pool_issues else "match",
        }

    unknown_lots = lot_totals.get("__unknown__") or {}
    if int(unknown_lots.get("lot_count") or 0):
        has_structural_issue = True
        issues.append(
            f"{int(unknown_lots.get('lot_count') or 0)} credit lot(s) have a missing or unknown service type."
        )

    overall_status = "structural" if has_structural_issue else ("review" if has_variance else "match")
    return {
        "id": client.get("id") or "",
        "name": client.get("name") or "Unnamed client",
        "email": client.get("email") or "",
        "phone": client.get("phone") or "",
        "archived": bool(client.get("deleted") or client.get("archived")),
        "client_status": client.get("client_status") or "active",
        "overall_status": overall_status,
        "issues": issues,
        "issue_count": len(issues),
        "pools": pools,
        "unknown_lots": {
            "lot_count": int(unknown_lots.get("lot_count") or 0),
            "remaining": _credit_recon_num(unknown_lots.get("remaining")),
        },
    }


async def _credit_reconciliation_report(include_archived: bool = False) -> Dict[str, Any]:
    client_query: Dict[str, Any] = {}
    if not include_archived:
        client_query = {"deleted": {"$ne": True}, "archived": {"$ne": True}}
    clients = await db.clients.find(
        client_query,
        {
            "_id": 0, "id": 1, "name": 1, "email": 1, "phone": 1,
            "deleted": 1, "archived": 1, "client_status": 1,
            "credits": 1, "training_credits": 1, "boarding_credits": 1,
        },
    ).sort("name", 1).to_list(50000)
    selected_client_ids = {c.get("id") for c in clients if c.get("id")}
    # Orphan detection must consider archived clients too.  Otherwise hiding
    # archived clients from the report would falsely label their valid lots as
    # orphaned records.
    all_client_ids = {
        row.get("id")
        for row in await db.clients.find({}, {"_id": 0, "id": 1}).to_list(50000)
        if row.get("id")
    }

    lot_rows = await db.credit_lots.aggregate([
        {"$group": {
            "_id": {"client_id": "$client_id", "service_type": "$service_type"},
            "remaining": {"$sum": {"$ifNull": ["$qty_remaining", 0]}},
            "lot_count": {"$sum": 1},
            "negative_count": {"$sum": {"$cond": [{"$lt": [{"$ifNull": ["$qty_remaining", 0]}, 0]}, 1, 0]}},
            "overfilled_count": {"$sum": {"$cond": [{"$gt": [{"$ifNull": ["$qty_remaining", 0]}, {"$ifNull": ["$qty_total", 0]}]}, 1, 0]}},
        }},
    ]).to_list(100000)

    lots_by_client: Dict[str, Dict[str, Any]] = {}
    orphan_lots: List[Dict[str, Any]] = []
    for row in lot_rows:
        key = row.get("_id") or {}
        cid = key.get("client_id") or ""
        raw_pool = (key.get("service_type") or "").strip().lower()
        pool = raw_pool if raw_pool in _CREDIT_RECON_POOLS else "__unknown__"
        clean = {k: v for k, v in row.items() if k != "_id"}
        if cid not in all_client_ids:
            orphan_lots.append({"client_id": cid, "service_type": raw_pool or "unknown", **clean})
            continue
        if cid in selected_client_ids:
            lots_by_client.setdefault(cid, {})[pool] = clean

    adjustment_rows = await db.credit_adjustments.aggregate([
        {"$group": {
            "_id": "$client_id",
            "daycare": {"$sum": {"$ifNull": ["$changes.daycare.delta", 0]}},
            "training": {"$sum": {"$ifNull": ["$changes.training.delta", 0]}},
            "boarding": {"$sum": {"$ifNull": ["$changes.boarding.delta", 0]}},
            "count": {"$sum": 1},
            "last_adjusted_at": {"$max": "$adjusted_at"},
        }},
    ]).to_list(100000)
    adjustments_by_client: Dict[str, Dict[str, Any]] = {}
    orphan_adjustments: List[Dict[str, Any]] = []
    for row in adjustment_rows:
        cid = row.get("_id") or ""
        clean = {k: v for k, v in row.items() if k != "_id"}
        if cid not in all_client_ids:
            orphan_adjustments.append({"client_id": cid, **clean})
        elif cid in selected_client_ids:
            adjustments_by_client[cid] = clean

    rows = [
        _credit_recon_client_row(
            client,
            lots_by_client.get(client.get("id") or "", {}),
            adjustments_by_client.get(client.get("id") or "", {}),
        )
        for client in clients
    ]
    rows.sort(key=lambda r: (0 if r["overall_status"] == "structural" else 1 if r["overall_status"] == "review" else 2, r["name"].lower()))

    matched = sum(1 for r in rows if r["overall_status"] == "match")
    review = sum(1 for r in rows if r["overall_status"] == "review")
    structural = sum(1 for r in rows if r["overall_status"] == "structural")
    return {
        "generated_at": now_iso(),
        "read_only": True,
        "summary": {
            "client_count": len(rows),
            "matched_count": matched,
            "review_count": review,
            "structural_issue_count": structural,
            "orphan_lot_group_count": len(orphan_lots),
            "orphan_adjustment_group_count": len(orphan_adjustments),
        },
        "clients": rows,
        "orphan_lots": orphan_lots[:200],
        "orphan_adjustments": orphan_adjustments[:200],
        "notes": [
            "This report is read-only and never changes credit balances.",
            "A variance can be an older imported/legacy balance that predates credit-lot tracking; review it before making any adjustment.",
            "Tracked total equals remaining credit lots plus the net manual credit-adjustment history.",
        ],
    }


@api.get("/admin/credits/reconciliation")
async def credit_reconciliation_report(
    include_archived: bool = Query(False),
    _: dict = Depends(require_admin_and_permission("finance_reports")),
):
    return await _credit_reconciliation_report(include_archived=include_archived)


@api.get("/admin/credits/reconciliation/{client_id}")
async def credit_reconciliation_detail(client_id: str, _: dict = Depends(require_admin_and_permission("finance_reports"))):
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    lots = await db.credit_lots.find(
        {"client_id": client_id}, {"_id": 0}
    ).sort("purchased_at", -1).to_list(2000)
    adjustments = await db.credit_adjustments.find(
        {"client_id": client_id}, {"_id": 0}
    ).sort("adjusted_at", -1).to_list(1000)
    booking_projection = {
        "_id": 0, "id": 1, "date": 1, "end_date": 1, "service_type": 1,
        "service_name": 1, "dog_name": 1, "status": 1, "credits_deducted": 1,
        "credit_value_deducted": 1, "credit_lot_redemptions": 1,
        "checked_out_at": 1, "created_at": 1,
    }
    q = {"client_id": client_id, "credits_deducted": {"$gt": 0}}
    active = await db.bookings.find(q, booking_projection).sort("date", -1).to_list(500)
    archived = await db.bookings_archive.find(q, booking_projection).sort("date", -1).to_list(500)
    credit_bookings = sorted(
        active + archived,
        key=lambda row: str(row.get("checked_out_at") or row.get("date") or row.get("created_at") or ""),
        reverse=True,
    )[:500]
    return {
        "read_only": True,
        "client": {
            "id": client.get("id"), "name": client.get("name"),
            "email": client.get("email"), "phone": client.get("phone"),
            "credits": _credit_recon_num(client.get("credits")),
            "training_credits": _credit_recon_num(client.get("training_credits")),
            "boarding_credits": _credit_recon_num(client.get("boarding_credits")),
        },
        "lots": lots,
        "adjustments": adjustments,
        "credit_bookings": credit_bookings,
    }


@api.post("/credit-packs/seed-standard")
async def seed_credit_packs(_: dict = Depends(require_admin_and_permission("pricing"))):
    seeded = 0
    backfilled = 0
    for pack in SEED_CREDIT_PACKS:
        existing = await db.credit_packs.find_one({"slug": pack["slug"]}, {"_id": 0})
        if existing:
            # Backfill icon onto pre-existing default packs (one-time, idempotent).
            if not existing.get("icon") and pack.get("icon"):
                await db.credit_packs.update_one({"id": existing["id"]}, {"$set": {"icon": pack["icon"]}})
                backfilled += 1
            continue
        doc = {**pack, "id": str(uuid.uuid4()), "is_default": True, "active": True, "created_at": now_iso()}
        await db.credit_packs.insert_one(doc)
        seeded += 1
    total = await db.credit_packs.count_documents({"active": True})
    return {"seeded": seeded, "icon_backfilled": backfilled, "total_active": total}


# ─────────────── Sprint 110bw · Sell training programs as credit packs ───────────────
#
# Mirrors the credit-pack sell flow but for `programs`. Selling a program:
#   • Creates a `credit_lots` row tagged `pack_kind="training_program"` +
#     `program_id` so the per-program breakdown can be assembled at any time
#     (Q1c "hybrid" — global counter + per-program ledger).
#   • Increments `clients.training_credits` by the program's session count.
#   • Optionally enrols a specific dog (`dog_id` field — Q2c "optional dropdown").

class SellProgramIn(BaseModel):
    program_id: str
    payment_method: Literal["cash", "card", "venmo", "paypal", "check", "other", "complimentary"] = "cash"
    override_price: Optional[float] = Field(default=None, ge=0)
    dog_id: Optional[str] = None       # If set, auto-creates a dog_programs row
    started_at: Optional[str] = None   # YYYY-MM-DD, defaults to today
    note: Optional[str] = ""
    # Sprint 110ce — recurring session scheduling. When set (and program type
    # is NOT board_train), auto-creates N weekly bookings on the chosen
    # day-of-week/time, prepaid via the credit lot. Board & Train programs
    # don't need this — the dog is already on-site.
    schedule_day_of_week: Optional[int] = Field(default=None, ge=0, le=6)  # 0=Mon ... 6=Sun
    schedule_time: Optional[str] = None  # HH:MM (24h)
    schedule_start_date: Optional[str] = None  # YYYY-MM-DD, defaults to next instance of weekday from today
    schedule_override_closures: bool = False  # set to True to ignore closed-day warnings
    # Sprint 110di-61 — Partial pay support. When < effective_price, the
    # difference lands on client.account_balance and only amount_paid is
    # recognized as revenue today (cash-basis — option 1c).
    amount_paid: Optional[float] = Field(default=None, ge=0)


@api.post("/clients/{client_id}/sell-program")
async def sell_training_program(
    client_id: str,
    body: SellProgramIn,
    user: dict = Depends(require_admin_and_permission("sell_credits")),
):
    """Sell a training program — issues N training_credits where N = program
    session count, creates a per-program credit_lot for ledger/audit, and
    optionally enrols a specific dog so progress tracking starts immediately.

    Pricing: defaults to program.price, overrideable via `override_price`
    (admin discount). Does NOT trigger Stripe — same as sell-pack, this is
    the manual-payment path."""
    await _require_register_day_open(business_today().isoformat())
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    program = await db.programs.find_one({"id": body.program_id}, {"_id": 0})
    if not program:
        raise HTTPException(status_code=404, detail="Program not found")
    if not program.get("active", True):
        raise HTTPException(status_code=400, detail="Program is inactive")

    fmt = program.get("format") or {}
    qty = int(fmt.get("count") or 0)
    if qty <= 0:
        raise HTTPException(status_code=400,
                            detail="Program format.count must be > 0 to sell as credits")
    unit = fmt.get("unit") or "sessions"

    list_price = float(program.get("price") or 0)
    effective_price = float(body.override_price) if body.override_price is not None else list_price
    value_each = round(effective_price / max(qty, 1), 2)

    # If a dog is specified, make sure it belongs to this client.
    dog = None
    if body.dog_id:
        dog = await db.dogs.find_one({"id": body.dog_id}, {"_id": 0})
        if not dog:
            raise HTTPException(404, "Dog not found")
        if dog.get("owner_id") != client_id:
            raise HTTPException(400, "Dog does not belong to this client")

    # Dog eligibility MUST be checked before credit lots, client balances,
    # revenue rows, or any other financial mutation below. Minimum age applies
    # to every dog-targeted program sale; Online School also enforces pathway
    # prerequisites here (and again at the canonical grant boundary).
    if dog:
        _require_program_min_age(dog, program)
    if dog and program.get("purchase_fulfillment") == "online_school":
        await _require_program_prerequisites(dog["id"], program)

    lot = {
        "id": str(uuid.uuid4()),
        "client_id": client_id,
        # Re-uses the credit_lots schema. `pack_kind` distinguishes pack
        # sales ("credit_pack") from program sales ("training_program").
        "pack_kind": "training_program",
        "pack_id": program["id"],
        "pack_name": program["name"],
        "program_id": program["id"],
        "program_name": program["name"],
        "service_type": "training",
        "qty_total": qty,
        "qty_remaining": qty,
        "unit": unit,
        "price_paid": round(effective_price, 2),
        "list_price": round(list_price, 2),
        "value_each": value_each,
        "payment_method": _normalize_payment_method(body.payment_method, store=True),
        "note": body.note or "",
        "sold_by": user.get("name", "Admin"),
        "purchased_at": now_iso(),
    }
    await db.credit_lots.insert_one(lot)
    await db.clients.update_one({"id": client_id}, {"$inc": {"training_credits": qty}})

    # Sprint 110ca — record the sale as income immediately. Unlike credit packs
    # (which use deferred revenue recognition because each credit can be used
    # months later), training programs are a fixed commitment up-front, so the
    # operator wants the full sale price on the books on sale day. We write to
    # `retail_sales` because that's the collection the Income screen + monthly
    # P&L PDF + year-end CSV already aggregate.
    # Sprint 110di-61 — Partial-pay branch (cash-basis recognition).
    is_partial = (
        body.amount_paid is not None
        and effective_price > 0
        and abs(float(body.amount_paid) - effective_price) > 0.005
    )
    revenue_today = effective_price
    if is_partial:
        revenue_today = max(0.0, min(float(body.amount_paid), effective_price))
        await _apply_sale_partial_payment(
            client_id=client_id,
            total=effective_price,
            paid=float(body.amount_paid),
            sale_kind="training_program",
            sale_id=lot["id"],
            label=f"Training Program · {program['name']}",
            method=_normalize_payment_method(body.payment_method, store=True),
        )

    if revenue_today > 0:
        income_doc = {
            "id": str(uuid.uuid4()),
            "date": business_today().isoformat(),
            "description": f"Training Program · {program['name']}",
            "amount": round(revenue_today, 2),
            "category": "Training Program",
            "notes": body.note or "",
            "payment_method": _normalize_payment_method(body.payment_method, store=True),
            "client_id": client_id,
            "client_name": client.get("name") or "",
            "created_at": now_iso(),
            "created_by": user.get("id"),
            # Back-link so the audit trail joins program sale → income row → lot
            "source_kind": "training_program_sale",
            "source_id": lot["id"],
            "program_id": program["id"],
        }
        # Training is a service, not retail — keep it out of the retail sales
        # tax bucket (sales_tax.applies_to.retail) which is for tangible goods.
        # Operator can still recognize service tax separately if they configure
        # it on the program/service catalog.
        await db.retail_sales.insert_one(income_doc)
        income_doc.pop("_id", None)
        lot["income_event_id"] = income_doc["id"]
        await db.credit_lots.update_one(
            {"id": lot["id"]},
            {"$set": {"income_event_id": income_doc["id"]}},
        )

    enrollment_summary = None
    enrollment_warning = None
    if dog and program.get("purchase_fulfillment") == "online_school":
        # Commerce still determines how entitlement is acquired. Once granted,
        # Online School uses the same canonical curriculum/progress architecture.
        try:
            result = await _grant_online_school_enrollment(
                dog, program, enrolled_by=user.get("id"),
                enrollment_source="purchase", source_ref=f"sell_program:{lot['id']}",
            )
            enrollment_summary = result["enrollment"]
        except OnlineSchoolAlreadyEnrolledError as exc:
            existing = await db.dog_programs.find_one({"id": exc.dog_program_id}, {"_id": 0}) if exc.dog_program_id else None
            enrollment_summary = _enrollment_summary(existing) if existing else None
        except HTTPException as exc:
            # The sale/credit ledger is already durable. Do not create a
            # legacy enrollment as a fallback; tell Admin exactly what needs
            # fixing before the dog can start the curriculum.
            enrollment_warning = str(exc.detail)
    elif dog:
        canonical = await db.dog_programs.find_one(
            {"dog_id": dog["id"], "program_id": program["id"], "status": "active",
             "delivery_channel": {"$in": list(STAFF_SCHOOL_DELIVERY_CHANNELS)}},
            {"_id": 0},
        )
        legacy_active = await db.dog_programs.find_one(
            {"dog_id": dog["id"], "program_id": program["id"], "status": "active",
             "delivery_channel": {"$nin": list(SCHOOL_DELIVERY_CHANNELS)}},
            {"_id": 0, "id": 1},
        )
        if canonical:
            enrollment_summary = _enrollment_summary(canonical)
        elif legacy_active:
            enrollment_warning = "Program sold, but this dog still has an active retired legacy enrollment. Migrate that record into School before continuing training."
        elif not _school_curriculum_readiness(program).get("ready"):
            enrollment_warning = "Program sold, but this curriculum uses the retired legacy structure. Add explicit lessons in Program Studio before assigning it for training."
        else:
            try:
                result = await _grant_staff_school_enrollment(
                    dog, program, delivery_mode="in_person", enrolled_by=user.get("id"),
                    trainer_notes=body.note or "", started_at=body.started_at,
                )
                enrollment_summary = result["enrollment"]
                await db.dog_programs.update_one(
                    {"id": result["enrollment"]["id"]},
                    {"$set": {"credit_lot_id": lot["id"], "enrollment_source": "program_sale"}},
                )
                await db.school_enrollments.update_one(
                    {"id": result["school_enrollment"]["id"]},
                    {"$set": {"credit_lot_id": lot["id"], "enrollment_source": "program_sale"}},
                )
            except HTTPException as exc:
                enrollment_warning = str(exc.detail)

    # Sprint 110ce — recurring session scheduling. Skipped entirely for
    # board_train (the dog is on-site so weekly bookings don't make sense)
    # and for sales without a target dog (can't book a session for nobody).
    scheduled_bookings: list = []
    schedule_warnings: list = []
    can_schedule = (
        dog is not None
        and body.schedule_day_of_week is not None
        and body.schedule_time
        and (program.get("type") or "custom") != "board_train"
    )
    if can_schedule:
        # Pull closed dates so we can skip them (or warn the admin)
        settings_doc = await db.settings.find_one({"_id": "main"}, {"_id": 0}) or {}
        closed_dates = set(settings_doc.get("closed_dates") or [])

        # Anchor date: schedule_start_date if provided, else next instance of
        # the chosen weekday (including today if today matches)
        from datetime import date as _date, timedelta as _td
        if body.schedule_start_date:
            anchor = _date.fromisoformat(body.schedule_start_date)
        else:
            anchor = _date.today()
        # Roll forward to the desired weekday
        wd_target = body.schedule_day_of_week
        delta = (wd_target - anchor.weekday()) % 7
        first_date = anchor + _td(days=delta)

        # Generate `qty` weekly dates, skipping closed days (and adding extra
        # weeks at the end if any get skipped) — UNLESS override_closures is
        # set, in which case we include closed dates verbatim.
        generated: list = []
        cursor = first_date
        attempts = 0
        max_attempts = qty * 5  # safety net to avoid infinite loops
        while len(generated) < qty and attempts < max_attempts:
            iso = cursor.isoformat()
            if iso in closed_dates and not body.schedule_override_closures:
                schedule_warnings.append({
                    "date": iso,
                    "reason": "business_closed",
                    "note": "Skipped — business closed; rolled forward 7 days.",
                })
                cursor += _td(days=7)
                attempts += 1
                continue
            generated.append(iso)
            cursor += _td(days=7)
            attempts += 1

        # Now create the bookings. Each is prepaid ($0 actual_price) and tied
        # back to the credit lot so the books stay clean.
        for iso_date in generated:
            booking = {
                "id": _gid(),
                "dog_id": dog["id"],
                "dog_name": dog.get("name", ""),
                "client_id": client_id,
                "client_name": client.get("name", ""),
                "service_type": "training",
                "date": iso_date,
                "end_date": None,
                "time": body.schedule_time,
                "kennel": "",
                "notes": f"Program · {program['name']} · session {generated.index(iso_date) + 1} of {qty}",
                "status": "approved",
                "actual_price": 0.0,
                "payment_status": "paid",
                "payment_method": "credits",
                "created_at": now_iso(),
                "created_by": user.get("id"),
                # Sprint 110ce back-links — these let cancel/reschedule restore
                # the credit slot and let the trainer see "this is session X of Y"
                "credit_lot_id": lot["id"],
                "program_id": program["id"],
                "program_sale_session_index": generated.index(iso_date) + 1,
                "program_sale_session_total": qty,
                "is_prepaid_program_session": True,
            }
            probe = BookingIn(
                dog_id=dog["id"], date=iso_date, service_type="training",
                time=body.schedule_time or "", service_id=booking.get("service_id"),
            )
            keys = _capacity_resource_keys(probe)
            owner = await _acquire_capacity_locks(keys) if keys else None
            try:
                try:
                    await _assert_capacity_available(probe, await get_settings(), None)
                except HTTPException as exc:
                    if isinstance(exc.detail, dict) and exc.detail.get("code") in ("capacity_full", "capacity_busy"):
                        schedule_warnings.append({
                            "date": iso_date, "reason": "capacity_full",
                            "note": (exc.detail.get("message") or "Time slot unavailable"),
                        })
                        continue
                    raise
                await db.bookings.insert_one(booking)
            finally:
                if owner:
                    await _release_capacity_locks(owner, keys)
            booking.pop("_id", None)
            scheduled_bookings.append(booking)

    lot.pop("_id", None)
    # Sprint 110di-62 — Fire program's bound welcome email if set.
    if program.get("welcome_email_template_slug"):
        try:
            asyncio.create_task(_fire_product_welcome_email(
                client=client, slug=program["welcome_email_template_slug"],
                ctx={"program_name": program.get("name", ""), "dog_name": ""},
            ))
        except Exception as exc:
            logger.warning("program welcome email spawn failed: %s", exc)
    return {
        "lot": lot,
        "enrollment": enrollment_summary,  # null when dog_id not provided
        "enrollment_warning": enrollment_warning,
        "client_balance": int((client.get("training_credits") or 0)) + qty,
        "scheduled_bookings": scheduled_bookings,
        "schedule_warnings": schedule_warnings,
    }

async def reschedule_prepaid_session(booking_id: str, _: dict = Depends(require_admin)):
    """Sprint 110ce — push a prepaid program session forward to the next
    available same-weekday slot, skipping business-closure dates AND any other
    bookings already scheduled for that dog on the candidate date. Doesn't
    touch the credit lot (no re-credit because nothing was charged in the
    first place; the session is just moving in time)."""
    bk = await db.bookings.find_one({"id": booking_id}, {"_id": 0})
    if not bk:
        raise HTTPException(404, "Booking not found")
    if not bk.get("is_prepaid_program_session"):
        raise HTTPException(400, "This endpoint is only for prepaid program sessions")
    from datetime import date as _date, timedelta as _td
    settings_doc = await db.settings.find_one({"_id": "main"}, {"_id": 0}) or {}
    closed_dates = set(settings_doc.get("closed_dates") or [])
    cur_date = _date.fromisoformat(bk["date"])
    # Try the next 12 weeks; skip closures + dog-double-booked dates
    for i in range(1, 13):
        candidate = cur_date + _td(days=7 * i)
        iso = candidate.isoformat()
        if iso in closed_dates:
            continue
        conflict = await db.bookings.find_one(
            {"dog_id": bk["dog_id"], "date": iso,
             "id": {"$ne": booking_id},
             "status": {"$ne": "cancelled"}},
            {"_id": 0, "id": 1},
        )
        if conflict:
            continue
        try:
            updated = await _update_booking_with_capacity(bk, {
                "date": iso,
                "rescheduled_from": bk["date"],
                "rescheduled_at": now_iso(),
            })
        except HTTPException as exc:
            if isinstance(exc.detail, dict) and exc.detail.get("code") in ("capacity_full", "capacity_busy"):
                continue
            raise
        return {"ok": True, "booking": updated, "from": bk["date"], "to": iso}
    raise HTTPException(409, "No open slot found in the next 12 weeks on that weekday")



# ────────── Sprint 110cf · Client-initiated reschedule requests ──────────
#
# Flow: client taps "Reschedule" on a prepaid program session in the portal,
# picks 1–3 alternate dates/times. We store a `reschedule_requests` row in
# status="pending" + email the admin with one-click approve links. Admin
# picks the slot that works → booking moves, credit is untouched, client
# gets a confirmation email. If none of the slots work, admin declines and
# the client gets a "we'll be in touch" email; the original booking stays.

class RescheduleProposedSlot(BaseModel):
    date: str  # YYYY-MM-DD
    time: str  # HH:MM


class RescheduleRequestIn(BaseModel):
    proposed_slots: List[RescheduleProposedSlot] = Field(..., min_length=1, max_length=3)
    client_note: Optional[str] = ""


@api.post("/portal/bookings/{booking_id}/request-reschedule")
async def request_reschedule(
    booking_id: str,
    body: RescheduleRequestIn,
    current: dict = Depends(get_current_user),
):
    """Client portal — propose 1-3 alternate slots for a prepaid program session."""
    bk = await db.bookings.find_one({"id": booking_id}, {"_id": 0})
    if not bk:
        raise HTTPException(404, "Booking not found")
    if not bk.get("is_prepaid_program_session"):
        raise HTTPException(400, "Reschedule requests are only for prepaid program sessions")
    if current.get("role") == "client" and bk.get("client_id") != current.get("client_id"):
        raise HTTPException(403, "Not your booking")
    if bk.get("status") == "cancelled":
        raise HTTPException(400, "This booking is cancelled")

    # Don't allow piling up duplicate pending requests on the same booking
    existing = await db.reschedule_requests.find_one(
        {"booking_id": booking_id, "status": "pending"},
        {"_id": 0, "id": 1},
    )
    if existing:
        raise HTTPException(409, "There's already a pending reschedule request for this session")

    req_doc = {
        "id": _gid(),
        "booking_id": booking_id,
        "client_id": bk.get("client_id"),
        "client_name": bk.get("client_name"),
        "dog_id": bk.get("dog_id"),
        "dog_name": bk.get("dog_name"),
        "current_date": bk.get("date"),
        "current_time": bk.get("time"),
        "proposed_slots": [s.model_dump() for s in body.proposed_slots],
        "client_note": body.client_note or "",
        "status": "pending",
        "created_at": now_iso(),
        "created_by": current.get("id"),
    }
    await db.reschedule_requests.insert_one(req_doc)
    req_doc.pop("_id", None)

    # Email admin (best-effort)
    try:
        proposed_list_html = "<br/>".join(
            f"• {s.date} at {s.time}" for s in body.proposed_slots
        )
        await email_service._dispatch(
            slug="admin_reschedule_request",
            to_email=os.environ.get("ADMIN_NOTIFICATION_EMAIL", ""),
            ctx={
                "client_name": bk.get("client_name", ""),
                "dog_name": bk.get("dog_name", ""),
                "current_date": bk.get("date", ""),
                "current_time": bk.get("time", ""),
                "proposed_count": len(body.proposed_slots),
                "proposed_plural": "" if len(body.proposed_slots) == 1 else "s",
                "proposed_list": proposed_list_html,
            },
            rows=[
                ("Currently", f"{bk.get('date','')} at {bk.get('time','')}"),
                ("Client", bk.get("client_name", "")),
                ("Dog", bk.get("dog_name", "")),
            ] + ([("Client's note", body.client_note)] if body.client_note else []),
            cta_url=f"{os.environ.get('APP_PUBLIC_URL', '')}/" if os.environ.get("APP_PUBLIC_URL") else None,
            show_install=False,
        )
    except Exception as exc:
        logger.warning("Reschedule request email failed: %s", exc)

    return req_doc


@api.get("/admin/reschedule-requests")
async def list_reschedule_requests(
    status: Optional[str] = "pending",
    _: dict = Depends(require_admin),
):
    """Inbox of client-initiated reschedule requests."""
    q: dict = {}
    if status:
        q["status"] = status
    rows = await db.reschedule_requests.find(q, {"_id": 0}).sort([("created_at", -1)]).to_list(200)
    return rows


@api.get("/portal/reschedule-requests")
async def list_my_reschedule_requests(current: dict = Depends(get_current_user)):
    """Client portal — list pending/recent reschedule requests for this client."""
    if not current.get("client_id"):
        raise HTTPException(400, "No client linked to this account")
    rows = await db.reschedule_requests.find(
        {"client_id": current["client_id"]}, {"_id": 0},
    ).sort([("created_at", -1)]).to_list(50)
    return rows


class RescheduleApproveIn(BaseModel):
    slot_index: int = Field(..., ge=0, le=2)


@api.post("/admin/reschedule-requests/{req_id}/approve")
async def approve_reschedule_request(
    req_id: str,
    body: RescheduleApproveIn,
    _: dict = Depends(require_admin),
):
    """Approve one of the proposed slots — moves the booking, leaves credits
    alone, and emails the client a confirmation."""
    req = await db.reschedule_requests.find_one({"id": req_id}, {"_id": 0})
    if not req:
        raise HTTPException(404, "Request not found")
    if req.get("status") != "pending":
        raise HTTPException(400, f"Request is already {req.get('status')}")
    slots = req.get("proposed_slots") or []
    if body.slot_index >= len(slots):
        raise HTTPException(400, "slot_index out of range")
    chosen = slots[body.slot_index]

    bk = await db.bookings.find_one({"id": req["booking_id"]}, {"_id": 0})
    if not bk:
        raise HTTPException(404, "Original booking is gone")
    original_date = bk.get("date")
    await _update_booking_with_capacity(bk, {
        "date": chosen["date"],
        "time": chosen["time"],
        "rescheduled_from": original_date,
        "rescheduled_at": now_iso(),
        "rescheduled_via_request": req_id,
    })
    await db.reschedule_requests.update_one(
        {"id": req_id},
        {"$set": {
            "status": "approved",
            "approved_slot_index": body.slot_index,
            "approved_at": now_iso(),
        }},
    )

    # Email client
    client = await db.clients.find_one({"id": req["client_id"]}, {"_id": 0}) or {}
    if client.get("email"):
        try:
            await email_service._dispatch(
                slug="client_reschedule_approved",
                to_email=client["email"],
                ctx={
                    "first_name": (client.get("name") or "there").split(" ")[0],
                    "client_name": client.get("name", ""),
                    "dog_name": req.get("dog_name", ""),
                    "new_date": chosen["date"],
                    "new_time": chosen["time"],
                    "original_date": original_date,
                },
                rows=[
                    ("Dog", req.get("dog_name", "")),
                    ("New date", chosen["date"]),
                    ("New time", chosen["time"]),
                ],
                cta_url=f"{os.environ.get('APP_PUBLIC_URL', '')}/" if os.environ.get("APP_PUBLIC_URL") else None,
            )
        except Exception as exc:
            logger.warning("Approval email failed: %s", exc)

    updated = await db.reschedule_requests.find_one({"id": req_id}, {"_id": 0})
    return updated


class RescheduleDeclineIn(BaseModel):
    reason: Optional[str] = ""


@api.post("/admin/reschedule-requests/{req_id}/decline")
async def decline_reschedule_request(
    req_id: str,
    body: RescheduleDeclineIn,
    _: dict = Depends(require_admin),
):
    """Mark a reschedule request as declined and let the client know we'll
    follow up. Original booking is untouched."""
    req = await db.reschedule_requests.find_one({"id": req_id}, {"_id": 0})
    if not req:
        raise HTTPException(404, "Request not found")
    if req.get("status") != "pending":
        raise HTTPException(400, f"Request is already {req.get('status')}")
    await db.reschedule_requests.update_one(
        {"id": req_id},
        {"$set": {
            "status": "declined",
            "decline_reason": body.reason or "",
            "declined_at": now_iso(),
        }},
    )
    client = await db.clients.find_one({"id": req["client_id"]}, {"_id": 0}) or {}
    if client.get("email"):
        try:
            await email_service._dispatch(
                slug="client_reschedule_declined",
                to_email=client["email"],
                ctx={
                    "first_name": (client.get("name") or "there").split(" ")[0],
                    "client_name": client.get("name", ""),
                    "dog_name": req.get("dog_name", ""),
                    "original_date": req.get("current_date", ""),
                    "decline_reason": body.reason or "",
                },
                rows=[("Dog", req.get("dog_name", ""))],
            )
        except Exception as exc:
            logger.warning("Decline email failed: %s", exc)
    updated = await db.reschedule_requests.find_one({"id": req_id}, {"_id": 0})
    return updated





@api.get("/admin/clients/{client_id}/training-credits")
async def client_training_credits_breakdown(
    client_id: str,
    _: dict = Depends(require_admin_and_permission("finance_reports")),
):
    """Per-program breakdown of a client's outstanding training credits.

    Aggregates `credit_lots` rows where pack_kind=training_program and
    qty_remaining > 0, grouped by program. Used by the client profile to
    show "3 of 4 Puppy Preschool left" alongside the global total.
    """
    client = await db.clients.find_one({"id": client_id}, {"_id": 0, "training_credits": 1})
    if not client:
        raise HTTPException(404, "Client not found")
    lots = await db.credit_lots.find(
        {"client_id": client_id, "pack_kind": "training_program",
         "qty_remaining": {"$gt": 0}},
        {"_id": 0},
    ).sort([("purchased_at", 1)]).to_list(500)

    by_program: Dict[str, Dict[str, Any]] = {}
    for lot in lots:
        pid = lot.get("program_id") or lot.get("pack_id") or "unknown"
        bucket = by_program.setdefault(pid, {
            "program_id": pid,
            "program_name": lot.get("program_name") or lot.get("pack_name") or "Training",
            "unit": lot.get("unit") or "sessions",
            "qty_remaining": 0,
            "qty_total": 0,
            "lots": [],
        })
        bucket["qty_remaining"] += int(lot.get("qty_remaining") or 0)
        bucket["qty_total"] += int(lot.get("qty_total") or 0)
        bucket["lots"].append({
            "lot_id": lot.get("id"),
            "purchased_at": lot.get("purchased_at"),
            "qty_remaining": int(lot.get("qty_remaining") or 0),
            "qty_total": int(lot.get("qty_total") or 0),
            "price_paid": float(lot.get("price_paid") or 0),
            "value_each": float(lot.get("value_each") or 0),
        })

    return {
        "global_training_credits": int(client.get("training_credits") or 0),
        "by_program": list(by_program.values()),
        "lots_count": len(lots),
    }



@api.post("/clients/{client_id}/sell-pack")
async def sell_credit_pack(client_id: str, body: SellCreditPackIn, user: dict = Depends(require_admin_and_permission("sell_credits"))):
    """Sell a pack to a client — increments their credit balance AND creates a
    FIFO credit_lot tagged with the per-credit value. Does NOT generate a
    revenue event (income is recognized when each credit is redeemed at
    check-out)."""
    await _require_register_day_open(business_today().isoformat())
    await _require_drawer_open_for_cash(body.payment_method)
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    pack = await db.credit_packs.find_one({"id": body.pack_id}, {"_id": 0})
    if not pack:
        raise HTTPException(status_code=404, detail="Pack not found")
    qty = int(pack["qty"])
    # Sprint 110am — honour a legacy-pricing override if one is active for this
    # client + pack. Falls back to the catalog price when no override exists.
    pricing = await resolve_client_price(client_id, "credit_pack", pack["id"], float(pack["price"]))
    effective_price = pricing["effective_price"]
    value_each = round(effective_price / max(qty, 1), 2)
    svc_type = pack.get("service_type") or "daycare"
    lot = {
        "id": str(uuid.uuid4()),
        "client_id": client_id,
        "pack_id": pack["id"],
        "pack_name": pack["name"],
        "service_type": svc_type,
        "qty_total": qty,
        "qty_remaining": qty,
        "price_paid": effective_price,
        "list_price": float(pack["price"]),
        "price_override_id": pricing["override_id"],
        "value_each": value_each,
        "payment_method": _normalize_payment_method(body.payment_method, store=True),
        "note": body.note or "",
        "sold_by": user.get("name", "Admin"),
        "purchased_at": now_iso(),
        # Sprint 110cs — Mark new lots so revenue is recognized at sale-time
        # (point-of-sale / cash basis). Existing lots without this flag keep
        # their old behavior (recognize per-redemption) so we never touch
        # grandfathered data.
        "recognize_at_sale": True,
    }
    await db.credit_lots.insert_one(lot)
    balance_field = _credit_balance_field(svc_type) or "credits"
    await db.clients.update_one({"id": client_id}, {"$inc": {balance_field: qty}})

    # Sprint 110di-61 — Partial-pay branch. When `amount_paid` is provided
    # AND less than the pack price, only the paid portion hits today's
    # revenue (option 1c — cash basis); the rest goes onto the client's
    # running tab via the universal ledger helper.
    is_partial = (
        body.amount_paid is not None
        and effective_price > 0
        and abs(float(body.amount_paid) - effective_price) > 0.005
    )
    revenue_today = effective_price
    if is_partial:
        revenue_today = max(0.0, min(float(body.amount_paid), effective_price))
        await _apply_sale_partial_payment(
            client_id=client_id,
            total=effective_price,
            paid=float(body.amount_paid),
            sale_kind="credit_pack",
            sale_id=lot["id"],
            label=f"Credit pack · {pack['name']}",
            method=_normalize_payment_method(body.payment_method, store=True),
        )

    # Sprint 110cs — Insert matching retail_sales row so income reports show
    # the sale on the day cash came in. Sprint 110di-61: under partial-pay,
    # `amount` records ONLY what was paid today (cash-basis recognition).
    if revenue_today > 0:
        await db.retail_sales.insert_one({
            "id": str(uuid.uuid4()),
            "client_id": client_id,
            "client_name": client.get("name", ""),
            "amount": round(revenue_today, 2),
            "date": business_today().isoformat(),
            "payment_method": _normalize_payment_method(body.payment_method, store=True),
            "source_kind": "credit_pack_sale",
            "lot_id": lot["id"],
            "pack_id": pack["id"],
            "pack_name": pack["name"],
            "note": body.note or "",
            "logged_by": user.get("name", "Admin"),
            "created_at": now_iso(),
        })

    lot.pop("_id", None)
    # Sprint 110di-62 — Fire pack's bound welcome email if set.
    if pack.get("welcome_email_template_slug"):
        try:
            asyncio.create_task(_fire_product_welcome_email(
                client=client, slug=pack["welcome_email_template_slug"],
                ctx={"pack_name": pack.get("name", "")},
            ))
        except Exception as exc:
            logger.warning("pack welcome email spawn failed: %s", exc)
    try:
        asyncio.create_task(_maybe_auto_email_receipt("credit_pack", lot["id"], client_id))
    except Exception as exc:
        logger.warning("auto-email receipt spawn failed for credit pack %s: %s", lot["id"], exc)
    return lot


@api.post("/clients/{client_id}/sell-packs")
async def sell_credit_packs_bulk(client_id: str, body: SellCreditPacksBulkIn, user: dict = Depends(require_admin_and_permission("sell_credits"))):
    """Sell multiple credit packs to a client in a single transaction.
    Each {pack_id, quantity} pair mints `quantity` separate FIFO lots so
    accounting + redemption logic stays unchanged. Returns the list of new
    lots plus a per-pool totals summary (qty + price)."""
    await _require_register_day_open(business_today().isoformat())
    # Register-path parity: a CASH pack sale is physical drawer money, so it
    # follows the exact same open-drawer rule as the Front Desk POS cart and
    # every other cash-collecting endpoint — the same real-world transaction
    # must not obey different cash rules depending on which button sold it.
    await _require_drawer_open_for_cash(body.payment_method)
    client = await db.clients.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")

    # Pre-fetch every pack referenced so we fail fast on unknown ids before
    # any mutations land.
    pack_ids = [it.pack_id for it in body.items]
    packs = {p["id"]: p for p in await db.credit_packs.find({"id": {"$in": pack_ids}}, {"_id": 0}).to_list(200)}
    missing = [pid for pid in pack_ids if pid not in packs]
    if missing:
        raise HTTPException(status_code=404, detail=f"Pack(s) not found: {', '.join(missing)}")

    new_lots: List[Dict] = []
    pool_increments: Dict[str, int] = {"daycare": 0, "training": 0, "boarding": 0}
    totals_by_pool = {
        "daycare": {"qty": 0, "price": 0.0},
        "training": {"qty": 0, "price": 0.0},
        "boarding": {"qty": 0, "price": 0.0},
    }

    now = now_iso()
    for item in body.items:
        pack = packs[item.pack_id]
        qty = int(pack["qty"])
        # Sprint 110am — same legacy-pricing resolution as the single-sell path
        pricing = await resolve_client_price(client_id, "credit_pack", pack["id"], float(pack["price"]))
        effective_price = pricing["effective_price"]
        value_each = round(effective_price / max(qty, 1), 2)
        svc_type = pack.get("service_type") or "daycare"
        pool_key = svc_type if svc_type in pool_increments else "daycare"
        for _ in range(item.quantity):
            lot = {
                "id": str(uuid.uuid4()),
                "client_id": client_id,
                "pack_id": pack["id"],
                "pack_name": pack["name"],
                "service_type": svc_type,
                "qty_total": qty,
                "qty_remaining": qty,
                "price_paid": effective_price,
                "list_price": float(pack["price"]),
                "price_override_id": pricing["override_id"],
                "value_each": value_each,
                "payment_method": _normalize_payment_method(body.payment_method, store=True),
                "note": body.note or "",
                "sold_by": user.get("name", "Admin"),
                "purchased_at": now,
                # Sprint 110cs — Same point-of-sale recognition as the
                # singular sell-pack endpoint. Bulk flow is the one the UI
                # uses, so this is the one operators actually see.
                "recognize_at_sale": True,
            }
            new_lots.append(lot)
            pool_increments[pool_key] += qty
            totals_by_pool[pool_key]["qty"] += qty
            totals_by_pool[pool_key]["price"] += effective_price

    await db.credit_lots.insert_many(new_lots)
    # Sprint 110di-61 — Partial-pay across the bulk cart. The cart's
    # `body.amount_paid` represents what the client handed over for the
    # ENTIRE order. Under option 1c, today's revenue (across all retail_sales
    # rows we're about to insert) is capped at amount_paid; the unpaid
    # remainder goes onto the client's tab via ONE charge/payment pair on
    # the ledger labelled with the order summary.
    grand_total_full = round(sum(float(lot.get("price_paid") or 0) for lot in new_lots), 2)
    is_partial = (
        body.amount_paid is not None
        and grand_total_full > 0
        and abs(float(body.amount_paid) - grand_total_full) > 0.005
    )
    revenue_cap = grand_total_full
    if is_partial:
        revenue_cap = max(0.0, min(float(body.amount_paid), grand_total_full))
        # Build a human label like "Credit packs · 1× 10-pack Daycare, 2× 5-pack Training"
        label_parts = []
        for it in body.items:
            p = packs[it.pack_id]
            label_parts.append(f"{it.quantity}× {p['name']}")
        order_label = "Credit packs · " + ", ".join(label_parts)
        await _apply_sale_partial_payment(
            client_id=client_id,
            total=grand_total_full,
            paid=float(body.amount_paid),
            sale_kind="credit_pack",
            sale_id=new_lots[0]["id"] if new_lots else None,
            label=order_label,
            method=_normalize_payment_method(body.payment_method, store=True),
        )
    # Sprint 110cs — Bulk-sell mirrors the singular path: log every lot as a
    # `retail_sales` row on today's business date so the operator sees the
    # money land in Income / P&L immediately. One row per lot keeps audit
    # easy (matches qty + price 1:1 with credit_lots). Sprint 110di-61:
    # under partial-pay, we PRORATE each row's amount so the sum equals
    # revenue_cap (today's recognized cash).
    today_iso = business_today().isoformat()
    payment_ratio = (revenue_cap / grand_total_full) if grand_total_full > 0 else 0
    retail_rows = [
        {
            "id": str(uuid.uuid4()),
            "client_id": client_id,
            "client_name": client.get("name", ""),
            "amount": round(float(lot["price_paid"]) * payment_ratio, 2),
            "date": today_iso,
            "payment_method": _normalize_payment_method(body.payment_method, store=True),
            "source_kind": "credit_pack_sale",
            "lot_id": lot["id"],
            "pack_id": lot["pack_id"],
            "pack_name": lot["pack_name"],
            "note": body.note or "",
            "logged_by": user.get("name", "Admin"),
            "created_at": now,
        }
        for lot in new_lots if float(lot.get("price_paid") or 0) > 0 and payment_ratio > 0
    ]
    if retail_rows:
        await db.retail_sales.insert_many(retail_rows)
    inc_doc: Dict[str, int] = {}
    if pool_increments["daycare"]:
        inc_doc["credits"] = pool_increments["daycare"]
    if pool_increments["training"]:
        inc_doc["training_credits"] = pool_increments["training"]
    if pool_increments["boarding"]:
        inc_doc["boarding_credits"] = pool_increments["boarding"]
    if inc_doc:
        await db.clients.update_one({"id": client_id}, {"$inc": inc_doc})

    # Strip mongo _id from response payload defensively (insert_many mutates).
    for lot in new_lots:
        lot.pop("_id", None)
    for pool in totals_by_pool.values():
        pool["price"] = round(pool["price"], 2)
    grand_total = round(sum(p["price"] for p in totals_by_pool.values()), 2)

    # Build line-items for the receipt (group identical packs into one row).
    receipt_lines: List[Dict] = []
    for item in body.items:
        pack = packs[item.pack_id]
        pricing = await resolve_client_price(client_id, "credit_pack", pack["id"], float(pack["price"]))
        unit_price = float(pricing.get("effective_price") or pack["price"])
        receipt_lines.append({
            "pack_id": pack["id"],
            "name": pack["name"],
            "qty": item.quantity,
            "unit_price": unit_price,
            "line_total": round(unit_price * item.quantity, 2),
            "service_type": pack.get("service_type") or "daycare",
            "pack_qty": int(pack["qty"]),
        })

    receipt = {
        "client_id": client_id,
        "client_name": client.get("name", ""),
        "client_email": client.get("email", ""),
        "lines": receipt_lines,
        "totals": totals_by_pool,
        "total_price": grand_total,
        "payment_method": _normalize_payment_method(body.payment_method, store=True),
        "note": body.note or "",
        "sold_by": user.get("name", "Admin"),
        "sold_at": now,
    }

    # Best-effort: email the client a receipt copy.
    try:
        await notify_client_pack_receipt(
            client=client,
            lines=receipt_lines,
            totals=totals_by_pool,
            payment_method=_normalize_payment_method(body.payment_method, store=True),
            note=body.note or "",
            sold_by=user.get("name", "Admin"),
            sold_at=now,
        )
    except Exception:
        pass
    try:
        asyncio.create_task(_maybe_auto_email_bulk_credit_pack_receipt(
            client_id=client_id, client_name=client.get("name", ""), client_email=client.get("email"),
            lines=receipt_lines, total_price=grand_total,
            payment_method=_normalize_payment_method(body.payment_method, store=True),
            sold_by=user.get("name", "Admin"), sold_at=now,
            dedup_key=new_lots[0]["id"] if new_lots else None,
        ))
    except Exception as exc:
        logger.warning("auto-email receipt spawn failed for bulk credit packs: %s", exc)

    # Sprint 110di-62 — Fire each pack's bound welcome email if set. Dedupe
    # by slug so buying 3× of the same pack only sends ONE welcome email.
    fired_slugs: set = set()
    for item in body.items:
        p = packs[item.pack_id]
        slug = p.get("welcome_email_template_slug")
        if not slug or slug in fired_slugs:
            continue
        fired_slugs.add(slug)
        try:
            asyncio.create_task(_fire_product_welcome_email(
                client=client, slug=slug,
                ctx={"pack_name": p.get("name", "")},
            ))
        except Exception as exc:
            logger.warning("bulk pack welcome email spawn failed: %s", exc)

    return {
        "lots": new_lots,
        "totals": totals_by_pool,
        "total_price": grand_total,
        "lots_created": len(new_lots),
        "receipt": receipt,
    }


