async def _seed_bulk_email_templates_once() -> None:
    """Idempotently seed the 6 system templates if missing."""
    existing = {t["slug"] async for t in db.bulk_email_templates.find({"kind": "system"}, {"slug": 1})}
    for tpl in BULK_EMAIL_SYSTEM_TEMPLATES:
        if tpl["slug"] in existing:
            continue
        await db.bulk_email_templates.insert_one({
            "id": str(uuid.uuid4()),
            "kind": "system",
            "slug": tpl["slug"],
            "name": tpl["name"],
            "subject": tpl["subject"],
            "body": tpl["body"],
            "created_at": now_iso(),
            "created_by": "system",
        })


def _marketing_unsubscribe_token(client_id: str, email: str) -> str:
    return jwt.encode({
        "sub": client_id, "email": (email or "").lower(), "type": "marketing_unsubscribe",
        "iat": datetime.now(timezone.utc), "exp": datetime.now(timezone.utc) + timedelta(days=3650),
    }, JWT_SECRET, algorithm=JWT_ALG)


def _marketing_unsubscribe_url(client_id: str, email: str) -> str:
    return f"{_app_public_url()}/api/email/unsubscribe?token={quote(_marketing_unsubscribe_token(client_id, email))}"


@api.get("/email/unsubscribe", response_class=HTMLResponse)
async def marketing_email_unsubscribe(token: str):
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALG])
    except Exception:
        return HTMLResponse("<h2>That unsubscribe link is invalid or expired.</h2>", status_code=400)
    if payload.get("type") != "marketing_unsubscribe":
        return HTMLResponse("<h2>That unsubscribe link is invalid.</h2>", status_code=400)
    cid = payload.get("sub")
    email = (payload.get("email") or "").lower()
    client = await db.clients.find_one({"id": cid}, {"_id": 0, "email": 1})
    if not client or (client.get("email") or "").lower() != email:
        return HTMLResponse("<h2>That unsubscribe link no longer matches an account.</h2>", status_code=404)
    await db.clients.update_one({"id": cid}, {"$set": {"marketing_email_opt_out": True, "marketing_email_opt_out_at": now_iso(), "marketing_email_opt_out_source": "unsubscribe_link"}})
    return HTMLResponse("<html><body style='font-family:sans-serif;padding:32px'><h2>You're unsubscribed from marketing emails.</h2><p>Booking, payment, training, and other account/service messages can still be sent when needed.</p></body></html>")


class MarketingEmailPreferenceIn(BaseModel):
    opted_out: bool


@api.put("/portal/marketing-email-preference")
async def portal_marketing_email_preference(body: MarketingEmailPreferenceIn, user: dict = Depends(get_current_user)):
    if user.get("role") != "client" or not user.get("client_id"):
        raise HTTPException(status_code=403, detail="Client account required")
    await db.clients.update_one({"id": user["client_id"]}, {"$set": {
        "marketing_email_opt_out": bool(body.opted_out),
        "marketing_email_opt_out_at": now_iso() if body.opted_out else None,
        "marketing_email_opt_out_source": "portal" if body.opted_out else None,
    }})
    return {"opted_out": bool(body.opted_out)}


async def _bulk_email_resolve_recipients(filters: List[str]) -> List[Dict[str, Any]]:
    """Resolve a list of {id, name, email, dog_names} dicts matching ALL of the filters.

    Filters are AND-combined. An empty list = "all clients with an email"."""
    filt = {k for k in filters if k in BULK_EMAIL_FILTERS}
    base_q: Dict[str, Any] = {"email": {"$nin": [None, ""]}, "marketing_email_opt_out": {"$ne": True}}
    if "active" in filt:
        base_q["status"] = {"$ne": "inactive"}
    clients = await db.clients.find(base_q, {"_id": 0}).to_list(10000)

    # Pull all dogs once (indexed by owner_id) for missing_vaccine + dog_names.
    dogs_by_owner: Dict[str, List[Dict[str, Any]]] = {}
    async for d in db.dogs.find({}, {"_id": 0}):
        dogs_by_owner.setdefault(d.get("owner_id") or "", []).append(d)

    needs_booking_filter = bool(filt & {"daycare", "boarding", "training", "upcoming_bookings"})
    bookings_by_client: Dict[str, List[Dict[str, Any]]] = {}
    if needs_booking_filter:
        _bk_q = {"status": {"$nin": ["cancelled", "rejected"]}}
        _bk_proj = {"_id": 0, "client_id": 1, "service_type": 1, "date": 1, "end_date": 1, "status": 1}
        async for b in db.bookings.find(_bk_q, _bk_proj):
            bookings_by_client.setdefault(b.get("client_id") or "", []).append(b)
        # "Has ever boarded / done daycare / trained" is a LIFETIME question;
        # completed bookings older than 90 days live in the archive, and a
        # loyal client whose last stay was a season ago was silently dropped
        # from the audience. `upcoming_bookings` is future-only, so archived
        # rows never satisfy it — harmless to include.
        if filt & {"daycare", "boarding", "training"}:
            try:
                async for b in db.bookings_archive.find(_bk_q, _bk_proj):
                    bookings_by_client.setdefault(b.get("client_id") or "", []).append(b)
            except Exception as exc:
                logger.warning("bulk email: archive scan failed (audience may be short): %s", exc)

    not_switched_set: set = set()
    if "not_switched" in filt:
        async for u in db.users.find({"role": "client"}, {"client_id": 1}):
            cid = u.get("client_id")
            if cid:
                not_switched_set.add(cid)

    today = business_today().isoformat()
    out: List[Dict[str, Any]] = []
    for c in clients:
        cid = c.get("id")
        # filter: not_switched = client with NO user record
        if "not_switched" in filt and cid in not_switched_set:
            continue
        bks = bookings_by_client.get(cid or "", [])
        if "daycare" in filt and not any(b.get("service_type") == "daycare" for b in bks):
            continue
        if "boarding" in filt and not any(b.get("service_type") == "boarding" for b in bks):
            continue
        if "training" in filt and not any(b.get("service_type") == "training" for b in bks):
            continue
        if "upcoming_bookings" in filt and not any(
            (b.get("date") or "") >= today and b.get("status") not in ("cancelled", "rejected", "completed")
            for b in bks
        ):
            continue
        client_dogs = dogs_by_owner.get(cid or "", [])
        if "missing_vaccines" in filt:
            has_missing = False
            for d in client_dogs:
                vacs = d.get("vaccines") or []
                if not vacs:
                    has_missing = True; break
                for v in vacs:
                    if not isinstance(v, dict):
                        continue
                    exp = v.get("expires_on") or v.get("expiration") or ""
                    if not exp or str(exp)[:10] < today:
                        has_missing = True; break
                if has_missing:
                    break
            if not has_missing:
                continue
        dog_names = ", ".join(d.get("name", "") for d in client_dogs if d.get("name"))
        out.append({
            "id": cid,
            "name": c.get("name") or "",
            "email": c.get("email") or "",
            "first_name": (c.get("name") or "").strip().split(" ")[0],
            "dog_names": dog_names or "your pup",
        })
    # dedupe by email
    seen: set = set()
    deduped: List[Dict[str, Any]] = []
    for r in out:
        key = (r["email"] or "").lower()
        if not key or key in seen:
            continue
        seen.add(key)
        deduped.append(r)
    return deduped


class BulkEmailFiltersIn(BaseModel):
    filters: List[str] = []
    client_ids: Optional[List[str]] = None  # if provided, takes precedence over filters


class BulkEmailSendIn(BaseModel):
    subject: str
    body: str
    filters: List[str] = []
    client_ids: Optional[List[str]] = None
    test_only: bool = False  # if True, only send to first recipient (preview)


class BulkEmailTemplateIn(BaseModel):
    name: str
    subject: str
    body: str


@api.get("/admin/bulk-email/filters")
async def bulk_email_filters_meta(_: dict = Depends(require_admin_and_permission("manage_communications"))):
    return {
        "available": [
            {"id": "active",            "label": "Active clients only"},
            {"id": "daycare",           "label": "Has at least one daycare booking"},
            {"id": "boarding",          "label": "Has at least one boarding booking"},
            {"id": "training",          "label": "Has at least one training booking"},
            {"id": "upcoming_bookings", "label": "Has upcoming bookings"},
            {"id": "missing_vaccines",  "label": "Has a dog with missing/expired vaccines"},
            {"id": "not_switched",      "label": "Has not switched to the new app (no portal account)"},
        ],
    }


@api.post("/admin/bulk-email/recipients")
async def bulk_email_recipients(body: BulkEmailFiltersIn, _: dict = Depends(require_admin_and_permission("manage_communications"))):
    if body.client_ids is not None:
        ids = [c for c in (body.client_ids or []) if c]
        if not ids:
            return {"count": 0, "recipients": []}
        cur = db.clients.find({"id": {"$in": ids}, "email": {"$nin": [None, ""]}, "marketing_email_opt_out": {"$ne": True}}, {"_id": 0})
        rows = []
        async for c in cur:
            rows.append({
                "id": c.get("id"),
                "name": c.get("name") or "",
                "email": c.get("email") or "",
                "first_name": (c.get("name") or "").strip().split(" ")[0],
                "dog_names": "",
            })
        return {"count": len(rows), "recipients": rows}
    recipients = await _bulk_email_resolve_recipients(body.filters or [])
    return {"count": len(recipients), "recipients": recipients}


def _bulk_email_render(body: str, ctx: Dict[str, str]) -> str:
    """Replace {{client_first_name}} and {{dog_names}} merge tags."""
    out = body or ""
    for k, v in ctx.items():
        out = out.replace("{{" + k + "}}", v or "")
    return out


@api.post("/admin/bulk-email/send")
async def bulk_email_send(body: BulkEmailSendIn, user: dict = Depends(require_admin_and_permission("manage_communications"))):
    subj = (body.subject or "").strip()
    if not subj:
        raise HTTPException(status_code=400, detail="Subject is required")
    if not (body.body or "").strip():
        raise HTTPException(status_code=400, detail="Body is required")

    if body.client_ids is not None:
        ids = [c for c in (body.client_ids or []) if c]
        # Sprint 110ff — hand-picked recipients used to hardcode dog_names
        # to "" (always falling back to the generic "your pup" below),
        # unlike the filtered-group path which looks each client's dogs
        # up. An email meant to read "hope Bella is doing great" went out
        # saying "hope your pup is doing great" for every hand-picked send.
        dogs_by_owner: Dict[str, List[str]] = {}
        async for d in db.dogs.find({"owner_id": {"$in": ids}}, {"_id": 0, "owner_id": 1, "name": 1}):
            if d.get("name"):
                dogs_by_owner.setdefault(d.get("owner_id") or "", []).append(d["name"])
        recipients: List[Dict[str, Any]] = []
        async for c in db.clients.find({"id": {"$in": ids}, "email": {"$nin": [None, ""]}, "marketing_email_opt_out": {"$ne": True}}, {"_id": 0}):
            recipients.append({
                "id": c.get("id"),
                "name": c.get("name") or "",
                "email": c.get("email") or "",
                "first_name": (c.get("name") or "").strip().split(" ")[0],
                "dog_names": ", ".join(dogs_by_owner.get(c.get("id") or "", [])),
            })
    else:
        recipients = await _bulk_email_resolve_recipients(body.filters or [])

    if not recipients:
        raise HTTPException(status_code=400, detail="No recipients matched the chosen filters")

    if body.test_only:
        recipients = recipients[:1]

    # Build a sent record up front so the UI can show "Sending…" history.
    history_id = str(uuid.uuid4())
    started_at = now_iso()

    success = 0
    failures: List[Dict[str, str]] = []
    for r in recipients:
        ctx = {
            "client_first_name": r.get("first_name") or "there",
            "client_name": r.get("name") or "",
            "dog_names": r.get("dog_names") or "your pup",
        }
        rendered_subj = _bulk_email_render(subj, ctx)
        rendered_body = _bulk_email_render(body.body, ctx)
        # Lightweight HTML body — wrap rendered text in the existing brand wrapper.
        text_paragraphs = "".join(f"<p style='margin:0 0 12px;font-size:15px;line-height:1.55;'>{p}</p>"
                                  for p in rendered_body.split("\n") if p.strip())
        try:
            html = email_service._wrap(  # type: ignore
                title=rendered_subj,
                intro="",
                rows=[],
                show_install=False,
                body_html=text_paragraphs or f"<p>{rendered_body}</p>",
            )
        except Exception:
            html = f"<html><body>{text_paragraphs or rendered_body}</body></html>"
        unsubscribe_url = _marketing_unsubscribe_url(r.get("id") or "", r["email"])
        unsubscribe_html = f"<div style='margin-top:28px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777'>Marketing email · <a href='{unsubscribe_url}' style='color:#777'>Unsubscribe</a></div>"
        html = html.replace("</body>", unsubscribe_html + "</body>") if "</body>" in html else html + unsubscribe_html
        try:
            ok = await email_service._send(r["email"], rendered_subj, html)  # type: ignore
        except Exception as e:
            ok = False
            failures.append({"client_id": r.get("id") or "", "email": r["email"], "error": str(e)[:200]})
            continue
        if ok:
            success += 1
            # Log into client_communications so it appears on the client's timeline.
            try:
                await db.client_communications.insert_one({
                    "id": str(uuid.uuid4()),
                    "client_id": r.get("id"),
                    "client_name": r.get("name") or "",
                    "type": "email",
                    "summary": f"[Bulk] {rendered_subj}",
                    "details": rendered_body,
                    "occurred_at": now_iso(),
                    "follow_up_required": False,
                    "follow_up_date": None,
                    "created_by_id": user.get("id"),
                    "created_by_name": user.get("name") or user.get("email"),
                    "bulk_email_id": history_id,
                })
            except Exception:
                pass
        else:
            failures.append({"client_id": r.get("id") or "", "email": r["email"], "error": email_service.last_send_error or "unknown"})

    record = {
        "id": history_id,
        "subject": subj,
        "body": body.body,
        "filters": body.filters or [],
        "manual_selection": body.client_ids is not None,
        "recipient_count": len(recipients),
        "success_count": success,
        "fail_count": len(failures),
        "failed": failures[:50],
        "test_only": bool(body.test_only),
        "sender_id": user.get("id"),
        "sender_name": user.get("name") or user.get("email"),
        "started_at": started_at,
        "finished_at": now_iso(),
    }
    await db.bulk_email_history.insert_one(record)
    record.pop("_id", None)
    return record


@api.get("/admin/bulk-email/history")
async def bulk_email_history(limit: int = 50, _: dict = Depends(require_admin_and_permission("manage_communications"))):
    rows = await db.bulk_email_history.find({}, {"_id": 0}).sort("started_at", -1).to_list(min(max(limit, 1), 200))
    return rows


@api.get("/admin/bulk-email/templates")
async def bulk_email_templates_list(_: dict = Depends(require_admin_and_permission("manage_communications"))):
    await _seed_bulk_email_templates_once()
    rows = await db.bulk_email_templates.find({}, {"_id": 0}).sort("created_at", 1).to_list(500)
    # system first, then custom
    rows.sort(key=lambda t: (0 if t.get("kind") == "system" else 1, t.get("name") or ""))
    return rows


@api.post("/admin/bulk-email/templates")
async def bulk_email_templates_create(body: BulkEmailTemplateIn, user: dict = Depends(require_admin_and_permission("manage_communications"))):
    name = (body.name or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="Template name is required")
    doc = {
        "id": str(uuid.uuid4()),
        "kind": "custom",
        "slug": None,
        "name": name,
        "subject": body.subject or "",
        "body": body.body or "",
        "created_at": now_iso(),
        "created_by": user.get("name") or user.get("email"),
    }
    await db.bulk_email_templates.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.delete("/admin/bulk-email/templates/{template_id}")
async def bulk_email_templates_delete(template_id: str, _: dict = Depends(require_admin_and_permission("manage_communications"))):
    tpl = await db.bulk_email_templates.find_one({"id": template_id}, {"_id": 0})
    if not tpl:
        raise HTTPException(status_code=404, detail="Template not found")
    if tpl.get("kind") == "system":
        raise HTTPException(status_code=400, detail="System templates cannot be deleted")
    await db.bulk_email_templates.delete_one({"id": template_id})
    return {"ok": True, "id": template_id}


