@app.middleware("http")
async def performance_timing_middleware(request: Request, call_next):
    """Expose backend timing and log genuinely slow API routes.

    This does not touch stored data. It gives the live server enough
    visibility to identify any remaining slow endpoint after deployment.
    """
    started = perf_time.perf_counter()
    response = await call_next(request)
    elapsed_ms = (perf_time.perf_counter() - started) * 1000.0
    response.headers.setdefault("Server-Timing", f'app;dur={elapsed_ms:.1f}')
    response.headers.setdefault("X-Response-Time-Ms", f"{elapsed_ms:.1f}")
    if request.url.path.startswith("/api/") and elapsed_ms >= 1000.0:
        logger.warning(
            "SLOW API %.1fms %s %s status=%s",
            elapsed_ms, request.method, request.url.path, response.status_code,
        )
    return response


@app.middleware("http")
async def security_headers_middleware(request: Request, call_next):
    response = await call_next(request)
    response.headers.setdefault("X-Content-Type-Options", "nosniff")
    response.headers.setdefault("X-Frame-Options", "DENY")
    response.headers.setdefault("Referrer-Policy", "strict-origin-when-cross-origin")
    response.headers.setdefault("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
    if request.url.path.startswith("/api/auth/") or request.url.path.startswith("/api/claim/"):
        response.headers.setdefault("Cache-Control", "no-store")
    return response


def _cors_origins() -> List[str]:
    def origin_only(value: str) -> Optional[str]:
        try:
            parsed = urlsplit((value or "").strip())
            if parsed.scheme in ("http", "https") and parsed.netloc:
                return f"{parsed.scheme}://{parsed.netloc}"
        except Exception:
            pass
        return None

    raw = (os.environ.get("CORS_ORIGINS") or "").strip()
    if raw and raw != "*":
        return list(dict.fromkeys(
            origin for origin in (origin_only(x) for x in raw.split(",")) if origin
        ))
    # The shipped deployment is same-origin through nginx and needs no CORS.
    # If APP_PUBLIC_URL is set, allowing only that exact origin keeps split
    # deployments working without restoring the unsafe wildcard.
    public = origin_only(os.environ.get("APP_PUBLIC_URL") or "")
    return [public] if public else []


