if _cors:
    app.add_middleware(
        CORSMiddleware,
        allow_credentials=True,
        allow_origins=_cors,
        allow_methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
        allow_headers=["Authorization", "Content-Type", "Accept", "X-Requested-With"],
    )
